window.__SUM[12]={"LR003559":{"pair":"ADAM15 -> ITGAV","headline":"ADAM15 disintegrin domain specifically binds integrin alphavbeta3 in two papers, one of which tested ten integrins.","interaction_type":"direct binding","direction_and_effect":"Recombinant D-15 (disintegrin-like domain) specifically interacts with alphavbeta3 and not with nine other tested integrins; mutating RGD to SGA blocked binding [PMID:9516430]. Metargidin is an alphavbeta3 ligand on U937 cells and the disintegrin domain mediates adhesion [PMID:9914169].","molecular_requirements":"Binding needs the RGD tripeptide; changing RPTRGD to NWKRGD makes D-15 also recognised by alphaIIbbeta3. alphavbeta1 was not bound, so beta3 pairing matters [PMID:9516430].","affinity_potency":[],"species_and_systems":"GST-D-15 produced in bacteria and tested on mammalian cells expressing recombinant integrins [PMID:9516430]; ADAM15-Fc on human U937 cells [PMID:9914169].","localisation_and_range":"ADAM15 is a membrane-anchored protein; cell-cell interaction proposed [PMID:9516430].","caveats":"Both papers abstract only. IntAct lists an ELISA record [DB:IntAct]. One further row was abstract-insufficient.","key_references":[{"PMID":"9516430","why":"D-15 binds alphavbeta3 specifically; RGD dependent"},{"PMID":"9914169","why":"alphavbeta3 as ADAM15 ligand on U937 cells"}],"covers":["LR000009","LR003559"]},"LR005395":{"pair":"ADAM17 -> ITGA6","headline":"Co-immunoprecipitation in mouse cells shows integrins alpha6 and beta1 bind ADAM17/TACE via its disintegrin domain; abstract read only.","interaction_type":"direct binding","direction_and_effect":"Integrins alpha6 and beta1 bind TACE (ADAM17) via the disintegrin domain, and mechanical strain enhances the interaction; force on these integrins activates TACE and sheds HB-EGF and TGF-alpha [PMID:23888051].","molecular_requirements":"Binding is via the ADAM17 disintegrin domain; alpha6 and beta1 are both implicated, so the heterodimer alpha6beta1 is the likely unit [PMID:23888051].","affinity_potency":[],"species_and_systems":"Fetal epithelial cells, wild-type and TACE knock-out cells (mouse knock-out cells noted) with TACE constructs [PMID:23888051]. Human pair is ortholog-inferred; mouse pair is not.","localisation_and_range":"ADAM17 is flagged non-secreted [flag]; contact/cis interaction at the cell surface.","caveats":"Abstract read only. Direction is the integrin acting on ADAM17 sheddase activity, rather than classic ligand signalling.","key_references":[{"PMID":"23888051","why":"Integrins alpha6/beta1 bind TACE disintegrin domain; strain enhances"}],"covers":["LR002069","LR005395"]},"LR003568":{"pair":"ADAM2 -> ITGA9","headline":"ADAM2 binds ITGA9 integrins in adhesion assays, including a novel ITGA9-ITGB7 pairing in RPMI 8866 cells.","interaction_type":"direct binding","direction_and_effect":"Adhesion of Tera-2 cells (ITGA9-ITGB1) to ADAM2 was inhibited by an anti-ITGA9 antibody; RPMI 8866 adhesion was inhibited 60% by anti-ITGA9 [PMID:21060781]. Curator label: agonist.","molecular_requirements":"ITGA9 pairs with ITGB1 or, in RPMI 8866 cells lacking detectable ITGB1, with ITGB7 [PMID:21060781].","affinity_potency":[],"species_and_systems":"Human cell lines with recombinant ADAM2 at 50 \u00b5g/ml; anti-ITGB1 antibody inhibited ADAM2 binding to mouse eggs [PMID:21060781].","localisation_and_range":"ADAM2 flagged non-secreted [flag]; adhesion to immobilised ADAM2.","caveats":"Antibody and siRNA adhesion assays rather than purified binding. Percentage inhibition from the excerpts (60%) is for partial inhibition.","key_references":[{"PMID":"21060781","why":"ITGA9-ITGB7 identified as ADAM2 binding partner"}],"covers":["LR000018","LR003568"]},"LR003577":{"pair":"ADCYAP1 -> SCTR","headline":"PACAP shows only weak, low-affinity activity at a secretin-preferring site in guinea pig chief cells; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"PACAP-38 and secretin both increased pepsinogen release from isolated guinea pig chief cells, with biphasic (PACAP) versus monophasic (secretin) curves; secretin had a >500-fold lower affinity than PACAP-38 for displacing 125I-PACAP-27 and 125I-VIP, so PACAP's main site is distinct from the secretin receptor [PMID:1335692].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"secretin 197-fold more potent than PACAP-38","assay":"displacement of 125I-secretin","system":"isolated guinea pig chief cells","cite":"PMID:1335692"}],"species_and_systems":"Guinea pig gastric chief cells (native receptors), not human or mouse recombinant SCTR [PMID:1335692]; the human and mouse pairs are ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; BioGRID lists a protein-peptide record from the same paper [DB:BioGRID].","caveats":"Weak off-target cross-reactivity, not PACAP's primary receptor pairing; SCTR identity is inferred from a secretin-preferring site; abstract read only; database support derives from the same paper.","key_references":[{"PMID":"1335692","why":"PACAP and VIP share a high-affinity site distinct from the secretin receptor"}],"covers":["LR000027","LR003577"]},"LR006781":{"pair":"ADM2 -> CALCR","headline":"ADM2 is only a weak agonist at CALCR alone in COS-7 cells; it is potent at the RAMP1-containing AMY1(a) complex. Functional evidence only, one paper.","interaction_type":"functional only","direction_and_effect":"ADM2 (intermedin short) is a weak agonist at the CT(a) receptor and AMY2(a)/AMY3(a), but considerably more potent at AMY1(a) [PMID:15692146]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Potent activity needs RAMP1 co-expressed with CALCR (AMY1(a)); CALCR alone gives a weak response [PMID:15692146].","affinity_potency":[{"value":"pEC50 6.5","assay":"cAMP accumulation","system":"COS-7 cells (curator-recorded; receptor context not stated in the abstract)","cite":"PMID:15692146"}],"species_and_systems":"COS-7 cells expressing CT(a) receptor with or without RAMPs; curators annotate human ligand and receptor [PMID:15692146].","localisation_and_range":"ADM2 is flagged secreted [flag]; receptor is transmembrane [flag].","caveats":"Abstract-only; no binding assay. A second paper is review_only. Do not read this as strong CALCR-alone signalling.","key_references":[{"PMID":"15692146","why":"cAMP pharmacology of CT(a) alone and with RAMPs"}],"covers":["LR006781"]},"LR007087":{"pair":"ADM2 -> CALCRL:RAMP2","headline":"Database records support ADM2 at CALCRL with RAMP2; the one paper is gene-expression and knockdown work, not direct ligand-receptor evidence.","interaction_type":"functional only","direction_and_effect":"In breast cancer cell lines, ADM2 knockdown and RAMP2 overexpression each suppressed proliferation and invasion [PMID:41150812]. GtoPdb lists ADM2 as a full agonist at CALCRL and RAMP2 [DB:GtoPdb]; Reactome records the adrenomedullin receptor binding adrenomedullin and intermedin [DB:Reactome R-HSA-420214].","molecular_requirements":"Only RAMP2 is named in the paper; CALCRL was not individually tested [PMID:41150812]. Pairing with CALCRL rests on databases.","affinity_potency":[{"value":"pEC50 7.5-8.3","assay":"GtoPdb agonist record (ADM2-RAMP2)","system":"not given","cite":"DB:GtoPdb"}],"species_and_systems":"Human breast cancer lines BT-549 and MDA-MB-231 [PMID:41150812].","localisation_and_range":"ADM2 is flagged secreted; complex is flagged transmembrane [flag].","caveats":"The paper never tests ADM2 acting through RAMP2: both manipulations, ADM2 knockdown and RAMP2 overexpression, were separate and gave the same direction. Read as abstract plus full text. One other paper was abstract_insufficient.","key_references":[{"PMID":"41150812","why":"ADM2 and RAMP2 each affect breast cancer cell proliferation and invasion"}],"covers":["LR007087"]},"LR008455":{"pair":"AFDN -> EPHB3","headline":"Database-only protein interaction between AFDN and EPHB3; no paper supports a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists two-hybrid, affinity capture-Western and reconstituted complex records for AFDN (MLLT4) with EPHB3; IntAct lists a two-hybrid [DB:BioGRID][DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the database experiments is not reported in our evidence.","localisation_and_range":"No localisation flag for AFDN; EPHB3 flagged receptor and transmembrane [flag].","caveats":"No papers support this pair; all judged papers were different_entity or inconclusive, so it may be a partner-binding interaction rather than ligand-receptor.","key_references":[],"covers":["LR008455"]},"LR008482":{"pair":"AFDN -> NECTIN1","headline":"Database-only protein interaction between AFDN and NECTIN1; no paper supports a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists two-hybrid, co-purification, reconstituted complex and affinity capture-Western records; IntAct lists pull-down and two-hybrid [DB:BioGRID][DB:IntAct]. UniProt says NECTIN1 interacts via its cytoplasmic domain with AFDN via its PDZ domain [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the database experiments is not reported in our evidence.","localisation_and_range":"No localisation flag for AFDN; NECTIN1 flagged receptor and transmembrane [flag]; the UniProt text places binding at the cytoplasmic domain.","caveats":"No papers support this pair; judged papers were different_entity (3) or unresolvable (1). Support is database-only.","key_references":[],"covers":["LR008482"]},"LR009373":{"pair":"AFDN -> NRXN2","headline":"Database-only protein interaction between AFDN and NRXN2; no paper supports a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists a two-hybrid interaction between AFDN (MLLT4) and NRXN2 [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the database experiments is not reported in our evidence.","localisation_and_range":"No localisation flag for AFDN; NRXN2 flagged receptor and transmembrane [flag].","caveats":"No papers support this pair; all judged papers were different_entity or inconclusive, so it may be a partner-binding interaction rather than ligand-receptor.","key_references":[],"covers":["LR009373"]},"LR003595":{"pair":"Agt -> Agtr1a","headline":"Angiotensin II activates AT1 receptors in binding and functional assays across several systems; the ligand acting is the processed peptide, not full-length Agt.","interaction_type":"direct binding","direction_and_effect":"Angiotensin II acts as an agonist: it increased inositol phosphate accumulation in CHO cells expressing human AT1 and bound the receptor in [3H]-angiotensin II binding [PMID:10193788]. In mouse AgRP neurons, Ang-II inhibited firing via AT1A (Agtr1a) and Gai; losartan abolished this and Agtr1a deletion removed it [PMID:37540598]. Reactome lists AGT(25-32) binding AGTR1 [DB:Reactome R-HSA-374173].","molecular_requirements":"Not reported in our evidence beyond a single receptor chain; the active ligand is Ang II (the AGT(25-32) fragment) [DB:Reactome R-HSA-374173]. Ang III and Ang IV act differently and depend on receptor residues such as Asp281 [PMID:12006574].","affinity_potency":[{"value":"EC50 3.4 nM","assay":"angiotensin II-induced inositol phosphate accumulation (10 mM LiCl)","system":"CHO-K1 cells expressing human AT1","cite":"PMID:10193788"}],"species_and_systems":"Mouse pair, but most binding work used human AT1 in CHO-K1 cells [PMID:10193788, PMID:12006574] or rat and human tissues [PMID:2775266]; mouse evidence comes from AgRP neuron recordings [PMID:37540598]. Structure and SPA records exist [DB:PDB 6OS0, DB:IntAct P30556-P01019].","localisation_and_range":"Ligand flagged secreted [flag]; Ang II is a circulating or local hormone acting on a membrane receptor.","caveats":"Our evidence concerns the cleavage product Ang II, which a gene-level Agt row cannot separate from Ang III or Ang IV [PMID:12006574]. Most papers were read as abstracts only. PMID:10993080 is about AT1-B2 heterodimers and only frames Ang II binding as background. In mouse AgRP neurons AT1A can also switch coupling after diet-induced obesity [PMID:37540598].","key_references":[{"PMID":"10193788","why":"Ang II binding and IP response at human AT1 with EC50"},{"PMID":"37540598","why":"Full-text mouse neuron work: Ang-II acts via AT1A/Gai, blocked by losartan"},{"PMID":"12006574","why":"Ang II residues needed for AT1 activation, with Ang III/IV contrast"}],"covers":["LR003595"]},"LR005449":{"pair":"APLP2 -> CNTN4","headline":"APLP2 binds CNTN4 in a single paper using binding assays, biolayer interferometry and a crystal structure; the affinity is weak.","interaction_type":"direct binding","direction_and_effect":"The paper reports APLP2 binding CNTN4 in extracellular binding assays and biolayer interferometry (BLI), and states that APLP2 only binds CNTN4 and CNTN5, not CNTN3 [PMID:34958801]. Signalling effect and agonist or antagonist role are not reported in our evidence; contactins are described as forming coreceptor complexes with transmembrane proteins [PMID:34958801].","molecular_requirements":"A zebrafish CNTN4-APLP2 crystal structure (PDB 7MQY) is listed; the conserved interface involves the second fibronectin type III repeat of CNTNs and the copper-binding domain of amyloid proteins [PMID:34958801]. Further co-receptors are not reported in our evidence.","affinity_potency":[{"value":"6.3 \u03bcM","assay":"biolayer interferometry","system":"human APLP2 with CNTN4","cite":"PMID:34958801"}],"species_and_systems":"Human and mouse proteins were tested, plus zebrafish proteins (APLP2 with CNTN4 about 21.4 \u03bcM) [PMID:34958801]. The mouse pair is ortholog-inferred. Recombinant protein assays.","localisation_and_range":"APLP2 carries transmembrane, secreted and receptor annotation flags [flag]. CNTNs are GPI-anchored to the plasma membrane [PMID:34958801], so contact (juxtacrine) signalling is suggested.","caveats":"Weaker than CNTN4-APP or APP-APLP1 pairs per the paper [PMID:34958801]. Single paper. The curated direction label is not supported by the text.","key_references":[{"PMID":"34958801","why":"BLI affinity, selectivity within the CNTN family and crystal structure"}],"covers":["LR002132","LR005449"]},"LR005458":{"pair":"APOB -> TREM2","headline":"TREM2 binds LDL and apolipoproteins in one study; apoB itself is inferred from the LDL result.","interaction_type":"direct binding","direction_and_effect":"A protein microarray screen identified lipoprotein particles including LDL, and apolipoproteins including CLU/APOJ and APOE, as TREM2 ligands; binding was abolished or reduced by disease-associated TREM2 mutations [PMID:27477018]. Trem2 knockout microglia showed reduced LDL internalization [PMID:27477018]. BioGRID lists a TREM2-APOB reconstituted complex [DB:BioGRID].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins listed; mouse knockout microglia were used for uptake [PMID:27477018]. Mouse pair is ortholog-inferred.","localisation_and_range":"TREM2 is flagged secreted and receptor; APOB flagged secreted [flag].","caveats":"The abstract names LDL, not APOB, as the ligand; APOB itself is not named. Abstract only.","key_references":[{"PMID":"27477018","why":"TREM2 binds LDL and apolipoproteins"}],"covers":["LR002141","LR005458"]},"LR005476":{"pair":"APP -> LRP2","headline":"No supporting paper; only a BioGRID reconstituted-complex record supports this pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the BioGRID record [DB:BioGRID].","localisation_and_range":"Not reported in our evidence; flags mark LRP2 as a receptor [flag].","caveats":"All 8 judged papers were rated as concerning a different entity, so none confirm the pair. The only support is a BioGRID reconstituted-complex record [DB:BioGRID]. Treat as unverified.","key_references":[],"covers":["LR002161","LR005476"]},"LR007096":{"pair":"APP -> TREM2:TYROBP","headline":"One recent abstract reports direct sAPPalpha-TREM2 binding by solid-phase, pull-down and co-IP.","interaction_type":"direct binding","direction_and_effect":"sAPPalpha binds TREM2 directly; TREM2 knockdown worsened LPS-induced loss of viability and inflammation in BV-2 cells, and exogenous sAPPalpha reversed these changes [PMID:42689388].","molecular_requirements":"TREM2 residues 51-71 and the APP E1+Ac fragment contributed to binding; TREM2 variants Y38C, R47H, R62H and T66M reduced binding affinity [PMID:42689388]. TYROBP's role is not tested; cell-cell communication analysis only predicted APP-(TREM2+TYROBP) signalling [PMID:42689388].","affinity_potency":[],"species_and_systems":"Mouse APP/PS1 single-cell data, BV-2 microglia, and biochemical assays; ligand form is soluble sAPPalpha [PMID:42689388].","localisation_and_range":"TREM2 flagged secreted and receptor; TYROBP transmembrane [flag]. The ligand is a soluble APP fragment.","caveats":"Abstract only. UniProt describes TREM2 as a receptor for Abeta42, a different APP fragment [DB:UniProt]. IntAct also lists binding records [DB:IntAct].","key_references":[{"PMID":"42689388","why":"sAPPalpha-TREM2 binding and microglial function"}],"covers":["LR007096"]},"LR005485":{"pair":"Azgp1 -> Itgb3","headline":"Mouse Azgp1 is supported as an integrin alphaVbeta3 ligand by a single abstract-level cell adhesion study; direct binding was not shown.","interaction_type":"functional only","direction_and_effect":"Cell adhesion to Znalpha2gp was inhibited by RGDS and ELRGDV peptides and by an antibody against the vitronectin receptor, suggesting the RGD region of Znalpha2gp interacts with alphavbeta3 [PMID:9813179]. This is an adhesion (ligand-anchoring) readout; agonist or antagonist effect is not reported in our evidence.","molecular_requirements":"The evidence concerns the alphavbeta3 heterodimer (vitronectin receptor), not Itgb3 alone; Itgav is the partner chain. Whether one chain is enough is not reported in our evidence [PMID:9813179].","affinity_potency":[],"species_and_systems":"Human Znalpha2gp was used with mouse MC3T3-E1 osteoblast-like cells, so the receptor tested is the mouse cell-surface integrin; the pair here is projected from this evidence [PMID:9813179].","localisation_and_range":"Ligand is flagged secreted and the receptor as a receptor [flag]; in the assay Znalpha2gp was coated on plates and cells adhered to it, i.e. a surface-bound presentation [PMID:9813179].","caveats":"Single paper, read as abstract only. No binding assay or affinity. The ligand protein in the experiments was human, not mouse [PMID:9813179]. The integrin chain assignment rests on the paper naming alphavbeta3.","key_references":[{"PMID":"9813179","why":"RGD- and anti-vitronectin-receptor-blocked adhesion of MC3T3-E1 cells to Znalpha2gp"}],"covers":["LR005485"]},"LR009625":{"pair":"B2M -> KIR2DL3","headline":"B2M-KIR2DL3 rests on a crystal structure of the receptor with an HLA-C ligand, not on direct B2M binding.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence for B2M; structure of KIR2DL3 with HLA-C*07:02 [DB:PDB 6PAG] and Reactome HLA-C group 1 with KIR2DL2/3 [DB:Reactome R-HSA-198958].","molecular_requirements":"Complex includes HLA-C and B2M chains [DB:PDB 6PAG]; B2M contact is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in the database records; no paper-level evidence in our evidence set.","localisation_and_range":"B2M is flagged secreted [flag]; the receptor is flagged transmembrane [flag]; range is otherwise not reported in our evidence.","caveats":"No curator-verified paper supports this pair; it rests on database records alone (PDB, Reactome). ","key_references":[],"covers":["LR009625"]},"LR009715":{"pair":"B2M -> KLRD1","headline":"B2M-KLRD1 rests on HLA-E complex structures and SPR with the CD94/NKG2 receptor, not on direct B2M binding.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence for B2M; Reactome KLRC1:KLRD1 heterodimer interacts with HLA-E [DB:Reactome R-HSA-199062]; SPR entry [DB:IntAct Q13241-P61769]; structures [DB:PDB 3CDG].","molecular_requirements":"KLRD1 acts as part of the KLRC1:KLRD1 heterodimer in these records [DB:Reactome R-HSA-198914]; B2M-specific contact is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in the database records; no paper-level evidence in our evidence set.","localisation_and_range":"B2M is flagged secreted [flag]; range is otherwise not reported in our evidence.","caveats":"No curator-verified paper supports this pair; it rests on database records alone (IntAct, PDB, Reactome).  2 additional rows were classified different_entity.","key_references":[],"covers":["LR009715"]},"LR003649":{"pair":"BDNF -> NGFR","headline":"proBDNF, not mature BDNF, acts on NGFR (p75NTR) with sortilin; low-affinity binding of BDNF to NGFR is also reported.","interaction_type":"direct binding","direction_and_effect":"Cells transfected with the low-affinity NGF receptor gene bind BDNF, whereas untransfected cells do not, so NGFR is a low-affinity BDNF receptor [PMID:2157470]. The precursor proBDNF is an apoptotic ligand acting at subnanomolar concentrations in sympathetic neurons coexpressing sortilin and p75NTR [PMID:15930396]; mature BDNF induces TrkB phosphorylation but proBDNF does not [PMID:15930396]. UniProt describes a receptor with SORCS2 that binds precursor forms with high affinity and mature NGF and BDNF with much lower affinity [DB:UniProt].","molecular_requirements":"The proBDNF apoptotic effect needs both p75NTR and sortilin on the cell surface; preformed soluble sortilin-proBDNF complexes failed to induce apoptosis [PMID:15930396]. UniProt describes a SORCS2 heterodimer [DB:UniProt].","affinity_potency":[],"species_and_systems":"Both papers were read as abstracts only; the abstracts do not name the species or the transfected cells [PMID:2157470][PMID:15930396]. The dossier lists a human pair with mouse also listed (ortholog-inferred human).","localisation_and_range":"BDNF has a secreted flag and NGFR a transmembrane flag [flag]; proBDNF is secreted by cultured neurons [PMID:15930396].","caveats":"Gene-level BDNF -> NGFR combines two processing states: precursor (pro-apoptotic via p75NTR/sortilin) and mature BDNF (TrkB signalling, low-affinity NGFR binding). The 1990 paper reports low affinity only and no numbers. Both papers are abstract-only. GtoPdb record lacks type and affinity [DB:GtoPdb].","key_references":[{"PMID":"2157470","why":"NGFR-transfected cells bind BDNF (low affinity)"},{"PMID":"15930396","why":"proBDNF induces apoptosis via p75NTR plus sortilin"}],"covers":["LR000100","LR003649"]},"LR007159":{"pair":"BDNF -> SORT1","headline":"Sortilin interacts specifically with BDNF in neurons and controls its sorting; this is an intracellular sorting receptor role, supported by several database records.","interaction_type":"direct binding","direction_and_effect":"Sortilin interacts specifically with BDNF in a region encompassing the methionine substitution and colocalizes with BDNF in secretory granules [PMID:15987945]. Truncated sortilin or sortilin siRNA causes BDNF missorting to the constitutive pathway [PMID:15987945]. Binding is also recorded in BioGRID (affinity capture-Western, reconstituted complex) and IntAct (surface plasmon resonance) [DB:BioGRID][DB:IntAct].","molecular_requirements":"Not reported in our evidence beyond the BDNF region encompassing the methionine substitution [PMID:15987945].","affinity_potency":[],"species_and_systems":"Neurons; species not stated in the abstract, abstract-only read [PMID:15987945]. Human pair.","localisation_and_range":"Function is intracellular sorting to the regulated secretory pathway in secretory granules, not cell-surface signalling [PMID:15987945]. BDNF has a secreted flag and SORT1 a transmembrane flag [flag].","caveats":"The paper concerns sorting, not paracrine signalling, so it may not apply to cell-cell communication inference. No affinity given in the dossier.","key_references":[{"PMID":"15987945","why":"sortilin binds BDNF and controls its regulated secretion"}],"covers":["LR007159"]},"LR003658":{"pair":"BMP10 -> BMPR2","headline":"Well supported: BMP10 binds the type II receptor BMPR2 with high affinity by SPR, with structural and functional support.","interaction_type":"direct binding","direction_and_effect":"BMPR2 is a high-affinity growth-factor receptor for BMP10 [PMID:35643319]. BMPRII shRNA suppressed BMP10 signalling in MC3T3 cells [PMID:16049014]. GtoPdb lists BMP10 as an agonist [DB:GtoPdb].","molecular_requirements":"BMPR2-Fc bound BMP10 with a slow dissociation rate [PMID:35643319]; BMP10 does not discriminate among ACVR2A, ACVR2B and BMPR2 [PMID:22718755]. PDB 7PPA/7PPB/7PPC give structures with BMP10 [DB:PDB 7PPA].","affinity_potency":[{"value":"KD 2.1E-09 M (SD 2.8E-10)","assay":"SPR, BMP10 over captured BMPRII-Fc","system":"recombinant proteins","cite":"PMID:35643319"}],"species_and_systems":"Recombinant Fc-fusion SPR [PMID:35643319]; MC3T3 cell line shRNA [PMID:16049014]. Curators annotate human. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP10 is annotated as secreted and the receptor as transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence tests range.","caveats":"Abstract read; the KD comes from a table in the full-text excerpts. The binding KD is from a single-curve fit average of two injections.","key_references":[{"PMID":"35643319","why":"SPR: BMP10 binds BMPR2 with high affinity"},{"PMID":"22718755","why":"BMP10 does not discriminate among type II receptors"},{"PMID":"16049014","why":"BMPRII shRNA suppresses BMP10 signalling"}],"covers":["LR000109","LR003658"]},"LR003667":{"pair":"BMP2 -> ACVR2B","headline":"Direct binding shown by SPR/Bio-Layer Interferometry with recombinant human proteins, plus mouse-cell receptor complex labelling and a crystal structure record.","interaction_type":"direct binding","direction_and_effect":"rhBMP2 bound ACVR2B and activated SMAD signalling and osteoblast markers in C3H10T1/2 cells; effect recorded as agonist [PMID:21702718]. GtoPdb lists BMP2 as agonist [DB:GtoPdb]. In mouse P19 cells, [125I]BMP2 formed heteromeric complexes with ActRII and ActRIIB [PMID:9748228].","molecular_requirements":"Type II receptor; BMP2 also bound type I ALK3 and ALK6 with similar affinity and ALK2 far more weakly [PMID:21702718]. Complex formation with type I receptors was seen in P19 cells [PMID:9748228]. PDB 2H62 has a chain of BMP2 (P12643) and of ACVR2B (Q13705) [DB:PDB 2H62].","affinity_potency":[{"value":"KD (kin) 8.0 nM","assay":"surface plasmon resonance, 1:1 Langmuir fit (read from Table III column order)","system":"recombinant human BMP2 and ACVR2B","cite":"PMID:21702718"}],"species_and_systems":"Human recombinant ligand and receptor for binding [PMID:21702718]; mouse P19 cells for the labelling experiment [PMID:9748228]. Human and mouse pairs both present.","localisation_and_range":"BMP2 is flagged secreted and not transmembrane, and the receptor complex is flagged transmembrane (annotation flags), so signalling is paracrine/juxtacrine from a secreted ligand to a cell-surface receptor [flag].","caveats":"The 21702718 abstract was the curated read, with binding values taken from full-text excerpts; the dossier mentions both SPR and Bio-Layer Interferometry. The 9748228 quote is browser-read and unverifiable, spot-check pending. The abstract of 9748228 concerns BMP7 and activin, not BMP2 as main subject. Binding affinity alone did not predict outcome [PMID:21702718]. Three further papers are pending.","key_references":[{"PMID":"21702718","why":"measured BMP2 binding to ACVR2B and other BMPRs"},{"PMID":"9748228","why":"BMP2 heteromeric complexes with ActRIIB in P19 cells"}],"covers":["LR000118","LR003667"]},"LR003676":{"pair":"BMP4 -> ACVR2A","headline":"No curator-verified paper; support rests on BioGRID and GtoPdb records only.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists the interaction as Agonist [DB:GtoPdb]. BioGRID records a reconstituted complex between ACVR2A and BMP4 [DB:BioGRID 2469097].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence; BioGRID reconstituted complex suggests an in vitro system.","localisation_and_range":"BMP4 is flagged secreted and ACVR2A a transmembrane receptor [flag].","caveats":"No paper was confirmed (8 abstract_insufficient, 1 review_only), so no binding or functional result was verified; database records only.","key_references":[],"covers":["LR000127","LR003676"]},"LR005494":{"pair":"BMP4 -> MUSK","headline":"MuSK binds BMP4 directly with low-nanomolar affinity and acts as a BMP co-receptor; one paper, human/human labels, read in full.","interaction_type":"direct binding","direction_and_effect":"MuSK is reported as a BMP4 co-receptor: it promotes BMP4-dependent SMAD phosphorylation and Id1 transcription in myoblasts, and the curators label it agonist [PMID:27601729]. The soluble MuSK ectodomain instead inhibited BMP4-induced Id1 reporter activity by 50% at 50 or 100 nM, possibly by sequestering BMP4 [PMID:27601729].","molecular_requirements":"High-affinity BMP4 binding required the alternatively spliced third Ig-like domain (Ig3) of MuSK; a construct lacking Ig3 showed only low, nonsaturable binding. MuSK also bound type I receptors ALK3 and ALK6 independently of ligand, and its BMP effect needed type I BMP receptor activity but not MuSK kinase activity [PMID:27601729].","affinity_potency":[{"value":"Kd 6.1 nM","assay":"SPR, BMP4 immobilised, MuSK ectodomain as analyte","system":"recombinant proteins","cite":"PMID:27601729"},{"value":"half-maximal binding ~30 nM","assay":"binding titration of BMP4 to Fc-fused full-length MuSK ectodomain","system":"recombinant proteins","cite":"PMID:27601729"}],"species_and_systems":"Curators label ligand and receptor experiments as human. Binding was shown by nickel-bead pull-down and SPR with recombinant proteins; signalling used C2C12-derived myoblasts/myotubes, whose species the excerpts do not state [PMID:27601729]. Mouse pair is projected from human evidence.","localisation_and_range":"BMP4 is flagged secreted [flag]; MuSK is a receptor tyrosine kinase described in muscle cells [PMID:27601729]. Ligand-receptor range beyond that is not reported in our evidence.","caveats":"Single paper. Binding Kd varied by assay (6.1 nM SPR; half-maximal about 30 nM in a binding titration with Fc-fusion ectodomain).","key_references":[{"PMID":"27601729","why":"SPR and pull-down binding of BMP4 to MuSK; Ig3 requirement; BMP signalling effects"}],"covers":["LR002180","LR005494"]},"LR003685":{"pair":"BMP6 -> BMPR1A","headline":"Weak direct binding of BMP-6 to BMPR-IA in one full-text paper; database agonist and UniProt notes agree.","interaction_type":"direct binding","direction_and_effect":"BMP-6 weakly bound BMPR-IA (ALK-3), to which BMP-2 also bound; curated effect is agonist [PMID:10504300]. GtoPdb lists BMP6 as agonist at BMPR1A [DB:GtoPdb]. UniProt says BMP6 may promote HAMP expression via BMPR1A/ALK3 [DB:UniProt].","molecular_requirements":"Binding was assayed with type I and type II receptors co-expressed; the paper reports binding by BMPR-IA in MC3T3-E1 and C2C12 cells [PMID:10504300]. Whether BMPR-IA alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Affinity cross-linking and co-immunoprecipitation of 125I-BMP-6 (recombinant human) with transfected COS-7 cells; endogenous binding in mouse MC3T3-E1 and C2C12 cell lines [PMID:10504300]. The human pair is not ortholog-inferred; the mouse pair is.","localisation_and_range":"BMP6 is flagged as secreted [flag], so action would be paracrine or endocrine; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Binding was described as weak, in contrast to strong binding to ALK-2. Only one verified paper; no affinity value reported.","key_references":[{"PMID":"10504300","why":"Direct binding of BMP-6 to BMPR-IA, weak, cross-linking in COS-7 and mouse cell lines"}],"covers":["LR000136","LR003685"]},"LR003694":{"pair":"BMP7 -> ENG","headline":"Endoglin associates with BMP7 only via activin type II receptors; endoglin cannot bind the ligand alone.","interaction_type":"direct binding","direction_and_effect":"Endoglin interacts with BMP-7 but requires coexpression of the respective ligand-binding kinase receptor; it cannot bind ligands on its own [PMID:9872992]. It interacts with activin-A and BMP-7 via activin type II receptors ActRII and ActRIIB, regardless of the type I partner, and did not interact with BMP-7 through complexes containing the BMP type II receptor [PMID:9872992]. Effect on signalling: endoglin did not alter heteromeric complex formation, though it coprecipitated [PMID:9872992].","molecular_requirements":"ActRII or ActRIIB is required; endoglin is described as an accessory protein of multiple TGF-beta superfamily kinase receptor complexes [PMID:9872992]. Not a stand-alone receptor.","affinity_potency":[],"species_and_systems":"Human, cell-based affinity labelling and coprecipitation [PMID:9872992]. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"Single paper read as abstract only; this is accessory-receptor association, not direct ligand binding, and the interaction class for this row is Ligand-Receptor without a stated effect.","key_references":[{"PMID":"9872992","why":"Endoglin associates with BMP-7 through ActRII/ActRIIB"}],"covers":["LR000145","LR003694"]},"LR001669":{"pair":"BMP8A -> TGFBR1","headline":"BMP8A -> TGFBR1 is supported only by a mouse spermatogonia signalling abstract (ALK5), no database record.","interaction_type":"functional only","direction_and_effect":"Agonist (curator annotation). ALK5 (equated by curators with TGFBR1) with ACVR2A, ACVR2B or TGFBR2 mediated SMAD2/3 activation, which promoted germ-cell proliferation [PMID:28465413].","molecular_requirements":"TGFBR1 acts together with a type II receptor: ACVR2A, ACVR2B or TGFBR2 [PMID:28465413].","affinity_potency":[],"species_and_systems":"Undifferentiated mouse spermatogonia and cultured mouse testis explants; abstract-only read; the human pair is listed without ortholog inference but the experiments were mouse [PMID:28465413].","localisation_and_range":"BMP8A is flagged secreted [flag]; the abstract does not state range of action.","caveats":"No database record. Evidence is functional and abstract-only; the paper uses the name ALK5, not TGFBR1.","key_references":[{"PMID":"28465413","why":"BMP8A signals through SMAD1/5/8 and SMAD2/3 receptor complexes in mouse spermatogonia"}],"covers":["LR001669"]},"LR008266":{"pair":"BMP8B -> ACVR1:ACVR2A","headline":"BMP8B -> ACVR1:ACVR2A rests on GtoPdb agonist records only; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8B as an agonist at ACVR1 and ACVR2A [DB:GtoPdb]; no verified paper supports the effect.","molecular_requirements":"Complex is assembled from separate chain records; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"Not reported in our evidence; the ligand has no secretion flag in the dossier.","caveats":"Judged papers were abstract-insufficient, review-only or about a different entity; none confirmed this pair. No affinity.","key_references":[],"covers":["LR008266"]},"LR008239":{"pair":"BTC -> ERBB2:ERBB3","headline":"BTC binds the ERBB2:ERBB3 heteromeric complex, not either receptor alone, in one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"[125I]EGF-crosslinked species in 32D.E2/E3 cells were displaced by HRG and BTC but not by other EGF-like ligands; BTC induced receptor tyrosine phosphorylation, signalling and proliferation [PMID:9312020]. Curator effect: agonist.","molecular_requirements":"Both ErbB2 and ErbB3 are needed: BTC bound the ErbB2:ErbB3 complex but not either receptor alone, and was as effective as HRG when ErbB2 was co-expressed with an ErbB3-EGFR chimera [PMID:9312020].","affinity_potency":[],"species_and_systems":"Human BTC with 32D.E2/E3 cells co-expressing ErbB2 and ErbB3 (receptor species not reported in our evidence).","localisation_and_range":"BTC is flagged secreted and transmembrane [flag]; PDB 8U4K has BTC and ERBB2 chains [DB:PDB 8U4K].","caveats":"Abstract only; one paper; no affinity. Physical binding rests on crosslink displacement, not purified-protein assays.","key_references":[{"PMID":"9312020","why":"BTC specifically binds ErbB2:ErbB3 heteromer, not either chain alone."}],"covers":["LR008239"]},"LR009058":{"pair":"C1QTNF1 -> AVPR2","headline":"No curator-verified paper; only two BioGRID records (two-hybrid, reconstituted complex) support this pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists AVPR2 - C1QTNF1 by two-hybrid and reconstituted complex, both from one publication [DB:BioGRID, PMID:12409230]; species and system not given in our evidence.","localisation_and_range":"AVPR2 is flagged as a transmembrane receptor [flag]; no secretion flag for C1QTNF1 in the dossier.","caveats":"Support rests on database records only. Both judged papers were classed 'different_entity', i.e. the evidence concerned another entity, so the pair is unverified.","key_references":[],"covers":["LR009058"]},"LR008734":{"pair":"C3 -> CD19","headline":"No curated paper supports it; only Reactome records of a CR2-C3d complex that includes CD19.","interaction_type":"database-asserted only","direction_and_effect":"No direction or effect is reported in our evidence. Reactome shows CR2:C3d,C3dg,iC3b binding CD19:CD81, not C3 binding CD19 directly [DB:Reactome].","molecular_requirements":"In Reactome, CD19 acts within a CR2:CD19:CD81 complex that binds C3d fragments [DB:Reactome].","affinity_potency":[],"species_and_systems":"not reported in our evidence; Reactome entries are human.","localisation_and_range":"Not assessed.","caveats":"No papers were confirmed (reviews and insufficient abstracts only). This looks like a co-receptor-complex member rather than a ligand-binding receptor for C3.","key_references":[],"covers":["LR008734"]},"LR001678":{"pair":"CADM1 -> CADM1","headline":"CADM1 binds itself (trans-homophilic) and this drives adhesion and PI3K signalling; several papers, mostly abstract-level.","interaction_type":"direct binding","direction_and_effect":"CADM1-Fc interacted with CADM1 by SPR imaging [PMID:30131958]. Trans-homophilic CADM1 interaction induced cell spreading through PI3K, Akt and Rac1, via MPP3 and Dlg bridging to p85 [PMID:25268382]. Homophilic binding between nerve and mast cells promoted mast cell degranulation after nerve stimulation [PMID:17250899].","molecular_requirements":"Homophilic dimer; intracellular MAGuK proteins MPP3 and Dlg connect CADM1 to PI3K p85 [PMID:25268382]. UniProt notes the CRTAM interaction competes with CADM1 homodimerization [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human recombinant proteins (SPR), MDCK cells expressing CADM1 [PMID:24503895]; mouse nerve-mast cell work [PMID:17250899] (curated as human species). Reactome and IntAct list homodimer records [DB:Reactome] [DB:IntAct].","localisation_and_range":"Transmembrane, not secreted [flag]; acts by trans-homophilic cell-cell contact (juxtacrine) [PMID:24503895].","caveats":"Self-interaction pair, so direction is not meaningful. Eight papers confirmed, only some shown; one pending. One paper reports CADM1 binding nectin-3 heterophilically instead [PMID:22703826].","key_references":[{"PMID":"30131958","why":"SPR imaging of CADM1 interactions"},{"PMID":"24503895","why":"Trans-homophilic CADM1 activates PI3K"},{"PMID":"17250899","why":"Homophilic nerve-mast cell adhesion in vivo"}],"covers":["LR001678","LR005054"]},"LR005539":{"pair":"CADM2 -> CADM2","headline":"Homophilic CADM2 binding detected by SPRi in one paper; no affinity reported for it in our evidence.","interaction_type":"direct binding","direction_and_effect":"SPRi detected homophilic and heterophilic interactions of CADM2 with all CADM family proteins [PMID:30131958]. This is self-binding, so direction is not meaningful.","molecular_requirements":"CADM2 ectodomain-Fc; homodimer, no other subunit reported [PMID:30131958].","affinity_potency":[],"species_and_systems":"Human-labelled recombinant Fc ectodomains [PMID:30131958]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both flagged non-secreted [flag]; homophilic trans adhesion is consistent with Reactome Necl transhomodimerisation entries [DB:Reactome].","caveats":"One paper. The curated sentence (CADM1-Fc binding CADM2) describes a different pairing than CADM2-CADM2, so support is via the paper's general statement. Affinity for CADM2-CADM2 is not reported in our evidence.","key_references":[{"PMID":"30131958","why":"SPRi of CADM family, homophilic CADM2 binding"}],"covers":["LR002229","LR005539"]},"LR005548":{"pair":"CALCA -> CRCP","headline":"No evidence that CALCA binds CRCP; the only link is a gene name containing 'CGRP'. Both papers judged pair-absent.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. The paper studied RCP (CRCP) and found a direct interaction with an intracellular domain of CLR, not with CGRP [PMID:22315449].","molecular_requirements":"Not reported in our evidence. CRCP is described only as a CGRP receptor component affecting CLR signalling [PMID:22315449].","affinity_potency":[],"species_and_systems":"Not reported in our evidence; the mouse pair is the recorded species, human is ortholog-inferred.","localisation_and_range":"CALCA flagged secreted [flag]; CRCP is flagged receptor only [flag].","caveats":"Curators verified the pair as absent. The only database item is the HGNC name 'CGRP receptor component', which contains the ligand name [DB:HGNC]. This is likely a name-based pairing, not binding.","key_references":[{"PMID":"22315449","why":"RCP-CLR intracellular interaction, no CGRP-RCP binding"}],"covers":["LR002238","LR005548"]},"LR009076":{"pair":"CALM1 -> OPRM1","headline":"Calmodulin-OPRM1 rests on a single UniProt statement.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says OPRM1 interacts with calmodulin [DB:UniProt]. Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not stated.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only. The UniProt record is one line with no site or assay in our dossier.","key_references":[],"covers":["LR009076"]},"LR008914":{"pair":"CALM3 -> KCNQ5","headline":"Cryo-EM structures show calmodulin bound to human KCNQ5; no curated paper tests a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. PDB entries show human KCNQ5-CaM with PIP2 and with PIP2 plus HN37 in a closed conformation [DB:PDB 9LIZ] [DB:PDB 9LJ1].","molecular_requirements":"Each structure contains one calmodulin chain and one KCNQ5 chain [DB:PDB 9LIZ]. Further subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human KCNQ5-CaM, cryo-EM [DB:PDB 9LIZ] [DB:PDB 9LJ1].","localisation_and_range":"Not reported in our evidence.","caveats":"Six PDB records are the only support, with no verified paper; the judged paper concerned a different entity. Calmodulin here is a channel-bound regulatory subunit rather than a secreted ligand.","key_references":[{"PMID":"40172963","why":"Cryo-EM structures of human KCNQ5-CaM with PIP2 (PDB 9LIZ, 9LJ1)"}],"covers":["LR008914"]},"LR005557":{"pair":"CBLN2 -> NRXN1","headline":"CBLN2 acts with NRXN1 SS4+ in mouse prefrontal cortex and hippocampus; evidence is genetic.","interaction_type":"functional only","direction_and_effect":"Nrxn1SS4+ and Nrxn3SS4+ act by binding secreted Cbln2, which activates postsynaptic GluD1 receptors; in prefrontal cortex Nrxn1SS4+-Cbln2 signalling selectively controlled NMDA-receptors without changing spine or synapse numbers [PMID:36205393].","molecular_requirements":"The SS4+ splice variant of Nrxn1 is used; Cbln2 then signals to GluD1 [PMID:36205393].","affinity_potency":[],"species_and_systems":"Mouse constitutive Cbln2 knockouts at CA1 to subiculum synapses and in prefrontal cortex; curators recorded human [PMID:36205393].","localisation_and_range":"CBLN2 is flagged secreted and NRXN1 transmembrane [flag].","caveats":"Abstract read only. The abstract states binding but the shown assays are physiological. GluD1 is the downstream receptor in this paper. A second confirmed paper was not shown.","key_references":[{"PMID":"36205393","why":"Nrxn1SS4+-Cbln2-GluD1 signalling regulates NMDA receptors"}],"covers":["LR002247","LR005557"]},"LR006790":{"pair":"CCL13 -> CCR1","headline":"CCL13 is listed as a CCR1 agonist in GtoPdb, but the papers found concern MCP-3 (a different chemokine); evidence for CCL13 itself is weak.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CCL13 as an agonist of CCR1 [DB:GtoPdb]. The papers show MCP-3 binding and activating CCR1 [PMID:8530354][PMID:7545673]; a third reports a panel of chemokines that act as full agonists with the exception of MCP-2 [PMID:12381680].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human receptor in transfectants and cells [PMID:8530354][PMID:12381680].","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Curator notes say the papers concern MCP-3 (CCL7), not CCL13 (MCP-4); CCL13 is not clearly in the tested panel. Abstract-only reads.","key_references":[{"PMID":"8530354","why":"MCP-3 is a CCR1 agonist (ligand may not be CCL13)"},{"PMID":"12381680","why":"Panel of chemokines on hCCR1 incl. full agonists"}],"covers":["LR006790"]},"LR001687":{"pair":"CCL18 -> CCR3","headline":"CCL18 binds CCR3 and acts as a competitive antagonist, binding only a subset of receptor populations.","interaction_type":"conflicting","direction_and_effect":"Antagonist: CCL18 inhibited chemotaxis to other CCR3 agonists and behaved as a competitive antagonist by Schild analysis [PMID:23951310]; GtoPdb lists an antagonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 317.6 nM","assay":"inhibition of CCL11-induced chemotaxis (CCL11 at 1 nM)","system":"L1.2/CCR3 transfectants","cite":"PMID:23951310"}],"species_and_systems":"Human CCL18 on L1.2 cells expressing CCR3; abstract and excerpts [PMID:23951310].","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"CCL18 binds only a subset of CCR3 receptor populations. Its inhibition of CCR1, CCR2, CCR4 and CCR5 works via GAG displacement rather than receptor binding [PMID:23951310]. IC50 values vary with the agonist used (e.g. 317.6 nM for CCL11).","key_references":[{"PMID":"23951310","why":"CCL18 competitive antagonism of CCR3"}],"covers":["LR001687"]},"LR003739":{"pair":"CCL19 -> CCRL2","headline":"CCL19 binds CCRL2 (CRAM) with CCR7-like affinity but without signalling; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Binding does not trigger calcium mobilization or migration; CCRL2 constitutively recycles via clathrin-coated pits and internalises CCL19, suggesting a scavenger or competitor role [PMID:20002784]. GtoPdb lists the type as agonist with action unknown [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pIC50 7.36","assay":"radioactive labelling binding","system":"CRAM-expressing cells","cite":"PMID:20002784"}],"species_and_systems":"Human ligand and receptor [PMID:20002784]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"Single paper, abstract only; it states affinity similar to that of CCR7 without a second source. Reactome records the complex [DB:Reactome].","key_references":[{"PMID":"20002784","why":"CCL19 binding and internalisation by CRAM/CCRL2"}],"covers":["LR000211","LR003739"]},"LR003757":{"pair":"CCL2 -> CCR2","headline":"Strongly supported, the canonical CCL2 receptor, with picomolar binding and an agonist role, from five papers and several databases.","interaction_type":"direct binding","direction_and_effect":"CCL2 (MCP-1) is the agonist; calcium mobilization through CCR2 was as efficient with CCL2 as with vCCL4, with cross-desensitisation [PMID:12554737]; CHO-CCR2 cells treated CCL2 as primary agonist [PMID:15207250]. GtoPdb: full agonist [DB:GtoPdb].","molecular_requirements":"The 35 N-terminal residues of CCR2 bound MCP-1 with affinity similar to intact receptor and were necessary and sufficient for high-affinity binding [PMID:9287323].","affinity_potency":[{"value":"35 pM","assay":"alanine-scanning binding of wild-type MCP-1","system":"THP-1 and CCR2-transfected CHL cells","cite":"PMID:10529171"},{"value":"Kd 60 nm","assay":"spiropiperidine blocking MCP-1 binding (antagonist)","system":"CCR2","cite":"PMID:10770925"}],"species_and_systems":"Human ligand and receptor in recombinant cell lines [PMID:10529171][PMID:15207250]; mouse pair is ortholog-inferred. PDB 7XA3 holds a structure of the two chains [DB:PDB 7XA3]; UniProt records CCR2 as the key functional CCL2 receptor [DB:UniProt].","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"All papers abstract only. The 60 nm value describes a small-molecule inhibitor, not CCL2 affinity [PMID:10770925]. CCL2 also acts on CCR3 as agonist [PMID:15207250], so it is not CCR2-exclusive.","key_references":[{"PMID":"10529171","why":"Mutagenesis, wild-type affinity 35 pM"},{"PMID":"9287323","why":"N-terminal CCR2 domain needed for high-affinity binding"},{"PMID":"12554737","why":"Calcium mobilization and cross-desensitisation"}],"covers":["LR000236","LR003757"]},"LR003748":{"pair":"CCL25 -> CCR9","headline":"CCL25 (TECK) is an agonist of CCR9, supported by calcium flux, migration and chemotaxis data in human and mouse systems.","interaction_type":"functional only","direction_and_effect":"Agonist: TECK provoked calcium mobilisation in HEK 293 cells expressing human or murine GPR-9-6 (CCR9) and induced migration of human GPR-9-6 cells [PMID:10229797]. TECK specifically induced calcium flux in CCR9-expressing cell lines and chemotaxis of human thymocytes [PMID:10498628]. Mouse CD8+ lymphocytes migrated to CCL25 in line with CCR9 expression [PMID:11159507].","molecular_requirements":"CCR9 alone was sufficient in transfectants [PMID:10229797][PMID:10498628].","affinity_potency":[],"species_and_systems":"Human and murine ligand and receptor in HEK 293 cells [PMID:10229797]; human thymocytes [PMID:10498628]; mouse lymphocytes [PMID:11159507]. The mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag]; thymus and lymphoid-organ expression is reported [PMID:10229797][PMID:11159507].","caveats":"No binding constants in our evidence; evidence is functional. Abstracts only. PMID 11159507 treats the pairing as established. Reactome and GtoPdb records agree [DB:Reactome][DB:GtoPdb].","key_references":[{"PMID":"10229797","why":"Deorphanised GPR-9-6 as TECK receptor"},{"PMID":"10498628","why":"CCR9 calcium and thymocyte chemotaxis"},{"PMID":"11159507","why":"Mouse CCR9+ lymphocyte migration to CCL25"}],"covers":["LR000224","LR003748"]},"LR001696":{"pair":"CCL4L1 -> CCR5","headline":"CCL4L1 competes in binding on CCR5 cells with EC50 values comparable to CCL4; chemotaxis is also similar.","interaction_type":"direct binding","direction_and_effect":"Competitive binding with HEK-293/CCR5 cells gave comparable EC50 values for CCL4L1 and CCL4, and chemotaxis on CCR5-expressing cells showed no substantial difference [PMID:15240137]. CCL4L1 inhibited HIV-1 replication in PBMCs somewhat more than CCL4, not significantly [PMID:15240137].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins, recombinant: CCL4L1 produced in E. coli, tested on cells expressing the receptor [PMID:15240137]. The curator labels both species human.","localisation_and_range":"CCL4/CCL5 carry a secreted flag [flag], so paracrine or endocrine range is implied; the receptor carries receptor and transmembrane flags [flag].","caveats":"CCL4L1 differs from CCL4 by a single amino acid, so the evidence is a paralog comparison, not a CCL4L1-specific affinity. Abstract-level read; no database record. No numeric EC50 values appear in our evidence.","key_references":[{"PMID":"15240137","why":"CCL4L1 vs CCL4 binding and chemotaxis at CCR1, CCR3 and CCR5"}],"covers":["LR001696"]},"LR003766":{"pair":"CCL5 -> CCR1","headline":"Well established: CCL5 (RANTES) binds and activates CCR1, shown by binding, mutagenesis and functional assays; direct affinity for CCL5 is not given.","interaction_type":"direct binding","direction_and_effect":"RANTES binds CCR1-expressing transfectants specifically [PMID:7545673]; Arg17 in the N-loop is needed for binding, while P2, D6 and T7 contribute to activation [PMID:9289016]. CCL5 induced chemotaxis of mast cells, partly blocked by anti-CCR1 and anti-CCR4 antibodies and fully blocked by both [PMID:12270118]. GtoPdb records it as Full agonist [DB:GtoPdb].","molecular_requirements":"Mutating the 44RKNR47 BBXB motif of RANTES reduced CCR1 binding (80-fold lower affinity in the triple 40s mutant) while CCR5 binding was normal [PMID:11116158]. Syndecan-1, syndecan-4 and CD44 co-precipitate with RANTES on macrophages [PMID:14637022].","affinity_potency":[{"value":"pKi 6.8 to 8.2","assay":"GtoPdb interaction record","system":"not stated","cite":"DB:GtoPdb"}],"species_and_systems":"Human receptor and ligand: transfected 293 cells [PMID:7545673], mast cells from cord blood [PMID:12270118], monocyte-derived macrophages [PMID:14637022]. The mouse pair is inferred from human evidence.","localisation_and_range":"CCL4/CCL5 carry a secreted flag [flag], so paracrine or endocrine range is implied; the receptor carries receptor and transmembrane flags [flag]. RANTES also binds glycosaminoglycans [PMID:11116158].","caveats":"All papers were abstract-only reads. PMID:14637022 co-IP is weaker for CCR1 than CCR5. BioGRID lists reconstituted-complex records [DB:BioGRID]. The mast-cell result cannot separate CCR1 from CCR4.","key_references":[{"PMID":"9289016","why":"Mutagenesis maps RANTES residues for CCR1 binding"},{"PMID":"7545673","why":"Specific 125I-RANTES binding to CCR1 transfectants"},{"PMID":"12270118","why":"RANTES-induced mast cell chemotaxis via CCR1 and CCR4"}],"covers":["LR000256","LR003766"]},"LR006754":{"pair":"Ccl6 -> Ccr1","headline":"Mouse Ccl6 acts through Ccr1 in two papers (antagonist-based in neurons; knockout plus cAMP assay in eosinophil work); binding not measured.","interaction_type":"functional only","direction_and_effect":"In mouse neuron cultures, Ccl6 protected against glutamate neurotoxicity and this was suppressed by a CCR1 antagonist [PMID:31551151]. In allergic airway inflammation, Ccl6 knockout reduced eosinophilia, and the CCR1 antagonist BX471 reduced eosinophil differentiation and airway inflammation [PMID:33640900]. The full text states recombinant mouse CCL6 (aa 42-116) lowered cAMP in HEK293T cells expressing mouse CCR1 (GloSensor), consistent with Gai-coupled activation, with p-ERK1/2 and p-p38 downstream [PMID:33640900].","molecular_requirements":"Truncated recombinant CCL6 (aa 42-116) was the form used in the cAMP assay [PMID:33640900]. Other subunits not reported.","affinity_potency":[],"species_and_systems":"Mouse ligand and mouse receptor: primary cortical neurons/astrocytes [PMID:31551151]; Ccl6 knockout mice, bone-marrow cells, HEK293T-CCR1 [PMID:33640900]. The paper notes human orthologs CCL15/CCL23 [PMID:33640900].","localisation_and_range":"Ccl6 flagged secreted and Ccr1 flagged receptor, no transmembrane flag [flag]; the papers describe paracrine astrocyte-neuron and eosinophil-progenitor signalling.","caveats":"No binding or affinity data. Neuron paper read as abstract only; effects rely on a CCR1 antagonist, whose specificity is not discussed in our evidence.","key_references":[{"PMID":"33640900","why":"CCL6 activates CCR1 (cAMP, ERK/p38); BX471 and knockout data"},{"PMID":"31551151","why":"Neuroprotection by CCL6 blocked by CCR1 antagonist"}],"covers":["LR006754"]},"LR003775":{"pair":"CCL7 -> ACKR4","headline":"One paper measures MCP-3 binding to a receptor named CCR11 (ACKR4) at IC50 4.1 nM, but the interpretation of MCP-family ligands is contested.","interaction_type":"direct binding","direction_and_effect":"Competition binding showed MCP-3 recognised the receptor with IC50 4.1 nM, though MCP-3 acted as an agonist in chemotaxis only at concentrations about 100-fold higher [PMID:10734104]. The best ligand there was MCP-4 (IC50 0.14 nM) [PMID:10734104].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 4.1 nM","assay":"competition binding vs radiolabelled MCP-4","system":"receptor-transfected murine L1.2 cells (human receptor)","cite":"PMID:10734104"}],"species_and_systems":"Human ligand and receptor expressed in murine L1.2 cells [PMID:10734104]; mouse pair is ortholog-inferred.","localisation_and_range":"CCL7 flagged secreted; ACKR4 flagged transmembrane receptor [flag].","caveats":"Abstract only. Curator notes record that the paper calls the receptor CCR11 and that ACKR4's currently accepted ligands differ, so MCP claims were not upheld. No database records.","key_references":[{"PMID":"10734104","why":"MCP-3 binds CCR11/ACKR4, IC50 4.1 nM"}],"covers":["LR000265","LR003775"]},"LR003784":{"pair":"CCL8 -> CCR1","headline":"CCL8 (MCP-2) binds and activates CCR1 in transfected human cells; supported by binding and migration data and GtoPdb.","interaction_type":"direct binding","direction_and_effect":"CCL8 acts as an agonist: CCR1-transfected HEK293 cells migrated in response to MCP-2 [PMID:9115216], and GtoPdb lists it as an agonist [DB:GtoPdb]. In a second study, MCP-2 displaced radiolabelled MIP-1alpha from CCR1 but, unlike the other chemokines tested, was not a full agonist in [35S]-GTPgammaS exchange [PMID:12381680].","molecular_requirements":"CCR1 alone was sufficient in transfected cells; no co-receptor or subunit requirement is reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CCL8 and human CCR1 in recombinant cells (HEK293 [PMID:9115216]; Ba/F3-hCCR1 membranes [PMID:12381680]). The mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"CCL8 is flagged secreted and CCR1 is flagged transmembrane [flag], so signalling is paracrine via a soluble ligand acting on a cell-surface GPCR.","caveats":"Both papers were read as abstracts only. CCL8 binds CCR1 promiscuously with other chemokines. Efficacy is partial rather than full in one assay [PMID:12381680]. No affinity value is reported in our evidence. No mouse experiment is in the dossier.","key_references":[{"PMID":"9115216","why":"Radiolabelled MCP-2 binding to CCR1-transfected cells, displaced by other CCR1 ligands, plus migration"},{"PMID":"12381680","why":"MCP-2 displaces 125I-MIP-1alpha at hCCR1 but is not a full agonist in GTPgammaS exchange"}],"covers":["LR000274","LR003784"]},"LR003919":{"pair":"CCN1 -> ITGB2","headline":"CCN1 engages the beta2 integrin alphaMbeta2 on monocytes; evidence concerns the alphaM chain and heterodimer, not beta2 alone.","interaction_type":"direct binding","direction_and_effect":"Monocyte adhesion to Cyr61 (CCN1) was mediated primarily through integrin alphaMbeta2 [PMID:12036876]. Adhesion to the CCN1 H2 peptide was blocked by anti-alphaM mAb, and GST-alphaMI bound it [PMID:12736251].","molecular_requirements":"Binding was shown through the alphaM I-domain, so beta2 acts as the partner chain of alphaMbeta2; beta2 alone is not tested. HSPGs act as co-receptors [PMID:12036876].","affinity_potency":[],"species_and_systems":"Human THP-1 cells, monocytes and HEK293 transfectants; human CCN1. Mouse pair is ortholog-inferred.","localisation_and_range":"CCN1 is flagged secreted [flag] but described in the papers as matrix-associated, so adhesion-type contact with receptors on neighbouring cells is plausible.","caveats":"Chain-only evidence: the binding site is on alphaM, not beta2. Both papers abstract only. No affinity reported. Treat as the alphaMbeta2 complex when scoring.","key_references":[{"PMID":"12036876","why":"alphaMbeta2 as CCN1 monocyte adhesion receptor"},{"PMID":"12736251","why":"alphaM I-domain binding mapped to CCN1 H2 peptide"}],"covers":["LR000422","LR003919"]},"LR005575":{"pair":"CCN2 -> ITGB1","headline":"CTGF acts through an ITGB1-TrkA receptor complex in glioma stem cells; abstract-level, complex rather than ITGB1 alone.","interaction_type":"functional only","direction_and_effect":"In patient-derived glioma tumour-initiating cells, CTGF binding to ITGB1-TrkA receptor complexes led to NF-kappaB activation (relative luciferase activity 0.53 untreated vs 1.87 with CTGF 200 ng/mL), agonist effect [PMID:21771732]. ITGB1/TrkA inhibitors and CTGF shRNA reduced infiltration in vitro and in xenografts [PMID:21771732].","molecular_requirements":"The reported receptor is an ITGB1-TrkA (NTRK1) complex; the paper used inhibitors rather than showing ITGB1 alone is sufficient [PMID:21771732]. The integrin alpha partner is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Patient-derived human glioma stem-like cells and orthotopic mouse xenografts [PMID:21771732].","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers. In the paper, reactive astrocytes secrete CTGF [PMID:21771732].","caveats":"Abstract read only. Curators labelled the assay as direct_binding, but the abstract shows binding to a receptor complex inferred from signalling and inhibitor studies. No affinity reported.","key_references":[{"PMID":"21771732","why":"CTGF signalling via ITGB1-TrkA complex in glioma cells"}],"covers":["LR002274","LR005575"]},"LR003892":{"pair":"CCN2 -> LRP6","headline":"CTGF is reported to bind the Wnt co-receptor LRP6 and to regulate Wnt signalling in Xenopus; abstract-level.","interaction_type":"functional only","direction_and_effect":"CTGF regulates signalling through the Wnt pathway in Xenopus embryos, in accord with its ability to bind LRP6 [PMID:15105373]. Whether it enhances or inhibits Wnt signalling is not stated in our evidence.","molecular_requirements":"The interaction likely involves the C-terminal domain of CTGF, which is distinct from its BMP4- and TGF-beta-interacting domain [PMID:15105373].","affinity_potency":[],"species_and_systems":"Xenopus embryos for function; binding species not specified beyond human recombinant annotation by the curators [PMID:15105373]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers.","caveats":"Abstract read only. Binding is stated but its assay is not described in our evidence; domain assignment is 'likely' only. LRP6 is a co-receptor, so a ligand role is not established.","key_references":[{"PMID":"15105373","why":"CTGF binding to LRP6 and Wnt regulation in Xenopus"}],"covers":["LR000386","LR003892"]},"LR005584":{"pair":"Cd24a -> Siglecg","headline":"Evidence is thin: CD24 association with Siglec-G in mice is stated in one abstract; the second paper concerns Siglec-10.","interaction_type":"functional only","direction_and_effect":"CD24 association with Siglec-G in mice inhibits NF-kappaB and protects against lethal responses to danger signals, at least in part [PMID:19264983].","molecular_requirements":"Not reported in our evidence beyond the CD24-Siglec-G association.","affinity_potency":[],"species_and_systems":"CD24-deficient mice, read as abstract only [PMID:19264983].","localisation_and_range":"CD24 is flagged not secreted; Siglecg flagged both secreted and receptor [flag].","caveats":"Association is stated, not directly measured, and only 'at least in part'. The other curated paper concerns human Siglec-10 on tumour-associated macrophages, not Siglec-G [PMID:31367043]. No affinity.","key_references":[{"PMID":"19264983","why":"CD24-Siglec-G pathway in CD24-deficient mice"}],"covers":["LR005584"]},"LR003793":{"pair":"CD34 -> SELP","headline":"Human CD34 on HSPCs is described as a major vascular selectin ligand; single abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"CD34-positive HSPC fractions bound E- and P-selectin whereas CD34-negative ones did not; a proteomics screen identified CD34 as a major vascular selectin ligand [PMID:29296932].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HSPC-enriched fractions [PMID:29296932]; mouse pair projected from human.","localisation_and_range":"CD34 flagged transmembrane, not secreted; SELP membrane-bound [flag].","caveats":"Abstract only; selectin results are pooled for E- and P-selectin and no P-selectin-specific data appear in the abstract. IntAct solid-phase record also exists [DB:IntAct]. No affinity reported.","key_references":[{"PMID":"29296932","why":"CD34 as vascular selectin ligand on HSPCs"}],"covers":["LR000283","LR003793"]},"LR005089":{"pair":"CD48 -> CD2","headline":"Cell-surface adhesion pair supported by force measurements, a cell-binding assay and curated database records; binding is low-affinity.","interaction_type":"direct binding","direction_and_effect":"CD48 is a ligand of CD2 and the bond mediates adhesion; the CD48 interaction with the T11(1) region of CD2 was reported to be the same region that binds CD58, and CD48 binds CD2 with about 100-fold lower affinity than CD58 [PMID:7691954]. Direct force measurements describe a low-affinity bond that gives weak adhesion [PMID:12356317].","molecular_requirements":"Full-length extracellular domains adhere head-to-head; lateral receptor mobility is required for appreciable adhesion [PMID:12356317]. Extra evidence: an engineered CD2 showed about threefold higher CD48-binding affinity than wild type [PMID:18287277].","affinity_potency":[],"species_and_systems":"Force measurements used murine CD2 and CD48 [PMID:12356317]. Cell binding used human PBL and human CD48-transfected COS cells, with multimeric rCD2 binding CD48 transfectants [PMID:7691954]. The human pair is ortholog-inferred in the dossier; the mouse pair is listed directly.","localisation_and_range":"Both are cell-surface proteins; adhesion is between cells (contact-dependent) [PMID:12356317][PMID:7691954]. Annotation flags mark CD48 as both secreted and transmembrane, so the flag does not settle range [flag].","caveats":"All three confirming papers were read as abstracts only. No numeric affinity is given. The PMID 18287277 result is a protein-engineering paper that uses wild-type CD2-CD48 binding only as the baseline. A BioGRID record (reconstituted complex) and UniProt text also support the pair [DB:BioGRID][DB:UniProt].","key_references":[{"PMID":"7691954","why":"Human cell binding plus blocking mAbs; CD48 and CD58 compete for CD2"},{"PMID":"12356317","why":"Direct force measurement of murine CD2-CD48 adhesion"}],"covers":["LR001722","LR005089"]},"LR005593":{"pair":"CD5 -> CD5","headline":"Homophilic CD5 binding is shown by SPR with soluble protein; weak, species-specific and apparently inhibitory.","interaction_type":"direct binding","direction_and_effect":"CD5 binds CD5 homophilically; engagement of human CD5 domain 1 appears inhibitory, since blocking it by mutation or CD5 mAb increased antigen-specific mouse T cell responses [PMID:20952682].","molecular_requirements":"Only CD5 domain 1 is involved; human CD5 domain 1 is necessary and dominant for the interaction in chimaera experiments [PMID:20952682]. Protein purified at pH 2.5 lost specificity, so purification at neutral pH matters [PMID:20952682].","affinity_potency":[],"species_and_systems":"SPR at 37 C with His-tagged soluble human, rat and mouse CD5 on CD5CD4 fusion chips; human CD5 binds only human CD5, while mouse and rat CD5 cross-react [PMID:20952682]. The mouse pair is ortholog-inferred.","localisation_and_range":"Soluble extracellular region binding; annotation flags mark CD5 as secreted [flag]. Cell-surface homophilic contact is implied by the authors' framing but not shown in the excerpts.","caveats":"Interaction is weak with rapid dissociation and no affinity value is given [PMID:20952682]. Only one of two confirmed papers is displayed. A UniProt record concerns CD5 signalling and not this binding [DB:UniProt].","key_references":[{"PMID":"20952682","why":"SPR shows species-specific homophilic CD5 binding via domain 1"}],"covers":["LR002294","LR005593"]},"LR005098":{"pair":"CD86 -> CTLA4","headline":"CD86 engages CTLA-4 and is removed by CTLA-4 transendocytosis; supported by functional papers and structures, read mostly as abstracts.","interaction_type":"functional only","direction_and_effect":"CTLA-4 takes up CD86 by transendocytosis; with CD86 CTLA-4 detaches in a pH-dependent manner and recycles to the surface [PMID:35999394]. Blocking CTLA-4 with antibodies enhanced human T-cell activation in CD80- or CD80/CD86-dependent assays, i.e. the interaction is inhibitory [PMID:10583602]. UniProt describes CTLA4 as a decoy receptor that binds CD80 and CD86 more strongly than CD28 [DB:UniProt].","molecular_requirements":"CD86 and CD80 are both ligands of CTLA-4; the dossier does not report subunit requirements beyond the CTLA-4 cytoplasmic domain and lysines in the CD80 ubiquitylation experiments [PMID:35999394].","affinity_potency":[],"species_and_systems":"Transendocytosis experiments used human cells (CHO transfectants, Jurkat, primary Treg) [PMID:35999394]; the other paper used human T cells [PMID:10583602]. The mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are membrane proteins; contact-dependent (transendocytosis between cells) [PMID:35999394].","caveats":"Both papers read as abstract only for the curator judgement. Physical binding is supported by database structure/binding records (PDB 1I85, BioGRID, IntAct) rather than by the papers shown [DB:PDB 1I85] [DB:BioGRID].","key_references":[{"PMID":"35999394","why":"CD86 vs CD80 transendocytosis and CTLA-4 recycling"},{"PMID":"10583602","why":"CTLA-4 blockade enhances human T-cell activation"}],"covers":["LR001733","LR005098"]},"LR008851":{"pair":"CD9 -> ADAM2","headline":"CD9 on mouse eggs is needed for sperm ADAM2 (fertilin beta) binding via alpha6beta1; indirect, antibody-based evidence only.","interaction_type":"functional only","direction_and_effect":"Anti-CD9 mAb JF9 inhibited sperm-egg binding and fusion in vitro in a dose-dependent manner and disrupted binding of fertilin-coated beads to eggs [PMID:10518536].","molecular_requirements":"CD9 associates with the egg integrin alpha6beta1, which engages ADAM2; the effect is through alpha6beta1, so this is a co-receptor dependency, not a bimolecular pair [PMID:10518536].","affinity_potency":[],"species_and_systems":"Mouse eggs and oocytes, in vitro [PMID:10518536].","localisation_and_range":"Membrane-bound on the egg; sperm-egg contact.","caveats":"Abstract only; no direct CD9-ADAM2 binding shown; no database records.","key_references":[{"PMID":"10518536","why":"Anti-CD9 blocks sperm-egg binding and fertilin bead binding"}],"covers":["LR008851"]},"LR002299":{"pair":"CDCP1 -> CD6","headline":"CDCP1 (CD318) is reported as a CD6 ligand; one paper with KO mice and human synovium, one cancer paper.","interaction_type":"direct binding","direction_and_effect":"CD318 was identified as a CD6 ligand; CD318 KO mice are protected in EAE like CD6 KO mice, and CD318 participates in CD6-dependent adhesion of T cells to synovial fibroblasts [PMID:28760953]. CDCP1 binds CD6 and inhibits JAK-STAT in T cells, reducing CTL activity [PMID:39455095].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse KO and human synovial tissue and cells (species not stated for the binding itself) [PMID:28760953]; human cervical cancer and mouse tumour models [PMID:39455095].","localisation_and_range":"CDCP1 is annotated as secreted [flag]; soluble CD318 is chemoattractive to T cells and elevated in arthritis synovial fluid [PMID:28760953].","caveats":"Both papers read as abstract with limited excerpts; no database records. The second paper's binding evidence is a one-line statement [PMID:39455095].","key_references":[{"PMID":"28760953","why":"Identifies CD318 as CD6 ligand"},{"PMID":"39455095","why":"CDCP1-CD6 inhibits JAK-STAT in T cells"}],"covers":["LR002299","LR005597"]},"LR006844":{"pair":"CEACAM5 -> CEACAM6","headline":"Database-only evidence from IntAct protein array; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper. IntAct records physical association by protein array [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Both annotated secreted and transmembrane [flag].","caveats":"Two papers judged as a different entity; interaction class is Adhesion-Adhesion. High-throughput protein array only.","key_references":[],"covers":["LR006844"]},"LR007960":{"pair":"CHL1 -> L1CAM","headline":"Database-only support: an IntAct SPR record between CHL1 and L1CAM; no curated paper confirmation.","interaction_type":"database-asserted only","direction_and_effect":"Direction not reported in our evidence; classed adhesion-adhesion [flag].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct record from the PMID 35922511 surface plasmon resonance screen [DB:IntAct]; human proteins.","localisation_and_range":"Both flagged secreted, receptor and transmembrane [flag].","caveats":"No confirmed papers; judged papers were abstract_insufficient or a different entity. Support rests on one database record.","key_references":[],"covers":["LR007960"]},"LR005629":{"pair":"CKLF -> CCR4","headline":"CKLF1 acts as a functional, non-canonical CCR4 agonist in one human transfected-cell study; no direct binding measurement reported.","interaction_type":"functional only","direction_and_effect":"CKLF1 induced chemotaxis and calcium flux in CCR4-transfected cells, with cross-desensitisation of TARC/CCL17 responses, consistent with agonism at CCR4 [PMID:16137713]. Desensitisation was asymmetric: CKLF1 fully desensitised a later TARC/CCL17 response, but TARC/CCL17 only partly desensitised CKLF1 [PMID:16137713]. Pertussis toxin abolished chemotaxis, indicating Gi/o coupling [PMID:16137713].","molecular_requirements":"CCR4 alone in transfected cells was sufficient; no co-receptor requirement is reported in our evidence. CCR6-transfected cells did not respond to CKLF1 [PMID:16137713].","affinity_potency":[],"species_and_systems":"Human CKLF1 and human CCR4 in transfected HEK293 cells; the mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"CKLF is flagged secreted and CCR4 a transmembrane receptor [flag]; secreted ligand acting on a membrane receptor.","caveats":"Single primary paper; functional readouts only, no binding affinity. UniProt also lists CKLF as binding CCR4, citing the same paper [DB:UniProt]. Mouse evidence is not independent.","key_references":[{"PMID":"16137713","why":"Chemotaxis, calcium flux and desensitisation showing CKLF1 is a CCR4 agonist"}],"covers":["LR002346","LR005629"]},"LR005638":{"pair":"CLU -> LRP8","headline":"Clusterin binds ApoER2 and triggers a Reelin-like signal; one abstract-only paper, no affinity.","interaction_type":"direct binding","direction_and_effect":"Clusterin binds ApoER2 (LRP8) and VLDLR and is internalized by cells expressing either; binding triggers a Reelin-like signal in Dab1-expressing cells, inducing Dab1 phosphorylation and activation of PI3K/Akt and n-cofilin [PMID:24381170]. Agonist-like.","molecular_requirements":"Dab1 is needed for the signal in the described cells; either receptor alone was sufficient for internalization [PMID:24381170].","affinity_potency":[],"species_and_systems":"Species not specified in the dossier abstract; cell lines and subventricular zone explants [PMID:24381170]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Clusterin is flagged secreted [flag]; present in the subventricular zone where Reelin is absent [PMID:24381170], so paracrine.","caveats":"Abstract only; affinity not reported. UniProt records the interaction citing the same paper [DB:UniProt P10909]. Because both pairs rely on one paper, they are not independent.","key_references":[{"PMID":"24381170","why":"Clusterin binds ApoER2/VLDLR and activates the Reelin pathway"}],"covers":["LR002358","LR005638"]},"LR005647":{"pair":"CNTN2 -> NCAM1","headline":"No curator-confirmed paper; only a Reactome complex record.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence; Reactome lists an NCAM1-Contactin-2 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Species not stated beyond human and mouse entities.","localisation_and_range":"CNTN2 flagged secreted; NCAM1 flagged secreted and transmembrane [flag].","caveats":"Eight judged papers were all abstract_insufficient; support is a database assertion only.","key_references":[],"covers":["LR002367","LR005647"]},"LR005656":{"pair":"COL11A2 -> ITGA2","headline":"Only a cell-based report that integrin a2b1/DDR2 bind collagen XI; abstract-level and not chain-specific for COL11A2.","interaction_type":"functional only","direction_and_effect":"Integrin a2b1 and DDR2, but not a11b1, mediated high-affinity binding of cancer-associated fibroblasts to collagen type XI [PMID:36233024].","molecular_requirements":"The a2b1 heterodimer is what the paper names [PMID:36233024].","affinity_potency":[],"species_and_systems":"CAFs; species not reported in our evidence [PMID:36233024]. The human pair is ortholog-inferred.","localisation_and_range":"COL11A2 is annotated secreted and not transmembrane [flag].","caveats":"Abstract-only; the paper says collagen type XI without naming a chain, and does not isolate individual integrin subunits [PMID:36233024].","key_references":[{"PMID":"36233024","why":"Integrin a2b1 and DDR2 binding to collagen XI in CAFs"}],"covers":["LR002377","LR005656"]},"LR003829":{"pair":"COL1A1 -> DDR1","headline":"DDR1 is a collagen-activated receptor tyrosine kinase; type I collagen binds and activates it in three papers.","interaction_type":"direct binding","direction_and_effect":"Type I collagen bound DDR1-Fc by slot blot, with binding detectable at 3 mg loading [PMID:9659900]. Collagen types I, III, IV and V induced DDR1b tyrosine phosphorylation in 293 cells, an agonist effect needing native triple-helical collagen [PMID:9659899]. Collagen I also stimulated saturable DDR1 ectodomain shedding in carcinoma and transfected cells, reduced by a Src inhibitor [PMID:16440311].","molecular_requirements":"Receptor activation requires the native triple-helical structure of collagen; denatured collagen did not activate [PMID:9659899]. Collagen type I is the COL1A1/COL1A2 heterotrimer, so the evidence is not chain-specific (curator note).","affinity_potency":[],"species_and_systems":"Bovine dermal and human or mouse collagen I with human DDR1 in 293 cells and T-47D cells [PMID:9659900] [PMID:9659899]; species for the shedding paper not reported [PMID:16440311].","localisation_and_range":"Receptor is a membrane-bound tyrosine kinase; collagen is matrix, so signalling is by contact.","caveats":"Binding was slower to detect for DDR1 than DDR2 and activation required prolonged stimulation [PMID:9659900] [PMID:9659899]. The shedding paper was read as an abstract only. No affinity reported.","key_references":[{"PMID":"9659900","why":"Collagen I binds DDR1 and DDR2 Fc proteins"},{"PMID":"9659899","why":"Collagens activate DDR1 and DDR2 phosphorylation"},{"PMID":"16440311","why":"Collagen I triggers DDR1 ectodomain shedding"}],"covers":["LR000323","LR003829"]},"LR005665":{"pair":"COL1A2 -> DDR1","headline":"Type I collagen binds and activates DDR1; direct binding and phosphorylation shown in 1997 full-text papers.","interaction_type":"direct binding","direction_and_effect":"Collagen I induces DDR1 phosphorylation as an agonist [PMID:9659899] and stimulates DDR1 ectodomain shedding [PMID:16440311].","molecular_requirements":"Receptor activation requires native triple-helical collagen per the abstract [PMID:9659899]. DDR1 binding to type I collagen was detectable but needed more material than DDR2 (3 vs 1 mg loaded) [PMID:9659900].","affinity_potency":[],"species_and_systems":"Radiolabelled DDR1-Fc binding to bovine dermal collagen I [PMID:9659900]; mouse tail collagen on 293 cells transfected with DDR1b [PMID:9659899]; carcinoma and transfected cells, species unspecified [PMID:16440311].","localisation_and_range":"COL1A2 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"PMID:16440311 read as abstract only. Collagen I is a heterotrimer; chain-level contribution of COL1A2 not reported. Two other judged rows were review_only.","key_references":[{"PMID":"9659900","why":"Slot-blot binding of DDR1 to collagen I"},{"PMID":"9659899","why":"Collagen activates DDR1 phosphorylation"},{"PMID":"16440311","why":"Collagen I induces DDR1 shedding"}],"covers":["LR002386","LR005665"]},"LR003838":{"pair":"COL1A2 -> ITGA11","headline":"Integrin alpha11 (as alpha11beta1) binds collagen type I-Sepharose in one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"alpha11beta1 bound collagen type I-Sepharose [PMID:10464311]. Annotated effect is stimulatory.","molecular_requirements":"The binder shown is the alpha11beta1 heterodimer, not ITGA11 alone [PMID:10464311].","affinity_potency":[],"species_and_systems":"Human alpha11 integrin, muscle cells [PMID:10464311].","localisation_and_range":"COL1A2 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"Abstract-only. Ligand is collagen I heterotrimer; COL1A2 not isolated. No database support.","key_references":[{"PMID":"10464311","why":"alpha11beta1 binds collagen type I-Sepharose"}],"covers":["LR000332","LR003838"]},"LR006916":{"pair":"COL26A1 -> ITGA2:ITGB1","headline":"No papers support this pair in our evidence; a PDB structure of the integrin alpha2 I domain with a collagen is the only record.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond a structural record: PDB 4BJ3 (X-ray diffraction) is an 'Integrin alpha2 I domain E318W-collagen complex' containing a chain of Q96A83 and a chain of P17301 [DB:PDB 4BJ3]. Effect and direction are not reported in our evidence.","molecular_requirements":"The structure covers only the integrin alpha2 I domain (engineered E318W) [DB:PDB 4BJ3]. Whether ITGB1 is required is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant structure; species not reported in our evidence.","localisation_and_range":"COL26A1 is flagged secreted and not transmembrane [flag]; interaction class is 'Adhesion-Adhesion', not ligand-receptor.","caveats":"Rests on a database record alone. All four judged papers were review-only; no primary paper confirmed binding. The collagen in the structure is not identified in the dossier beyond the accession.","key_references":[],"covers":["LR006916"]},"LR002389":{"pair":"COL2A1 -> DDR2","headline":"Collagen II directly binds and activates DDR2 via the discoidin domain, shown in two independent biochemical papers; mouse pair is projected.","interaction_type":"direct binding","direction_and_effect":"Collagen II is a much better ligand for DDR2 than for DDR1 and strongly stimulated DDR2 autophosphorylation, requiring triple-helical collagen [PMID:15544808]. Effect: agonist (receptor activation).","molecular_requirements":"Binding is mediated by the DDR2 discoidin domain and needs triple-helical collagen; the D2 period of collagen II is essential, D3 and D4 dispensable [PMID:15544808]. An NMR/transferred cross-saturation study mapped the collagen-binding site on the DDR2 discoidin domain [PMID:17703188].","affinity_potency":[],"species_and_systems":"Human DDRs, recombinant collagen II variants [PMID:15544808]; mouse pair is ortholog-inferred from human evidence.","localisation_and_range":"COL2A1 is flagged secreted, DDR2 is a cell-surface receptor kinase; contact with matrix collagen (inferred from flags and abstracts).","caveats":"Abstract read only for both. A third paper, PMID:9659900, was judged pair_absent: it never tested collagen II against DDRs (full text), so it is a missing test rather than a negative result. The SPR sentence from PMID:17703188 was a browser read still awaiting spot-check.","key_references":[{"PMID":"15544808","why":"Collagen II D2 period binds and activates DDR2"},{"PMID":"17703188","why":"DDR2 discoidin domain structure and collagen-binding site"}],"covers":["LR002389","LR005668"]},"LR003856":{"pair":"COL4A3 -> ITGAV","headline":"Tumstatin/alpha3NC1 binds integrin alphaVbeta3 in two papers; one binding paper, one mouse genetics.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha3NC1 binds alphaVbeta3 and alphaVbeta5 predominantly via its RGD site [PMID:14610079]; tumstatin's suppression of pathological angiogenesis requires alphaVbeta3 [PMID:12842087].","molecular_requirements":"The receptor is the alphaV:beta3 heterodimer [PMID:14610079]. The active form is the NC1 domain / tumstatin fragment, not intact COL4A3 [PMID:12842087].","affinity_potency":[],"species_and_systems":"Recombinant human domain in HEK293 and endothelial adhesion [PMID:14610079]; Col4a3- and Mmp9-knockout mouse tumour models [PMID:12842087].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Both papers abstract only. Non-RGD peptides were about 10-fold less potent than native protein [PMID:14610079]. Functional paper does not show direct binding.","key_references":[{"PMID":"14610079","why":"alphaVbeta3/beta5 bind RGD site of alpha3NC1"},{"PMID":"12842087","why":"Tumstatin requires alphaVbeta3 in mouse angiogenesis"}],"covers":["LR000350","LR003856"]},"LR003865":{"pair":"COL5A1 -> SDC3","headline":"Likely mis-assigned: syndecan-3 binding is to the alpha4(V) chain N-terminal domain in rat cells.","interaction_type":"direct binding","direction_and_effect":"Syndecan-3 was isolated by affinity chromatography on immobilised alpha4(V) N-terminal domain, supporting Schwann cell adhesion [PMID:11751872].","molecular_requirements":"Binding depends on a heparan sulfate / heparin-binding region of alpha4(V)-NTD absent in other type V collagen NTDs [PMID:11751872].","affinity_potency":[{"value":"IC50 ~30 ng/ml","assay":"heparin inhibition of Schwann cell adhesion","system":"rat Schwann cells on alpha4(V)-NTD","cite":"PMID:11751872"}],"species_and_systems":"Rat Schwann cells [PMID:11751872]; human and mouse pairs are projections.","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"The relevant chain is alpha4(V), not COL5A1; heparin inhibited adhesion with IC50 ~30 ng/ml [PMID:11751872]. Abstract only.","key_references":[{"PMID":"11751872","why":"Schwann cell syndecan-3 binds alpha4(V) NTD"}],"covers":["LR000359","LR003865"]},"LR006970":{"pair":"COL6A1 -> ITGA10:ITGB1","headline":"Weak: one abstract reports COL6A1 binding ITGB1 in glioblastoma; the alpha subunit is not named.","interaction_type":"functional only","direction_and_effect":"COL6A1 is bound to ITGB1 on endothelial cells, disrupting tight junctions via UBD-mediated claudin-5 degradation [PMID:41297453].","molecular_requirements":"The paper names only ITGB1, not the alpha partner, so ITGA10:ITGB1 is not distinguished from other beta1 heterodimers [PMID:41297453].","affinity_potency":[],"species_and_systems":"Human patient-derived glioblastoma organoids and endothelial cells [PMID:41297453].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Abstract only; the binding wording is an abstract statement. No affinity reported. Other rows were review_only or abstract_insufficient.","key_references":[{"PMID":"41297453","why":"COL6A1 binds endothelial ITGB1 in TMZ-resistant glioblastoma"}],"covers":["LR006970"]},"LR001759":{"pair":"COMP -> CD47","headline":"COMP-mediated cell attachment depends on CD47 in one functional study; direct binding not demonstrated.","interaction_type":"functional only","direction_and_effect":"A function-blocking anti-CD47 antibody reduced ligament-cell attachment to COMP to background levels at 25 \u03bcg/ml; attachment is inhibited by an SFYVVMWK peptide from COMP's C-terminal domain, independent of RGD-dependent attachment [PMID:20033473].","molecular_requirements":"CD47 acts alongside alphaVbeta3 integrin as a parallel, independent attachment mechanism [PMID:20033473].","affinity_potency":[],"species_and_systems":"Ligament cells and human fetal chondrocytes attached to recombinant COMP; ligament cell species is not stated in the excerpts [PMID:20033473].","localisation_and_range":"COMP is an extracellular matrix protein per the paper, and carries a secreted flag [flag][PMID:20033473]; CD47 is a transmembrane receptor by flag [flag]; matrix-to-cell contact.","caveats":"The authors state a direct interaction between COMP and CD47 has yet to be demonstrated and other proteins may be involved [PMID:20033473]. Reactome lists the binding reaction (COMP binds Integrin alpha5beta1, alphaVbeta3, CD47) [DB:Reactome R-HSA-2426259]. One paper, abstract-level curation.","key_references":[{"PMID":"20033473","why":"Anti-CD47 antibody blocks cell attachment to COMP"}],"covers":["LR001759","LR005117"]},"LR003874":{"pair":"CORT -> SSTR2","headline":"Cortistatin binds SSTR2 with high affinity in two recombinant-receptor binding papers, plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"Human cortistatin-17 bound all human SSTR subtypes much like rat CST-14 and inhibited forskolin-induced cAMP production through SSTRs [PMID:9125122]. [125I]Tyr10-CST bound all five receptors with high affinity and no marked selectivity versus somatostatin [PMID:9650799]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor reported in our evidence.","affinity_potency":[{"value":"pKd 9.45","assay":"[125I]Tyr10-CST radioligand binding","system":"human sst2 stably expressed in CCL39 cells","cite":"PMID:9650799"},{"value":"pKi 8.8-9.3","assay":"GtoPdb full agonist","system":"not reported","cite":"PMID:15333679"}],"species_and_systems":"Human receptors in CCL39 cells [PMID:9650799]; human peptide on human SSTRs [PMID:9125122]; mouse pair ortholog-inferred.","localisation_and_range":"CORT secreted and SSTR2 transmembrane by flags [flag].","caveats":"Abstract-level reads; pan-SSTR binding, so not subtype-specific, and the radioligand is an iodinated CST14 analogue [PMID:9650799]. One further paper pending.","key_references":[{"PMID":"9650799","why":"Binding of cortistatin to all five human SSTRs, pKd values"},{"PMID":"9125122","why":"Human cortistatin binds all SSTR subtypes and lowers cAMP"}],"covers":["LR000368","LR003874"]},"LR003883":{"pair":"CSF2 -> CSF2RB","headline":"GM-CSF contacts the common beta chain only together with the alpha chain; supported by mutagenesis and kinetics.","interaction_type":"direct binding","direction_and_effect":"Betac interacts directly with GM-CSF during formation of the high-affinity receptor [PMID:8278375]. Betac residues Tyr365, His367 and Ile368 are required for GM-CSF and IL-5 but not IL-3 high-affinity binding, and interact with Glu21 of GM-CSF [PMID:7957082]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"Betac alone has no detectable cytokine-binding activity; interaction occurs only in the presence of the alpha chain, which GM-CSF needs [PMID:8278375]. GMRbeta facilitates ligand acquisition (higher k(on) for alpha/beta than alpha) [PMID:10572088]. Betac is shared with IL-3 and IL-5 receptors [PMID:7957082].","affinity_potency":[],"species_and_systems":"Human proteins; mutagenesis and binding assays with radiolabelled cytokines [PMID:7957082]. Mouse pair is ortholog-inferred.","localisation_and_range":"Not reported in our evidence beyond the ligand secreted annotation [flag].","caveats":"Abstracts only. Betac is not a standalone GM-CSF receptor, so a CSF2->CSF2RB edge should be read as part of the alpha/beta complex. Rows 10572088 list species unspecified. Two papers were abstract_insufficient and one pending.","key_references":[{"PMID":"8278375","why":"His-367 of betac critical for high-affinity GM-CSF binding"},{"PMID":"7957082","why":"Betac residues interacting with Glu21 of GM-CSF"},{"PMID":"10572088","why":"Kinetic role of beta in high-affinity binding"}],"covers":["LR000377","LR003883"]},"LR006826":{"pair":"CSH1 -> PRLR","headline":"Placental lactogen binds the prolactin receptor in a crystal structure, but the structure used ovine and rat proteins, so human CSH1 itself is not directly shown.","interaction_type":"direct binding","direction_and_effect":"Two rat prolactin receptor extracellular domains bind opposite sides of one ovine placental lactogen [PMID:10966654]. GtoPdb lists CSH1-PRLR as agonist; curators label the effect stimulatory [DB:GtoPdb].","molecular_requirements":"The complex has a 1:2 ligand:receptor stoichiometry with two distinct binding sites on the ligand [PMID:10966654].","affinity_potency":[],"species_and_systems":"Ovine ligand with rat receptor ectodomain, purified proteins, X-ray crystallography [PMID:10966654]; no human experiment reported in our evidence.","localisation_and_range":"Not reported in our evidence; receptor annotated transmembrane [flag].","caveats":"Single paper, abstract only, from other species than the pair. Reactome binding reaction covers prolactin receptor ligands generally [DB:Reactome R-HSA-976991].","key_references":[{"PMID":"10966654","why":"Ovine placental lactogen/rat PRLR ternary complex"}],"covers":["LR006826"]},"LR005728":{"pair":"CTLA4 -> CD86","headline":"CTLA4 targets CD86 for transendocytosis; co-crystal structure and database support; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"CTLA-4 removes CD86 from donor cells by transendocytosis; with CD86, CTLA-4 detaches pH-dependently and recycles to the cell surface to permit further transendocytosis [PMID:35999394]. UniProt describes CTLA4 as a decoy receptor binding CD80 and CD86 more strongly than CD28 [DB:UniProt].","molecular_requirements":"Autoimmune-disease mutations selectively disrupt CD86 transendocytosis by affecting CTLA-4 recycling or CD86 binding [PMID:35999394]. A co-crystal structure exists [DB:PDB 1I85].","affinity_potency":[],"species_and_systems":"CHO cells, Jurkat T cells and human Treg cells [PMID:35999394]; mouse pair ortholog-inferred.","localisation_and_range":"Both partners flagged receptor/transmembrane [flag]; transendocytosis requires cell-cell contact between donor and CTLA-4 recipient cells [PMID:35999394].","caveats":"Paper's assay is functional (transendocytosis), not a binding measurement; its curated direction label is agonist although CTLA-4 acts here as a ligand-removing inhibitory receptor. No affinity in our evidence.","key_references":[{"PMID":"35999394","why":"CD86 transendocytosis by CTLA-4 with recycling"}],"covers":["LR002452","LR005728"]},"LR007168":{"pair":"CTSG -> F2RL3","headline":"Database-asserted only: UniProt links cathepsin G to PAR4-mediated platelet activation; three papers pending, none verified.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says cathepsin G is required for recruitment and activation of platelets mediated by the F2RL3/PAR4 receptor [DB:UniProt]; annotated stimulatory.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"CTSG flagged secreted [flag].","caveats":"No judged papers: three are pending. Support rests on UniProt only [DB:UniProt]. A paper on the F2R pair mentions aggregation via PAR4 at higher cathepsin G, but it is not judged for this pair.","key_references":[],"covers":["LR007168"]},"LR005737":{"pair":"CXCL12 -> GPR17","headline":"One abstract-only 2016 paper reports SDF-1 activating GPR17 in vitro with cangrelor blockade, supported by in silico modelling.","interaction_type":"functional only","direction_and_effect":"SDF-1 activated GPR17 in a reference GPCR pharmacological assay and a primary oligodendrocyte precursor maturation model; the orthosteric antagonist cangrelor blocked the activation concentration-dependently [PMID:26971834]. Effect is agonist.","molecular_requirements":"Not reported in our evidence; GPR17 acts as a single chain. In silico modelling was used to study the recognition mechanism [PMID:26971834].","affinity_potency":[],"species_and_systems":"Species labelled human for both partners by the curator; the abstract does not name the species. Primary oligodendrocyte precursors were used [PMID:26971834]. The mouse pair is projected.","localisation_and_range":"CXCL12 is flagged secreted [flag].","caveats":"Abstract only; no binding measurement or affinity reported. A single paper, with no independent replication in our evidence.","key_references":[{"PMID":"26971834","why":"Only paper: SDF-1 activates GPR17, blocked by cangrelor"}],"covers":["LR002463","LR005737"]},"LR001768":{"pair":"CXCL12 -> ITGA4","headline":"One abstract-only 2018 paper: CXCL12 binds integrin allosteric site 2 and activates integrin alpha4beta1 independently of CXCR4.","interaction_type":"direct binding","direction_and_effect":"Integrin activation was shown by direct binding to the allosteric site 2: SDF1 activated soluble integrin alphavbeta3 in cell-free conditions and the site 2 peptide bound SDF1 [PMID:29301984]. SDF1 activated integrin alpha4beta1 on CXCR4-negative CHO cells, suppressed by site 2 peptide and not by AMD3100 [PMID:29301984]. Effect is activating. UniProt agrees [DB:UniProt].","molecular_requirements":"The binding unit appears to be the alpha/beta heterodimer, not ITGA4 alone; the paper tested alphavbeta3, alpha4beta1 and alpha5beta1 [PMID:29301984]. Proteoglycan binding of SDF1 is proposed to facilitate activation. Mutations in SDF1's predicted site 2 binding region suppressed activation.","affinity_potency":[],"species_and_systems":"Cell-free soluble integrin and CHO cells; species labelled human by the curator, not stated in the abstract. The mouse pair is projected from human.","localisation_and_range":"CXCL12 is flagged secreted [flag]; activation was proposed for SDF1 presented on proteoglycans [PMID:29301984].","caveats":"Abstract only; one paper from one group; no affinity reported. Receptor is a heterodimer and CCC tools may score subunits separately.","key_references":[{"PMID":"29301984","why":"Only paper: CXCL12 site 2 integrin activation"}],"covers":["LR001768","LR005125"]},"LR005746":{"pair":"CXCL9 -> ACKR1","headline":"CXCL9 binds the Duffy antigen (ACKR1) weakly on human erythrocytes; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"CXCL9 displaced 125I-CXCL8 from human erythrocytes with Ki 162.0 nM, in the paper's weak-binding class (Ki 100 nM-1 microM) [PMID:15358176]. Direction/signalling is not reported; ACKR1 is an atypical receptor and effect on signalling is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 162.0 nM","assay":"125I-CXCL8 competition displacement binding","system":"human erythrocytes","cite":"PMID:15358176"}],"species_and_systems":"Human erythrocytes with human chemokine [PMID:15358176]. The mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Only one paper; affinity is markedly weaker than the strong binders in that study. The stored evidence sentence is a fragment and does not itself name CXCL9; the Ki comes from the curator's assay detail.","key_references":[{"PMID":"15358176","why":"Duffy antigen chemokine binding panel, Ki 162.0 nM"}],"covers":["LR002472","LR005746"]},"LR007177":{"pair":"CXCL9 -> DPP4","headline":"No curator-verified evidence that CXCL9 acts through DPP4; only a database enzymatic record.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. No confirmed papers; the only record is an IntAct enzymatic study [DB:IntAct], which suggests DPP4 as a protease acting on CXCL9, not a signalling receptor.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"DPP4 is a flagged transmembrane receptor [flag]; no ligand-receptor localisation evidence.","caveats":"One review-only and two abstract-insufficient papers; none confirmed. Support is an IntAct enzymatic study only [DB:IntAct]. Probably an enzyme-substrate relation rather than a ligand-receptor pair.","key_references":[],"covers":["LR007177"]},"LR002479":{"pair":"DCN -> KDR","headline":"Decorin binds VEGFR-2 (KDR) and competes with VEGF-E in human trophoblasts; measured Ki.","interaction_type":"direct binding","direction_and_effect":"Antagonist: DCN displaced 125I-VEGF-E, inhibited VEGF-E-induced migration by interfering with ERK1/2 activation; LRR5 fragments blocked the interaction [PMID:21659473].","molecular_requirements":"Binding abrogated by a VEGFR-2-blocking antibody, indicating overlap between the ligand-binding and DCN-binding domains [PMID:21659473].","affinity_potency":[{"value":"Ki 3.93-5.78 nM","assay":"competition against 125I-VEGF-E (Kd 566 pM)","system":"extravillous trophoblasts","cite":"PMID:21659473"}],"species_and_systems":"Human extravillous trophoblasts, native and recombinant VEGFR-2; far-Western and co-IP [PMID:21659473]. Mouse and human pairs are ortholog-projected.","localisation_and_range":"Decorin flagged secreted; KDR transmembrane receptor [flag].","caveats":"One paper, abstract only; affinity is 7- to 10-fold lower than VEGF-E [PMID:21659473].","key_references":[{"PMID":"21659473","why":"Binding, competition and antagonism at VEGFR-2"}],"covers":["LR002479","LR005753"]},"LR007186":{"pair":"DHH -> BOC:PTCH1","headline":"No support for the complex: the only verified paper is negative (Ptch2, not Ptch1, is the Dhh receptor in tilapia); only DHH-BOC binding is in databases.","interaction_type":"database-asserted only","direction_and_effect":"Nile tilapia knockouts of ptch1 and ptch2 in stem Leydig cells indicate Ptch2 likely acts as the functional receptor for Dhh; ptch2 mutation rescued dhh-mutant testis defects, and Ptch1 was not implicated [PMID:42371991]. BOC is never mentioned [PMID:42371991]. UniProt states generically that Hedgehog binds patched receptor PTCH1 or PTCH2 and that two PTCH1 molecules engage one hedgehog molecule [DB:UniProt].","molecular_requirements":"A BOC:PTCH1 complex as a joint receptor is not demonstrated in our evidence. The PDB structure 3N1G shows DhhN with only the BOC fibronectin domain [DB:PDB 3N1G]; this does not show PTCH1.","affinity_potency":[],"species_and_systems":"The negative paper used Nile tilapia, in vitro and in vivo [PMID:42371991]; structural data are mammalian [DB:PDB 3N1G].","localisation_and_range":"DHH is flagged secreted and transmembrane [flag]; no range data in our evidence.","caveats":"Abstract-level negative read, in a fish, so it does not exclude PTCH1 in mammals. Complex assembly is an annotation, not tested. Per-subunit scoring by CCC tools would require both partners.","key_references":[{"PMID":"42371991","why":"Negative: Ptch2 is the Dhh receptor in tilapia"}],"covers":["LR007186"]},"LR003928":{"pair":"DHH -> CDON","headline":"Structural evidence (PDB 3N1Q) that DHH binds CDON; positive modulator role, abstract-level.","interaction_type":"direct binding","direction_and_effect":"x-ray structures of Sonic, Indian and Desert Hh alone and in complex with the active domains of CDO and BOC show all mammalian Hh proteins bind CDO and BOC in the same manner [PMID:20519495]. Database records agree: PDB 3N1Q (DhhN bound to CDOFn3) [DB:PDB 3N1Q], IntAct x-ray crystallography [DB:IntAct], UniProt subunit annotation [DB:UniProt]. The abstract notes that CDO and BOC positively regulate Hh signalling, but this is background and not measured for DHH here [PMID:20519495].","molecular_requirements":"The N-terminal signalling domain of DHH (DhhN) binds the CDON fibronectin domain in the structure [DB:PDB 3N1Q]. Whether Patched is also needed is not reported for this pair.","affinity_potency":[],"species_and_systems":"Mammalian proteins in a crystal; the species of the recombinant proteins is not stated in the abstract [PMID:20519495]. The mouse row is projected by orthology (ortholog_inferred) [flag].","localisation_and_range":"DHH is flagged both secreted and transmembrane [flag]; membrane tethering is therefore suggested only by an annotation flag, and contact-dependent versus diffusible action is not reported in our evidence.","caveats":"Abstract only. Affinity for DHH is not given in the abstract; micromolar affinities are cited for Ihog and for CDO with Sonic Hh as background [PMID:20519495]. Crystal binding does not show signalling effect for DHH.","key_references":[{"PMID":"20519495","why":"Crystal structures of Hh proteins with CDO and BOC"}],"covers":["LR000436","LR003928"]},"LR005755":{"pair":"DKK1 -> CKAP4","headline":"Direct binding supported: CKAP4 identified as a DKK1 receptor with binding, internalization and signalling data; one paper.","interaction_type":"direct binding","direction_and_effect":"DKK1 binds CKAP4 and LRP6 with similar affinity, using different cysteine-rich domains; DKK1 induced clathrin-dependent CKAP4 internalization, and DKK1/CKAP4 activated AKT via a CKAP4-PI3K complex, driving proliferation [PMID:27322059]. An anti-CKAP4 antibody blocked binding [PMID:27322059].","molecular_requirements":"CKAP4 alone mediates the AKT signalling; LRP6 binds a different DKK1 domain [PMID:27322059]. BioGRID records affinity capture-western and reconstituted complex [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Cancer cell lines, human tumour samples and a xenograft in immunodeficient mice [PMID:27322059]; mouse pair is ortholog-inferred.","localisation_and_range":"DKK1 is flagged secreted, CKAP4 as a receptor [flag].","caveats":"One paper, abstract only; a numeric affinity is not given. Second confirmed row is the same paper.","key_references":[{"PMID":"27322059","why":"CKAP4 identified as DKK1 receptor"}],"covers":["LR002487","LR005755"]},"LR001777":{"pair":"DKK1 -> LRP4","headline":"Direct binding to LRP4 shown in vitro by coprecipitation; one paper, supporting a bone-context link.","interaction_type":"direct binding","direction_and_effect":"Lrp4 binds Dkk1 and sclerostin in vitro; the authors suggest Lrp4 could compete with Lrp5/6 or present the ligands to Lrp5/6 [PMID:19936252].","molecular_requirements":"Binding was shown with HEK293A cells overexpressing Lrp4 and AP-fusion ligands; R-spondin2 served as negative control [PMID:19936252]. Co-receptor needs are not reported.","affinity_potency":[],"species_and_systems":"HEK293A cells overexpressing Lrp4 and primary osteoblasts; Lrp4 deficient mutant mice analysed for bone phenotype [PMID:19936252]. Both pairs are ortholog-inferred.","localisation_and_range":"DKK1 is flagged secreted; LRP4 as a receptor [flag].","caveats":"One paper; no affinity value; whether Lrp4 acts as receptor, competitor or presenter is not resolved by the authors [PMID:19936252].","key_references":[{"PMID":"19936252","why":"Lrp4 binds Dkk1 and sclerostin in vitro"}],"covers":["LR001777","LR005133"]},"LR003937":{"pair":"DKK2 -> LRP6","headline":"DKK2 binds LRP6 and can act as antagonist or agonist depending on context; supported by binding and functional papers, mostly abstract-read.","interaction_type":"direct binding","direction_and_effect":"One paper reports LRP6 as a specific, high-affinity receptor for Dkk1 and Dkk2, with Dkk1 blocking Wnt/beta-catenin signalling [PMID:11357136]. Dkk2 itself is context-dependent: it activates LRP6 signalling in human 293 cells [PMID:12527209], its second cysteine-rich domain stimulates the canonical pathway when LRP-6 is ectopically expressed and this is blocked by an anti-LRP-5/6 antibody [PMID:11742004], and Dkk2 knockdown in Xenopus embryos loses neural crest, rescued by Lrp6 [PMID:30035713].","molecular_requirements":"Kremen2 co-transfection blocks Dkk2 activation of LRP6 and turns Dkk2 into a Wnt inhibitor; Krm2 interaction is mediated by the second cysteine-rich domain of Dkks [PMID:12527209]. Which cofactor is present therefore changes the sign of the effect.","affinity_potency":[],"species_and_systems":"Human and mouse pair entries. Experiments: human/mouse proteins in mammalian cells and Xenopus embryos [PMID:11357136]; human 293 cells [PMID:12527209]; NIH3T3 cells [PMID:11742004]; Xenopus embryos [PMID:30035713]. IntAct also lists a bio-layer interferometry record [DB:IntAct].","localisation_and_range":"DKK2 is flagged secreted and LRP6 as a transmembrane receptor [flag], so paracrine action on cell-surface LRP6 is implied.","caveats":"Three of four shown papers were read as abstract only. Direction conflicts across papers (antagonist vs agonist). The Xenopus paper shows genetic rescue, not binding. No affinity value reported in our evidence.","key_references":[{"PMID":"11357136","why":"LRP6 as high-affinity receptor for Dkk1 and Dkk2"},{"PMID":"12527209","why":"Dkk2 agonist on LRP6; switched by Kremen2"},{"PMID":"11742004","why":"Dkk-2 second cysteine-rich domain stimulates via LRP-6"}],"covers":["LR000445","LR003937"]},"LR002488":{"pair":"DKK3 -> CKAP4","headline":"DKK3 reported to interact with CKAP4 in muscle cells to cause atrophy; single recent paper, no direct binding measurement shown.","interaction_type":"functional only","direction_and_effect":"DKK3 is secreted by skeletal muscle cells, acts in autocrine and paracrine manners and interacts with the cell surface receptor CKAP4 to induce mitochondrial dysfunction and myotube atrophy; DKK3 ablation prevented cigarette smoke-induced muscle dysfunction [PMID:39571512]. Direction is agonist-like in the curator record.","molecular_requirements":"Not reported in our evidence (no subunit or co-receptor requirement).","affinity_potency":[],"species_and_systems":"Human and mouse pair entries, both ortholog-inferred. The paper used C2C12 myocytes with DKK3 overexpression and knockdown and patient plasma cohorts [PMID:39571512].","localisation_and_range":"Secreted by muscle cells, autocrine/paracrine [PMID:39571512]; DKK3 is also flagged secreted [flag].","caveats":"Assay is labelled direct_binding but the abstract and excerpts shown describe functional effects and an interaction claim, not a binding assay or affinity. Only one paper; no database record.","key_references":[{"PMID":"39571512","why":"DKK3-CKAP4 interaction driving myotube atrophy"}],"covers":["LR002488","LR005756"]},"LR001786":{"pair":"DSC1 -> DSG4","headline":"DSC1-DSG4 support is a family-wide SPR claim; DSG4 is not among the paper's named Dsg1/2/3 matrix.","interaction_type":"direct binding","direction_and_effect":"Passing a Dsg over a Dsc surface or the reverse gave binding responses indicative of strong heterophilic interaction [PMID:27298358].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"KD 3.6-43.9 uM","assay":"SPR (Biacore T100), all pairwise human Dsg/Dsc combinations; range across pairs, not specific to this pair","system":"human ectodomains","cite":"PMID:27298358"}],"species_and_systems":"Human proteins; mouse record ortholog-inferred [PMID:27298358].","localisation_and_range":"Annotated transmembrane [flag]; adhesive binding [PMID:27298358].","caveats":"Browser-read full text, quote unverifiable, spot-check pending. The curator note describes the matrix as Dsg1/2/3 x Dsc1/2/3, so Dsg4 testing is not shown.","key_references":[{"PMID":"27298358","why":"SPR of Dsc/Dsg ectodomains"}],"covers":["LR001786","LR005142"]},"LR005764":{"pair":"DSC2 -> DSC2","headline":"Homophilic DSC2 trans binding shown by cross-linking in keratinocytes.","interaction_type":"direct binding","direction_and_effect":"Extracellular cross-linking in HaCaT keratinocytes gave evidence for homophilic, isoform-specific Dsc2 binding that represents trans interaction [PMID:21098030]. Mutating Trp-2 and Ala-80 abolished Dsc2 binding [PMID:21098030].","molecular_requirements":"No evidence for heterophilic or cis interaction, though neither was fully excluded; adducts sit in the detergent-insoluble fraction [PMID:21098030].","affinity_potency":[],"species_and_systems":"Human HaCaT keratinocytes [PMID:21098030].","localisation_and_range":"Transmembrane, in desmosomes; cell-cell trans interaction [PMID:21098030][flag].","caveats":"Abstract read only. Self-pair, so ligand and receptor are the same protein. The paper reports no cross-isoform binding between Dsc2 and Dsg2/Dsg3, which differs from the heterophilic picture in other papers for related pairs.","key_references":[{"PMID":"21098030","why":"Cross-linking shows homophilic Dsc2 trans binding"}],"covers":["LR002496","LR005764"]},"LR002497":{"pair":"DSC3 -> DSC3","headline":"Homophilic DSC3 trans self-binding shown by cross-linking in human keratinocytes; abstract-level evidence only.","interaction_type":"direct binding","direction_and_effect":"DSC3 binds itself: extracellular cross-linking gave homophilic, isoform-specific adducts in HaCaT keratinocytes, consistent with trans (cell-cell) interaction [PMID:21098030]. No directional effect beyond a curator agonist-style label is reported.","molecular_requirements":"Trp-2 and Ala-80 mutation abolished Dsc2 binding specifically, not tested for DSC3, so a requirement for DSC3 is not shown [PMID:21098030]. Other subunits or co-receptors: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HaCaT keratinocytes (cross-linking, electron microscopy) [PMID:21098030]. Pair is recorded for human and mouse (mouse projected from human).","localisation_and_range":"Membrane-bound desmosomal cadherin; trans cell-cell contact, with adducts in the detergent-insoluble fraction and probably in desmosomes by electron microscopy [PMID:21098030]. Entity flags mark it as a transmembrane receptor [flag].","caveats":"Only the abstract was read. The authors found no evidence for heterophilic or cis interaction (not fully excluded), so this paper argues against, not for, DSC3 binding Dsg partners [PMID:21098030]. No affinity reported, and no database record.","key_references":[{"PMID":"21098030","why":"Cross-linking evidence for homophilic, isoform-specific desmosomal cadherin binding"}],"covers":["LR002497","LR005765"]},"LR001795":{"pair":"DSG1 -> DSC3","headline":"DSG1 -> DSC3: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358]. Database records also exist (IntAct), which are not independent of the evidence above. [DB:IntAct]","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001795"]},"LR005773":{"pair":"DSG3 -> DSG3","headline":"Homophilic trans DSG3 self-binding shown by cross-linking in keratinocytes; abstract only.","interaction_type":"direct binding","direction_and_effect":"Cross-linking showed isoform-specific homophilic trans binding of Dsg3 in HaCaT keratinocytes; adducts were detergent-insoluble and probably within desmosomes by electron microscopy [PMID:21098030].","molecular_requirements":"Trp-2 and Ala-80 mutations abolished Dsc2 binding specifically (not tested on Dsg3) [PMID:21098030]. UniProt notes DSG3 forms a complex with PKP1 and YWHAG for YAP1 localisation, a cytoplasmic interaction not relevant to the ectodomain pair [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human HaCaT keratinocytes; mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are flagged as non-secreted receptors, so this is membrane-bound, contact-dependent (juxtacrine) adhesion [flag].","caveats":"Abstract only. The authors found no evidence for heterophilic or cis interaction, though neither was excluded [PMID:21098030]. A self-pair is one chain acting as both ligand and receptor; a single-subunit homodimer.","key_references":[{"PMID":"21098030","why":"Cross-linking evidence for homophilic trans DSG3 binding"}],"covers":["LR002505","LR005773"]},"LR003946":{"pair":"EBI3 -> IL27RA","headline":"EBI3 is a subunit of IL-27; IL27RA engagement is by the complex, so this chain-level pair is inferred.","interaction_type":"functional only","direction_and_effect":"IL-27 (EBI3 + p28) acts through WSX-1/TCCR (IL27RA) as agonist; this is functional attribution, not a binding measurement [PMID:12121660].","molecular_requirements":"EBI3 is not an independent IL27RA ligand; it needs p28 to form IL-27 [PMID:12121660]. Structures of IL27RA/IL6ST chains with EBI3 are in the PDB [DB:PDB 7U7N][DB:PDB 8D85]; UniProt describes IL6ST as a signal-transducing subunit for p28/EBI3 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human; abstract-only functional study of naive CD4+ T cells.","localisation_and_range":"EBI3 is flagged as secreted [flag].","caveats":"Database records (BioGRID Affinity Capture-Western, Reactome, GtoPdb agonist) are at complex level. A curator note warns not to read this as EBI3 monomer binding.","key_references":[{"PMID":"12121660","why":"IL-27 identified as EBI3 + p28 acting via WSX-1"}],"covers":["LR000455","LR003946"]},"LR003955":{"pair":"EDN3 -> EDNRA","headline":"ET-3 reaches ETA only weakly in our evidence; two abstract-read papers, with unclear support.","interaction_type":"conflicting","direction_and_effect":"ET-3 produced gallbladder contraction acting mainly via ETB and also interacting with ETA [PMID:11982704]. A cloned-ETA displacement study reports BQ123 with a potency similar to ET-3 against 125I-ET-1 [PMID:8440682].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human gallbladder muscle strips and an opossum model [PMID:11982704]; COS cells with cloned ETA [PMID:8440682]. Mouse pair is ortholog-inferred.","localisation_and_range":"ET-3 secreted, EDNRA transmembrane [flag].","caveats":"The functional paper attributes the effect mainly to ETB, so ETA involvement is secondary [PMID:11982704]. The binding paper gives no ET-3 affinity number in our evidence. Both read as abstracts only. Reactome lists generic EDN binding by EDNRA [DB:Reactome R-HSA-9731924].","key_references":[{"PMID":"11982704","why":"ET-3 gallbladder contraction, ETB main and ETA also"},{"PMID":"8440682","why":"cloned human ETA binding pharmacology"}],"covers":["LR000464","LR003955"]},"LR010777":{"pair":"EFEMP2 -> CATSPER1","headline":"Database-only: a two-hybrid pooling physical association; no ligand-receptor evidence.","interaction_type":"database-asserted only","direction_and_effect":"No curated paper evidence. The only record is an IntAct physical association by two hybrid pooling (EBI-754087) [DB:IntAct]. Direction and effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human yeast two-hybrid pooling record [PMID:16189514] via [DB:IntAct]; no other system reported.","localisation_and_range":"Not reported in our evidence; no localisation flags for the ligand.","caveats":"Rests on one high-throughput two-hybrid record, which does not establish that CATSPER1 is a receptor for EFEMP2. No papers were judged for this pair.","key_references":[],"covers":["LR010777"]},"LR003964":{"pair":"EFNA1 -> EPHA7","headline":"Database-asserted only: UniProt lists EphA receptors including EPHA7 as EFNA1 binders; no papers judged.","interaction_type":"database-asserted only","direction_and_effect":"UniProt SUBUNIT states EFNA1 binds EPHA2, EPHA3, EPHA4, EPHA5, EPHA6 and EPHA7 [DB:UniProt PMID:18794797]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; human pair is ortholog-inferred, mouse is not.","localisation_and_range":"EFNA1 annotated secreted and transmembrane [flag]; no paper text on localisation.","caveats":"No curated paper evidence; support is a single UniProt annotation.","key_references":[],"covers":["LR000473","LR003964"]},"LR003973":{"pair":"EFNA2 -> EPHA8","headline":"Database-only: UniProt says EFNA2 interacts with EPHA8; no papers judged.","interaction_type":"database-asserted only","direction_and_effect":"UniProt SUBUNIT: Interacts with EPHA8 [DB:UniProt PMID:19836338]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species not reported in our evidence; human pair ortholog-inferred.","localisation_and_range":"EFNA2 annotated transmembrane, EPHA8 transmembrane [flag].","caveats":"Single database annotation, no paper evidence.","key_references":[],"covers":["LR000482","LR003973"]},"LR003982":{"pair":"EFNA4 -> EPHA1","headline":"Only a UniProt note: EphA1 binds EFNA4 with low affinity; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says EPHA1 binds 'with a low affinity EFNA3 and EFNA4' and with high affinity EFNA1, its probable cognate ligand [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence; human and mouse pairs are ortholog-inferred.","localisation_and_range":"EFNA4 is flagged both secreted and transmembrane; EPHA1 is flagged membrane-bound [flag].","caveats":"No curator-verified paper (all judged papers review-only); evidence is one database statement.","key_references":[],"covers":["LR000491","LR003982"]},"LR003991":{"pair":"EFNA5 -> EPHA2","headline":"Soluble ephrin-A5 (LERK-7) induces EphA2 (eck) phosphorylation; crystal structures of the complex exist in PDB.","interaction_type":"direct binding","direction_and_effect":"A soluble form of LERK-7 (EFNA5) induced phosphorylation of eck in a human duodenum adenocarcinoma cell line [PMID:9245480]. PDB holds structures of EphA2 ectodomain with ephrin-A5 [DB:PDB 2X11] [DB:PDB 3MX0]; IntAct lists light scattering and pull-down records [DB:IntAct].","molecular_requirements":"The PDB 2X11 entry covers the complete EphA2 ectodomain with the ephrin-A5 receptor-binding domain [DB:PDB 2X11].","affinity_potency":[],"species_and_systems":"Human cancer cell line [PMID:9245480]; the species of the structural work is not reported in our evidence. Mouse pair is ortholog-inferred.","localisation_and_range":"Both flagged membrane-bound [flag]; the paper reports GPI-anchored LERK-7 with a soluble form active [PMID:9245480].","caveats":"The only confirmed paper is a functional abstract-only read; the identity of eck as EPHA2 comes from a curator note, and binding rests on database structural records.","key_references":[{"PMID":"9245480","why":"Soluble LERK-7 induces eck phosphorylation"}],"covers":["LR000500","LR003991"]},"LR005791":{"pair":"EGF -> AXL","headline":"EGF activates AXL kinase in human cancer cells, but via EGFR-AXL hetero-interaction; direct EGF-AXL binding is not shown.","interaction_type":"functional only","direction_and_effect":"EGF stimulated activation of Axl kinase; the paper reports a hetero-interaction between the two RTKs [PMID:27775700]. Axl phosphorylation by EGF was blocked by the EGFR inhibitor gefitinib but not by the Axl inhibitor BGB324 [PMID:27775700].","molecular_requirements":"EGFR activity is required; only the fully glycosylated mature 140 kDa Axl responded to EGF, not the 120 kDa Gas6-activated form [PMID:27775700].","affinity_potency":[],"species_and_systems":"Human glioblastoma cells, also seen in breast and head and neck cancer lines (western blot, kinase assay, co-IP, BiFC); mouse entry is ortholog-inferred [PMID:27775700].","localisation_and_range":"EGF is secreted and AXL is a transmembrane receptor [flag]; range not otherwise reported in our evidence.","caveats":"Curators note this is likely transactivation through EGFR, not direct EGF-AXL binding. Only one paper, read as abstract plus excerpts.","key_references":[{"PMID":"27775700","why":"EGF activates Axl via EGFR-Axl hetero-interaction in GBM cells"}],"covers":["LR002523","LR005791"]},"LR010759":{"pair":"EGF -> EGFR:ERBB2","headline":"EGF binds EGFR; ERBB2 as a partner is not supported for native EGF in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"EGF engages EGFR, shown by crystal structure with EGFR alone [PMID:12297050] and EGFR activation by EGF-induced dimerisation [PMID:12620237]. No cited paper shows EGF acting on an EGFR:ERBB2 complex.","molecular_requirements":"EGFR is the EGF-binding chain; the ERBB2 half is not evidenced by these papers. ERBB2/ERBB3 affinity is a property of engineered EGF chimeras, not native EGF [PMID:12093292].","affinity_potency":[],"species_and_systems":"Human structures and cell systems [PMID:12297050][PMID:12093292]. Reactome and PDB list EGF:EGFR:ERBB2 complexes [DB:Reactome].","localisation_and_range":"EGF is secreted [flag].","caveats":"The complex row rests on EGFR-only evidence plus database records; the confirmed papers do not test ERBB2.","key_references":[{"PMID":"12297050","why":"EGF-EGFR structure (EGFR chain only)"},{"PMID":"12093292","why":"Native EGF vs engineered chimeras for ErbB-2/ErbB-3"}],"covers":["LR010759"]},"LR005818":{"pair":"EPHA4 -> EFNA1","headline":"EPHA4-EFNA1 is supported by SPR/ELISA and BioGRID records; no verified papers.","interaction_type":"direct binding","direction_and_effect":"IntAct lists direct interaction by ELISA and surface plasmon resonance [DB:IntAct]; BioGRID lists affinity capture-Western [DB:BioGRID]. UniProt says EphA4 is highly promiscuous and, on activation by EFNA1, induces NGEF phosphorylation by CDK5 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence; the mouse pair is non-inferred.","localisation_and_range":"EFNA1 is flagged secreted, EPHA4 non-secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Database evidence only; two review-only rows. No affinity values in our dossier.","key_references":[],"covers":["LR002550","LR005818"]},"LR005836":{"pair":"EPHA7 -> EFNA2","headline":"Two abstract-level papers support EPHA7/ephrin-A2 binding or signalling, but one does not name the pair explicitly.","interaction_type":"functional only","direction_and_effect":"In human rhabdomyosarcoma cells, EphA7 binds and signals to ephrin-A2, and Fc chimeras of EphA7 and ephrin-A5 inhibit proliferation [PMID:40426233]. The abstract does not say which partner is the signalling receptor beyond this. An earlier mouse study reports high-affinity binding of the ligands Elf-1 and B61 to MDK1 and receptor autophosphorylation in Rat1 cells, but its abstract does not name EphA7 or ephrin-A2 [PMID:9010230].","molecular_requirements":"Subunit or co-receptor requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human rhabdomyosarcoma cell lines in vitro [PMID:40426233]; mouse receptor MDK1 fusion proteins and Rat1 cells [PMID:9010230]. Both papers were read as abstracts only.","localisation_and_range":"EPHA7 carries secreted and transmembrane flags; EFNA2 carries a transmembrane flag [flag]. Both papers describe cell-based assays; range is not reported beyond that.","caveats":"Abstract-only reading. The 1.7 x 10(-10) M and 2.2 x 10(-10) M values in [PMID:9010230] are for Elf-1 and B61 binding MDK1, and the abstract does not link them to EFNA2 in our evidence, so they are not assigned to this pair. BioGRID lists an affinity capture-Western record [DB:BioGRID 280891]. Three other papers were judged abstract-insufficient.","key_references":[{"PMID":"40426233","why":"Human hRMS cells: EphA7 binds and signals to ephrin-A2, abstract only."},{"PMID":"9010230","why":"Scatchard binding of Elf-1 and B61 to MDK1; link to this pair not explicit in the abstract."}],"covers":["LR002568","LR005836"]},"LR002569":{"pair":"EPHA7 -> EFNA3","headline":"Database-only pair: one BioGRID Western affinity capture record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"EPHA7 carries secreted and transmembrane flags; EFNA3 carries a transmembrane flag [flag]; range is unclear.","caveats":"No curator-verified paper; support is database records only. The record is an Affinity Capture-Western entry [DB:BioGRID 280892]; affinity not reported in our evidence. Six papers were judged abstract-insufficient and two review-only.","key_references":[],"covers":["LR002569","LR005837"]},"LR002578":{"pair":"EPHB1 -> EFNB1","headline":"Eph B1-ephrin-B1 pair supported by UniProt statements and an IntAct solid-phase assay; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states ephrin-B1 shows high affinity for EPHB1/ELK and can also bind EPHB2 and EPHB3; EPHB1 entry lists EFNB1, EFNB2 and EFNB3 as cognate/functional ephrin ligands [DB:UniProt]. Activating or inhibitory effect is not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. IntAct reports a solid phase assay [DB:IntAct P98172-P54762], the closest record to a direct binding test; no affinity value is given in our evidence. Four papers were review-only.","key_references":[],"covers":["LR002578","LR005846"]},"LR005854":{"pair":"EPHB2 -> EFNB1","headline":"Eph B2-ephrin-B1 pair supported by IntAct and UniProt records; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that upon activation by EFNB1, EPHB2 abolishes ARHGEF15-mediated negative regulation of excitatory synapse formation, and that EFNB1 can also bind EPHB2 and EPHB3 [DB:UniProt]. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. IntAct records an anti-tag coimmunoprecipitation [DB:IntAct EBI-54525293] and a solid phase assay [DB:IntAct P29323-P98172]. Affinity not reported in our evidence.","key_references":[],"covers":["LR002586","LR005854"]},"LR002587":{"pair":"EPHB2 -> EFNB2","headline":"Eph B2-ephrin-B2 pair supported by BioGRID, IntAct and a UniProt functional statement; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states forward and reverse signalling through the EFNB2/EPHB2 complex regulate movement and adhesion of cells that tubularize the urethra and septate the cloaca [DB:UniProt]. This implies bidirectional signalling. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. BioGRID lists a Reconstituted Complex [DB:BioGRID 315434]; IntAct lists affinity chromatography [DB:IntAct EBI-32718255] and anti-tag coimmunoprecipitation [DB:IntAct EBI-54556805]. Affinity not reported in our evidence.","key_references":[],"covers":["LR002587","LR005855"]},"LR002596":{"pair":"EPHB4 -> EFNB2","headline":"Well supported EphB4-ephrin-B2 binding: ELISA, a PDB structure, SPR and reconstituted-complex records, plus a cis-inhibition paper.","interaction_type":"direct binding","direction_and_effect":"Ephrin-B2 Fc binds best of the three ephrin-Bs to all EphB receptors in ELISA [PMID:22568954]. In cancer cells, coexpressed ephrin-B2 inhibits EphB4 through cis association, in addition to its trans interactions [PMID:24348920]; the curator labels this effect antagonist.","molecular_requirements":"Not reported beyond the two partners. A crystal structure contains one chain of each protein [DB:PDB 2HLE].","affinity_potency":[],"species_and_systems":"Human cancer cells [PMID:24348920] (species recorded by curator); ELISA with Fc proteins, species unspecified [PMID:22568954].","localisation_and_range":"Both partners transmembrane-flagged [flag]; Eph receptors signal in trans between cells (juxtacrine) and the paper adds cis interactions on the same cell [PMID:24348920].","caveats":"[PMID:22568954] quote was browser-read and marked unverifiable pending spot-check; [PMID:24348920] is full text available but was read as an abstract here. Apparent KD values are in a figure not in our evidence. Other records: BioGRID Reconstituted Complex [DB:BioGRID 3885527] and IntAct surface plasmon resonance [DB:IntAct P52799-P54760].","key_references":[{"PMID":"22568954","why":"ELISA: ephrin-B2 Fc binds EphB receptors best of the ephrin-Bs."},{"PMID":"24348920","why":"Coexpressed ephrin-B2 inhibits EphB4 in cancer cells via cis association."}],"covers":["LR002596","LR005864"]},"LR005872":{"pair":"ESAM -> ESAM","headline":"ESAM mediates homophilic cell adhesion in CHO aggregation assays; self-pair, abstract-level.","interaction_type":"functional only","direction_and_effect":"ESAM-expressing CHO cells show cell-cell adhesion through homophilic interactions in aggregation assays [PMID:11279107]. Direction is not applicable; the pair is self-binding.","molecular_requirements":"Structure is V-type and C2-type immunoglobulin domains with a single transmembrane region [PMID:11279107]. Subunit needs: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human and murine ESAM cloned; adhesion assay in CHO cells [PMID:11279107]. IntAct lists ESAM-ESAM in protein array and solid phase assays [DB:IntAct].","localisation_and_range":"Membrane-bound adhesion molecule, juxtacrine contact [flag; PMID:11279107].","caveats":"Abstract-only; functional adhesion, not purified binding. No affinity.","key_references":[{"PMID":"11279107","why":"Homophilic ESAM adhesion in CHO aggregation assays"}],"covers":["LR002605","LR005872"]},"LR005881":{"pair":"FBLN2 -> ITGA2B","headline":"Fibulin-2 binds integrin alpha IIb beta 3 in purified-protein assays; mouse fibulin-2 binds strongly, RGD-dependent.","interaction_type":"direct binding","direction_and_effect":"Mouse fibulin-2 bound alpha IIb beta 3 almost as strongly as fibrinogen, and an RGD peptide (SVPRGDLDG) antagonized binding [PMID:7543056]. Mouse fibulin-2 also promoted adhesion of thrombin-stimulated platelets, inhibited by RGD peptides [PMID:7543056].","molecular_requirements":"Binding was to the alpha IIb beta 3 heterodimer, not a single chain; the RGD site of fibulin-2 is involved [PMID:7543056].","affinity_potency":[],"species_and_systems":"Recombinant proteins from kidney cell clones and five purified integrins [PMID:7543056]. Human fibulin-2, in which RGD is changed to RSS, bound less strongly and showed no cell-adhesion activity [PMID:7543056]. The human pair is therefore weaker; the mouse pair is ortholog-inferred.","localisation_and_range":"FBLN2 is flagged secreted [flag]; the paper says fibulins occur in basement membranes and vessel walls [PMID:7543056], so it is a matrix ligand.","caveats":"Single paper, abstract only. No affinity number for fibulin-2 itself. The entity here is ITGA2B but the assay used the integrin heterodimer; no ITGB3 role is separated.","key_references":[{"PMID":"7543056","why":"Fibulin-2 binds alpha IIb beta 3, RGD-dependent."}],"covers":["LR002614","LR005881"]},"LR007195":{"pair":"FCER2 -> ITGAM:ITGB2","headline":"CD23 interacts with the CD11b-CD18 complex: binding and monocyte activation (1995), supported by a modelling paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant CD23 liposomes bound COS cells expressing CD11b-CD18, inhibited by anti-CD11b and anti-CD23; CD23 triggering increased IL-1 beta, IL-6, TNF alpha in monocytes [PMID:7621072]. A modelling paper states CD23 recognizes CD11b and CD11c via its lectin domain [PMID:8745401]. Effect labelled agonist by curators.","molecular_requirements":"Complex is CD11b-CD18; CD11a-CD18 did not bind [PMID:7621072]. Binding depends on Ca2+ and appears to involve sugars (reduced by tunicamycin, not neuraminidase) [PMID:7621072] [PMID:8745401]. CD18 as co-chain is covered by the same data.","affinity_potency":[],"species_and_systems":"Human CD23, COS transfectants and human monocytes; model is computational [PMID:8745401].","localisation_and_range":"CD23 is flagged secreted and transmembrane [flag].","caveats":"PMID 8745401 was read as abstract only and is a structural model, not binding data. Interaction classed Receptor-Receptor. No affinity reported.","key_references":[{"PMID":"7621072","why":"CD23 binds CD11b-CD18, monocyte activation"},{"PMID":"8745401","why":"Model of CD23 lectin domain recognizing CD11b/c in a calcium-dependent way"}],"covers":["LR007195"]},"LR005890":{"pair":"FGB -> ITGB3","headline":"Direct binding of fibrinogen to integrin alphaIIbbeta3 (abstract-level), plus functional trophoblast data; chain-level for both partners.","interaction_type":"direct binding","direction_and_effect":"Integrin alphaIIbbeta3 binds fibrinogen, and RGD peptide binding converts it to a high-affinity fibrinogen-binding, platelet-aggregating state; RGD mimetics can be partial agonists and competitive antagonists [PMID:2018974]. Fibrinogen is stated to be recognized by alphaVbeta3 and alphaIIbbeta3, curated as agonist [PMID:15031111].","molecular_requirements":"The receptor in both papers is the alphaIIbbeta3 integrin (beta3 paired with alphaIIb); fibrinogen is FGA:FGB:FGG and the assay does not separate the chains [PMID:2018974]. Fibrinogen binding requires agonist activation of platelets [PMID:2018974].","affinity_potency":[],"species_and_systems":"Human platelets, human ligand and receptor [PMID:2018974]; human fibrinogen on mouse trophoblast cells [PMID:15031111]. Both human and mouse interaction records exist, neither ortholog-inferred.","localisation_and_range":"FGB is flagged secreted [flag]; the paper context is soluble fibrinogen binding platelet receptors [PMID:2018974].","caveats":"Both papers are read at abstract or limited level for this pair; no affinity value in our evidence. The trophoblast sentence is partly literature-cited background [PMID:15031111]. Five further papers were judged abstract_insufficient. No database records.","key_references":[{"PMID":"2018974","why":"Fibrinogen binding to alphaIIbbeta3 and RGD-induced activation"},{"PMID":"15031111","why":"Fibrinogen recognition by beta3 integrins in mouse trophoblast outgrowth"}],"covers":["LR002624","LR005890"]},"LR000598":{"pair":"FGF1 -> NRP1","headline":"FGF1 binds neuropilin-1 strongly in an optical biosensor assay; one paper, no functional effect shown for FGF1.","interaction_type":"direct binding","direction_and_effect":"FGF-1, FGF-2, FGF-4 and FGF-7 all showed strong binding to immobilised Npn-1 [PMID:15695515]. Direction or agonist/antagonist effect for FGF1 is not reported in our evidence; the paper reports potentiation of FGF-2 activity, not FGF-1 [PMID:15695515].","molecular_requirements":"Binding was heparin-sensitive and dependent on ionic strength, suggesting a heparin-mimetic site on Npn-1 [PMID:15695515]. Whether other co-receptors are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Purified proteins on an optical biosensor surface (IAsys); species of the proteins not reported in our evidence [PMID:15695515]. Both human and mouse pairs are projected (ortholog_inferred).","localisation_and_range":"FGF1 flagged secreted; NRP1 flagged secreted and transmembrane, so it exists as membrane and soluble forms [flag].","caveats":"Kinetic constants were given for FGF-2, FGF-4 and HGF/SF only, not FGF-1. Binding is heparin-inhibited, so it may be non-specific for heparin-binding proteins. Single paper [PMID:15695515].","key_references":[{"PMID":"15695515","why":"biosensor binding of FGF1 to Npn-1"}],"covers":["LR000598","LR004082"]},"LR000589":{"pair":"FGF19 -> FGFR2","headline":"Functional evidence only: FGF19 activates FGFR2 c splice forms in one BaF3 assay; no binding data.","interaction_type":"functional only","direction_and_effect":"FGF19 showed consistent activity toward FGFR1c, 2c, 3c and FGFR4 but none toward FGFR1b, 2b or 3b in a BaF3 cell mitogenic assay [PMID:16597617].","molecular_requirements":"Only the c splice form of FGFR2 responded; KLB involvement is not reported in our evidence for this pair.","affinity_potency":[],"species_and_systems":"BaF3 cells expressing individual FGFRs; species not stated [PMID:16597617]. No database records for this pair.","localisation_and_range":"Ligand annotated secreted and receptor transmembrane [flag].","caveats":"Single functional paper, read as abstract only, with the quote marked as browser-read and pending spot-check. No direct binding, no affinity, no KLB dependence tested for this pair in our evidence.","key_references":[{"PMID":"16597617","why":"BaF3 mitogenic activity of FGF19 on c-form FGFRs"}],"covers":["LR000589"]},"LR004099":{"pair":"FGF2 -> SDC1","headline":"FGF2 binds syndecan-1 through its heparan sulfate chains in several assays; mostly proteoglycan-chain binding.","interaction_type":"direct binding","direction_and_effect":"bFGF bound only the HS chains of syndecan-1 and -4 ectodomains by BIAcore [PMID:15226297]. FGF2-GST affinity precipitation bound human SDC1 via heparitinase-cleavable HS [PMID:16982797]. Cotransfection of syndecans with FGFR1 raised specific 125I-bFGF binding two- to three-fold in K562 cells [PMID:8609172]. BioGRID lists co-purification and affinity-capture records [DB:BioGRID].","molecular_requirements":"Binding needs HS chains, not CS chains or core protein [PMID:15226297; PMID:16982797]. In K562 cells syndecan supports FGF2 binding to FGFR1 [PMID:8609172]. Lacritin and FGF2 appear to target different forms of SDC1 [PMID:16982797].","affinity_potency":[],"species_and_systems":"BIAcore on murine mammary epithelial syndecan ectodomains [PMID:15226297]; HEK293T cells expressing human SDC1 [PMID:16982797]; human K562 cells [PMID:8609172].","localisation_and_range":"SDC1 is flagged transmembrane and FGF2 secreted [flag], so FGF2 presented at the cell surface in cis or trans.","caveats":"Evidence is binding to HS chains, a feature shared with many proteoglycans, not a specific protein-protein interface. FGF2 was a positive control in one paper [PMID:16982797]. Two further papers were judged abstract_insufficient or review_only and are not shown.","key_references":[{"PMID":"15226297","why":"BIAcore: bFGF binds HS chains of syndecan-1"},{"PMID":"16982797","why":"FGF2-GST pull-down of SDC1, full text"},{"PMID":"8609172","why":"Syndecans increase FGF2 binding to FGFR1"}],"covers":["LR000615","LR004099"]},"LR005179":{"pair":"FGG -> TLR4","headline":"Fibrinogen is reported as an endogenous TLR4 ligand activating monocytes; functional with database support.","interaction_type":"functional only","direction_and_effect":"Fibrinogen activated monocytes from pre-eclamptic patients as an endogenous TLR4 ligand [PMID:24661950]. Reactome describes cleaved fibrinogen products binding TLR4:LY96 [DB:Reactome R-HSA-8870678].","molecular_requirements":"Reactome lists the TLR4:LY96 complex [DB:Reactome R-HSA-8870678]; requirement for MD-2 is not shown by the paper in our evidence.","affinity_potency":[],"species_and_systems":"Human monocytes from patients [PMID:24661950]. Mouse pair is ortholog-inferred.","localisation_and_range":"FGG is flagged secreted [flag].","caveats":"Abstract-only read; whole fibrinogen, not FGG chain, and cleaved products in Reactome. Direct binding is not shown in our evidence; IntAct records ELISA [DB:IntAct].","key_references":[{"PMID":"24661950","why":"Fibrinogen as TLR4 ligand on monocytes"}],"covers":["LR001824","LR005179"]},"LR005908":{"pair":"FLRT1 -> ADGRL1","headline":"FLRT proteins are reported as ligands for latrophilins; FLRT1-LPHN1 evidence is a general family statement.","interaction_type":"direct binding","direction_and_effect":"FLRT1-3 are reported as endogenous ligands for LPHN1 and LPHN3 [PMID:22405201]. Direction/effect on signalling is not reported in our evidence for FLRT1.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Receptor-ligand binding assays; species recorded as human, though the dossier lists the pair as human ortholog-inferred and mouse not inferred [PMID:22405201].","localisation_and_range":"FLRT1 flagged secreted and transmembrane [flag]; FLRT proteins are single-pass transmembrane [PMID:22405201], so contact-dependent.","caveats":"The excerpts concern FLRT3 and FLRT2 pull-downs; FLRT1 named only in the family sentence [PMID:22405201]. One confirmed paper; others were review-only or abstract-insufficient. No database records.","key_references":[{"PMID":"22405201","why":"FLRTs as latrophilin ligands"}],"covers":["LR002642","LR005908"]},"LR005917":{"pair":"FLRT2 -> ITGB4","headline":"FLRT2 is reported to associate with integrin beta 4 in endothelial cells, restraining senescence; evidence is co-association rather than a ligand-receptor binding study.","interaction_type":"functional only","direction_and_effect":"FLRT2 silencing increased ITGB4 phosphorylation (Y1510) and senescence; silencing ITGB4 reversed AKT activation and the rise in p53/p21 [PMID:38587072]. FLRT2 and ITGB4 were co-associated in FLAG-FLRT2-overexpressing cells, and colocalised by immunofluorescence and Duolink [PMID:38587072]. The curated row labels the effect antagonist.","molecular_requirements":"ITGB4 only (no alpha subunit) is mentioned; partner subunits are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human endothelial cells (HUVEC), aged rat and human vascular tissue, and mice (FLRT2 silencing and overexpression) [PMID:38587072].","localisation_and_range":"FLRT2 is flagged secreted and transmembrane [flag]; ITGB4 was found in plasma membrane lipid rafts [PMID:38587072].","caveats":"Co-immunoprecipitation, colocalisation and proximity ligation do not prove direct binding; the curated assay_class is direct_binding.","key_references":[{"PMID":"38587072","why":"FLRT2-ITGB4 association and senescence control."}],"covers":["LR002651","LR005917"]},"LR002659":{"pair":"FLRT3 -> UNC5B","headline":"FLRT3 is the established UNC5B partner; supported by a binding screen, database complexes and repulsion work.","interaction_type":"direct binding","direction_and_effect":"Unc5B binds FLRT3, and shed FLRT2/3 ectodomains act as repulsive guidance cues for Unc5-positive neurons [PMID:21673655]. In a 126 x 126 screen, FLRT3 and Unc5B bound near saturation [PMID:26633812]; BioGRID lists reconstituted-complex records [DB:BioGRID].","molecular_requirements":"Interaction is via the extracellular domains; UNC5B has higher affinity for FLRT3 than FLRT2 [DB:UniProt]. FLRT3, ADGRL3 and UNC5B are found together in complexes [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse retina, CHO.K1 and purified ectodomains [PMID:26633812]; 2011 paper supports it as background, abstract only [PMID:21673655]. Dossier covers human (ortholog-inferred) and mouse.","localisation_and_range":"FLRT3 annotated secreted and transmembrane, UNC5B transmembrane [flag]; ectodomains are shed [PMID:21673655].","caveats":"The 2011 row treats FLRT3-Unc5B as prior work, not its own test [PMID:21673655]. Unc5B stripes elicited no significant neuronal response in one assay (n=3/380, 1% repulsive) [PMID:26633812]. No affinity value in our evidence.","key_references":[{"PMID":"26633812","why":"Screen: all FLRT x Unc5 pairs bind"},{"PMID":"21673655","why":"Context: FLRT2/3 shed ectodomains repel Unc5 neurons"}],"covers":["LR002659","LR005925"]},"LR005926":{"pair":"FLRT3 -> UNC5C","headline":"FLRT3 binds UNC5C in a high-throughput screen; one primary study, no affinity.","interaction_type":"direct binding","direction_and_effect":"All three FLRTs bound all four Unc5s near saturation (mean Abs650nm value = 2.14) [PMID:26633812]. Neurons responded to FLRT3 stripes with 8% attractive and 8% repulsive responses (n=37/438 and n=33/438) and to Unc5C stripes with 11% repulsion (n=45/396) [PMID:26633812]; these are separate stripe assays, not the pair tested together.","molecular_requirements":"Purified ectodomains were sufficient [PMID:26633812].","affinity_potency":[],"species_and_systems":"Screen with purified ectodomains, CHO.K1 aggregation, mouse retinal neurons [PMID:26633812].","localisation_and_range":"FLRT3 annotated secreted and transmembrane, UNC5C transmembrane [flag].","caveats":"Based on a single paper. The human pair is ortholog-inferred. No affinity in our evidence.","key_references":[{"PMID":"26633812","why":"Binding screen of all FLRT x Unc5 combinations"}],"covers":["LR002660","LR005926"]},"LR002668":{"pair":"FTH1 -> SCARA5","headline":"H-ferritin is bound by the SCARA5 SRCR domain in biochemical assays; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"SCARA5 recognises H-ferritin (FTH1) through its SRCR domain, Ca2+-dependently [PMID:32907880]. Effect on signalling is not reported in our evidence; only recognition is reported.","molecular_requirements":"The SRCR domain of SCARA5 is the ferritin-recognising region [PMID:32907880]. Whether other subunits are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Biochemical binding assays with purified proteins; crystal structures of the SRCR domain were solved for human and mouse SCARA5 [PMID:32907880].","localisation_and_range":"FTH1 is flagged as secreted and non-transmembrane; SCARA5 is flagged as a transmembrane receptor [flag].","caveats":"Based on an abstract only, no affinity reported. The same study reports L-ferritin binding, so FTH1 and FTL cannot be distinguished as the preferred ligand [PMID:32907880].","key_references":[{"PMID":"32907880","why":"Biochemical binding of H- and L-ferritin to the SCARA5 SRCR domain"}],"covers":["LR002668"]},"LR005935":{"pair":"GAS1 -> PTPRA","headline":"GAS1 binds PTPRA directly by SPR (KD ~1 uM) and stains PTPRA-expressing cells; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"GAS1 bound PTPRA exclusively among tested RPTPs and tetramerised GAS1 bound K562 cells overexpressing PTPRA, which the authors interpret as GAS1 acting as a soluble ligand for cell-surface PTPRA [PMID:36178190]. Activating or inhibitory effect is not reported in our evidence.","molecular_requirements":"Full-length PTPRA was used in cells and the ectodomain for SPR; no PTPRU or PTPRJ binding was seen by SPR [PMID:36178190]. Co-receptor needs are not reported in our evidence.","affinity_potency":[{"value":"KD of ~1 uM","assay":"surface plasmon resonance","system":"human GAS1 analyte binding PTPRA ectodomain","cite":"PMID:36178190"}],"species_and_systems":"Human proteins: CRISPRa screen, SPR and cell-surface staining of K562 cells [PMID:36178190]. The mouse pair is projected from human evidence.","localisation_and_range":"GAS1 is flagged as non-secreted and as a receptor [flag], although the paper calls it a soluble ligand [PMID:36178190].","caveats":"Single paper from a high-throughput deorphanisation screen; affinity is low (micromolar). The curator evidence sentence is a figure legend describing the cell staining assay.","key_references":[{"PMID":"36178190","why":"CRISPRa screen, SPR and cell staining identifying GAS1-PTPRA"}],"covers":["LR002670","LR005935"]},"LR000679":{"pair":"GAS6 -> AXL","headline":"Well-supported direct agonist interaction: crystal structure, Kd binding and receptor activation, all in curator-verified papers.","interaction_type":"direct binding","direction_and_effect":"GAS6 is an agonist that activates AXL; Gas6 binds Axl and stimulates its phosphorylation [PMID:8939948], and a purified factor identified as the Gas6 product stimulated Axl [PMID:7854420]. Activation by GAS6 varies with context: soluble ligand, apoptotic cells, phosphatidylserine vesicles or enveloped virus [PMID:25074926].","molecular_requirements":"The crystal structure of a minimal human Gas6/Axl complex shows 2:2 stoichiometry; Gas6's first laminin G-like domain crosslinks two Axl immunoglobulin-like domains, and both a major and a minor contact site are needed for signalling [PMID:16362042]. The Gla domain and EGF-like repeats were not required for receptor binding; the G-domain region is sufficient to bind [PMID:8621659]. Gamma-carboxylation of ligands is essential for full TAM activation [PMID:25074926]. PDB structures exist [DB:PDB 2C5D] [DB:PDB 4RA0] [DB:PDB 5VXZ].","affinity_potency":[{"value":"Kd 0.4 nM","assay":"BIAcore kinetic analysis, rat Gas6 to Axl-Fc","system":"soluble receptor-Fc fusion","cite":"PMID:8939948"}],"species_and_systems":"Human Gas6 and human Axl in the structural and reporter studies [PMID:16362042] [PMID:25074926]; the Kd comes from rat Gas6 binding Axl-Fc, with activation tested in CHO cells [PMID:8939948]. The mouse pair is projected from human evidence.","localisation_and_range":"GAS6 is flagged secreted and AXL transmembrane [flag]; GAS6 can also bridge phosphatidylserine on apoptotic cells or virus envelope to AXL [PMID:25074926] [DB:UniProt].","caveats":"All papers were read as abstracts only. One further paper was review-only. Gas6 also binds other TAM receptors, so AXL signalling is not unique to this ligand [PMID:8939948].","key_references":[{"PMID":"16362042","why":"Crystal structure of the Gas6/Axl 2:2 complex"},{"PMID":"8939948","why":"Kd of Gas6 for Axl-Fc and Gas6-induced Axl phosphorylation"},{"PMID":"25074926","why":"Context-dependent TAM activation by GAS6 and need for gamma-carboxylation"}],"covers":["LR000679","LR004163"]},"LR002677":{"pair":"GDF10 -> BMPR1A","headline":"GDF10 binds a BMPR2/ALK3 receptor pair in mouse hepatic stellate cells; ALK3 alone is not shown sufficient.","interaction_type":"direct binding","direction_and_effect":"Autocrine GDF10 binds BMPR2/ALK3 to elicit SMAD1/5/8-SMAD7 signalling, which inhibits TGF-beta-SMAD2/3 signalling and suppresses stellate-cell activation [PMID:40125634]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"GDF10-Fc bound HEK293 cells overexpressing both Bmpr2 and Alk3 better than other single receptors or pairs; SPR showed dose-dependent binding to a BMPR2:ALK3-Fc heterodimer; knockdown of Bmpr2 and/or Alk3 abolished the effect [PMID:40125634]. ALK3 is therefore paired with BMPR2.","affinity_potency":[],"species_and_systems":"Primary mouse hepatic stellate cells, HEK293 transfectants and mouse receptor ectodomains; mouse and human liver expression [PMID:40125634].","localisation_and_range":"GDF10 is flagged secreted [flag]; the paper describes an autocrine loop in hepatic stellate cells [PMID:40125634].","caveats":"Single paper; binding to ALK3 alone is not separated from the BMPR2:ALK3 heterodimer. The paper words the receptor as 'potential'. No affinity number in our evidence. Human and mouse pairs are ortholog-inferred.","key_references":[{"PMID":"40125634","why":"BMPR2/ALK3 binding and signalling of GDF10 in stellate cells"}],"covers":["LR002677","LR005942"]},"LR005944":{"pair":"GDF10 -> TGFBR2","headline":"Cross-linking competition suggests GDF10 competes with TGF-beta1 for TbetaRII binding; evidence is a browser-read quote, not spot-checked.","interaction_type":"direct binding","direction_and_effect":"GDF10 selectively activated TbetaRI/II-dependent Smad3 phosphorylation [PMID:21518866]. The curator sentence says GDF10 competes with [125I]TGF-beta1 for TbetaRI (55 kDa), TbetaRII (70 kDa) and betaglycan [PMID:21518866].","molecular_requirements":"TbetaRI/II heterodimer needed for signalling; betaglycan also competes in cross-linking [PMID:21518866].","affinity_potency":[],"species_and_systems":"Mouse tumour-cell system per the abstract [PMID:21518866]; the human pair is ortholog-inferred.","localisation_and_range":"GDF10 is flagged secreted and non-transmembrane [flag], so signalling would be paracrine or autocrine; range not studied in our evidence.","caveats":"The binding sentence is a browser-read Results quote marked unverifiable with spot-check pending; the dossier abstract holds only the signalling claim. Competition does not show direct GDF10 binding. Three other screened papers had insufficient abstracts.","key_references":[{"PMID":"21518866","why":"GDF10-dependent TGF-beta receptor signalling and competition for receptor binding"}],"covers":["LR002679","LR005944"]},"LR000688":{"pair":"GDF11 -> ACVR2A","headline":"GDF11 binds ActRIIA (ACVR2A) and ActRIIB and induces Smad2 phosphorylation, with supporting structural and binding work.","interaction_type":"direct binding","direction_and_effect":"Gdf11 binds both ActRIIA and ActRIIB and induces Smad2 phosphorylation; the two receptors cooperate in axial vertebral patterning [PMID:12414726]. A 2022 study lists GDF11 among high-affinity ACVR2A growth factors [PMID:35643319].","molecular_requirements":"ActRIIA and ActRIIB can compensate for one another; the type I receptor is not established there [PMID:12414726].","affinity_potency":[],"species_and_systems":"Mouse genetics plus biochemistry [PMID:12414726]; human proteins in SPR and crystallography of ACVR2A with activin A [PMID:35643319].","localisation_and_range":"GDF11 flagged secreted and ACVR2A transmembrane [flag].","caveats":"Both papers are abstract-level for this pair. The 2022 crystal structure is of ACVR2A with activin A, not GDF11; GDF11 data come from SPR (80 nM injections) and no GDF11 affinity value is quoted in our evidence.","key_references":[{"PMID":"12414726","why":"Gdf11 binds ActRIIA and ActRIIB, Smad2 phosphorylation"},{"PMID":"35643319","why":"ACVR2A high-affinity ligand panel including GDF11"}],"covers":["LR000688","LR004172"]},"LR002686":{"pair":"GDF3 -> ACVR2B","headline":"GDF3 signalling involves ActRIIB (with ALK4 and Cripto) in reporter assays; binding is not shown.","interaction_type":"functional only","direction_and_effect":"GDF3 signalling can be mediated by ALK4, type II receptors ActRIIA and ActRIIB, and Cripto, activating Smad-dependent reporters [PMID:17936261]. Agonist [PMID:17936261][DB:GtoPdb].","molecular_requirements":"The paper tests the full set (ALK4, ActRIIA, ActRIIB, Cripto), so the role of this receptor alone is not separated; native GDF3 needs a heterologous prodomain, Furin or Nodal to signal [PMID:17936261].","affinity_potency":[],"species_and_systems":"Heterologous cell reporter assays; curators label human [PMID:17936261]. The human pair is ortholog-inferred and the mouse pair listed as direct.","localisation_and_range":"GDF3 is flagged secreted [flag]; the receptor is flagged transmembrane [flag].","caveats":"Abstract only. No direct binding data; the paper treats the type II receptors as a group.","key_references":[{"PMID":"17936261","why":"GDF3 signals via ALK4, ActRIIA/B and Cripto"}],"covers":["LR002686","LR005951"]},"LR000697":{"pair":"GDF5 -> ACVR2B","headline":"GDF5 binds ActR-IIB with nanomolar affinity in biosensor work, and in COS-1 cells; well supported.","interaction_type":"direct binding","direction_and_effect":"GDF5 binds preferentially to BMPR-IB and ActR-IIB [PMID:19735544]. GDF-5 also bound ActR-IIB in COS-1 transfectants [PMID:8702914]. Agonist per curators [PMID:8702914].","molecular_requirements":"Binding was measured with immobilised receptor ectodomains; CHAPS changed affinities and specificities [PMID:19735544]. Whether ActR-IIB acts with a type I partner is not reported in our evidence.","affinity_potency":[{"value":"KD (kin) 4.0 \u00b1 1.24 nM; KD (eq) 5.6 \u00b1 0.90 nM","assay":"biosensor (kinetic and equilibrium)","system":"GDF-5 over immobilised ActR-IIB ectodomain","cite":"PMID:19735544"}],"species_and_systems":"Recombinant ectodomain biosensor and COS-1 transfectants; curators label human [PMID:19735544][PMID:8702914].","localisation_and_range":"The receptor is flagged transmembrane [flag].","caveats":"Two of four confirmed rows shown. The biosensor used high salt buffer (500 mM NaCl) [PMID:19735544].","key_references":[{"PMID":"19735544","why":"Biosensor kinetics of GDF5 with type II receptors"},{"PMID":"8702914","why":"GDF-5 binds ActR-IIB in COS-1 cells"}],"covers":["LR000697","LR004181"]},"LR005953":{"pair":"GDF6 -> ACVR2B","headline":"GDF6 binds the type II receptor ACVR2B with affinity similar to type I receptors, by recombinant binding; one paper.","interaction_type":"direct binding","direction_and_effect":"rhBMP13 (GDF6 alias) bound ACVR2B [PMID:21702718]. Despite similar binding to BMP2, BMP12/BMP13 induced a tendon marker (Thbs4) without detectable SMAD1/5/8 activation in C3H10T1/2 cells [PMID:21702718].","molecular_requirements":"ACVR2B is a type II receptor; ALK3 and ALK6 bound with high affinity as type I partners [PMID:21702718]. Whether ACVR2B acts alone is not reported in our evidence.","affinity_potency":[{"value":"KD (kin) 1.6 nM","assay":"Bio-Layer Interferometry, immobilised ACVR2B-Fc, rhBMP13 (GDF6 alias)","system":"recombinant proteins","cite":"PMID:21702718"}],"species_and_systems":"Recombinant proteins in vitro and C3H10T1/2 cells [PMID:21702718]. Human pair listed directly; mouse pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag]; range beyond that is not reported in our evidence.","caveats":"Only one paper; the ligand mapping (GDF6 = BMP13) rests on alias names. The paper states ACVR2B affinity for BMP12/BMP13 is similar to that of type I receptors [PMID:21702718]. No database records.","key_references":[{"PMID":"21702718","why":"Binding of rhBMP13 (GDF6) to ACVR2B"}],"covers":["LR002688","LR005953"]},"LR004189":{"pair":"GDF7 -> ACVR2A","headline":"GDF7 binds ACVR2A directly (KD 17.1 nM for rhBMP12) with functional support.","interaction_type":"direct binding","direction_and_effect":"Binding: rhBMP12 (GDF7) bound ACVR2A with similar affinity to rhBMP13 (GDF6) [PMID:21702718]. ActRIIA shRNA suppressed GDF7-induced Smad1/5/8 signalling in MC3T3 cells [PMID:16049014]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Type II receptors act with a type I partner: ALK3 or ALK6 overexpression conferred GDF7 signalling [PMID:16049014].","affinity_potency":[{"value":"KD 17.1 nM","assay":"surface plasmon resonance, KD (kin), rhBMP12 (GDF7) vs ACVR2A ectodomain-Fc","system":"recombinant human proteins","cite":"PMID:21702718"}],"species_and_systems":"Recombinant human BMP12 and receptor ectodomains in binding assays; musculoskeletal marker assays in C3H10T1/2 cells and rat ectopic implants [PMID:21702718]. Signalling studies in COS7 and MC3T3 cells [PMID:16049014]. The mouse pair is projected from human evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"Binding is not the same as activation: rhBMP12 gave no detectable SMAD1/5/8 activation in C3H10T1/2 cells at low dose [PMID:21702718], whereas Smad1/5/8 reporters were activated in MC3T3 cells [PMID:16049014]. ACVR2A binding was more than 10-fold weaker than type I binding. rhBMP12 is mapped to GDF7 via alternate names [PMID:16049014]. Both papers are abstract-only reads.","key_references":[{"PMID":"21702718","why":"Kinetic binding of rhBMP12 (GDF7) to type I and II receptors."},{"PMID":"16049014","why":"Receptor requirements for GDF7 signalling."}],"covers":["LR000705","LR004189"]},"LR010975":{"pair":"GDF9 -> ACVR1C","headline":"GDF9 -> ACVR1C rests on a GtoPdb agonist record alone; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb records the interaction as Agonist, action Agonist, with no affinity units [DB:GtoPdb]. No curator-verified paper supports it.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted and the receptor chain(s) as receptor [flag], which would imply paracrine signalling to a membrane receptor; localisation is not otherwise reported in our evidence.","caveats":"Support is a database assertion only. Two papers were judged abstract-insufficient.","key_references":[],"covers":["LR010975"]},"LR004198":{"pair":"Gh -> Prlr","headline":"Weak for mouse: evidence is a human GH-human PRLR crystal structure projected to the mouse pair.","interaction_type":"direct binding","direction_and_effect":"hGH binds both hGHR and hPRLR, and the crystal structure of the 1:1 complex of hGH bound to the hPRLR extracellular domain was presented [PMID:7984244].","molecular_requirements":"hGH binds hPRLR as a 1:1 complex with the receptor extracellular domain [PMID:7984244].","affinity_potency":[],"species_and_systems":"Human GH and human PRLR extracellular domain; the mouse pair is ortholog-inferred, so no mouse experiment is in our evidence [PMID:7984244].","localisation_and_range":"GH is flagged secreted [flag].","caveats":"Abstract only; one paper; no affinity value in the dossier. A second paper was abstract_insufficient.","key_references":[{"PMID":"7984244","why":"Crystal structure of hGH-hPRLR complex"}],"covers":["LR004198"]},"LR009481":{"pair":"GNAI2 -> CXCR1","headline":"GNAI2-CXCR1 is supported only by database interaction records; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists affinity capture-Western records [DB:BioGRID][PMID:8903513][PMID:8662698]; UniProt says GNAI2 interacts with CXCR1 and CXCR2 [DB:UniProt][PMID:8662698]. Direction and effect as a ligand-receptor pair not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Receptor flagged transmembrane where annotated [flag]; otherwise not reported in our evidence.","caveats":"No paper confirmed; judged papers were different_entity, abstract_insufficient, unresolvable or review_only. The records describe protein association, not a ligand activating a receptor.","key_references":[],"covers":["LR009481"]},"LR008518":{"pair":"GNAS -> TSHR","headline":"Database-asserted only: UniProt lists TSHR as interacting with GNAS; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Assay and species not reported in our evidence [PMID:35940205][PMID:35940204].","localisation_and_range":"TSHR is annotated as a transmembrane receptor [flag]; GNAS is intracellular.","caveats":"No paper in our evidence supports this pair; it rests on database records alone. One curated judgement: 'different_entity'.","key_references":[],"covers":["LR008518"]},"LR002695":{"pair":"GP1BA -> ITGAM","headline":"Direct, mapped binding of GP Ibalpha to the alphaM I domain of Mac-1, with strong gain-of-function evidence (human).","interaction_type":"direct binding","direction_and_effect":"GP Ibalpha binding to Mac-1 (alphaM beta2) is mapped to the P201-K217 sequence of the alphaM I domain: swapping it for alphaL sequence abolished adhesion, and grafting it onto alphaL made alphaL beta2 bind GP Ibalpha [PMID:14530377]. Synthetic P201-K217 peptide bound GP Ibalpha directly and blocked alphaM beta2 adhesion [PMID:14530377]. Effect is adhesion; agonist/antagonist role not reported in our evidence.","molecular_requirements":"The alphaM I domain carries the binding site (recombinant alphaMI domains were tested). Intact Mac-1 is the alphaM beta2 heterodimer; whether beta2 is needed for binding is not reported in our evidence [PMID:14530377].","affinity_potency":[],"species_and_systems":"Human proteins; alphaM beta2-expressing 293 cells and THP-1 cells with soluble GP Ibalpha (full text) [PMID:14530377]. Mouse pair is ortholog-inferred.","localisation_and_range":"GP Ibalpha is the platelet counter receptor and Mac-1 is on leukocytes, so contact-dependent platelet-leukocyte adhesion [PMID:14530377]; both are annotated non-secreted [flag].","caveats":"One paper only, with an experimental-system claim from excerpts; no affinity reported in our evidence.","key_references":[{"PMID":"14530377","why":"Maps the GP Ibalpha binding site to alphaM P201-K217"}],"covers":["LR002695","LR005960"]},"LR005962":{"pair":"GPC1 -> LRRTM4","headline":"Glypicans bind LRRTM4 in a heparan-sulfate-dependent manner; GPC1 was detected among five glypicans in LRRTM4-Fc pulldowns.","interaction_type":"direct binding","direction_and_effect":"Glypican acts as a presynaptic partner of postsynaptic LRRTM4 in a trans-synaptic interaction; the abstract calls glypican a receptor for LRRTM4. LRRTM4 positively regulates excitatory synapse development, and its synaptogenic activity requires neuronal-surface heparan sulfate [PMID:23911103].","molecular_requirements":"Binding is heparan-sulfate (HS) dependent and selective for LRRTM4 over LRRTM2 [PMID:23911103]. LRRTM4-Fc bound strongly to all glypican isoforms tested in cell-surface assays [PMID:23911103]. LRRTM4 forms separate complexes with neurexin and glypican, not a tripartite complex (GPC4 data) [PMID:23911103].","affinity_potency":[],"species_and_systems":"Rat brain homogenate pulldown, HA-tagged mouse glypican cDNAs in HEK293T cells, cultured hippocampal neurons [PMID:23911103]; the curators labelled the experiment species human. Pair is ortholog-inferred for both species.","localisation_and_range":"Glypican is a GPI-anchored HSPG (full text) and annotated as secreted [flag]; LRRTM4 is a transmembrane receptor [flag]. Interaction is trans-synaptic and needs local glypican concentration, since soluble GPC4 did not induce LRRTM4 clustering [PMID:23911103].","caveats":"Paper-level evidence is for 'glypican' as a class. GPC1 was detected in the LRRTM4-Fc mass spectrometry sample (Figure S1A) and the abstract does not name it [PMID:23911103]. Direct cell-free binding was shown for GPC4 only. Abstract plus excerpts.","key_references":[{"PMID":"23911103","why":"Unbiased discovery of glypican-LRRTM4 binding and its role in synapse development"}],"covers":["LR002697","LR005962"]},"LR005971":{"pair":"GPR15LG -> CXCR4","headline":"GPR15LG binds CXCR4 at the orthosteric site, but acts as a modulator or biased antagonist, not a plain agonist.","interaction_type":"conflicting","direction_and_effect":"The abstract says GPR15LG binds the orthosteric site of CXCR4 and enhances CXCL12-mediated signalling synergistically, boosting migration of CD4+ T cells and cancer cells [PMID:40394646]. The full text adds that GPR15LG did not activate CXCR4 in primary CD4+ T cells (no Akt/Erk activation), and acts as a biased antagonist of beta-arrestin-2 recruitment and internalisation [PMID:40394646].","molecular_requirements":"Binding needs the CXCR4 N-terminus: deleting residues 2-29 strongly reduced binding, and D181A reduced it [PMID:40394646].","affinity_potency":[{"value":"IC50 829 \u00b1 139 nM","assay":"competition with labelled CXCL12","system":"CXCR4 cells","cite":"PMID:40394646"},{"value":"IC50 1.3 \u00b1 0.1 \u00b5M","assay":"competition with anti-CXCR4 antibody 12G5","system":"SupT1 cells","cite":"PMID:40394646"}],"species_and_systems":"Human proteins; SupT1 cells, primary human CD4+ T cells, HIV-1 infection assays and molecular dynamics modelling [PMID:40394646].","localisation_and_range":"GPR15LG is flagged as secreted [flag].","caveats":"Single paper. Effect direction is context dependent and depends on the readout. Binding rests on competition assays and simulation, not direct affinity measurement. A second pair (GPR15LG with ACKR3) was modelled but not supported by competition [PMID:40394646].","key_references":[{"PMID":"40394646","why":"Binding, competition IC50 values and functional modulation of CXCR4"}],"covers":["LR002706","LR005971"]},"LR005188":{"pair":"GRN -> TNFRSF1A","headline":"Progranulin is reported to bind TNFR1 directly and antagonise TNF-alpha, from one mouse-focused paper.","interaction_type":"direct binding","direction_and_effect":"PGRN bound directly to TNF receptors and disturbed the TNF\u03b1-TNFR interaction; the authors call PGRN an antagonist of TNF\u03b1 signalling [PMID:21393509].","molecular_requirements":"The abstract says 'TNFRs' in plural; it does not separate TNFR1 from TNFR2. Atsttrin, an engineered protein of three PGRN fragments, showed selective TNFR binding [PMID:21393509].","affinity_potency":[],"species_and_systems":"The study is largely mouse in vivo (PGRN-deficient mice, collagen-induced arthritis) [PMID:21393509]. The human pair is ortholog-inferred. IntAct lists two-hybrid and pull-down records [DB:IntAct].","localisation_and_range":"GRN is flagged secreted; TNFRSF1A is flagged as a transmembrane receptor [flag].","caveats":"Only an abstract was read; receptor-specific (TNFR1) binding is inferred from a plural statement. Orthogonal TNFR1 evidence is database-only.","key_references":[{"PMID":"21393509","why":"PGRN binds TNFRs and blocks TNF\u03b1"}],"covers":["LR001833","LR005188"]},"LR006808":{"pair":"GUCA1A -> GUCY2D","headline":"GCAP1 regulates retinal guanylyl cyclase RetGC1; our curated paper supports it only indirectly via disease mutants.","interaction_type":"functional only","direction_and_effect":"GtoPdb lists GUCA1A as an activator of GUCY2D [DB:GtoPdb]. The curated paper treats RetGC1:GCAP1 as a complex whose deregulated activity elevates cGMP in the dark [PMID:39909376].","molecular_requirements":"Full-text excerpts describe RetGC1 as regulated by GCAP1 and GCAP2, and GCAP1 as the main calcium sensor of RetGC1 (cited as prior work) [PMID:39909376].","affinity_potency":[],"species_and_systems":"Transgenic mouse rods (R838S RetGC1, Y99C GCAP1) with ectopic PDE5; a rescue study, not a binding or activation assay [PMID:39909376].","localisation_and_range":"Not a conventional secreted ligand: GCAP1 is an intracellular calcium sensor acting on the cyclase's intracellular side [PMID:39909376]; no localisation flag given.","caveats":"The paper tests disease mutants and PDE5 rescue, not GCAP1-RetGC1 interaction itself. An additional paper was classed review-only.","key_references":[{"PMID":"39909376","why":"RetGC1/GCAP1 deregulation and PDE5 rescue in mouse rods"}],"covers":["LR006808"]},"LR006763":{"pair":"H60b -> Klrk1","headline":"H60b is a mouse NKG2D ligand identified by NKG2D-Ig binding and NK-cell target susceptibility.","interaction_type":"direct binding","direction_and_effect":"H60 family proteins are GPI-anchored cell-surface ligands for mouse activating NKG2D; ectopic RAE-1 and H60 expression confers NK-cell target susceptibility [PMID:10894171].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse ligand and receptor; mNKG2D-Ig fusion protein used to identify ligands [PMID:10894171].","localisation_and_range":"GPI-anchored cell-surface protein, so contact-dependent (juxtacrine) signalling [PMID:10894171]; entity flagged not secreted [flag].","caveats":"No affinity reported. The family is treated together in the paper; the excerpts do not separate H60a, H60b and H60c individually.","key_references":[{"PMID":"10894171","why":"RAE-1/H60 family as NKG2D ligands"}],"covers":["LR006763"]},"LR010768":{"pair":"HBEGF -> EGFR:ERBB2","headline":"Complex entry rests on EGFR-only binding evidence; no heterodimer data in our evidence.","interaction_type":"direct binding","direction_and_effect":"The one curated paper shows synthetic HB-EGF(44-86) binding EGFR on A431 cells [PMID:12725245]. Effect of ERBB2 in the complex is not reported in our evidence.","molecular_requirements":"Only EGFR was tested; ERBB2 requirement is not reported in our evidence. Database records (BioGRID, IntAct, Reactome) concern EGFR/HBEGF [DB:BioGRID][DB:IntAct].","affinity_potency":[],"species_and_systems":"Human A431 cells, synthetic peptide [PMID:12725245].","localisation_and_range":"Not reported in our evidence beyond flags [flag].","caveats":"Evidence supports the EGFR chain alone, not the EGFR:ERBB2 complex. Abstract only.","key_references":[{"PMID":"12725245","why":"EGFR binding of the HB-EGF EGF-like domain"}],"covers":["LR010768"]},"LR000769":{"pair":"HP -> ITGAM","headline":"Haptoglobin binds the CD11b/CD18 integrin on monocytic cells; evidence is chain-level for ITGAM (CD11b) from one 1996 paper.","interaction_type":"direct binding","direction_and_effect":"Haptoglobin binds purified CD11b/CD18, indicating direct binding; anti-CD11b mAb44 inhibits haptoglobin binding to THP1/U937 cells, and an anti-CD18 mAb partly inhibits it [PMID:8786317]. Binding was increased by Ca2+/ADP and inhibited by fibrinogen [PMID:8786317].","molecular_requirements":"The functional receptor is the CD11b/CD18 heterodimer; CD11b antibody blocking is the stronger evidence, with CD18 involvement only partial [PMID:8786317]. No interference from anti-CD11a or anti-CD11c mAbs [PMID:8786317].","affinity_potency":[{"value":"Kd 6.5 x 10(-6)","assay":"radioiodinated haptoglobin binding, one receptor class, 1.7 x 10(5) sites per cell (low affinity)","system":"human THP1 cells","cite":"PMID:8786317"}],"species_and_systems":"Human haptoglobin and human monocytic cell lines (THP1, U937), monocytes and granulocytes [PMID:8786317]. The mouse pair is ortholog-inferred.","localisation_and_range":"HP is flagged as secreted [flag].","caveats":"Abstract-only reading. The affinity was measured on whole cells, not on the single chain. One further row is pending.","key_references":[{"PMID":"8786317","why":"Haptoglobin binds CD11b/CD18 on THP1 cells and purified integrin"}],"covers":["LR000769","LR004228"]},"LR008194":{"pair":"HP -> ITGAM:ITGB2","headline":"Haptoglobin binds the CD11b/CD18 complex on THP1 cells with low affinity; one 1996 paper.","interaction_type":"direct binding","direction_and_effect":"Radioiodinated haptoglobin binds a single class of receptors on THP1 cells, with binding increased by Ca2+ [PMID:8786317]. Fluorescein-haptoglobin also binds monocytes, granulocytes, a CD8+ T-cell subset and NK cells [PMID:8786317].","molecular_requirements":"The receptor is the ITGAM:ITGB2 heterodimer (CD11b/CD18); whole-cell binding does not separate the chains [PMID:8786317].","affinity_potency":[{"value":"Kd 6.5 x 10(-6)","assay":"radioiodinated haptoglobin binding, 1.7 x 10(5) sites per cell (low affinity); curator note gives 6.5 uM","system":"human THP1 cells","cite":"PMID:8786317"}],"species_and_systems":"Human cells and human haptoglobin [PMID:8786317].","localisation_and_range":"HP is flagged as secreted [flag].","caveats":"Abstract-only reading. Low affinity.","key_references":[{"PMID":"8786317","why":"Haptoglobin binds CD11b/CD18; Kd on THP1 cells"}],"covers":["LR008194"]},"LR000778":{"pair":"HSPG2 -> ITGB1","headline":"Recombinant perlecan domain V promotes cell adhesion blocked by anti-integrin beta1 antibodies (abstract only); functional, not direct binding.","interaction_type":"functional only","direction_and_effect":"Recombinant perlecan fragment V, but not fragment Vc, promoted adhesion of several cell lines, and this was blocked by antibodies against the integrin beta1 chain [PMID:9431988]. Reactome lists endorepellin binding alpha2beta1 integrin, which includes ITGB1 [DB:Reactome R-HSA-4088236].","molecular_requirements":"Domain V (three LG and four EG modules) is the active region; beta1 is paired with an alpha chain, but the alpha partner in this paper is not reported in our evidence [PMID:9431988].","affinity_potency":[],"species_and_systems":"Human recombinant domain V produced in embryonic kidney cells; cell-line identities are not reported in our evidence [PMID:9431988]. Mouse pair is ortholog-inferred.","localisation_and_range":"Perlecan is flagged secreted [flag]; the paper concerns a matrix cell-adhesion site, so it is contact or matrix-mediated [PMID:9431988].","caveats":"Abstract only. Antibody blockade of adhesion does not show direct binding, and the abstract notes this domain may be only one of several adhesive sites. Two other papers were abstract_insufficient.","key_references":[{"PMID":"9431988","why":"Perlecan domain V adhesion blocked by anti-beta1 integrin antibodies"}],"covers":["LR000778","LR004236"]},"LR002758":{"pair":"IBSP -> ITGB5","headline":"Integrin beta5 (alphaVbeta5) mediates BSP-RGD adhesion and proliferation in breast cancer cells; one abstract.","interaction_type":"functional only","direction_and_effect":"Blocking antibodies showed adhesion and proliferation responses to BSP-RGD were alpha(v)beta5-mediated, while migration used alpha(v)beta3 [PMID:9699501].","molecular_requirements":"Receptor is the alphaV/beta5 heterodimer; ITGB5 alone is not shown.","affinity_potency":[],"species_and_systems":"Human MDA-MB-231 breast cancer cells [PMID:9699501]. Mouse pair is ortholog-inferred.","localisation_and_range":"IBSP is flagged secreted [flag].","caveats":"Abstract only; antibody blocking is indirect. No database records for ITGB5 in our evidence.","key_references":[{"PMID":"9699501","why":"alpha(v)beta5 used for BSP-RGD adhesion and proliferation"}],"covers":["LR002758","LR006005"]},"LR000787":{"pair":"ICAM1 -> ITGB2","headline":"ICAM-1 binds beta2 integrins (LFA-1, CD11c/CD18) with direct-binding support, but ITGB2 alone is a shared chain, not a specific partner.","interaction_type":"direct binding","direction_and_effect":"ICAM-1 acts as an agonist/adhesion ligand: direct binding to sLFA-1 [PMID:9780171], to CD11c/CD18 [PMID:16252253] and an LFA-1 alpha-chain binding region [PMID:7642561]; ICAM-1/CD18 engagement was needed for macrophage-mediated myeloma drug resistance in vitro and in a SCID mouse model [PMID:22996336].","molecular_requirements":"ITGB2 pairs with different alpha chains: the binding data are for LFA-1 (alphaL) and alphaX heterodimers, and the ICAM-1 D1D2 fragment sufficed for LFA-1 binding [PMID:9780171]. In the myeloma study, antibodies to CD11a, CD11b or CD11c did not affect the protective effect, so the alpha partner there is unresolved [PMID:22996336].","affinity_potency":[{"value":"Kd 500 nM","assay":"surface plasmon resonance, monomeric sLFA-1 binding to ICAM-1 D1D2-IgG chimera; k(diss) 0.1 s(-1)","system":"soluble human LFA-1","cite":"PMID:9780171"}],"species_and_systems":"Human proteins and cells; the myeloma study also used a human myeloma-SCID mouse model [PMID:22996336]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound adhesion on cell contact (the myeloma effect was cell-contact based [PMID:22996336]); ICAM1 also carries a secreted flag [flag].","caveats":"Most papers were read as abstracts. Seven confirmed and eight abstract_insufficient rows; only a subset is shown. BioGRID and UniProt support ICAM1-ITGB2 and LFA-1/Mac-1 receptor roles [DB:BioGRID][DB:UniProt].","key_references":[{"PMID":"9780171","why":"Kd 500 nM for sLFA-1 binding ICAM-1 D1D2"},{"PMID":"16252253","why":"SPR for ICAM-1 with CD11c/CD18"},{"PMID":"22996336","why":"Functional ICAM-1/CD18 role in myeloma drug resistance, in vitro and in vivo"}],"covers":["LR000787","LR004245"]},"LR010858":{"pair":"ICAM2 -> ITGAM:ITGB2","headline":"Mac-1 binding by an ICAM-2 peptide is cited as prior work in the one supporting paper; weak, indirect support.","interaction_type":"functional only","direction_and_effect":"An ICAM-2 first-Ig-domain peptide (P1) binds Mac-1 (CD11b/CD18) as well as LFA-1 and activates CD11/CD18-dependent adhesion; soluble ICAM-2Fc was a more potent activator than ICAM-1Fc or ICAM-3Fc [PMID:10352278].","molecular_requirements":"Mac-1 is ITGAM:ITGB2; the dossier does not separate subunit contributions.","affinity_potency":[],"species_and_systems":"Human T lymphocytes with purified immobilised ICAMs [PMID:10352278].","localisation_and_range":"Membrane-bound; contact-dependent.","caveats":"The Mac-1 binding statement is framed as previous findings, not this paper's result, and it was read as abstract only [PMID:10352278]. Database records shown concern LFA-1, not Mac-1 [DB:UniProt][DB:Reactome].","key_references":[{"PMID":"10352278","why":"ICAM-2 peptide P1 and ICAM-2Fc activate CD11/CD18 adhesion"}],"covers":["LR010858"]},"LR000796":{"pair":"ICAM4 -> ITGA4","headline":"Single abstract-only study: alpha4beta1-dependent cell adhesion to ICAM-4-Fc, inferred from blocking experiments.","interaction_type":"functional only","direction_and_effect":"Adhesion of haemopoietic cell lines to ICAM-4-Fc was inhibited by LDV peptide and antibodies, identifying alpha4beta1 as the integrin; ICAM-4 is described as the first ICAM family member that is a ligand for non-beta2 integrins [PMID:11435317].","molecular_requirements":"The evidence points to the alpha4/beta1 heterodimer. Neither the LETS nor the LDV motif in ICAM-4 domain 1 was critical for integrin binding [PMID:11435317].","affinity_potency":[],"species_and_systems":"Human haemopoietic and non-haemopoietic cell lines with an ICAM-4-Fc construct [PMID:11435317]; the mouse pair is ortholog-inferred.","localisation_and_range":"ICAM4 carries both secreted and transmembrane flags [flag], so range is unclear; the papers used recombinant ICAM-4-Fc and cell-surface ICAM-4, consistent with contact-dependent adhesion.","caveats":"One paper, abstract only, with no database support. Evidence is peptide and antibody inhibition of adhesion, not purified-protein binding. Affinity not reported.","key_references":[{"PMID":"11435317","why":"ICAM-4-Fc adhesion mediated by alpha4beta1"}],"covers":["LR000796","LR004250"]},"LR005197":{"pair":"Icos -> Icosl","headline":"Mouse pair inferred from human evidence; the only paper is a functional human DC study, with binding backed by human database records.","interaction_type":"direct binding","direction_and_effect":"ICOS-Fc triggering of B7h (ICOSL) on human monocyte-derived dendritic cells raised IL-23 and IL-10, increased IL-17A/IL-17F in MLCs, and inhibited DC adhesion to endothelial cells, migration and beta-Pix expression [PMID:23275603]. Curated as antagonist, though the effects are mixed.","molecular_requirements":"The ICOS-ICOSL binding is stated in this paper only as background [PMID:23275603]. Database records: SPR, far western and solid-phase assays, BioGRID reconstituted complex, PDB 6X4G, Reactome [DB:IntAct, DB:BioGRID, DB:PDB 6X4G, DB:Reactome].","affinity_potency":[],"species_and_systems":"Experiments used human cells and human ICOS-Fc [PMID:23275603]; the database records carry human accessions. No mouse experiments in our evidence.","localisation_and_range":"Icos carries secreted, receptor flags and Icosl a receptor flag [flag]; ICOS-Fc was used as a soluble reagent, otherwise not reported.","caveats":"One paper, abstract only; mouse interaction is ortholog-inferred. Affinity not reported.","key_references":[{"PMID":"23275603","why":"ICOS-Fc triggering of B7h alters human dendritic cell function"}],"covers":["LR005197"]},"LR001849":{"pair":"ICOS -> ICOSLG","headline":"Direct binding is supported by database records (SPR, structure); the curated paper shows functional effects of ICOS-Fc on human dendritic cells.","interaction_type":"direct binding","direction_and_effect":"ICOS-Fc triggering of B7h (ICOSLG) on human monocyte-derived DCs raised IL-23 and IL-10, increased IL-17A/IL-17F in MLCs and inhibited DC adhesion to endothelial cells, migration and beta-Pix expression [PMID:23275603]. UniProt: ICOS delivers costimulatory signals on binding ICOSL on antigen-presenting cells [DB:UniProt].","molecular_requirements":"Database evidence for the complex: SPR and far western blotting, BioGRID reconstituted complex, PDB 6X4G, Reactome ICOS:ICOSL [DB:IntAct, DB:BioGRID, DB:PDB 6X4G, DB:Reactome].","affinity_potency":[],"species_and_systems":"Human ICOS-Fc and human DCs [PMID:23275603].","localisation_and_range":"ICOS carries secreted, receptor and transmembrane flags and ICOSLG receptor and transmembrane flags [flag]: membrane-bound contact signalling, with ICOS-Fc as a soluble reagent.","caveats":"The paper is abstract only and states the binding as background; one further row was review-only. Affinity not reported in our evidence.","key_references":[{"PMID":"23275603","why":"ICOS-Fc triggering of B7h on human DCs"}],"covers":["LR001849"]},"LR007276":{"pair":"IFNA5 -> IFNAR1:IFNAR2","headline":"IFNA5 to the IFNAR1:IFNAR2 heterodimer rests on class-wide binding data for each chain.","interaction_type":"direct binding","direction_and_effect":"Alpha-IFNs, as a class of 12 human subtypes, bind IFNAR1 at 0.5-5 \u03bcM and IFNAR2 at 0.4-5 nM [PMID:21856167]. GtoPdb lists IFNA5 as an agonist at both chains [DB:GtoPdb].","molecular_requirements":"Both chains are listed; each binds separately, IFNAR2 much more tightly [PMID:21856167]. Binding to the assembled heterodimer is not reported in our evidence.","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"IFNAR1 chain affinity for human alpha-IFN subtypes (class-wide; subtype not individually named in abstract)","system":"isolated human receptor chains","cite":"PMID:21856167"},{"value":"0.4-5 nM","assay":"IFNAR2 chain affinity for human alpha-IFN subtypes (class-wide; IFN-alpha1 220 nM)","system":"isolated human receptor chains","cite":"PMID:21856167"}],"species_and_systems":"Human alpha-IFN subtypes and human isolated receptor chains; affinity determination, abstract only [PMID:21856167].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Single verified paper, abstract only, class-wide values with no value for IFNA5; one further row was review only and one abstract_insufficient.","key_references":[{"PMID":"21856167","why":"Class-wide affinities of 12 human alpha-IFN subtypes for IFNAR1 and IFNAR2 (abstract only)."}],"covers":["LR007276"]},"LR002767":{"pair":"IGF1 -> ITGB3","headline":"Integrin alphavbeta3 directly binds IGF-1 in one verified study; ITGB3 is the beta chain.","interaction_type":"direct binding","direction_and_effect":"alphavbeta3 specifically and directly bound IGF-1 in cell adhesion, ELISA-type binding and surface plasmon resonance studies; the R36E/R37E mutant lost integrin binding but kept IGF1R binding, and wild-type IGF-1 mediated an alphavbeta3-IGF1R ternary complex [PMID:19578119].","molecular_requirements":"The alphavbeta3 heterodimer was tested; ITGB3 alone is not shown. UniProt records the ternary complex [DB:UniProt].","affinity_potency":[],"species_and_systems":"Cells and species other than Chinese hamster ovary cell proliferation are not reported in our evidence [PMID:19578119].","localisation_and_range":"IGF1 is flagged secreted [flag].","caveats":"Abstract-only read; no affinity value is reported in our evidence.","key_references":[{"PMID":"19578119","why":"Direct alphavbeta3-IGF-1 binding"}],"covers":["LR002767","LR006013"]},"LR010939":{"pair":"IGFBP3 -> IGF1","headline":"Well-documented IGFBP3-IGF1 binding in databases, including a ternary-complex structure; no curated paper, classed as ligand-ligand.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as inhibitory, interaction class Ligand-Ligand (a binding protein, not a receptor). Reactome lists formation of the IGF:IGFBP3:ALS complex [DB:Reactome].","molecular_requirements":"IGF1 forms a ternary complex with IGFBP3 and ALS [DB:UniProt]; a human IGF1/IGFBP3/ALS ternary complex structure is deposited [DB:PDB 7WRQ]. UniProt notes IGFBP3 binds IGF2 more than IGF1 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human only; BioGRID lists reconstituted complex and affinity-capture Western; IntAct lists bio-layer interferometry [DB:BioGRID][DB:IntAct].","localisation_and_range":"Both partners are annotated as secreted [flag].","caveats":"No curator-verified paper (eight candidates judged as a different entity). Evidence is database records only; no affinity reported.","key_references":[],"covers":["LR010939"]},"LR002776":{"pair":"IGFBP7 -> CD93","headline":"A human CD93-IGFBP7 complex structure maps binding to CD93 EGF1 and the IGFBP7 IB domain (preprint abstract).","interaction_type":"direct binding","direction_and_effect":"CD93 acts as a receptor for IGFBP7 on endothelial cells, where the axis mediates angiogenesis and migration; curator effect: agonist [PMID:37333140]. UniProt also describes CD93 as a receptor for IGFBP7 [DB:UniProt].","molecular_requirements":"Binding is between the EGF 1 domain of CD93 and the IB domain of IGFBP7; mutagenesis confirmed the interactions [PMID:37333140]. A structure is deposited [DB:PDB 8IVD].","affinity_potency":[],"species_and_systems":"Human proteins; cellular and mouse tumour studies reported for physiological relevance [PMID:37333140].","localisation_and_range":"IGFBP7 is annotated as secreted and CD93 as transmembrane [flag]; the paper says CD93 protrudes from the cell surface [PMID:37333140].","caveats":"Abstract-only read of a bioRxiv preprint; no affinity reported. The 'agonist' label comes from the curator, and the abstract describes blockade of the axis as favourable.","key_references":[{"PMID":"37333140","why":"Human CD93-IGFBP7 complex structure and mutagenesis"}],"covers":["LR002776","LR006022"]},"LR007267":{"pair":"IGFL2 -> IGFLR1","headline":"Verified negative: IGFL2 failed to bind IGFLR1 with high affinity by SPR.","interaction_type":"conflicting","direction_and_effect":"No effect reported. The paper states IGFL2 and IGFL4 failed to interact with IGFLR1 with high affinity [PMID:21454693]; IGFL2 gave only a low SPR response with fast dissociation per the curator note.","molecular_requirements":"Not applicable.","affinity_potency":[],"species_and_systems":"Human FLAG-tagged IGFL paralogues against immobilized IGFLR1-Fc by SPR [PMID:21454693].","localisation_and_range":"IGFL2 is annotated as secreted and IGFLR1 as transmembrane [flag].","caveats":"A curator-verified negative (pair_absent), correcting an earlier confirmed verdict. The IntAct SPR record for this pair comes from the same paper and should not be read as support [DB:IntAct]. Weak binding is not excluded.","key_references":[{"PMID":"21454693","why":"States IGFL2 did not bind IGFLR1 with high affinity"}],"covers":["LR007267"]},"LR004279":{"pair":"IHH -> CDON","headline":"Crystal structures and binding show all mammalian Hh proteins, including IHH, bind CDO (CDON); abstract only.","interaction_type":"direct binding","direction_and_effect":"X-ray structures of Hh proteins with the active domains of CDO and BOC show that all mammalian Hh proteins bind them in the same manner; Hh-CDO interaction is weakened at low pH [PMID:20519495]. CDO binds Sonic Hh with micromolar affinity and positively regulates Hh signalling, according to the abstract's background [PMID:20519495].","molecular_requirements":"Binding is through the CDO active domain [PMID:20519495]. Other requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant proteins; the PDB entry 3N1F holds Q14623 (IHH) with Q4KMG0 (CDON) [DB:PDB 3N1F]. Mouse pair is ortholog-inferred.","localisation_and_range":"IHH is flagged secreted and transmembrane [flag]; range from annotation only.","caveats":"Abstract only; IHH-specific affinity is not given. The micromolar figure refers to Sonic Hh and background, not IHH.","key_references":[{"PMID":"20519495","why":"Structures of Hh proteins with CDO and BOC"}],"covers":["LR000849","LR004279"]},"LR004288":{"pair":"IL12A -> IL12RB2","headline":"IL12A-IL12RB2 is supported by direct binding data and a cryo-EM structure, though the ligand is really the IL12A:IL12B heterodimer.","interaction_type":"direct binding","direction_and_effect":"IL-12 induced heterodimerization of IL-12Rbeta1 and IL-12Rbeta2 [PMID:22306691]. IL12RB2-deficient mice had no detectable IL-12-induced function [PMID:11086056]. GtoPdb lists it as agonist [DB:GtoPdb].","molecular_requirements":"IL12RB2 binds IL-12 on its own and with IL12RB1 forms high- and low-affinity sites [PMID:8943050]. Cryo-EM structures 8XRP and 8YI7 show an IL-12, IL12RB1 and IL12RB2 complex [DB:PDB 8XRP]. The same paper reports that IL-35 (p35-containing) also acts through IL-12Rbeta2 [PMID:22306691].","affinity_potency":[{"value":"Kd of about 5 nM","assay":"125I-huIL-12 radioligand binding to IL-12R beta2 alone","system":"cloned human subunit in COS-7 cells","cite":"PMID:8943050"},{"value":"Kds of about 55 pM and 8 nM","assay":"high- and low-affinity sites with IL-12R beta1 coexpressed","system":"COS-7 cells","cite":"PMID:8943050"}],"species_and_systems":"Human receptor cloned and tested in COS-7 [PMID:8943050]; HEK293T co-IP/FRET [PMID:22306691]; knockout mice [PMID:11086056].","localisation_and_range":"IL12A is flagged secreted [flag].","caveats":"IL12A alone is not the ligand: the dossier notes IL-12 is the p35/p40 heterodimer. Two of three shown papers were abstract-only, and the knockout paper does not test binding. One paper was judged a different entity.","key_references":[{"PMID":"8943050","why":"cloned IL-12Rbeta2 binds IL-12, with Kd values"},{"PMID":"22306691","why":"IL-12 induces IL-12Rbeta1/beta2 heterodimerization"},{"PMID":"11086056","why":"IL12RB2 required for IL-12 function in mice"}],"covers":["LR000858","LR004288"]},"LR000859":{"pair":"IL12B -> IL12RB1","headline":"IL12B (p40) binds IL12RB1 by binding and structural data, but papers are abstract-only and often concern IL-12 or p40 homodimer generally.","interaction_type":"direct binding","direction_and_effect":"p40 homodimer binds the IL-12 receptor without mediating biologic activity and inhibits IL-12-induced proliferation with an IC50 of 65 ng/ml [PMID:7527811]; mouse (p40)2 acts as an IL-12 antagonist [PMID:7843232]. GtoPdb lists IL12B-IL12RB1 as agonist [DB:GtoPdb].","molecular_requirements":"p40 interacts with the beta subunit of IL-12R, while p35 is required for signalling [PMID:7843232]. A human IL-23 crystal structure indicates p40 binds IL-12Rbeta1 with high affinity [PMID:29287995]. The ternary IL-23:IL-23R:IL-12Rbeta1 complex had low stability [PMID:29287995].","affinity_potency":[{"value":"IC50 of 20 to 70 ng/ml","assay":"80-kDa p40 dimer inhibiting 125I-IL-12 binding","system":"KIT225/K6 human T cells","cite":"PMID:7527811"}],"species_and_systems":"Human COS-expressed p40 on KIT225/K6 cells [PMID:7527811]; mouse p40 on COS cells expressing human IL-12R beta, with little activity on human PHA blasts [PMID:7843232]; human crystal structure [PMID:29287995]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL12B is flagged secreted [flag].","caveats":"All papers are abstract-only reads. Several tests concern the IL-12 receptor as a whole, not IL12RB1 alone [PMID:7527811]. The knockout paper concerns IL12RB2 [PMID:11086056]. Affinity values for IL12B-IL12RB1 are not given (GtoPdb notes pKd only as a unit) [DB:GtoPdb].","key_references":[{"PMID":"7843232","why":"p40 interacts with IL-12R beta subunit"},{"PMID":"7527811","why":"p40 monomer and dimer bind IL-12R"},{"PMID":"29287995","why":"structure; p40 binds shared IL-12Rbeta1"}],"covers":["LR000859","LR004289"]},"LR007294":{"pair":"IL12B:IL23A -> IL12RB1:IL23R","headline":"IL-23 (IL12B:IL23A) binds a receptor made of IL12RB1 and IL23R; supported by two abstract-read papers plus database records.","interaction_type":"direct binding","direction_and_effect":"IL-23 signals through the IL-12Rbeta1/IL-23R pair: IL-23R pairs with IL-12Rbeta1 to confer IL-23 responsiveness, and antibodies to either chain block IL-23 responses [PMID:12023369]. IL-23 binds IL-12Rbeta1 but not IL-12Rbeta2 [PMID:11114383]. GtoPdb lists the ligand as agonist [DB:GtoPdb].","molecular_requirements":"Both chains are needed: responsiveness requires cells expressing both subunits [PMID:12023369]. Human IL-23, but not IL-12, shows detectable affinity for IL-23R itself [PMID:12023369]. IL-12Rbeta2 is not used [PMID:12023369]. The 2000 paper evidences only the IL12RB1 chain, since IL23R was not yet identified [PMID:11114383]. Ligand is the IL12B:IL23A heterodimer [flag].","affinity_potency":[],"species_and_systems":"Human proteins in human NK cell line and Ba/F3 transfectants [PMID:12023369]; PHA blast T cells and dendritic cells [PMID:11114383]. BioGRID and IntAct list reconstituted-complex and co-immunoprecipitation records [DB:BioGRID] [DB:IntAct]; PDB has co-structures of the two partners [DB:PDB 6WDQ].","localisation_and_range":"Ligand is flagged secreted; receptor flagged transmembrane [flag]. Released by antigen-presenting cells such as dendritic cells or macrophages per UniProt [DB:UniProt]. Acts as a soluble paracrine cytokine on receptor-expressing cells.","caveats":"Both papers were read as abstracts only. Affinity values are not reported in our evidence.","key_references":[{"PMID":"12023369","why":"Identifies IL-23R pairing with IL-12Rbeta1; antibody blockade"},{"PMID":"11114383","why":"Discovery of IL-23; binds IL-12Rbeta1 not IL-12Rbeta2"}],"covers":["LR007294"]},"LR004297":{"pair":"IL15 -> IL2RG","headline":"IL15 uses the shared IL2RG with IL2RB; chain-level evidence from two abstracts.","interaction_type":"direct binding","direction_and_effect":"IL-15 interacts with the IL-2R beta/gamma c subunits; IL-15 forms a less stable bridge between IL-2Rbeta and gamma c than IL-2 does [PMID:8568232]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL-2R beta and gamma c co-precipitate 1:1 with IL-2; with IL-15 only IL-2R beta was found [PMID:8568232]. High-affinity receptors share beta and gamma chains with a private alpha [PMID:15265897].","affinity_potency":[],"species_and_systems":"YT cells and OKT3 blasts (human) for cross-linking; the curated species is mouse in the record [PMID:8568232]. Soluble receptor work in human cell lines [PMID:15265897].","localisation_and_range":"IL15 flagged secreted [flag].","caveats":"Abstract only. The 1996 paper's co-precipitation shows IL2RG poorly associated with IL15, so direct IL15-IL2RG binding is not clearly shown [PMID:8568232]. One paper judged different_entity.","key_references":[{"PMID":"8568232","why":"Compares IL-15 and IL-2 interaction with beta/gamma c"},{"PMID":"15265897","why":"Receptor architecture"}],"covers":["LR000867","LR004297"]},"LR000868":{"pair":"IL16 -> CD4","headline":"IL16 acts through CD4 with direct binding and functional evidence across human and mouse cells.","interaction_type":"direct binding","direction_and_effect":"IL-16 (LCF) is a CD4 ligand that elicits eosinophil migration (ED50 10(-12) to 10(-11) M) [PMID:1851800]. LCF-induced migration requires membrane-expressed CD4 [PMID:7910967]. IL-16 induced c-fos in CD4-expressing cerebellar granule neurons [PMID:10479680]. Agonist [PMID:1851800].","molecular_requirements":"LCF needs both autoaggregation of its monomers and membrane CD4 [PMID:7910967]. The D4 domain of CD4 contains the IL-16 binding site [PMID:10438516]. Monovalent OKT4 Fab competitively inhibited the response [PMID:1851800].","affinity_potency":[{"value":"ED50 10(-12) to 10(-11) M","assay":"eosinophil migration (potency, not affinity)","system":"human eosinophils, recombinant LCF","cite":"PMID:1851800"}],"species_and_systems":"Human eosinophils and lymphocytes [PMID:1851800] [PMID:7910967]; mouse cerebellar neurons [PMID:10479680]; D4 peptide inhibition of IL-16 binding in vitro [PMID:10438516].","localisation_and_range":"IL16 flagged secreted [flag]; secreted from a neuronal precursor after caspase-3 processing [PMID:10479680].","caveats":"Mostly abstract reads; 10479680 and 10438516 are functional rather than direct binding. Bivalent/tetrameric LCF is required, so monomer behaviour is uncertain [PMID:7910967]. Binding affinity not reported in our evidence.","key_references":[{"PMID":"1851800","why":"CD4 affinity purification; eosinophil migration"},{"PMID":"10438516","why":"CD4 D4 domain binds IL-16"},{"PMID":"7910967","why":"CD4 required for LCF migration"}],"covers":["LR000868","LR004298"]},"LR002785":{"pair":"IL16 -> CD9","headline":"IL-16 is reported to signal through CD9 as an alternative receptor, with binding to CD9-expressing CHO cells and CD9-dependent responses; abstracts only.","interaction_type":"direct binding","direction_and_effect":"Agonist. Anti-CD9 antibodies blocked IL-16-driven chemotaxis and Ca2+ mobilisation in CD4-negative HMC-1 mast cells, and inhibited activation of cord-blood-derived human and mouse bone-marrow-derived mast cells by 50% to 60% [PMID:16144798]. CD9 knockdown in A549 cells reduced migration towards IL-16 [PMID:29884309].","molecular_requirements":"CD9 acts as an alternative to CD4, which HMC-1 cells lack [PMID:16144798]. Whether other co-receptors are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cell lines (HMC-1, A549, CHO transfectants) and primary human and mouse mast cells [PMID:16144798]; A549 CRISPR knockdown clones [PMID:29884309]. The mouse pair is ortholog-inferred, not directly tested here.","localisation_and_range":"IL-16 is annotated as secreted [flag]; CD9 is annotated as a receptor [flag]. Range from papers is not described.","caveats":"Both papers were read as abstracts only. Evidence for the CHO binding is a single statement without affinity. The A549 study is a functional migration readout and only supports the hypothesis.","key_references":[{"PMID":"16144798","why":"Antibody block, antisense and CHO transfectant binding for IL-16 and CD9"},{"PMID":"29884309","why":"CRISPR CD9 knockdown reduces IL-16-directed migration"}],"covers":["LR002785","LR006028"]},"LR001858":{"pair":"IL17C -> IL17RA","headline":"IL-17C binds a receptor complex of IL-17RA and IL-17RE; the evidence is one abstract-only paper, so IL-17RA alone is not shown.","interaction_type":"direct binding","direction_and_effect":"Agonist. IL-17C bound a receptor complex of IL-17RA and IL-17RE on epithelial cells and stimulated proinflammatory cytokine, chemokine and antimicrobial peptide expression [PMID:21993848]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL-17RA is needed with IL-17RE; the paper describes binding to the IL-17RA/IL-17RE complex, not IL-17RA alone [PMID:21993848]. Reactome lists IL17C dimer:IL17RA:IL17RE [DB:Reactome].","affinity_potency":[],"species_and_systems":"Curators recorded human; the abstract does not name species for the imiquimod skin and DSS colitis models [PMID:21993848]. Mouse pair is ortholog-inferred.","localisation_and_range":"Autocrine action on epithelial cells is described [PMID:21993848]; IL-17C is annotated as secreted [flag].","caveats":"Abstract-only read. IL-17RA alone binding is not demonstrated. IL-17C was pro-inflammatory in skin but protective in colitis [PMID:21993848].","key_references":[{"PMID":"21993848","why":"IL-17C binds IL-17RA/IL-17RE complex on epithelial cells"}],"covers":["LR001858","LR005204"]},"LR000877":{"pair":"IL19 -> IL20RB","headline":"IL-19 signals via IL20RB as the shared partner in the IL20RA/IL20RB complex; complex-level evidence in human transfected cells.","interaction_type":"functional only","direction_and_effect":"IL-19 acts as an agonist through the IL-20RA/IL-20RB complex, with STAT3 phosphorylation and promoter activation [PMID:11564763, PMID:12351624]; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL20RB works with IL20RA; IL-19 uses only the type I complex and not IL-22R/IL-20Rbeta [PMID:11564763]. IL20RB alone is not shown to bind IL-19 in our evidence.","affinity_potency":[],"species_and_systems":"Human cell lines expressing transfected receptors [PMID:11564763, PMID:12351624]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand carries the secreted annotation flag [flag], which implies paracrine/endocrine range; receptor localisation beyond the receptor flag is not reported in our evidence.","caveats":"Both papers read as abstracts; single-chain row inherits complex-level evidence. Growth inhibition in one line needed levels two orders of magnitude above STAT activation [PMID:12351624].","key_references":[{"PMID":"11564763","why":"IL-19 uses the IL-20Ralpha/IL-20Rbeta complex"},{"PMID":"12351624","why":"Reporter and STAT assays across receptor combinations"}],"covers":["LR000877","LR004307"]},"LR002794":{"pair":"IL1F10 -> IL1RL2","headline":"IL-38 binds the IL-36 receptor (IL1RL2) specifically among the IL-1 receptor family and acts like an antagonist; two confirming papers.","interaction_type":"direct binding","direction_and_effect":"In a screen of immobilised receptor extracellular domains IL-38 bound only the IL-36 receptor, as did IL-36Ra [PMID:22315422]. Recombinant IL-38 reduced IL-22 (37% decrease), IL-17 (39% decrease) and IL-36gamma-induced IL-8 (42% decrease); in dendritic cells IL-38 increased LPS-induced IL-6 twofold [PMID:22315422]. A second paper reports IL-38 binding IL1R6 (alias of IL1RL2) [PMID:26892022].","molecular_requirements":"Receptor extracellular domain alone was tested; accessory chain requirement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant IL-38 (152 amino acids), human PBMC and monocyte-derived dendritic cells, immobilised receptor domains [PMID:22315422]; mouse pair inferred.","localisation_and_range":"IL1F10 is flagged secreted [flag].","caveats":"Both papers abstract-only in the dossier; the 2016 binding statement was browser-read and its spot-check is pending [PMID:26892022]. Dose-response is biphasic, unlike classical antagonist anakinra, so antagonism is not clean [PMID:22315422]. No affinity reported.","key_references":[{"PMID":"22315422","why":"Receptor-specific binding screen and functional effects"},{"PMID":"26892022","why":"Independent binding of IL-38 to IL1R6"}],"covers":["LR002794","LR006037"]},"LR000895":{"pair":"IL23A -> IL12RB1","headline":"IL-23 binds IL12RB1 via its IL-12p40 partner chain; abstract-level support in two papers.","interaction_type":"direct binding","direction_and_effect":"IL-23 binds IL-12R beta 1 but not IL-12R beta 2, and activates Stat4 in PHA blast T cells [PMID:11114383]; like IL-12, IL-23 binds IL-12Rbeta1 [PMID:12023369]. GtoPdb lists agonists [DB:GtoPdb].","molecular_requirements":"The ligand is a heterodimer of p19 (IL23A) and IL-12p40; IL-23R pairs with IL-12Rbeta1 to confer IL-23 responsiveness [PMID:12023369][PMID:11114383]. IL23A alone is not shown to bind IL12RB1.","affinity_potency":[],"species_and_systems":"Human IL-23 in human cells; mouse memory T cells were used for a proliferation readout [PMID:11114383]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL23A is flagged secreted [flag].","caveats":"Both papers read as abstracts only. The row credits IL23A with binding that rests on the heterodimeric ligand. IntAct anti bait coimmunoprecipitation [DB:IntAct].","key_references":[{"PMID":"11114383","why":"IL-23 binds IL-12Rbeta1, not beta2"},{"PMID":"12023369","why":"IL-23R pairs with IL-12Rbeta1"}],"covers":["LR000895","LR004325"]},"LR007924":{"pair":"INHA -> ACVR1C:ACVR2B","headline":"INHA on ACVR1C plus ACVR2B: database-asserted only; the type II receptor is the likely contact, no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHA with the type II receptor as agonist [DB:GtoPdb]; UniProt says the ACVR2B type 2 receptor binds inhibin-A/INHA-INHBA [DB:UniProt]. Effect is stimulatory by annotation only.","molecular_requirements":"Type II chain ACVR2B carries the database evidence; the type I chain is not specifically evidenced in our evidence.","affinity_potency":[],"species_and_systems":"Species of database experiments not reported in our evidence.","localisation_and_range":"Secreted ligand [flag]; receptor complex transmembrane [flag].","caveats":"No paper evidence supports this pair; it rests on database records. Both judged papers were review_only. GtoPdb calls INHA an agonist, whereas related papers on other INHA pairs describe inhibin as competing with activin and BMPs.","key_references":[],"covers":["LR007924"]},"LR007933":{"pair":"INHA:INHBB -> ACVR1B:ACVR2A","headline":"Inhibin A:activin B to ACVR1B:ACVR2A rests on database records for single chains only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper; GtoPdb lists the component pairs as agonist [DB:GtoPdb]. BioGRID records ACVR2A with INHBB and INHA (Reconstituted Complex, Affinity Capture-Western) [DB:BioGRID]; IntAct has a coimmunoprecipitation record [DB:IntAct]; Reactome lists activin binding to ACVR2A,B:ACVR1B [DB:Reactome].","molecular_requirements":"Receptor is a type I plus type II pair (ACVR1B:ACVR2A); whether this specific heterodimeric ligand binds this exact combination is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair; no experimental species reported in our evidence (no verified papers).","localisation_and_range":"Ligand carries a secreted flag and receptor a transmembrane flag [flag]; suggests endocrine or paracrine action on membrane receptors.","caveats":"Rests on databases alone; the two papers judged were review_only, so none confirms this pair. Database records concern individual subunits or related complexes, not necessarily this exact combination. ","key_references":[],"covers":["LR007933"]},"LR007258":{"pair":"INHBA:INHBB -> ACVR1:ACVR2A","headline":"Activin AB to ACVR1:ACVR2A is database-supported only; two papers were review_only.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHBA and INHBB as agonists at ACVR2A [DB:GtoPdb]. BioGRID records ACVR2A with INHBA and INHBB [DB:BioGRID]; IntAct has a coimmunoprecipitation record [DB:IntAct]; PDB 7U5P is a structure with an INHBA chain [DB:PDB 7U5P]. UniProt says activin A can engage ACVR1 in a non-signaling complex [DB:UniProt].","molecular_requirements":"Type I (ACVR1) plus type II (ACVR2A) receptors; whether the AB heterodimer binds this exact combination is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair; no experimental species reported in our evidence.","localisation_and_range":"Ligand secreted flag, receptor transmembrane flag [flag].","caveats":"No verified paper; ACVR1 may form a non-signaling complex with activin A, so effect may be inhibitory rather than agonist.","key_references":[],"covers":["LR007258"]},"LR008275":{"pair":"INHBB -> ACVR1C:ACVR2A","headline":"Activin B to ACVR1C:ACVR2A; supported by database records only.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHBB with each receptor chain as agonist [DB:GtoPdb]. UniProt: ACVR1C is a receptor for activin AB, activin B, activin E and NODAL [DB:UniProt].","molecular_requirements":"Chain-level records; BioGRID covers the type II chain with INHBB [PMID:9202237]. Complex requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond human database records.","localisation_and_range":"Ligand is flagged secreted [flag], so likely paracrine/endocrine; receptor is flagged transmembrane [flag].","caveats":"Only abstract-insufficient rows exist; no curator-verified paper supports the assembled complex.","key_references":[],"covers":["LR008275"]},"LR010984":{"pair":"INHBC -> ACVR1C:ACVR2B","headline":"Activin C acting through ALK7 (ACVR1C) and ACVR2B: functional evidence in cells, but each receptor chain was studied separately.","interaction_type":"functional only","direction_and_effect":"Recombinant activin C activated SMAD2/3 signalling via ALK7 and suppressed lipolysis in human adipocytes [PMID:39283655]. A second paper reports INHBC activating ACVR2B-Smad2 signalling in hepatocellular carcinoma cells, with ACVR2B blockade by Bimagrumab reducing xenograft tumour growth in mice [PMID:41298802].","molecular_requirements":"ACVR1C and ACVR2B were tested in different papers; neither shows the ACVR1C:ACVR2B complex as a unit. In adipocytes with low ACVR1C, activin C only very weakly stimulated SMAD2/3 phosphorylation and reporter activity; stimulation, less potent than activin B, needed ACVR1C overexpression [PMID:39283655].","affinity_potency":[],"species_and_systems":"Immortalised human abdominal and gluteal adipocytes with doxycycline-inducible ACVR1C [PMID:39283655]; human hepatocellular carcinoma cells and a mouse xenograft [PMID:41298802].","localisation_and_range":"Ligand is flagged secreted [flag]. Range (endocrine versus local) is not reported in our evidence.","caveats":"Both papers were read as abstracts by curators (the first also has full-text excerpts); no direct binding was shown. The first paper is a Mendelian randomisation study with the in vitro work as a secondary part.","key_references":[{"PMID":"39283655","why":"Activin C signals via ALK7 in human adipocytes, weakly without receptor overexpression"},{"PMID":"41298802","why":"INHBC-ACVR2B-Smad2 axis in hepatocellular carcinoma, ACVR2B blockade in vivo"}],"covers":["LR010984"]},"LR010993":{"pair":"INHBE -> ACVR1C:ACVR2B","headline":"Activin E to ACVR1C:ACVR2B complex rests on UniProt text only; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt records that INHBE signals via ACVR1C to activate SMAD2/3 signalling and suppress PPARG target genes [DB:UniProt]. UniProt also lists ACVR1C as a receptor for activin AB, activin B, activin E and NODAL [DB:UniProt].","molecular_requirements":"The type II partner in this complex is not addressed by the UniProt text in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag].","caveats":"No papers were judged for this complex (two rows pending). Support is database annotation only, and covers ACVR1C rather than the complex.","key_references":[],"covers":["LR010993"]},"LR000949":{"pair":"INS -> IGF1R","headline":"Insulin binds IGF1R only weakly: a human tissue competition-binding study shows cross-reactivity at micromolar concentration.","interaction_type":"direct binding","direction_and_effect":"Insulin displaces [125I]IGF-I from IGF-I receptor preparations, but only at high concentration [PMID:1851182]. Structures with insulin and IGF1R chains exist [DB:PDB 6JK8] [DB:PDB 7V3P].","molecular_requirements":"Partially purified IGF-I receptors were used; chain composition is not reported in our evidence.","affinity_potency":[{"value":"about 1 x 10(-6) M (insulin, 50% displacement of [125I]IGF-I binding)","assay":"competition binding","system":"partially purified human liver, muscle and adipose IGF-I receptors","cite":"PMID:1851182"},{"value":"about 1 x 10(-9 M (IGF-I, 50% displacement)","assay":"competition binding","system":"same preparations","cite":"PMID:1851182"}],"species_and_systems":"Human liver, muscle and adipose tissue preparations [PMID:1851182].","localisation_and_range":"Ligand is flagged secreted [flag].","caveats":"Weak, cross-reactive binding, much weaker than IGF-I. The paper's main question was proinsulin, not insulin. Abstract only.","key_references":[{"PMID":"1851182","why":"Competition binding of insulin, IGF-I, IGF-II and proinsulin at human IGF-I receptors"}],"covers":["LR000949"]},"LR008581":{"pair":"ITGA4:ITGB7 -> VCAM1","headline":"Integrin alpha4beta7 with VCAM1 is supported only indirectly by database records for alpha4beta1; no paper judged.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says ITGB7 'also interacts with VCAM1 and fibronectin' [DB:UniProt].","molecular_requirements":"The shown Reactome records describe the alpha4beta1:VCAM1 complex, not alpha4beta7 [DB:Reactome]. The BioGRID record is ITGA4-VCAM1 alone [DB:BioGRID].","affinity_potency":[],"species_and_systems":"No experimental paper judged for this pair; species is human per the record.","localisation_and_range":"Both partners carry receptor flags and VCAM1 is flagged transmembrane [flag]; contact-mediated adhesion is implied by the plasma membrane complexes listed [DB:Reactome].","caveats":"The UniProt statement is marked 'Probable'. Most shown records concern the beta1 partner, so beta7-specific evidence is not reported in our evidence.","key_references":[],"covers":["LR008581"]},"LR008563":{"pair":"ITGAL:ITGB2 -> ICAM1","headline":"LFA-1 binding to ICAM1 is well supported by structures, binding assays and a functional paper.","interaction_type":"direct binding","direction_and_effect":"LFA-1 mediates adhesion and migration on ICAM-1; Rap1 inside-out signalling raises LFA-1 adhesive activity [PMID:12808052]. UniProt says ITGAL:ITGB2 is a receptor for ICAM1 [DB:UniProt].","molecular_requirements":"Both alphaL and beta2 chains form the receptor. The alphaL cytoplasmic region, not beta2, was needed for Rap1V12-dependent adhesion to ICAM-1 [PMID:12808052]. BioGRID lists reconstituted complex with each chain [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Human LFA-1 mutants expressed in mouse BAF/3 proB cells on ICAM-1 [PMID:12808052]. Structures include PDB 1MQ8 and 3TCX [DB:PDB 1MQ8][DB:PDB 3TCX].","localisation_and_range":"Membrane integrin and membrane ICAM1; contact-dependent [flag].","caveats":"The curated paper is about inside-out signalling, read as abstract only; the binding evidence comes mainly from databases. No affinity in the dossier. Row is stored with the integrin in the ligand slot.","key_references":[{"PMID":"12808052","why":"Human LFA-1 reconstituted in BAF/3 cells adhering to ICAM-1"}],"covers":["LR008563"]},"LR007942":{"pair":"ITGAV:ITGB3 -> ADGRA2","headline":"Processed soluble TEM5 (ADGRA2) binds integrin alphavbeta3 via a cryptic RGD site; abstract-level functional evidence.","interaction_type":"direct binding","direction_and_effect":"MMP9-processed, not full-length, sTEM5 mediated endothelial adhesion by direct interaction with alphavbeta3 and promoted survival of growth-factor-deprived cells; an alphavbeta3 blocking antibody inhibited survival [PMID:16982628]. UniProt agrees [DB:UniProt].","molecular_requirements":"Processing exposes the RGD motif; the cleaved extracellular fragment is the active form [PMID:16982628].","affinity_potency":[],"species_and_systems":"Endothelial cells; species not stated in the dossier [PMID:16982628].","localisation_and_range":"Shed soluble ectodomain, so it acts on the matrix and cell surface [PMID:16982628].","caveats":"Abstract only. Two other papers were review-only. Roles are reversed relative to the usual: the receptor is the cleaved adhesion-GPCR fragment acting as ligand.","key_references":[{"PMID":"16982628","why":"Processed sTEM5 binds alphavbeta3 to support endothelial survival"}],"covers":["LR007942"]},"LR001867":{"pair":"JAG1 -> CD46","headline":"Jagged1 binds CD46 directly (NMR, SPR) and acts on human T cells; one full-text paper supports it.","interaction_type":"direct binding","direction_and_effect":"Jagged1 bound CD46 but not soluble CR1, and bound cell-surface CD46 on red blood cells from human-CD46 transgenic mice [PMID:23086448]. Disturbing CD46-Notch crosstalk impeded IFN-gamma induction and the switch to IL-10; CD4+ T cells from CD46-deficient and Alagille-syndrome (JAG1 hypomorph) patients failed to mount proper TH1 responses [PMID:23086448]. The curator labels the effect agonist [PMID:23086448].","molecular_requirements":"The two N-terminal CD46 domains were fully competent for Jagged1 binding; the Jagged1 DSL-EGF3 region was used [PMID:23086448]. It did not bind murine Crry [PMID:23086448].","affinity_potency":[{"value":"KD about 8 uM","assay":"SPR, J-1DSL-EGF3 to truncated CD46","system":"recombinant proteins","cite":"PMID:23086448"}],"species_and_systems":"Human recombinant proteins and human T cells; transgenic mouse red blood cells for cell-surface binding [PMID:23086448]. The mouse pair is ortholog-inferred.","localisation_and_range":"JAG1 is flagged as transmembrane, not secreted [flag]; IntAct also records NMR, SPR and solid-phase assays [DB:IntAct].","caveats":"Single primary paper; the curator row was read from the abstract, though full-text excerpts were available. Affinity is modest (micromolar).","key_references":[{"PMID":"23086448","why":"Binding, SPR/NMR and patient T-cell data"}],"covers":["LR001867","LR005212"]},"LR004378":{"pair":"JAG1 -> NOTCH4","headline":"Functional in vivo and cell evidence that JAG1 activates NOTCH4 under disturbed flow; no direct binding in our evidence.","interaction_type":"functional only","direction_and_effect":"Disturbed flow activated JAG1-NOTCH4 signalling in porcine and murine arteries and cultured human coronary artery endothelial cells [PMID:36044575]. Endothelial Jag1 deletion reduced atherosclerosis at disturbed-flow sites [PMID:36044575]. In cells under low oscillatory shear stress, N4ICD activation fell when JAG1 was blocked, but not when DLL4 was blocked [PMID:36044575]. Effect labelled agonist.","molecular_requirements":"Not reported in our evidence beyond JAG1 being the dominant ligand and NOTCH4 the dominant receptor in these cells [PMID:36044575].","affinity_potency":[],"species_and_systems":"Porcine and mouse arteries, human coronary artery endothelial cells [PMID:36044575]. The mouse pair is a separate record; the human pair is ortholog-inferred.","localisation_and_range":"JAG1 is flagged as transmembrane [flag]; this is an endothelial context.","caveats":"Only one paper, with no binding assay in the excerpts. A Reactome complex record exists [DB:Reactome]. The curator row was read as abstract although full text was available.","key_references":[{"PMID":"36044575","why":"JAG1-NOTCH4 mechanosensing in atherosclerosis"}],"covers":["LR000955","LR004378"]},"LR000958":{"pair":"JAG2 -> NOTCH3","headline":"Jagged2 binds Notch3 directly in vitro; one paper plus database records.","interaction_type":"direct binding","direction_and_effect":"Soluble Notch3 bound Jagged2 on cells and in solid-phase assays, Ca2+-dependent [PMID:11006133]. Annotation: stimulatory.","molecular_requirements":"Ca2+ required [PMID:11006133].","affinity_potency":[],"species_and_systems":"Human proteins [PMID:11006133].","localisation_and_range":"JAG2 flagged as not secreted [flag].","caveats":"Abstract-only; no affinity in our evidence. BioGRID and Reactome records exist [DB:BioGRID][DB:Reactome].","key_references":[{"PMID":"11006133","why":"Direct binding"}],"covers":["LR000958","LR004381"]},"LR002839":{"pair":"KISS1 -> NPFFR2","headline":"Kisspeptin-10 binds and activates NPFFR2 in one 2011 study; the pair is ortholog-projected from that evidence.","interaction_type":"direct binding","direction_and_effect":"Kisspeptin-10 showed potent binding and activation of NPFFR2, whereas short GPR54-selective peptide agonists bound with much lower affinity [PMID:24900254]. Reported NPFFR ligands showed negligible affinity for GPR54, i.e. cross-reactivity runs one way [PMID:24900254].","molecular_requirements":"Kisspeptin-10 form specifically; short synthetic agonists were weak at NPFFRs [PMID:24900254].","affinity_potency":[],"species_and_systems":"Human and mouse entries are both ortholog-inferred; the paper's experiment species are labelled human by the curators; abstract-only read [PMID:24900254].","localisation_and_range":"KISS1 is flagged secreted [flag]; the paper suggests secondary kisspeptin targets may lie in the median eminence [PMID:24900254].","caveats":"Single paper, abstract only, with no numbers in the dossier. The canonical kisspeptin receptor is GPR54, so this is a cross-reactivity finding [PMID:24900254]. Not present in any database.","key_references":[{"PMID":"24900254","why":"Kisspeptin-10 binds and activates NPFFR1 and NPFFR2"}],"covers":["LR002839","LR006075"]},"LR004387":{"pair":"KNG1 -> ITGAM","headline":"Cleaved kininogen (HKa) binds the Mac-1 integrin with nanomolar affinity; the evidence is for the ITGAM:ITGB2 heterodimer.","interaction_type":"direct binding","direction_and_effect":"HKa blocked adhesion of Mac-1-transfected cells to fibrinogen and ICAM-1 in a dose-dependent manner, an inhibitory effect [PMID:10845911].","molecular_requirements":"The evidence is for the Mac-1 heterodimer (CD11b/CD18, ITGAM:ITGB2), and the ligand form tested is cleaved high-molecular-weight kininogen (HKa), not intact KNG1 [PMID:10845911].","affinity_potency":[{"value":"Kd 3.2 nM","assay":"IAsys resonant mirror optical biosensor, purified Mac-1","system":"cell-free","cite":"PMID:10845911"},{"value":"Kd 62 nM","assay":"FITC-labelled HKa cell binding","system":"Mac-1-transfected HEK 293 cells","cite":"PMID:10845911"}],"species_and_systems":"Human Mac-1 in transfected HEK 293 cells and purified protein [PMID:10845911].","localisation_and_range":"KNG1 is secreted [flag]; binds a leukocyte surface integrin.","caveats":"Abstract only. One chain alone is not shown to bind; one abstract_insufficient paper also exists for ITGAM.","key_references":[{"PMID":"10845911","why":"HKa-Mac-1 binding and adhesion block"}],"covers":["LR000965","LR004387"]},"LR006079":{"pair":"L1CAM -> FGFR1","headline":"Surface plasmon resonance shows direct L1 FN3-FGFR1 Ig II-III binding with receptor activation; abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Direct interaction of L1 FN3 modules I-V with FGFR1 Ig modules II and III by surface plasmon resonance; L1-FN3 modules activated FGFR1 (phosphorylation) and induced neurite outgrowth in primary neurons [PMID:18222703]. Agonist-like effect.","molecular_requirements":"L1 FN3 I-V and FGFR1 Ig II-III are the mapped regions; binding was enhanced by ATP, AMP-PCP and GTP, but not AMP [PMID:18222703]. Reactome lists L1:FGFR1 [DB:Reactome R-HSA-443643].","affinity_potency":[],"species_and_systems":"Recombinant protein fragments by SPR; species not specified in dossier; primary neurons for function [PMID:18222703]. The mouse pair is listed as a separate non-inferred record.","localisation_and_range":"Reactome describes L1-FGFR cis-heterodimerization [DB:Reactome R-HSA-437230]; FGFR1 not flagged secreted [flag].","caveats":"Abstract only; no affinity values; species unspecified.","key_references":[{"PMID":"18222703","why":"SPR binding of L1 FN3 to FGFR1 plus activation"}],"covers":["LR002844","LR006079"]},"LR004396":{"pair":"L1CAM -> ITGAV","headline":"Direct L1-alphavbeta3 binding (ELISA, FN3) and L1-Ig6 RGD adhesion; alphav acts within alphavbeta3 or beta1 heterodimers.","interaction_type":"direct binding","direction_and_effect":"Purified alphaVbeta3 bound L1 FN3 directly [PMID:10871287]; L1-Ig6 is a heterophilic ligand for alphavbeta3 and alphavbeta1, supporting endothelial cell adhesion; agonist-like [PMID:9396761].","molecular_requirements":"Two sites: RGD-independent FN3 [PMID:10871287] and RGD-dependent Ig6; beta3 binding in Ca2+, Mg2+ or Mn2+ [PMID:9396761]. Evidence is on heterodimers; ITGAV alone is chain-level.","affinity_potency":[],"species_and_systems":"Human proteins, purified in ELISA, CHO cells and HUVEC adhesion [PMID:10871287][PMID:9396761]. Mouse pair is ortholog-inferred.","localisation_and_range":"Cell-contact adhesion [PMID:9396761].","caveats":"Alphavbeta3 ranked highest in the integrin hierarchy [PMID:9396761]; no affinity; ELISA-based, two papers.","key_references":[{"PMID":"10871287","why":"ELISA binding of alphavbeta3 to FN3"},{"PMID":"9396761","why":"L1-Ig6 RGD-dependent alphav integrin binding"}],"covers":["LR000974","LR004396"]},"LR002848":{"pair":"L1CAM -> ITGB3","headline":"L1-Ig6 RGD binds beta3 integrins alphavbeta3 and alphaIIbbeta3; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"L1-Ig6 is a heterophilic ligand for alphavbeta3 and alphaIIbbeta3, supporting HUVEC and platelet adhesion [PMID:9396761].","molecular_requirements":"RGD-dependent; beta3 integrin binding occurs in Ca2+, Mg2+ or Mn2+ [PMID:9396761]. ITGB3 pairs with alphav or alphaIIb; chain-level row.","affinity_potency":[],"species_and_systems":"Human L1-Ig6, HUVEC, platelets [PMID:9396761]. Mouse pair is ortholog-inferred.","localisation_and_range":"Cell-contact adhesion [PMID:9396761].","caveats":"Single paper, no affinity; prefer complex rows for scoring.","key_references":[{"PMID":"9396761","why":"L1-Ig6 binds beta3 integrins"}],"covers":["LR002848","LR006083"]},"LR008356":{"pair":"LAIR1 -> LAIR1","headline":"LAIR1 self-interaction rests only on an IntAct protein-array record; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Only a protein-array record is available; species not stated beyond the human entity [DB:IntAct Q6GTX8-Q6GTX8].","localisation_and_range":"LAIR1 is flagged as a transmembrane receptor [flag].","caveats":"No paper was confirmed; two papers were judged abstract_insufficient and two concerned a different entity. Support is a single database assertion [DB:IntAct].","key_references":[],"covers":["LR008356"]},"LR000976":{"pair":"LAMA1 -> ITGA1","headline":"A recombinant laminin alpha1 N-terminal fragment binds purified alpha1beta1 integrin; abstract-only read.","interaction_type":"direct binding","direction_and_effect":"Fragment alpha1VI/V bound purified alpha1beta1 and alpha2beta1 integrins, whereas fragment alpha1V alone did not [PMID:9688542]. Effect (activating or inhibitory) not reported in our evidence.","molecular_requirements":"The binding site localises to the LN module (domain VI); the integrin was tested as the alpha1beta1 heterodimer, so ITGB1 is also needed in our evidence [PMID:9688542].","affinity_potency":[],"species_and_systems":"Recombinant laminin alpha1 fragments and purified integrins; species not stated in the abstract [PMID:9688542].","localisation_and_range":"Ligand flagged secreted [flag]; a matrix ligand.","caveats":"Abstract only; the fragment, not full-length LAMA1, was tested. The ITGA1 pair is assigned from an alpha1beta1 heterodimer result. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"9688542","why":"Laminin alpha1 LN module binds alpha1beta1 integrin"}],"covers":["LR000976","LR004397"]},"LR000985":{"pair":"LAMA2 -> ITGA7","headline":"Recombinant alpha7X1beta1 binds laminin-211/221 with Kd 0.64 nM; full-text plus functional support.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha7beta1 binds laminin-211/221 [PMID:16413178]. Alpha7beta1 is described as a receptor for laminin-2 mediating myoblast migration [PMID:11278916]. Labelled Stimulatory [flag].","molecular_requirements":"The alpha7X1beta1 variant gave Kd 0.64 nM; the alpha7X2beta1 variant gave 2.6 nM [PMID:16413178]. The receptor is the alpha7beta1 heterodimer.","affinity_potency":[{"value":"Kd 0.64 nM","assay":"solid-phase saturation binding","system":"recombinant human alpha7X1beta1 ectodomain with laminin-211/221","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant integrins [PMID:16413178]; human myoblasts and HEK293 transfectants [PMID:11278916]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted; matrix ligand.","caveats":"Evidence is for the assembled laminin heterotrimer, not the single alpha chain alone [PMID:16413178]. The second paper is abstract-only and the identity statement is background [PMID:11278916].","key_references":[{"PMID":"16413178","why":"Kd 0.64 nM for alpha7X1beta1 and laminin-211/221"},{"PMID":"11278916","why":"Alpha7beta1 mediates myoblast migration on laminin-2"}],"covers":["LR000985","LR004405"]},"LR006088":{"pair":"LAMA3 -> ITGA3","headline":"Recombinant alpha3beta1 binds laminin-332 with Kd 14 nM; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha3beta1 binds laminin-332 in solid-phase assay [PMID:16413178]. Labelled Stimulatory [flag].","molecular_requirements":"The receptor is the alpha3beta1 heterodimer; laminin-332 was recognised by alpha3- and alpha6-containing integrins but not alpha7-containing ones [PMID:16413178].","affinity_potency":[{"value":"Kd 14 nM","assay":"solid-phase saturation binding","system":"recombinant human alpha3beta1 ectodomain with laminin-332","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant integrins [PMID:16413178]; mouse is listed as a separate non-inferred pair.","localisation_and_range":"Ligand flagged secreted; matrix ligand.","caveats":"Evidence is for the assembled laminin heterotrimer, not the single alpha chain alone [PMID:16413178]. Five other papers were abstract_insufficient.","key_references":[{"PMID":"16413178","why":"Kd 14 nM for alpha3beta1 and laminin-332"}],"covers":["LR002854","LR006088"]},"LR002857":{"pair":"LAMA3 -> ITGB4","headline":"Laminin-332 (with LAMA3) binds recombinant integrin alpha6beta4 directly; one full-text study, assembled trimer.","interaction_type":"direct binding","direction_and_effect":"Laminin-332 bound recombinant alpha6beta4 in solid-phase saturation binding [PMID:16413178]. Interaction record lists a Stimulatory effect [flag].","molecular_requirements":"Receptor tested is the alpha6beta4 heterodimer; ITGB4 alone is not shown to suffice. Ligand is the laminin-332 trimer, not LAMA3 alone [PMID:16413178].","affinity_potency":[{"value":"Kd 12 nM","assay":"solid-phase saturation binding, laminin-332 vs recombinant alpha6beta4","system":"human recombinant","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant integrin and purified laminin [PMID:16413178].","localisation_and_range":"LAMA3 is flagged secreted and not transmembrane [flag]; laminin acts as a basement-membrane matrix ligand (not stated in the paper text we hold).","caveats":"Single paper; no cellular or in vivo data. Three other papers were abstract-insufficient.","key_references":[{"PMID":"16413178","why":"Kd of alpha6beta4 for laminin-332"}],"covers":["LR002857","LR006091"]},"LR000994":{"pair":"LAMA5 -> BCAM","headline":"Lutheran glycoprotein (BCAM) binds alpha5-containing laminin directly with high affinity; two abstract-level papers, human and mouse.","interaction_type":"direct binding","direction_and_effect":"Human and mouse Lutheran glycoprotein specifically bound laminin 10/11 with high affinity [PMID:11133776]. Soluble recombinant Lu bound laminin-10/11 by ELISA and did not bind sections of laminin alpha5 knockout embryos [PMID:12244066].","molecular_requirements":"The first 3 N-terminal Ig-superfamily domains of human Lu are critical [PMID:11133776]; the alpha5 LG3 module is essential on the laminin side [PMID:12244066]. Ligand tested as laminin-10/11 trimers.","affinity_potency":[],"species_and_systems":"Human and mouse Lu with human laminin [PMID:11133776]; soluble recombinant Lu with mouse transgenic tissue [PMID:12244066].","localisation_and_range":"LAMA5 flagged secreted [flag]; Lu is described as a transmembrane receptor and laminin alpha5 as subendothelial [PMID:12244066][PMID:11133776].","caveats":"No numeric affinity in our evidence; abstract-only reads. BioGRID, PDB 21IR and UniProt also support the pair [DB:BioGRID][DB:PDB 21IR][DB:UniProt].","key_references":[{"PMID":"11133776","why":"Human and mouse Lu bind laminin 10/11"},{"PMID":"12244066","why":"Lu binds laminin alpha5 LG3"}],"covers":["LR000994","LR004413"]},"LR006097":{"pair":"LAMA5 -> ITGA7","headline":"Laminin alpha5 (as laminin-511/521) binds integrin alpha7X1beta1 with Kd 1.2 nM in one recombinant-binding study.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 bound recombinant integrin alpha7X1beta1 [PMID:16413178]. Effect annotation is not given for this row.","molecular_requirements":"Heterotrimer ligand and alpha7beta1 heterodimer receptor were used; single chains were not tested [PMID:16413178]. The alpha7X2beta1 splice variant did not give a determinable Kd with laminin-511/521 in the table (ND(+)) [PMID:16413178].","affinity_potency":[{"value":"Kd 1.2 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoforms (laminin-511/521 vs alpha7X1beta1)","system":"human recombinant proteins","cite":"PMID:16413178"}],"species_and_systems":"Human recombinant proteins [PMID:16413178]; mouse pair ortholog-inferred.","localisation_and_range":"LAMA5 is flagged secreted [flag] and ITGA7 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"A single paper supports this pair, and the Kd applies to the alpha7X1 splice variant with the beta1 partner.","key_references":[{"PMID":"16413178","why":"Recombinant alpha7beta1 binding to laminin-511/521"}],"covers":["LR002863","LR006097"]},"LR002866":{"pair":"LAMB2 -> DAG1","headline":"Laminin beta2-containing laminins (laminin-11, merosin) bind alpha-dystroglycan in brain and nerve; chain-level, abstract-only evidence.","interaction_type":"direct binding","direction_and_effect":"Laminin-10/11 preferentially bound brain alpha-dystroglycan over skeletal-muscle alpha-dystroglycan [PMID:16709410]. Peripheral-nerve alpha-dystroglycan binds laminin (A/B1/B2) and merosin (M/B1/B2) [PMID:7925941]. Annotated stimulatory.","molecular_requirements":"Binding depends on the alpha-dystroglycan form (brain glycoepitope) [PMID:16709410]; in nerve it is Ca2+-dependent and heparin-inhibitable [PMID:7925941]. LAMB2 was not tested alone, and only laminin-11 among the laminin-10/11 pair contains beta2.","affinity_potency":[],"species_and_systems":"Mammalian brain and peripheral nerve extracts; species not reported in our evidence. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"LAMB2 is flagged secreted [flag] and DAG1 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"Both papers are abstract-only reads on whole laminins; LAMB2 is inferred from laminin-11 and merosin composition. No affinity values reported.","key_references":[{"PMID":"16709410","why":"Laminin-10/11 binds brain alpha-dystroglycan"},{"PMID":"7925941","why":"Nerve alpha-dystroglycan binds laminin and merosin"}],"covers":["LR002866","LR006100"]},"LR001876":{"pair":"LEAP2 -> GHSR","headline":"LEAP2 is an endogenous GHSR antagonist that fully inhibits ghrelin activation and blocks ghrelin effects in vivo.","interaction_type":"direct binding","direction_and_effect":"LEAP2 fully inhibits GHSR activation by ghrelin and blocks ghrelin effects on food intake, GH release and glucose maintenance in vivo; neutralizing antibodies against LEAP2 enhance ghrelin action [PMID:29233536]. GtoPdb lists it as an antagonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pIC50 8.22","assay":"inhibition of GHSR activation (as recorded by curators)","system":"human ligand and receptor","cite":"PMID:29233536"}],"species_and_systems":"Human ligand and receptor in vitro; in vivo effects in the paper, species not detailed in our evidence [PMID:29233536]. Mouse pair listed too.","localisation_and_range":"LEAP2 is a secreted hormone from liver and small intestine whose secretion is suppressed by fasting [PMID:29233536]; flagged secreted [flag].","caveats":"Abstract only; BioGRID lists a reconstituted complex [DB:BioGRID 3496523]. Whether LEAP2 binds the orthosteric site is not reported in our evidence.","key_references":[{"PMID":"29233536","why":"LEAP2 as an endogenous GHSR antagonist"}],"covers":["LR001876","LR005218"]},"LR002875":{"pair":"LECT2 -> TIE1","headline":"LECT2 is reported as a functional ligand of orphan receptor Tie1; evidence is one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"LECT2 binding to Tie1 interrupts Tie1/Tie2 heterodimerization, facilitates Tie2/Tie2 homodimerization, activates PPAR signaling and inhibits endothelial migration and tube formation; curated as agonist [PMID:31474362].","molecular_requirements":"Acts through the Tie1/Tie2 receptor complex balance; Tie2 is involved [PMID:31474362].","affinity_potency":[],"species_and_systems":"In vivo mice with LECT2 overexpression and Lect2-knockout, endothelial cells in vitro, and human liver fibrosis samples [PMID:31474362]. Mouse pair is ortholog-projected.","localisation_and_range":"LECT2 is flagged secreted [flag].","caveats":"Abstract only; no affinity or direct binding data in the dossier; single paper.","key_references":[{"PMID":"31474362","why":"LECT2 as a functional Tie1 ligand in liver fibrosis"}],"covers":["LR002875","LR006109"]},"LR002884":{"pair":"LGALS3 -> ITGB3","headline":"Galectin-3 binds integrin alphavbeta3, enabling KRAS dependence in cancer cells; direct binding claimed in an abstract.","interaction_type":"direct binding","direction_and_effect":"Galectin-3 directly binds cell-surface integrin alphavbeta3 and enables KRAS functions, including macropinocytosis; a drug disrupting alphavbeta3/galectin-3 binding suppressed tumours [PMID:28893801].","molecular_requirements":"The receptor is the alphavbeta3 heterodimer, so ITGB3 pairs with ITGAV [PMID:28893801].","affinity_potency":[],"species_and_systems":"Cancer cells with patient-derived xenografts and spontaneous tumours in mice [PMID:28893801]. Species of reagents not reported in our evidence.","localisation_and_range":"Galectin-3 flagged secreted; ITGB3 flagged receptor, not secreted [flag].","caveats":"Read depth is abstract only; direct binding is asserted in the abstract and no assay details or affinity are given. No database records.","key_references":[{"PMID":"28893801","why":"Galectin-3 binds alphavbeta3, driving KRAS addiction"}],"covers":["LR002884","LR006118"]},"LR002893":{"pair":"LGALS3BP -> SIGLEC5","headline":"LGALS3BP was identified by affinity chromatography as a sialic-acid-dependent ligand of SIGLEC5 and inhibits neutrophil activation; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"LGALS3BP is a sialic acid-dependent ligand for human Siglec-9, Siglec-5 and Siglec-10, and inhibited neutrophil activation in a sialic acid- and Siglec-dependent manner (immunoinhibitory) [PMID:25320078].","molecular_requirements":"Sialic acid on LGALS3BP is required; the paper does not say whether other chains are needed [PMID:25320078].","affinity_potency":[],"species_and_systems":"Human tumour cell extracts; neutrophil assay system is not specified in the abstract. The mouse homolog Siglec-E binds murine LGALS3BP with lower affinity [PMID:25320078].","localisation_and_range":"LGALS3BP is a heavily glycosylated secreted molecule, up-regulated in the extracellular matrix of colorectal and prostate cancer [PMID:25320078].","caveats":"Abstract only. The inhibition of neutrophil activation was shown for Siglecs collectively, not necessarily SIGLEC5 specifically. Same paper supports three Siglec partners. BioGRID lists a Reconstituted Complex record [DB:BioGRID]. No affinity reported.","key_references":[{"PMID":"25320078","why":"LGALS3BP identified as a sialic acid-dependent ligand for CD33-related Siglecs"}],"covers":["LR002893"]},"LR001885":{"pair":"LGI1 -> ADAM23","headline":"LGI1 binds ADAM23 with significant ability in one study, secondary to ADAM22; Reactome and IntAct support.","interaction_type":"direct binding","direction_and_effect":"ADAM23 had a significant binding ability to LGI1 or LGI4, indicating ADAM22 is not the sole receptor [PMID:18974846]. Reactome lists LGI1 binds ADAM22 and ADAM23 [DB:Reactome]; IntAct lists an anti-tag coimmunoprecipitation [DB:IntAct]. Effect direction not reported.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins per excerpts (curator labels human) [PMID:18974846].","localisation_and_range":"LGI1 secreted; ADAM23 flagged secreted and receptor [flag].","caveats":"Abstract does not say which of LGI1 or LGI4 bound ADAM23; no affinity; abstract only [PMID:18974846].","key_references":[{"PMID":"18974846","why":"LGI-ADAM binding specificity incl. ADAM23"}],"covers":["LR001885","LR005227"]},"LR008392":{"pair":"LRFN3 -> PTPRS","headline":"LRFN3 -> PTPRS rests on one full-text interactome paper reporting SALM-LAR-PTPR SPR binding; no affinity or direction.","interaction_type":"direct binding","direction_and_effect":"In a surface plasmon resonance test of all LAR-PTPRs against all SALMs, binding was seen for all pairs except PTPRF-SALM4 [PMID:32822567]. No LAR-PTPR binding to SALM1 or SALM4 had been reported and none was seen in the screen [PMID:32822567]. Direction and functional effect are not reported in our evidence.","molecular_requirements":"Recombinant Fc-fusion ectodomains; not reported beyond that. Relative max response units suggested a spectrum of affinities [PMID:32822567].","affinity_potency":[],"species_and_systems":"Human recombinant proteins in vitro (ELISA screen and SPR) [PMID:32822567].","localisation_and_range":"LRFN3 is flagged as not secreted and as a receptor; PTPRS is flagged transmembrane and secreted [flag]. LAR-PTPRs act in trans-synaptic adhesion [PMID:32822567].","caveats":"Evidence is a family-wide statement; which SALM corresponds to LRFN3 is not stated in our evidence. Screen did not show SALM1/SALM4 binding, SPR did [PMID:32822567]. No affinity values in our evidence.","key_references":[{"PMID":"32822567","why":"SPR of LAR-PTPRs against SALMs"}],"covers":["LR008392"]},"LR002929":{"pair":"LRRTM1 -> NRXN3","headline":"LRRTM1 is reported to share the S4-lacking neurexin binding code that covers neurexins 1, 2 and 3; support is one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"The neurexin binding code of LRRTM2, which binds neurexins 1, 2 and 3 alpha and beta variants lacking an insert at splice site 4, is conserved in LRRTM1 and functional in a coculture hemisynapse formation assay [PMID:20519524].","molecular_requirements":"Neurexin variants must lack the splice site 4 insert [PMID:20519524].","affinity_potency":[],"species_and_systems":"One paper, read as abstract only; species not specified. Both human and mouse pairs are projected from other evidence (ortholog inferred) [PMID:20519524]. No database records.","localisation_and_range":"Both partners are flagged transmembrane [flag]; localisation is not discussed in our evidence for this pair.","caveats":"The paper's text does not specifically name NRXN3 for LRRTM1; the pair is inferred from the general statement that the code is conserved, and the curator note itself says it covers NRXN1-3. Single paper, abstract read, no affinity reported.","key_references":[{"PMID":"20519524","why":"conserved neurexin binding code in LRRTM1"}],"covers":["LR002929","LR006154"]},"LR002938":{"pair":"LRRTM4 -> GPC6","headline":"LRRTM4 binds glypicans in a heparan sulfate-dependent manner; GPC6 is not singled out, so support for GPC6 specifically is indirect.","interaction_type":"direct binding","direction_and_effect":"Glypican is identified as a receptor for LRRTM4, with binding in an HS-dependent manner [PMID:23911103]. Glypican 4 and LRRTM4 localize to pre- and postsynaptic membranes, and the paper concludes a trans-synaptic glypican-LRRTM4 interaction regulates excitatory synapse development [PMID:23911103].","molecular_requirements":"Binding depends on heparan sulfate. Glypican binds LRRTM4 but not LRRTM2 [PMID:23911103]. LRRTM4-Fc bound strongly to all glypican isoforms tested, and five glypicans (GPC1, GPC3-6) were detected in the LRRTM4-Fc pulldown [PMID:23911103].","affinity_potency":[],"species_and_systems":"Mass spectrometry used rat brain homogenate; binding assays used HA-tagged mouse glypican cDNAs in HEK293T cells [PMID:23911103]. Curated species labels say human, but these were not the experimental species.","localisation_and_range":"LRRTM4 is flagged membrane-bound and GPC6 secreted [flag]; the paper describes glypican as a GPI-anchored HSPG and the interaction as trans-synaptic [PMID:23911103].","caveats":"The abstract speaks of glypican as a class; follow-up experiments focused on GPC4, and GPC4 but not GPC6 is strongly expressed in developing cortex and hippocampus (Fig. S1B) [PMID:23911103]. Whether GPC6 was among the isoforms tested in cell-surface binding is not stated explicitly in our excerpts.","key_references":[{"PMID":"23911103","why":"Identifies glypican as an LRRTM4 receptor; five glypicans including GPC6 seen in the LRRTM4 pulldown"}],"covers":["LR002938","LR006163"]},"LR011938":{"pair":"LTBP1 -> TGFB2","headline":"Database-only association of LTBP1 with TGF-beta-2 latent complex; no verified evidence.","interaction_type":"database-asserted only","direction_and_effect":"No verified paper (three pending). Reactome lists LTBP1,LTBP3:TGFB2:LAP2 in the extracellular region [DB:Reactome]. UniProt says LTBP1 regulates TGF-beta activation by maintaining it in an inactive state (text truncated) [DB:UniProt]. Annotated Inhibitory.","molecular_requirements":"Complex includes LAP2 [DB:Reactome]; further requirements not reported.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Both flagged secreted [flag].","caveats":"Ligand-Ligand pair; no papers verified.","key_references":[],"covers":["LR011938"]},"LR004459":{"pair":"LTF -> LRP1","headline":"Lactoferrin binds LRP1 and both blocks uptake of other ligands and drives mitogenic signalling; evidence mixes bovine and human/rat systems.","interaction_type":"direct binding","direction_and_effect":"Bovine lactoferrin bound LRP on blots and blocked LRP-dependent cholesteryl ester synthesis stimulation in cultured human fibroblasts, acting as a competitive inhibitor of other ligands [PMID:1464627]. In osteoblasts, lactoferrin induced RAP-sensitive p42/44 MAPK signalling and proliferation, reduced in LRP1-null fibroblasts [PMID:15178744].","molecular_requirements":"RAP, an LRP1/2 inhibitor, blocked lactoferrin endocytosis and signalling [PMID:15178744]. Endocytic and signalling functions of LRP1 are independent of each other [PMID:15178744]. LRP has at least three distinct, partially overlapping ligand sites [PMID:1464627].","affinity_potency":[],"species_and_systems":"Bovine lactoferrin with LRP in cultured human fibroblasts [PMID:1464627]; primary rat osteoblasts, human SaOS-2 cells and LRP1-null fibroblasts [PMID:15178744]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Lactoferrin flagged secreted [flag]; endocytic receptor uptake from the extracellular space [PMID:15178744].","caveats":"Both papers abstract-only. No affinity. In 15178744, osteoblasts also express LRP2, so LRP1-specificity relies on SaOS-2 and LRP1-null cells. Human lactoferrin was not used in the first paper.","key_references":[{"PMID":"1464627","why":"LRP binds lactoferrin and blocks other ligands"},{"PMID":"15178744","why":"LRP1-dependent lactoferrin mitogenic signalling"}],"covers":["LR001046","LR004459"]},"LR006169":{"pair":"LY6H -> CD36","headline":"LY6H binds CD36 on cells in a CRISPRa screen follow-up; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Tetramerized LY6H (400 nM) stained CD36-transfected cells by flow cytometry, identifying CD36 as a receptor in a cell-based CRISPR activation screen [PMID:36178190]. Effect not reported in our evidence.","molecular_requirements":"Full-length CD36 transfected cells were used; other ligands including NRN1, VWC2L and SCRG1 also bound CD36 [PMID:36178190]. Subunit requirements not reported.","affinity_potency":[],"species_and_systems":"Cell-surface staining of CD36-transfected cells with SA-647 tetramerized ligand; species of the constructs labelled human [PMID:36178190].","localisation_and_range":"LY6H flagged not secreted, CD36 transmembrane [flag]; the screen used multimerized ligands.","caveats":"Evidence is cell staining, not purified-protein binding or affinity in our excerpts. Scavenger receptor CD36 binds multiple ligands [PMID:36178190], so specificity is a concern.","key_references":[{"PMID":"36178190","why":"CRISPRa screen identifies CD36 binding LY6H"}],"covers":["LR002944","LR006169"]},"LR002947":{"pair":"MBL2 -> LRP1","headline":"MBL binds CD91 (LRP1) directly in vitro in one paper; a second paper places CD91 downstream of calreticulin.","interaction_type":"direct binding","direction_and_effect":"MBL binds CD91 in a time- and concentration-dependent manner, inhibited by known CD91 ligands [PMID:21054788]. MBL with C1q stimulates apoptotic cell ingestion via calreticulin bound to CD91 [PMID:11560994].","molecular_requirements":"MASP-3 inhibits MBL-CD91 binding and MASP-binding-deficient MBL mutants cannot interact with CD91, so the site is at or near the MASP-binding site [PMID:21054788]. Calreticulin may be a co-partner [PMID:11560994].","affinity_potency":[],"species_and_systems":"Human proteins and human macrophages (HMDM) and Jurkat targets [PMID:11560994]; PMID:21054788 labelled human. Mouse pair is ortholog-inferred.","localisation_and_range":"MBL2 is flagged secreted [flag]; soluble pattern-recognition molecule acting on phagocyte surface CD91 (paracrine/local).","caveats":"Both papers read as abstracts (PMID:11560994 with full-text excerpts). In PMID:11560994 CD91 is a partner of calreticulin rather than a proven direct MBL binder. IntAct lists surface plasmon resonance for PMID:21054788 [DB:IntAct].","key_references":[{"PMID":"21054788","why":"MBL-CD91 binding and MASP-site dependence"},{"PMID":"11560994","why":"MBL/C1q uptake via calreticulin-CD91"}],"covers":["LR002947","LR006172"]},"LR004468":{"pair":"MDK -> ALK","headline":"Midkine binds ALK with picomolar apparent affinity on intact human cells, but curators mark the pair as contested.","interaction_type":"direct binding","direction_and_effect":"Midkine binds ALK and stimulates ALK phosphorylation in WI-38 fibroblasts and activates PI3-kinase and MAP kinase signalling (agonist). Anti-ALK antibodies blocked MK binding and MK-stimulated colony formation [PMID:12122009].","molecular_requirements":"ALK extracellular ligand-binding domain is involved; pleiotrophin competes for ALK binding [PMID:12122009].","affinity_potency":[{"value":"Kd 170 pM","assay":"apparent Kd of MK binding to ALK","system":"intact human cells","cite":"PMID:12122009"},{"value":"Kd 20 pM","assay":"apparent Kd of PTN competition of MK binding","system":"intact human cells","cite":"PMID:12122009"}],"species_and_systems":"Human cells (SW-13, WI-38, HUVEC, SH-SY5Y, U87MG) and athymic nude mice for tumour growth [PMID:12122009]. Mouse pair is ortholog-inferred.","localisation_and_range":"MDK is flagged secreted, not transmembrane; ALK is a transmembrane receptor [flag]. Secreted growth factor, paracrine.","caveats":"Curator notes the pair is contested, not accepted in much of the ALK literature, and warrants downweighting pending independent replication. Abstract only. Reactome, BioGRID and UniProt records exist [DB:Reactome][DB:BioGRID][DB:UniProt].","key_references":[{"PMID":"12122009","why":"MK-ALK binding, blockade and signalling"}],"covers":["LR001055","LR004468"]},"LR009346":{"pair":"MDK -> LRP2","headline":"Megalin (LRP2) bound midkine less strongly than LRP; qualitative, abstract-only evidence.","interaction_type":"direct binding","direction_and_effect":"Brushin/megalin bound to MK, less strongly than LRP [PMID:10772929]. Effect direction not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Day-13 mouse embryo affinity chromatography per the abstract; species labels are blank in the curated row [PMID:10772929].","localisation_and_range":"MDK is flagged secreted, not transmembrane [flag].","caveats":"Single abstract-only sentence, no affinity given for megalin. UniProt records the interaction [DB:UniProt].","key_references":[{"PMID":"10772929","why":"megalin binds midkine less strongly than LRP"}],"covers":["LR009346"]},"LR004477":{"pair":"MDK -> TSPAN1","headline":"One abstract-only paper reports midkine interacting with TSPAN1 in head and neck cancer cells; assay not detailed.","interaction_type":"direct binding","direction_and_effect":"Midkine interacted with TSPAN1 and promoted TSPAN1 association with integrin alpha6beta1 in HNSCC cells, with FAK, paxillin and Stat1alpha activation and increased migration/invasiveness [PMID:18851943].","molecular_requirements":"Signalling is described as integrin-dependent, with TSPAN1-alpha6beta1 integrin association [PMID:18851943].","affinity_potency":[],"species_and_systems":"Human HNSCC cells [PMID:18851943]. Mouse pair is ortholog-inferred.","localisation_and_range":"Not reported in our evidence; midkine flagged secreted [flag]. TSPAN1 is a tetraspanin and its extracellular binding site is not described.","caveats":"Abstract-only; the physical assay for the MK-TSPAN1 interaction is not given, and our curated 'direct_binding' label may overstate it. Acts as an integrin-organising partner rather than a classic receptor, and no affinity.","key_references":[{"PMID":"18851943","why":"MK interacts with TSPAN1 and enhances TSPAN1-integrin association in HNSCC cells"}],"covers":["LR001064","LR004477"]},"LR008374":{"pair":"MELTF -> PLG","headline":"Membrane-bound melanotransferrin acts as a cell-surface plasminogen receptor in one abstract-only paper; direction is a curation convention.","interaction_type":"direct binding","direction_and_effect":"Membrane-bound melanotransferrin expression in CHO cells raised cell-surface plasminogen binding about 2-fold; antibody L235 and soluble MTf abolished binding, so mMTf is described as a potential plasminogen receptor [PMID:15936756]. It also stimulated plasminogen activation about 2.5-fold and cell invasion about 3-fold [PMID:15936756].","molecular_requirements":"Membrane-bound form was needed; soluble truncated MTf blocked rather than supported binding [PMID:15936756].","affinity_potency":[],"species_and_systems":"Human MTf in transfected CHO cells and SK-MeL-28 melanoma cells [PMID:15936756].","localisation_and_range":"Membrane-bound melanotransferrin acts at the cell surface [PMID:15936756]; plasminogen is a secreted protein [flag].","caveats":"Class is Receptor-Receptor in the database, so the ligand/receptor labelling is conventional. 'Potential' receptor wording, abstract only, binding shown on cells without purified-protein affinity.","key_references":[{"PMID":"15936756","why":"mMTf increases cell-surface plasminogen binding and activation"}],"covers":["LR008374"]},"LR006178":{"pair":"MFGE8 -> ITGB5","headline":"Mouse RPE evidence that MFG-E8 ligates alphavbeta5 to drive rhythmic phagocytosis; abstract only.","interaction_type":"functional only","direction_and_effect":"MFG-E8 stimulates rhythmic POS phagocytosis by ligating apical alphavbeta5 receptors of the RPE [PMID:17620600]. Loss of MFG-E8, like loss of alphavbeta5, eliminated alphavbeta5 downstream signalling via MerTK [PMID:17620600].","molecular_requirements":"Acts through the alphavbeta5 heterodimer [PMID:17620600].","affinity_potency":[],"species_and_systems":"Mouse retinal pigment epithelium, MFG-E8-deficient mice [PMID:17620600]. Human pair is ortholog-inferred.","localisation_and_range":"Mfge8 is flagged secreted [flag]; alphavbeta5 sits on RPE apical microvilli [PMID:17620600].","caveats":"Functional (knockout) evidence, abstract only; retinal adhesion was only minimally reduced without MFG-E8.","key_references":[{"PMID":"17620600","why":"MFG-E8-alphavbeta5 signalling in RPE phagocytosis"}],"covers":["LR002953","LR006178"]},"LR002956":{"pair":"MIA -> ITGB1","headline":"MIA binds integrin beta1 (as alpha4beta1 and alpha5beta1) in melanoma cells by far-Western and co-IP and reduces integrin activity; abstract only.","interaction_type":"direct binding","direction_and_effect":"MIA interacts with integrin alpha4beta1 and alpha5beta1, down-regulating integrin activity and MAPK signalling, an antagonist-type effect [PMID:16517605].","molecular_requirements":"The paper identifies alpha4beta1 and alpha5beta1 heterodimers, so both subunits belong to the complex [PMID:16517605]. MIA also binds fibronectin [PMID:16517605]. beta1 is the shared chain of both integrins.","affinity_potency":[],"species_and_systems":"Human malignant melanoma cells [PMID:16517605]. Mouse pair is ortholog-inferred.","localisation_and_range":"MIA is flagged secreted [flag].","caveats":"Abstract only; no affinity. Evidence is for the integrin heterodimers, not a single chain; the abstract does not say which assay showed which integrin.","key_references":[{"PMID":"16517605","why":"MIA binds alpha4beta1/alpha5beta1 integrins and reduces MAPK signalling"}],"covers":["LR002956","LR006181"]},"LR004486":{"pair":"Mmp1a -> Itga2","headline":"Direct binding of MMP-1 to the alpha2 integrin I domain by ELISA; mouse pair projected from human, one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"The alpha(2) integrin I domain bound pro and active MMP-1 specifically and in a divalent cation-dependent manner, but not MMP-3 or MMP-13 [PMID:11359774]. Effect direction is not reported in our evidence.","molecular_requirements":"Binding is via the I domain of the alpha(2) subunit; both the linker and hemopexin-like domains of MMP-1 were needed for optimal binding [PMID:11359774]. Whether beta1 is required is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Purified human MMP-1 and recombinant alpha(2) integrin I domain in ELISA [PMID:11359774]. The mouse Mmp1a pair is ortholog-inferred, with no mouse experiment in our evidence.","localisation_and_range":"Mmp1a is flagged as secreted [flag]; alpha2 integrin is a cell-surface receptor, so presentation would be proteinase anchored at the cell surface [PMID:11359774].","caveats":"Only purified-protein ELISA with an isolated I domain; no cell or in vivo data in our evidence. Abstract read only. Mouse pair is projected from human.","key_references":[{"PMID":"11359774","why":"ELISA mapping of MMP-1 binding to alpha2 I domain"}],"covers":["LR004486"]},"LR006187":{"pair":"MMP2 -> PECAM1","headline":"MMP-2 co-immunoprecipitates with PECAM-1 in rat retinal endothelial cells, where MMP-2 treatment lowers PECAM-1; one paper, mainly cleavage.","interaction_type":"functional only","direction_and_effect":"MMP-2 treatment (50 to 400 ng/ml) significantly decreased PECAM-1 in rat retinal microvascular endothelial cells, and GM6001 restored PECAM-1 under high glucose [PMID:30793207]. This is an antagonist-type (loss of receptor) effect rather than signalling.","molecular_requirements":"Three possible MMP-2 cleavage sites on PECAM-1 were predicted in silico (PROSPER); the interaction was seen by immunoprecipitation [PMID:30793207].","affinity_potency":[],"species_and_systems":"Primary rat retinal microvascular endothelial cells and streptozotocin-diabetic rats; the pair is ortholog-inferred for human and mouse [PMID:30793207].","localisation_and_range":"MMP-2 is annotated as secreted and PECAM1 as transmembrane [flag]; the effect is on an endothelial junction protein.","caveats":"Co-IP is the only interaction evidence and was in cell lysates, so direct binding is not established. Cleavage sites were predicted in silico, not mapped experimentally. Human and mouse rows are inferred from rat data.","key_references":[{"PMID":"30793207","why":"Co-IP of PECAM-1/MMP-2 and MMP-2-induced PECAM-1 loss in rat retinal cells"}],"covers":["LR002962","LR006187"]},"LR002965":{"pair":"MMP9 -> TLR4","headline":"A Neu1-MMP9 complex is bound to TLR4 on macrophages and is needed for LPS-induced signalling; abstract only.","interaction_type":"functional only","direction_and_effect":"A Neu1-MMP9 complex is bound to TLR4 on the cell surface of naive macrophages; MMP9 inhibition, knockdown or knockout reduced LPS-induced Neu1 activity and NF\u03baB activation (agonist-type support) [PMID:21873432].","molecular_requirements":"MMP9 acts in a complex with Neu1 and G\u03b1(i) signalling; the alpha-2,3-sialyl residue of TLR is the Neu1 target [PMID:21873432].","affinity_potency":[],"species_and_systems":"Macrophage cells, including MMP9-knockout primary macrophages [PMID:21873432]. The human pair is ortholog-inferred; the mouse row is not.","localisation_and_range":"MMP9 is flagged as secreted [flag]; the paper places the complex on the macrophage cell surface [PMID:21873432].","caveats":"MMP9 is a TLR4-associated component rather than a ligand activating TLR4 itself; direct MMP9-TLR4 binding is not shown in the abstract. Abstract only; the curated experiment species is human while the abstract mentions knockout macrophages.","key_references":[{"PMID":"21873432","why":"Neu1-MMP9 complex bound to TLR4 and required for LPS signalling"}],"covers":["LR002965","LR006190"]},"LR007249":{"pair":"MSTN -> ACVR2B:TGFBR1","headline":"No judged papers; rests on BioGRID and IntAct records for ACVR2B-MSTN only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"ACVR2B binding is recorded; TGFBR1 is not evidenced here [DB:BioGRID 297250][DB:IntAct].","affinity_potency":[],"species_and_systems":"BioGRID Affinity Capture-Western [DB:BioGRID 297250] and IntAct surface plasmon resonance [DB:IntAct O14793-Q13705].","localisation_and_range":"Myostatin is secreted [flag].","caveats":"No confirmed papers (abstract_insufficient and review_only). The database records concern ACVR2B and MSTN, not the complex.","key_references":[],"covers":["LR007249"]},"LR006196":{"pair":"MUC1 -> ICAM1","headline":"Adhesion-type MUC1:ICAM-1 interaction supported by one full-text in vitro paper.","interaction_type":"functional only","direction_and_effect":"MUC1 on cancer cells bound ICAM-1; ZR-75-1 cells showed stronger ICAM-1 binding than MCF7 cells, and slow E-selectin rolling led to MUC1:ICAM-1 firm adhesion [PMID:22866263].","molecular_requirements":"E-selectin engagement slows rolling before ICAM-1 contact; underglycosylated MUC1 core epitope is involved [PMID:22866263].","affinity_potency":[],"species_and_systems":"Human breast cancer cell lines and recombinant ICAM-1 in flow microtubes [PMID:22866263]; mouse pair ortholog-inferred.","localisation_and_range":"Both annotated secreted and membrane flags [flag]; the paper concerns cell-surface adhesion.","caveats":"Single paper; cell-line level correlation rather than purified binding; no affinity.","key_references":[{"PMID":"22866263","why":"MUC1:ICAM-1 adhesion in rolling assays"}],"covers":["LR002971","LR006196"]},"LR004495":{"pair":"MYOC -> FZD3","headline":"Myocilin-AP fusion bound FZD3 in a browser-read Results sentence; modulates Wnt signalling.","interaction_type":"direct binding","direction_and_effect":"Myocilin-AP bound Fzd1, Fzd3, Fzd4, Fzd7, Fzd10 and sFRPs; myocilin modulated Wnt signalling and its stress fiber activity was blocked by sFRP1/sFRP3 and beta-catenin siRNA [PMID:19188438]. Effect of myocilin on the receptor (agonist versus modulator) is not clear from our evidence.","molecular_requirements":"Binding was to cysteine-rich domains of Frizzled receptors; sFRPs also bound, so Wnt pathway modulators are involved [PMID:19188438]. Co-receptor requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Myocilin expressed in HEK293 cells, tested on human trabecular meshwork and NIH 3T3 cells; construct species for the binding sentence not stated. Mouse pair is ortholog-inferred [PMID:19188438].","localisation_and_range":"Myocilin is flagged secreted [flag]; acts as a secreted modulator in conditioned medium [PMID:19188438].","caveats":"Binding sentence was browser-read and unverified (spot-check pending); dossier abstract only. Binding is AP-fusion to receptor CRDs, not full receptor, and shared across several Fzd paralogs, so paralog specificity is weak.","key_references":[{"PMID":"19188438","why":"Myocilin-AP binding to Fzd CRDs and Wnt signalling modulation"}],"covers":["LR001084","LR004495"]},"LR002974":{"pair":"NAMPT -> TLR4","headline":"Direct binding of recombinant NAMPT/PBEF to TLR4 by SPR, with TLR4-dependent NF-kB activation and lung injury.","interaction_type":"direct binding","direction_and_effect":"NAMPT/PBEF acts as a TLR4 agonist: TLR4 antibodies or inhibitors reduced rPBEF-induced NF-kB Ser536 phosphorylation, and rPBEF-induced lung inflammation was reduced in TLR4-/- mice [PMID:26272519].","molecular_requirements":"The paper proposes MD-2-independent activation, via a protruding region (S402-N412) resembling LPS; this is predicted, not confirmed by mutation [PMID:26272519].","affinity_potency":[],"species_and_systems":"Human lung endothelial cells, recombinant proteins in SPR, and mice (wild type and TLR4-/-) [PMID:26272519]. In silico modelling used murine NAMPT/PBEF.","localisation_and_range":"NAMPT flagged secreted [flag]; extracellular NAMPT is described as released and acting on lung endothelium [PMID:26272519].","caveats":"SPR was qualitative (no Kd reported). The dossier excerpts do not show a binding assay in cells; activity relies on inhibitors and knockouts. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"26272519","why":"SPR binding and TLR4-dependent NF-kB activation by NAMPT/PBEF"}],"covers":["LR002974","LR006199"]},"LR002983":{"pair":"NECTIN1 -> FGFR1","headline":"One abstract-only paper: the nectin-1 Ig3 module binds FGFR isoforms by SPR and induces FGFR1c phosphorylation.","interaction_type":"direct binding","direction_and_effect":"Recombinant nectin-1 Ig3 induced neurite outgrowth, abolished by SU5402 or dominant-negative FGFR1, and induced FGFR1c phosphorylation like the whole ectodomain [PMID:22955284]. Agonist of FGFR signalling.","molecular_requirements":"Only the third, membrane-proximal Ig module (Ig3) was tested; the full-length protein is not reported to bind in our evidence [PMID:22955284]. SPR showed direct interaction with various FGFR isoforms [PMID:22955284].","affinity_potency":[],"species_and_systems":"Mouse nectin-1 Ig3, primary hippocampal and cerebellar granule neurons [PMID:22955284]. The human row is ortholog-inferred. BioGRID lists a reconstituted complex [DB:BioGRID].","localisation_and_range":"Nectin-1 is a flagged secreted and transmembrane protein [flag]; the tested form was a soluble recombinant fragment.","caveats":"Single paper read as abstract; no SPR affinity in our evidence.","key_references":[{"PMID":"22955284","why":"SPR and functional data for nectin-1 Ig3 with FGFR"}],"covers":["LR002983","LR006208"]},"LR002992":{"pair":"NLGN2 -> LHFPL4","headline":"Abstract reports LHFPL4/GARLH4 as a major NL2 binding partner at inhibitory synapses; PDB records exist for the pair.","interaction_type":"direct binding","direction_and_effect":"LHFPL4/GARLH4 is identified as a major NL2 binding partner enriched at inhibitory postsynaptic sites; the two regulate each other's protein levels and synaptic clustering in the cerebellum, and Lhfpl4/Garlh4-/- mice have profound impairment of inhibitory synapse formation [PMID:29742426]. A curator label of 'agonist' is not stated in the abstract.","molecular_requirements":"Not reported in our evidence beyond the two-protein association.","affinity_potency":[],"species_and_systems":"Abstract describes knockout mice and cerebellum; curator lists human for both partners. Human pair is ortholog-projected; the mouse pair is not [PMID:29742426].","localisation_and_range":"NLGN2 is a transmembrane protein at inhibitory postsynaptic sites [PMID:29742426]; LHFPL4 has a receptor flag only [flag]. Contact/synaptic setting.","caveats":"Abstract only; the binding method is not stated, and 'binding partner' may include indirect association. PDB lists 13 structures with a chain of Q8NFZ4 and a chain of Q7Z7J7 (e.g. 9FAJ) [DB:PDB 9FAJ]; the dossier does not say which accession is which protein.","key_references":[{"PMID":"29742426","why":"LHFPL4/GARLH4 as NL2 binding partner, knockout phenotype"}],"covers":["LR002992","LR006216"]},"LR007366":{"pair":"NODAL -> ACVR1B:ACVR2A:CFC1","headline":"Plausible Nodal complex, but the evidence concerns Cripto-1 (TDGF1), not CFC1 (Cripto-3).","interaction_type":"functional only","direction_and_effect":"Nodal bound to the type II receptor uses Cripto-1 to recruit ALK4 for SMAD2/3 activation [PMID:39840816].","molecular_requirements":"Requires an EGF-CFC co-receptor, but the paper names Cripto-1, not CFC1 [PMID:39840816]. ACVR2A is not named in the abstract.","affinity_potency":[],"species_and_systems":"NTERA-2 cells, SPR and AlphaFold3; species not stated in the abstract [PMID:39840816].","localisation_and_range":"Nodal flagged secreted [flag].","caveats":"CFC1 itself is not tested in our evidence. Two other papers were abstract-insufficient and one review-only. Paper read as abstract only.","key_references":[{"PMID":"39840816","why":"Cripto-1-dependent Nodal ternary complex with ALK4"}],"covers":["LR007366"]},"LR008257":{"pair":"NODAL -> ACVR1C:ACVR2B","headline":"No verified paper; support is from UniProt and BioGRID.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states ACVR1C is a receptor for activin AB, activin B, activin E and NODAL [DB:UniProt]; BioGRID lists a NODAL-ACVR2B reconstituted complex [DB:BioGRID].","molecular_requirements":"Row lists ACVR1C with ACVR2B; no co-receptor included.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Nodal flagged secreted [flag].","caveats":"The single judged paper was review-only; no primary experiment is verified for this exact complex.","key_references":[],"covers":["LR008257"]},"LR011929":{"pair":"NOG -> GDF6","headline":"Noggin to GDF6 rests on a hedged UniProt statement ('probably'); no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt says Noggin inhibits chondrocyte differentiation through its interaction with GDF5 and, probably, GDF6 [DB:UniProt, PMID:21976273]; annotated Inhibitory [flag].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"GDF6 is flagged secreted [flag].","caveats":"Weakest support in the group: the only evidence is a UniProt sentence with 'probably'; three papers had insufficient abstracts.","key_references":[],"covers":["LR011929"]},"LR008428":{"pair":"NOTCH2 -> JAG1","headline":"Jagged1 binds Notch2 with sub-nanomolar Kd in mouse proteins; human row supported by orthology.","interaction_type":"direct binding","direction_and_effect":"Mouse Jagged1 bound mouse Notch2 on cells and as a purified extracellular portion, Ca2+-dependent [PMID:10551863]. Jagged1 also bound Notch1 and Notch3 [PMID:10551863].","molecular_requirements":"The DSL domain of Jagged1 is the minimal binding unit and is indispensable; EGF-like repeats 1 and 2 modulate affinity [PMID:10551863].","affinity_potency":[{"value":"Kd 0.4 nM","assay":"Scatchard analysis of Jagged1 binding","system":"BaF3 cells (mouse Notch2)","cite":"PMID:10551863"},{"value":"Kd 0.7 nM","assay":"Scatchard analysis of Jagged1 binding","system":"soluble Notch2 protein","cite":"PMID:10551863"}],"species_and_systems":"Mouse proteins; abstract only. The human row is described by the curators as supported by orthology.","localisation_and_range":"JAG1 flagged transmembrane [flag]; the ligand was used as fusion proteins [PMID:10551863].","caveats":"Species gap between mouse experiments and human pair. Row stored reversed (NOTCH2 in ligand slot). Reactome and BioGRID agree [DB:Reactome R-HSA-1980058].","key_references":[{"PMID":"10551863","why":"Quantitative binding of Jagged1 to Notch2"}],"covers":["LR008428"]},"LR007357":{"pair":"NRG1 -> ITGA6:ITGB4","headline":"NRG1 to the alpha6beta4 integrin rests on database records only; the underlying paper is judged on the single-chain rows.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states ITGA6:ITGB4 binds NRG1 via its EGF domain and that this binding is essential for NRG1-ERBB signalling [DB:UniProt].","molecular_requirements":"UniProt describes ITGA6:ITGB4 in a ternary complex with NRG1 and ERBB3 [DB:UniProt]. Both chains form the complex.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond a human row.","localisation_and_range":"NRG1 is flagged secreted and transmembrane [flag].","caveats":"No papers were accepted for this complex row (one judged different_entity); support is from UniProt annotations that cite PMID 20682778, which curators verified only for the single-chain rows.","key_references":[],"covers":["LR007357"]},"LR004558":{"pair":"NRG2 -> ERBB3","headline":"NRG2 binds ErbB3 and activates it; supported by two 1997 abstract-level papers plus database records.","interaction_type":"direct binding","direction_and_effect":"Agonist: the NRG-2 EGF-like domain binds ErbB3 and ErbB4 and stimulates a different ErbB phosphorylation profile from NRG-1 [PMID:9168115]. Neuregulin-2beta only activated cell lines with ErbB3 and/or ErbB4 [PMID:9168114].","molecular_requirements":"Recombinant NRG2-beta induced phosphorylation of ErbB2, ErbB3 and ErbB4 in cells expressing all three; in defined combinations, activity required ErbB3 and/or ErbB4 [PMID:9168114]. UniProt says ERBB3 extracellular domain binds NRG1 and NRG2, shifting it to an extended dimerisation-competent state [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in cell lines and binding assays; the human and mouse pairs are both ortholog-inferred.","localisation_and_range":"NRG2 is flagged secreted and transmembrane [flag].","caveats":"Both papers are abstract only; no affinity quoted. One further paper is still pending. The ortholog-inferred species rows are projected.","key_references":[{"PMID":"9168115","why":"NRG-2 EGF domain binds ErbB3 and ErbB4"},{"PMID":"9168114","why":"NRG2 activates cells with ErbB3/ErbB4"}],"covers":["LR001149","LR004558"]},"LR004567":{"pair":"NTF3 -> NTRK2","headline":"NT-3 binds and activates TrkB as a non-cognate ligand, via Arg-31/His-33; support is abstract-only.","interaction_type":"direct binding","direction_and_effect":"NT-3 can to some extent bind and activate non-cognate TrkA and TrkB; Arg31/His33-to-Ala mutation greatly diminished binding and activation of TrkB [PMID:8621424].","molecular_requirements":"The binding site on TrkA/TrkB is dominated by Arg-31 and His-33, the same residues used for p75LNGFR binding; the cognate TrkC was unaffected [PMID:8621424].","affinity_potency":[],"species_and_systems":"Human experiment species per curator; abstract only [PMID:8621424]. Mouse pair is ortholog-inferred.","localisation_and_range":"NTF3 flagged secreted, NTRK2 transmembrane [flag].","caveats":"The abstract says the physiological relevance of NT-3 binding to TrkA/TrkB is unclear [PMID:8621424]. The verified evidence is mutational loss of binding. No numeric affinity. One review-only row is not shown.","key_references":[{"PMID":"8621424","why":"Arg31/His33 determine NT-3 binding to TrkA/TrkB"}],"covers":["LR001158","LR004567"]},"LR004576":{"pair":"NTN1 -> UNC5C","headline":"Netrin-1 binds UNC5 family fragments by pull-down with human protein; UNC5C is not named individually in the evidence.","interaction_type":"direct binding","direction_and_effect":"Human soluble netrin binds each immunoglobulin repeat of UNC5 in a pull-down assay [PMID:12810718]. UniProt notes netrin-1 binding may dissociate UNC5C from TUBB3 and lead to axon repulsion [DB:UniProt].","molecular_requirements":"UNC5 binds soluble netrin with 1:1 stoichiometry in solution; no evidence of a ternary complex of netrin, DCC and UNC5 [PMID:12810718].","affinity_potency":[],"species_and_systems":"In vitro pull-down with human netrin purified from CHO cells [PMID:12810718]. Reactome lists NTN1:UNC5C complexes [DB:Reactome]. Mouse pair is ortholog-inferred.","localisation_and_range":"Netrin-1 is secreted and UNC5C is transmembrane [flag].","caveats":"Abstract read only, and it refers to the UNC5 family generally rather than UNC5C. Two other rows are abstract_insufficient and one retracted, not shown.","key_references":[{"PMID":"12810718","why":"Netrin pull-down with UNC5 receptor fragments"}],"covers":["LR001167","LR004576"]},"LR006259":{"pair":"NTN3 -> DCC","headline":"Murine netrin-3 binds DCC with lower affinity than other netrin receptors; evidence is one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Murine netrin-3 binds DCC, with lower affinity than to neogenin and the UNC5 receptors [PMID:10366627]. Netrin-3 can mimic netrin-1 outgrowth-promoting activity on commissural axons but with lower specific activity [PMID:10366627].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse netrin-3 protein; the human pair is ortholog-inferred and the mouse pair projected from human evidence. Assay format is not stated in the abstract [PMID:10366627].","localisation_and_range":"Netrin-3 is flagged secreted and DCC transmembrane [flag].","caveats":"Abstract only, no affinity numbers. Binding is weaker than for other receptors, so DCC may be a minor receptor for netrin-3.","key_references":[{"PMID":"10366627","why":"Murine netrin-3 binding to DCC with comparatively low affinity"}],"covers":["LR003035","LR006259"]},"LR005269":{"pair":"NTRK3 -> PTPRS","headline":"TrkC (NTRK3) binds PTPsigma directly in trans with high affinity; one abstract-only paper plus database records support it.","interaction_type":"direct binding","direction_and_effect":"Postsynaptic TrkC binds axonal PTPsigma in trans, neurotensin-independent, and the pair acts as a bidirectional synaptic organizer: PTPsigma triggers TrkC-mediated clustering of postsynaptic molecules and TrkC triggers presynaptic differentiation [PMID:21262467]. A TrkC-neutralising antibody that blocks the interaction and TrkC knockdown impair glutamatergic synapse formation [PMID:21262467].","molecular_requirements":"All TrkC isoforms, including noncatalytic ones, bind PTPsigma, but TrkA and TrkB do not [PMID:21262467]. Kinase activity is not needed for this adhesion role (noncatalytic isoforms act) [PMID:21262467]. Reactome lists a PTPRS:NTRK3 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Hippocampal neuron-fibroblast coculture and in vivo knockdown; the abstract does not name the species [PMID:21262467]. The human pair is ortholog-inferred; the mouse record is the direct one.","localisation_and_range":"Membrane-bound on both sides, acting by trans (contact) binding at synapses [PMID:21262467]. Note the PTPRS entity carries a secreted flag [flag], but the paper describes an axonal membrane protein.","caveats":"Only one paper was judged and it was read as an abstract. No affinity value is reported in our evidence beyond 'high-affinity'. BioGRID has an affinity-capture-western record and UniProt notes an interaction [DB:BioGRID][DB:UniProt]. Ligand/receptor roles are conventional here, since the interaction is symmetric.","key_references":[{"PMID":"21262467","why":"TrkC-PTPsigma trans binding and synaptic organizing function"}],"covers":["LR001930","LR005269"]},"LR004585":{"pair":"NXPH1 -> NRXN1","headline":"Neurexophilin-1 binds the LNS2 domain of neurexin-1 directly, supported by crystal structures and earlier biochemical work.","interaction_type":"direct binding","direction_and_effect":"Neurexophilin was purified in a complex with neurexin I alpha by alpha-latrotoxin affinity chromatography [PMID:8699246], and neurexophilins 1 and 3 bind the second LNS domain of all three alpha-neurexins [PMID:9856994]. Crystal structures of Nxph1 with Nrxn1 LNS2 show an extensive binding interface [PMID:31566781].","molecular_requirements":"Binding needs the LNS2 domain of alpha-neurexin; all LNS2 splice variants bind in the recombinant study [PMID:9856994]. The SS2A insert increases the binding affinity [PMID:31566781]. No co-receptor is reported.","affinity_potency":[],"species_and_systems":"Recombinant proteins and knockout mice (mouse) [PMID:9856994]; rat brain purification [PMID:8699246]; structures with human/mouse constructs per curator tags [PMID:31566781]. Both species pairs are ortholog-inferred.","localisation_and_range":"Secreted ligand [flag] binding a presynaptic transmembrane neurexin [flag][PMID:31566781]. Neurexophilin is expressed in a subpopulation of neurons, probably inhibitory interneurons [PMID:8699246].","caveats":"Affinity values are not given in the dossier text. The 1996 and 1998 papers were read as abstracts; the 1996 species is unspecified. Three of six confirmed papers are shown here.","key_references":[{"PMID":"31566781","why":"Structures of Nxph1 with Nrxn LNS2 and isoform specificity"},{"PMID":"9856994","why":"NXPH1 and NXPH3 bind LNS2 of all three alpha-neurexins"},{"PMID":"8699246","why":"Original co-purification of neurexophilin with neurexin I alpha"}],"covers":["LR001176","LR004585"]},"LR006268":{"pair":"OMG -> PTPRD","headline":"OMG binds PTPRD by SPR in the micromolar range in one full-text paper; no other evidence.","interaction_type":"direct binding","direction_and_effect":"Direction is OMG as ligand, PTPRD as receptor. SPR with human OMG and RPTP ectodomains showed micromolar-range binding to all three R2A RPTPs including PTPRD [PMID:36178190]. Functional effect is not reported in our evidence.","molecular_requirements":"PTPRD ectodomain used alone; no co-receptor or subunit requirement reported in our evidence.","affinity_potency":[{"value":"micromolar range","assay":"SPR, OMG vs RPTP ectodomains","system":"recombinant human proteins","cite":"PMID:36178190"}],"species_and_systems":"Human OMG and human PTPRD recombinant ectodomains, SPR [PMID:36178190]. Mouse pair is projected from human, not tested.","localisation_and_range":"OMG is flagged non-secreted [flag]; the paper treats it as a secreted ligand used as a multimerised bait, so range (contact versus diffusible) is not settled in our evidence. PTPRD is a flagged transmembrane receptor [flag].","caveats":"Single paper. The PTPRD interaction came from phylogenetic homology analysis, not from the CRISPRa screen (the screen's top hit was PTPRU) [PMID:36178190]. No exact Kd given for PTPRD in our excerpts. No database records.","key_references":[{"PMID":"36178190","why":"SPR validation of OMG binding to R2A RPTPs"}],"covers":["LR003044","LR006268"]},"LR004594":{"pair":"ORM1 -> CCR5","headline":"AGP (ORM1) binds CCR5-dependent sites on human macrophages; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"AGP binds specifically to monocyte-derived macrophages at two sites, and an anti-CCR5 antibody against the second extracellular loop inhibited AGP binding (67%) [PMID:11336643]. AGP also inhibited binding of V3Cs and MIP-1beta to these cells [PMID:11336643]. Agonist or antagonist action on CCR5 is not reported in our evidence.","molecular_requirements":"Glycans (probably mannose residues) are partly involved in binding; heat denaturation only partly inhibited it (43%), suggesting protein-protein interaction as well [PMID:11336643].","affinity_potency":[{"value":"Kd 16 nM","assay":"AGP binding to MDM, high-affinity site","system":"human primary macrophages","cite":"PMID:11336643"},{"value":"Kd 4.9 microM","assay":"AGP binding to MDM, low-affinity site","system":"human primary macrophages","cite":"PMID:11336643"}],"species_and_systems":"Human AGP on human monocyte-derived macrophages, native cell system [PMID:11336643]. Mouse pair is projected from human.","localisation_and_range":"ORM1 is flagged secreted and CCR5 transmembrane [flag]; AGP acts as a soluble ligand on the macrophage surface.","caveats":"Abstract only. The Kd values are for binding to whole macrophages, not purified CCR5; CCR5 involvement rests on antibody inhibition (the abstract is cut off before further results). No database records.","key_references":[{"PMID":"11336643","why":"AGP binding to CCR5-expressing macrophages"}],"covers":["LR001185","LR004594"]},"LR006286":{"pair":"PCDHB6 -> PCDHB6","headline":"Mouse PCDHB6 binds itself homophilically in trans (K562 aggregation and SPR), with strict isoform specificity.","interaction_type":"direct binding","direction_and_effect":"Pcdhb6 shows strict trans homophilic specificity: \u03b26 and \u03b28 do not engage heterophilically despite 91-97% identity in EC2-EC3 [PMID:25171406]. Five interfacial residues account for its specificity versus \u03b28 [PMID:35253643].","molecular_requirements":"Clustered protocadherin trans interaction is homophilic and isoform-specific; cis multimers with other isoforms may form the actual cell-surface unit, so one isoform alone may not reproduce the interface.","affinity_potency":[],"species_and_systems":"Mouse proteins: K562 aggregation [PMID:25171406]; EC1-4 fragments by SPR and K562 coaggregation [PMID:35253643]. Human pair is ortholog-inferred.","localisation_and_range":"Membrane-bound cell-adhesion molecule; trans homophilic contact between cells (juxtacrine), not secreted [flag].","caveats":"Isoforms 91-97% identical in EC2-EC3 do not cross-react, so paralogs cannot substitute [PMID:25171406]. Surface delivery of alpha isoforms needs cis partners, per curator note, so a multimer may be what meets across the cleft.","key_references":[{"PMID":"25171406","why":"strict homophilic specificity across isoforms"},{"PMID":"35253643","why":"SPR and residues tuning beta6 specificity"}],"covers":["LR003052","LR006286"]},"LR006817":{"pair":"PDGFC -> KDR","headline":"PDGFC -> KDR rests on a single GtoPdb record; no curated paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence; GtoPdb lists Type=None; Action=None [DB:GtoPdb]. The project record is annotated Stimulatory.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"PDGFC is flagged both secreted and transmembrane [flag]; KDR is flagged a transmembrane receptor [flag].","caveats":"No verified papers; three papers were judged abstract-insufficient. Support is a database assertion only, with no type or affinity.","key_references":[],"covers":["LR006817"]},"LR001939":{"pair":"PLA2G2A -> ITGA5","headline":"sPLA2-IIA activates integrin alpha5beta1 through site 2; abstract-level evidence from a single paper.","interaction_type":"functional only","direction_and_effect":"sPLA2-IIA activated integrins alpha4beta1 and alpha5beta1 in a site 2-mediated manner [PMID:25398877]. The curator detail reports activation of purified soluble and cell-surface alpha5beta1, independent of catalytic activity or M-type receptor [PMID:25398877]. Curated effect: agonist.","molecular_requirements":"The alpha5beta1 heterodimer is the unit; a site 2 peptide from integrin beta1 suppressed sPLA2-IIA effects [PMID:25398877]. UniProt lists ITGA5:ITGB1 binding PLA2G2A [DB:UniProt P05556].","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; integrin binding and cell assays [PMID:18635536][PMID:25398877]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted, from the PLA2G2A secreted flag [flag].","caveats":"Abstract only. The docking prediction and direct site 2 binding in the abstract concern alphavbeta3; alpha5beta1 is covered by one sentence [PMID:25398877]. Alpha5 alone is not the binding unit.","key_references":[{"PMID":"25398877","why":"sPLA2-IIA site 2 activation of alphavbeta3, alpha4beta1, alpha5beta1"}],"covers":["LR001939","LR005276"]},"LR005278":{"pair":"PLA2G2A -> ITGB1","headline":"sPLA2-IIA binds and activates beta1 integrins (alpha4beta1, alpha5beta1) via site 2; beta1 is one chain of the heterodimer.","interaction_type":"direct binding","direction_and_effect":"sPLA2-IIA bound alpha4beta1 and competed with VCAM-1 [PMID:18635536]. It activated alpha4beta1 and alpha5beta1 in a site 2-mediated manner; flow cytometry showed enhanced FN8-11 binding, blocked by an S2-beta1 peptide [PMID:25398877]. Agonist.","molecular_requirements":"Beta1 pairs with alpha4 or alpha5 here; a peptide from integrin beta1 site 2 specifically bound sPLA2-IIA and suppressed activation [PMID:25398877]. Beta1 alone: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; integrin binding and cell assays [PMID:18635536][PMID:25398877]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted, from the PLA2G2A secreted flag [flag].","caveats":"The 18635536 evidence sentence does not mention beta1; the curator labels it from the title. The 25398877 full-text read is marked unverified in notes. Species: human; mouse pair ortholog-inferred.","key_references":[{"PMID":"18635536","why":"Binds alpha4beta1, competes with VCAM-1"},{"PMID":"25398877","why":"Site 2 activation of beta1 integrins"}],"covers":["LR001941","LR005278"]},"LR007384":{"pair":"PLAUR -> ITGA4:ITGB1","headline":"Direct cell-based binding of soluble uPAR to alpha4beta1 (ITGA4:ITGB1) integrin in one paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Soluble uPAR (suPAR D2D3) bound integrin-transfected CHO cells in a cation-dependent manner, blocked by anti-integrin and anti-uPAR antibodies [PMID:11053440]. It acts as a ligand, signalling consequence not reported in our evidence.","molecular_requirements":"Binding shown to the alpha-beta heterodimer on cells; subunit contribution not resolved [PMID:11053440]. ","affinity_potency":[],"species_and_systems":"Human uPAR on hamster (CHO) cells [PMID:11053440].","localisation_and_range":"uPAR is described as a GPI-anchored protein lacking a transmembrane structure that acts as an integrin ligand, in trans between apposed cells, as well as an associated protein in cis [PMID:11053440]. Cell-cell contact range.","caveats":"Single paper (full text); no affinity. The paper reports heterodimers; this complex row is classed Receptor-Receptor.","key_references":[{"PMID":"11053440","why":"uPAR binds integrins alpha4beta1, alpha6beta1, alpha9beta1, alphavbeta3 on CHO cells"}],"covers":["LR007384"]},"LR004639":{"pair":"PODXL2 -> SELL","headline":"Endoglycan (PODXL2) functions as an L-selectin ligand through tyrosine sulfation and sLex; one primary paper plus a database record.","interaction_type":"direct binding","direction_and_effect":"Endoglycan can function as an L-selectin ligand, like CD34 and podocalyxin [PMID:12889478]. BioGRID records a reconstituted complex [DB:BioGRID].","molecular_requirements":"Binding uses sulfation on two tyrosine residues and O-linked sLex structures in the acidic amino-terminal region, unlike the 6-sulfo-sLex mucin-domain mechanism of CD34 and podocalyxin [PMID:12889478].","affinity_potency":[],"species_and_systems":"Species and cell system not stated in our evidence beyond the abstract [PMID:12889478]; mouse pair is ortholog-inferred.","localisation_and_range":"Flagged transmembrane, not secreted [flag]; contact-dependent adhesion.","caveats":"Primary evidence is a single abstract-only paper. PMID:18606703 only mentions L-selectin as prior work, not as its own result. No affinity reported.","key_references":[{"PMID":"12889478","why":"endoglycan as L-selectin ligand, sulfation and sLex mechanism"}],"covers":["LR001237","LR004639"]},"LR004648":{"pair":"POMC -> OPRM1","headline":"Beta-endorphin activates OPRM1 in a recent HEK293T assay within a heterodimer; support is thin and indirect.","interaction_type":"functional only","direction_and_effect":"In HEK293T cells expressing mouse Oprm1 with MrgprX1, 1 uM beta-endorphin raised intracellular calcium, and naltrexone abolished it [PMID:41904513]. Reactome records opioid binding to MOR [DB:Reactome]; a PDB structure with POMC and OPRM1 exists [DB:PDB 8F7Q].","molecular_requirements":"The response was seen in cells co-expressing OPRM1 and MRGPRX1 (heterodimer, switching to Galpha q/11 calcium signalling) [PMID:41904513]; OPRM1 alone was not tested with beta-endorphin in the excerpts shown.","affinity_potency":[],"species_and_systems":"Mouse receptors in HEK293T cells; human orthologs were used in some other experiments in the paper [PMID:41904513]. Full text was read. The mouse pair is ortholog-inferred.","localisation_and_range":"POMC flagged secreted, OPRM1 transmembrane [flag].","caveats":"The calcium readout is a non-canonical heterodimer response, not classic Gi/o signalling. Ligand is beta-endorphin, not full-length POMC. Curators judged 3 papers as different_entity and others abstract_insufficient or review_only.","key_references":[{"PMID":"41904513","why":"Beta-endorphin evokes naltrexone-sensitive calcium in OPRM1/MRGPRX1 cells"}],"covers":["LR001246","LR004648"]},"LR006349":{"pair":"POSTN -> STAB2","headline":"Periostin was independently confirmed as a circulating ligand of Stab1/Stab2 in one mouse atherosclerosis study, read as an abstract.","interaction_type":"direct binding","direction_and_effect":"Periostin, reelin and TGFBi were independently confirmed as novel circulating ligands of Stab1/2 [PMID:36325910]. Stab1/2 mediate clearance of circulating plasma molecules; ApoE-Stab1-KO and ApoE-Stab2-KO mice show reduced atherogenesis [PMID:36325910]. Receptor clearance, not signalling agonism, is the described effect.","molecular_requirements":"Not reported in our evidence; the curator's notes mention GST-pulldown and endocytosis assays [PMID:36325910].","affinity_potency":[],"species_and_systems":"Mouse knockout and plasma proteomics plus in vitro assays; read as abstract only [PMID:36325910]. Human pair is the dossier species; the mouse pair is ortholog-inferred in the dossier.","localisation_and_range":"Periostin is flagged secreted [flag]; the paper describes circulating ligands cleared by liver sinusoidal endothelium [PMID:36325910].","caveats":"Single abstract-level paper, with no affinity or species-of-binding detail. The paper confirms five ligand-receptor combinations at once, and the abstract does not give per-pair detail. Stab1 and Stab2 are paralogs with shared ligands; one study covers both.","key_references":[{"PMID":"36325910","why":"Stab1/2 identified as clearance receptors for periostin, reelin and TGFBi"}],"covers":["LR003128","LR006349"]},"LR008707":{"pair":"PROC -> THBD","headline":"No paper evidence; only UniProt text, which describes THBD as a cofactor for protein C activation, not as a PROC receptor.","interaction_type":"database-asserted only","direction_and_effect":"Not established as a ligand-receptor signal. UniProt says THBD acts as a cofactor for thrombin activation of protein C on endothelial cells [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not reported in our evidence; the pair is annotated human.","localisation_and_range":"PROC flagged secreted and THBD transmembrane [flag]; the UniProt text places activity on the endothelial cell surface [DB:UniProt].","caveats":"No judged papers: five abstracts were insufficient, one unresolvable, one about a different entity. The database record concerns THBD helping thrombin activate PROC, which is a substrate-cofactor relation and not receptor signalling by PROC.","key_references":[],"covers":["LR008707"]},"LR004657":{"pair":"PROK1 -> PROKR1","headline":"Well supported agonist-receptor pair: PROK1 binds and activates PROKR1 in transfected cells; evidence from abstracts only.","interaction_type":"direct binding","direction_and_effect":"PROK1 and PROK2 bound and activated the receptors, with nanomolar calcium responses in CHO cells expressing PK-R1 [PMID:12054613]. Activation mobilised calcium, stimulated phosphoinositide turnover and p44/p42 MAPK [PMID:11886876]. PK1 stimulated Ca2+ responses in PKR1 cells; PKRs also couple to Gq and Gi and induce cAMP accumulation [PMID:15772293]. GtoPdb lists PROK1 at PROKR1 as full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence; single receptor chain used in heterologous expression [PMID:11886876].","affinity_potency":[],"species_and_systems":"Human protein experiments in heterologous cells (CHO, recombinant) [PMID:11886876][PMID:12054613][PMID:15772293]; mouse pair is projected from human evidence (ortholog inferred).","localisation_and_range":"Both PROK1 and the receptor are annotated secreted and transmembrane respectively [flag], so paracrine signalling onto membrane receptors.","caveats":"All three papers read as abstracts only. Receptor selectivity between PKR1 and PKR2 is not quantified in the abstract [PMID:12054613]. GtoPdb affinities are given as pIC50 ranges without a stated assay [DB:GtoPdb].","key_references":[{"PMID":"12054613","why":"Deorphanisation: high-affinity binding and calcium responses in CHO cells."},{"PMID":"11886876","why":"Receptors bind and are activated by nanomolar recombinant prokineticins."},{"PMID":"15772293","why":"PK1 Ca2+ responses in PKR1 cells as pharmacological reference."}],"covers":["LR001257","LR004657"]},"LR008527":{"pair":"PRSS3 -> F2RL1","headline":"PRSS3 reported to activate PAR2 in cancer cell models; two abstract-only papers.","interaction_type":"functional only","direction_and_effect":"PRSS3 isoform 1 interacted with PAR2 and raised ERK1/2 phosphorylation in vitro and in vivo in breast cancer models [PMID:41046946]. Shear stress triggered PRSS3 to cleave the N-terminal inhibitory domain of PAR2 within 2 h in circulating lung cancer cells [PMID:37395651].","molecular_requirements":"The splicing isoform PRSS3-V1 mainly drove the effect [PMID:41046946].","affinity_potency":[],"species_and_systems":"Human cancer cell models and in vivo models; species of in vivo work not stated in our evidence [PMID:41046946][PMID:37395651].","localisation_and_range":"F2RL1 flagged as receptor; PRSS3 localisation not reported in our evidence.","caveats":"Both papers abstract-only and in cancer settings; one further abstract was insufficient. Activation is by cleavage rather than classical binding.","key_references":[{"PMID":"37395651","why":"Shear stress triggers PRSS3 cleavage of PAR2."},{"PMID":"41046946","why":"PRSS3-V1 interacts with PAR2 and drives ERK1/2."}],"covers":["LR008527"]},"LR004666":{"pair":"PSPN -> GFRA1","headline":"Persephin was reported to signal through GFRalpha1/RET in reporter assays; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"Persephin is identified as a novel ligand for the GFRalpha1/RET receptor complex, confirmed by several methods including neurite outgrowth [PMID:20350599].","molecular_requirements":"Functions with RET in the GFRalpha1/RET complex [PMID:20350599].","affinity_potency":[],"species_and_systems":"Reporter-gene system and neurite outgrowth from sympathetic ganglion explants; species not specified [PMID:20350599].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Abstract only; no binding measurement or affinity; species unspecified. The same paper treats GFRalpha4 as persephin's conventional receptor [PMID:20350599].","key_references":[{"PMID":"20350599","why":"Reporter-gene identification of PSPN as GFRalpha1/RET ligand."}],"covers":["LR001266","LR004666"]},"LR004675":{"pair":"PTN -> ALK","headline":"Reported high-affinity PTN-ALK binding and signalling, supported by databases, but the curators note the ligand role was later disputed.","interaction_type":"direct binding","direction_and_effect":"PTN binds the ALK extracellular domain and induces phosphorylation of ALK and of IRS-1, Shc, phospholipase C-gamma and phosphatidylinositol 3-kinase, so it acts as an activating ligand [PMID:11278720]. Reactome and UniProt record the binding [DB:Reactome R-HSA-201486] [DB:UniProt].","molecular_requirements":"The ALK extracellular domain is sufficient for binding; binding was blocked by excess ALK ECD [PMID:11278720]. Co-receptors are not reported in our evidence.","affinity_potency":[{"value":"Kd 32 +/- 9 pm","assay":"cell-free and intact-cell radioligand binding","system":"human PTN and ALK","cite":"PMID:11278720"}],"species_and_systems":"Human, recombinant and cell-line assays [PMID:11278720]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine. ALK is flagged as transmembrane [flag].","caveats":"Two papers are confirmed (one shown) and two rows are review_only. The curator note says PTN as an ALK ligand was disputed by later work, with other ligands now considered physiological [PMID:11278720]; this note is not from the paper itself.","key_references":[{"PMID":"11278720","why":"Phage display, Kd and phosphorylation evidence for PTN-ALK"}],"covers":["LR001275","LR004675"]},"LR006367":{"pair":"PTN -> ITGAV","headline":"PTN binds integrin alphavbeta3 directly in an RGD-independent way; the ITGAV chain is only implied by the heterodimer.","interaction_type":"direct binding","direction_and_effect":"Integrin alphavbeta3 directly interacts with PTN and mediates PTN-induced endothelial cell migration; a function-blocking anti-alphavbeta3 antibody abolished it [PMID:19141530]. PTN stimulated migration of alphavbeta3-positive U87MG cells but decreased migration of glioma cells lacking alphavbeta3 [PMID:19141530].","molecular_requirements":"Binding is RGD-independent and uses the beta3 specificity loop (residues 177-184); PTN-induced beta3 Tyr773 phosphorylation depends on RPTPbeta/zeta and c-Src [PMID:19141530]. Contribution of the alphaV chain alone is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human endothelial and glioma cell lines [PMID:19141530]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine.","caveats":"Abstract only. The binding determinant lies on beta3, so ITGAV-only evidence is lacking. BioGRID lists ITGB3-PTN and UniProt lists ITGAV:ITGB3 binding PTN [DB:BioGRID] [DB:UniProt]. Midkine did not interact with alphavbeta3 [PMID:19141530].","key_references":[{"PMID":"19141530","why":"Direct RGD-independent PTN-alphavbeta3 binding and migration"}],"covers":["LR003146","LR006367"]},"LR006376":{"pair":"PTN -> SDC4","headline":"Only evidence is BIAcore binding of PTN to syndecan-4 chains in one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"PTN bound both heparan sulfate and chondroitin sulfate chains of syndecan-4, with stronger CS binding than syndecan-1 [PMID:15226297]. Receptor activation not reported in our evidence.","molecular_requirements":"Glycosaminoglycan-chain dependent; simultaneous HS and CS binding suggested to form a ternary complex [PMID:15226297].","affinity_potency":[],"species_and_systems":"Syndecans from normal murine mammary gland epithelial cells [PMID:15226297]; dossier species label is human.","localisation_and_range":"Not reported in our evidence beyond the ectodomain used in vitro.","caveats":"Abstract only; no affinity; glycan-mediated binding that is not specific to PTN; the same paper serves the SDC1 pair.","key_references":[{"PMID":"15226297","why":"BIAcore of PTN binding to syndecan-4 chains"}],"covers":["LR003155","LR006376"]},"LR001948":{"pair":"PTPRC -> MRC1","headline":"Mannose receptor binds CD45 glycans; one paper reports a functional effect on T cells, both abstract-level.","interaction_type":"direct binding","direction_and_effect":"MRC1 on dendritic cells interacts with CD45 on T cells, inhibiting its phosphatase activity, upregulating CTLA-4 and inducing T-cell tolerance [PMID:27601670]. The cysteine-rich domain of MRC1 (CR-Fc) bound CD45 isoforms in a sugar-dependent manner [PMID:10575006].","molecular_requirements":"Binding by the CR domain is glycan-dependent and specific to cell-specific glycoforms; two low molecular weight CD45 isoforms bound [PMID:10575006].","affinity_potency":[],"species_and_systems":"Mouse spleen and lymph node lysates and macrophages [PMID:10575006]; dendritic cell/T-cell cocultures in vitro and in vivo [PMID:27601670]; species of the latter not specified.","localisation_and_range":"Both flagged transmembrane [flag]; contact-dependent.","caveats":"Abstracts only; no affinity; binding depends on particular glycoforms so may not occur on every CD45-expressing cell. IntAct lists a solid-phase assay [DB:IntAct]. Mouse pair listed as not ortholog-inferred, but dossier experiment species fields conflict with each other.","key_references":[{"PMID":"27601670","why":"MRC1-CD45 interaction inhibits CD45 phosphatase on T cells"},{"PMID":"10575006","why":"CR domain of mannose receptor binds CD45 glycoforms"}],"covers":["LR001948","LR005284"]},"LR006385":{"pair":"PTPRG -> CNTN3","headline":"PTPRG carbonic-anhydrase-like domain binds CNTN3 Ig repeats 2-3 by crystallography; one primary paper.","interaction_type":"direct binding","direction_and_effect":"PTPRG interacts with CNTN3, 4, 5 and 6, whereas PTPRZ binds only CNTN1 [PMID:20133774]. Effect direction is not reported in our evidence.","molecular_requirements":"Crystal structures show the carbonic anhydrase-like domains of PTPRZ/PTPRG interact directly with the second and third Ig repeats of contactins; the CNTN4 complex used mouse CNTN4 with mouse PTPRG's carbonic-anhydrase-like domain [PMID:20133774].","affinity_potency":[],"species_and_systems":"Curated as human proteins; the co-crystal used mouse CNTN4 and mouse PTPRG domains [PMID:20133774]. Human pair is ortholog-inferred; mouse pair is not.","localisation_and_range":"Not stated in the paper text shown; entity flags: CNTN3 not secreted [flag].","caveats":"Structure paper was read only as abstract; the abstract-level result shows PTPRG binds CNTN3, 4, 5 and 6 and no affinity is reported in our evidence. The PTPRG-CNTN3 evidence is the family-level statement, not a CNTN3-specific structure.","key_references":[{"PMID":"20133774","why":"Crystal structures of PTPRG/PTPRZ with contactins; CNTN specificity"}],"covers":["LR003164","LR006385"]},"LR006394":{"pair":"PTPRZ1 -> CNTN1","headline":"PTPRZ1 (PTPRZ) binds CNTN1: co-crystal structure, binding assays and in vivo oligodendrocyte data; well supported.","interaction_type":"direct binding","direction_and_effect":"PTPRZ binds only CNTN1 among contactins [PMID:20133774]. The cocrystal structure and binding assays show PTPRZ binds CNTN1 on oligodendrocyte precursor cells; in PTPRZ-deficient versus wild-type mice, PTPRZ-CNTN1 binding inhibits precursor proliferation and promotes maturation into oligodendrocytes (curated effect: antagonist) [PMID:21969550]. An earlier paper found F3 (mouse contactin 1) binds PTPzeta/RPTPbeta directly [PMID:10103110].","molecular_requirements":"The carbonic anhydrase-like domain of PTPRZ binds tandem Ig repeats of CNTN1 [PMID:21969550] [DB:PDB 3S97]. UniProt records the same domain-level interaction [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins in the structural papers (abstracts) and mice for the in vivo data [PMID:21969550]; mouse brain extracts and astrocyte cultures for F3 [PMID:10103110]. Both species pairs are direct.","localisation_and_range":"PTPRZ1 is flagged secreted [flag], and the 1999 paper's phosphacan/PTPzeta isoforms were affinity-isolated from brain, so secreted and membrane forms may both exist, but which acts here is not reported.","caveats":"Structural papers were read as abstract only. The 1999 paper used mouse F3 and unspecified species for the PTPzeta isoforms, and its abstract says binding was 'highest affinity' without a value. Two further rows were abstract_insufficient.","key_references":[{"PMID":"21969550","why":"PTPRZ-CNTN1 cocrystal structure; effect on oligodendrogenesis"},{"PMID":"20133774","why":"Domain specificity: PTPRZ binds only CNTN1"},{"PMID":"10103110","why":"F3/contactin binds PTPzeta/RPTPbeta directly"}],"covers":["LR003173","LR006394"]},"LR005287":{"pair":"PVR -> CD226","headline":"PVR (CD155) is a ligand of CD226 (DNAM-1) in Fc-staining and NK killing assays; activating; structure and UniProt support.","interaction_type":"direct binding","direction_and_effect":"PVR-Fc stained DNAM-1-expressing COS-7 cells and DNAM-1-Fc stained PVR-expressing CHO-K cells, and the DNAM-1/PVR interaction enhanced NK-mediated tumour lysis, reversed by masking either partner [PMID:15607800]. CD226 activates NK cytotoxicity on CD155 engagement and is opposed by CD96 [PMID:24658051]. UniProt says CD226 binding of PVR/NECTIN2 promotes NK and CTL cytotoxicity [DB:UniProt].","molecular_requirements":"The ligand is shared: NECTIN2 also binds DNAM-1 [PMID:15607800], and CD96 competes with CD226 for CD155 [PMID:24658051]. DNAM-1 stimulation is associated with beta(2) integrin [PMID:15034010]; that is background in that paper.","affinity_potency":[],"species_and_systems":"Human NK cells and cell lines in the curated rows; antibodies came from mouse immunisation [PMID:15607800]. Both human and mouse pairs are direct.","localisation_and_range":"Both membrane proteins; the NK-to-target contact is a juxtacrine interaction [PMID:15607800].","caveats":"Competing receptors (CD96, TIGIT) share PVR and give opposing outcomes [PMID:24658051], which matters when scoring PVR signalling. All papers were abstract-only. No affinity in our evidence. Structure [DB:PDB 6O3O] and BioGRID/IntAct/Reactome records exist.","key_references":[{"PMID":"15607800","why":"Reciprocal Fc staining identifies PVR as a DNAM-1 ligand"},{"PMID":"24658051","why":"CD96 competes with CD226 for CD155; CD226 activates NK cells"}],"covers":["LR001951","LR005287"]},"LR004684":{"pair":"QRFP -> QRFPR","headline":"QRFP is the cognate agonist of QRFPR (GPR103), supported by binding, cryo-EM structure, and databases in human and mouse.","interaction_type":"direct binding","direction_and_effect":"QRFP selectively activates GPR103 [PMID:38897996]; it is a full agonist in GtoPdb [DB:GtoPdb]. In mice, central QRFP induced feeding behaviour, blocked by a Y1 antagonist [PMID:16648250].","molecular_requirements":"Cryo-EM complex of QRFP26 with GPR103 and G protein (mini-Gsqi\u03b21\u03b32); QRFP26 residues 3-26 were modelled [PMID:38897996]. The extended QRFP form was more active (P518) [PMID:12714592].","affinity_potency":[{"value":"EC50 = 7 nm","assay":"activation of receptor-transfected cells by extended peptide P518","system":"SP9155 (GPR103) transfected cells","cite":"PMID:12714592"}],"species_and_systems":"Human GPR103 (cryo-EM, deorphanisation) [PMID:38897996][PMID:12714592]; mouse GPR103A and GPR103B and rat-derived QRFP in transfected cells and mice [PMID:16648250]. PDB 8ZH8 and Reactome records exist [DB:PDB 8ZH8][DB:Reactome].","localisation_and_range":"QRFP is flagged secreted [flag]; mRNA in hypothalamus, with central actions [PMID:16648250].","caveats":"PMID:38897996 and PMID:16648250 abstract only; the structure abstract is truncated. PMID:16648250 gives nanomolar affinities without numbers. Three rows are pending and one review only.","key_references":[{"PMID":"12714592","why":"Deorphanisation; EC50 7 nm"},{"PMID":"16648250","why":"QRFP purified from rat brain; human and mouse receptors"},{"PMID":"38897996","why":"Cryo-EM structure of QRFP26-GPR103-G protein"}],"covers":["LR001284","LR004684"]},"LR007393":{"pair":"RARRES2 -> GPR1","headline":"Supported only by structural and UniProt database records; the single judged paper was too limited to confirm.","interaction_type":"database-asserted only","direction_and_effect":"UniProt describes GPR1 as a receptor for chemerin [DB:UniProt]; PDB lists cryo-EM structures of human GPR1 bound to chemerin, for example 8XGM [DB:PDB 8XGM].","molecular_requirements":"Not reported in our evidence beyond the two chains in the PDB entries (Q99969 and P46091) [DB:PDB 8JJP].","affinity_potency":[],"species_and_systems":"Structures are human (electron microscopy) [DB:PDB 8XGM]; no curator-verified paper.","localisation_and_range":"Chemerin is flagged secreted [flag].","caveats":"The only paper row is abstract_insufficient, so no curated paper confirms this pair. Related GPR1 evidence sits under the CMKLR2 alias dossier. This entry is a likely duplicate of RARRES2 -> CMKLR2 under a different symbol.","key_references":[],"covers":["LR007393"]},"LR004693":{"pair":"Ren1 -> Atp6ap2","headline":"Mouse pair projected from human evidence on renin and ATP6AP2; no mouse experiment in our evidence.","interaction_type":"direct binding","direction_and_effect":"The only evidence is the human study in which transfected cells showed renin- and prorenin-specific binding and ERK1/ERK2 activation [PMID:12045255].","molecular_requirements":"No co-receptor reported in our evidence [PMID:12045255].","affinity_potency":[],"species_and_systems":"Experiments were on human receptor and renin [PMID:12045255]; the mouse pair is ortholog-inferred and not tested.","localisation_and_range":"Ligand flagged secreted [flag]; the human receptor has a single transmembrane domain [PMID:12045255].","caveats":"Ortholog projection only; abstract-level reading; no database records for this mouse pair.","key_references":[{"PMID":"12045255","why":"Human evidence from which the mouse pair is inferred"}],"covers":["LR004693"]},"LR001957":{"pair":"RLN2 -> RXFP3","headline":"Relaxin-2 is a weaker, biased agonist at RXFP3 relative to relaxin-3, shown in two cell-signalling studies read as abstracts.","interaction_type":"functional only","direction_and_effect":"H2 relaxin acts as a biased agonist at RXFP3: lower efficacy than H3 relaxin for p38MAPK and ERK1/2 but similar efficacy for JNK1/2 phosphorylation [PMID:24641548]. H3 relaxin gave stronger cAMP inhibition and ERK1/2 activation, while H2 relaxin strongly stimulated AP-1 reporters [PMID:20159943]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"H2 relaxin induced RXFP3 interaction only with Galphai2 or GalphaoB and did not promote beta-arrestin interaction [PMID:24641548]. A distinct 125I-H2 relaxin binding site was seen on RXFP3-expressing cells [PMID:20159943].","affinity_potency":[{"value":"pEC50 7.050000190734863 to 8.350000381469727","assay":"GtoPdb affinity range (pEC50)","system":"not reported in our evidence","cite":"DB:GtoPdb"}],"species_and_systems":"Human ligand and receptor; RXFP3 expressed in CHO-K1 and HEK-293 cells and murine septal neuron SN56 cells [PMID:20159943]; BRET assays in [PMID:24641548].","localisation_and_range":"Ligand flagged as secreted and receptor as transmembrane [flag].","caveats":"Both papers read as abstracts only. H2 relaxin is weaker than H3 relaxin on most readouts. One further paper was judged review only.","key_references":[{"PMID":"24641548","why":"H2 relaxin signalling bias and G-protein/arrestin profile at RXFP3"},{"PMID":"20159943","why":"H2 relaxin is a biased ligand relative to H3 relaxin at RXFP3"}],"covers":["LR001957"]},"LR012379":{"pair":"RNF43 -> FZD5:LRP6","headline":"RNF43 -> FZD5:LRP6 is supported only by database records; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a binding reaction in which ZNRF3 and RNF43 bind the FZD:LRP5/6 receptor complex [DB:Reactome]; BioGRID lists RNF43-FZD5 affinity-capture or PCA records [DB:BioGRID]; UniProt notes RNF43 interacts with FZD5 [DB:UniProt]. Direction and effect are not reported in our evidence.","molecular_requirements":"Receptor is a FZD plus LRP complex; the Reactome record is generic for the FZD:LRP5/6 complex, not specific to this paralog combination, and which subunit RNF43 contacts is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; experimental systems not reported in our evidence.","localisation_and_range":"Not reported in our evidence (no secreted or membrane flag given).","caveats":"No paper confirmed this pair (outcomes: pending 2). Two papers are still pending.","key_references":[],"covers":["LR012379"]},"LR010948":{"pair":"RPS27A -> RIPK1","headline":"RPS27A -> RIPK1 has only one IntAct co-immunoprecipitation record and is likely not a ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct anti-tag coimmunoprecipitation, citing PMID 31980649 [DB:IntAct].","localisation_and_range":"No localisation flags available.","caveats":"No judged papers; one judged row was a different entity. Association by co-IP only.","key_references":[],"covers":["LR010948"]},"LR010957":{"pair":"RSPO1 -> WNT1","headline":"RSPO1 -> WNT1 rests only on UniProt statements of interaction.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states RSPO1 interacts with WNT1, and WNT1 interacts with RSPO1, RSPO2 and RSPO3 (by similarity) [DB:UniProt]. Effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and assay not stated; UniProt cites PMIDs 17804805 and 26902720 [DB:UniProt].","localisation_and_range":"Both secreted per flag [flag].","caveats":"No judged papers; one judged row concerned a different entity. Ligand-ligand class, not a ligand-receptor interaction; WNT1 side is by similarity.","key_references":[],"covers":["LR010957"]},"LR003199":{"pair":"RTN4R -> ADGRB1","headline":"Direct, high-affinity binding with a crystal structure, confirmed by two independent papers; RTN4R is the ligand for the BAI1 adhesion-GPCR.","interaction_type":"direct binding","direction_and_effect":"RTN4R ectodomain binds the thrombospondin type 1 repeat (TSR) region of ADGRB1 (BAI1); the Cell paper calls RTN4 receptors high-affinity ligands for BAIs [PMID:34758294]. Binding was also found by CRISPRa selection with an ADGRB1 probe and by AVEXIS [PMID:30477585]. Effect on signalling is not reported in our evidence; in human neurons RTN4 receptors regulate dendritic arborization, axonal elongation and synapse formation via glial versus neuronal BAIs [PMID:34758294].","molecular_requirements":"A single TSR domain of BAI1 is sufficient and binds the RTN4R leucine-rich repeat domain; C-mannosylation of tryptophan and O-fucosylation of threonine in the TSR domain form the interface [PMID:34758294]. TSR1-3 of ADGRB1 were sufficient for binding [PMID:30477585]. BAI2 does not bind RTN4Rs [PMID:34758294]. No requirement for other subunits is reported.","affinity_potency":[{"value":"Kd = 1.9 nM","assay":"surface plasmon resonance, recombinant ectodomains (highest of the BAI-RTN4R pairs; BAI3-RTN4R)","system":"purified recombinant proteins","cite":"PMID:34758294"},{"value":"Kd = 30.0 nM","assay":"surface plasmon resonance (lowest, BAI1-RTN4RL2)","system":"purified recombinant proteins","cite":"PMID:34758294"}],"species_and_systems":"Recombinant human ectodomains and HEK293 cells; the 1.65 A crystal structure used mouse RTN4R LRR with mouse BAI1 TSR3, and the paper says contact residues are conserved in human [PMID:34758294]. Human neurons were used for function [PMID:34758294]. Human and mouse pairs are both listed in the dossier.","localisation_and_range":"RTN4R is not flagged secreted but is a GPI-linked cell-surface protein in the text; trans-cellular adhesion between cells expressing BAIs and RTN4Rs was shown, so contact-dependent (juxtacrine) [PMID:34758294][PMID:30477585]. ADGRB1 carries a secreted flag [flag].","caveats":"The Kd values quoted are the extremes across BAI/RTN4R-family pairs, not necessarily this pair. ADGRB1 is flagged secreted although described as a membrane receptor [flag]. One study is a single CRISPRa screen per bait [PMID:30477585].","key_references":[{"PMID":"34758294","why":"SPR affinities, crystal structure, neuronal function"},{"PMID":"30477585","why":"independent CRISPRa and AVEXIS discovery of the interaction"}],"covers":["LR003199","LR006419"]},"LR006439":{"pair":"S100A4 -> TLR4","headline":"S100A4 drives cytokine production in RA PBMCs partly through TLR4; functional evidence only, abstract only.","interaction_type":"functional only","direction_and_effect":"S100A4 raised IL-1beta, IL-6 and TNF-alpha in rheumatoid arthritis PBMCs; this was at least partly mediated via TLR4, not RAGE, and by NF-kappaB, p38 and ERK1/2 [PMID:24643522].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human PBMCs from RA patients [PMID:24643522].","localisation_and_range":"S100A4 is flagged secreted [flag].","caveats":"No binding data; TLR4 involvement is partial. Abstract only. Cytokine induction was lower than S100A9 but greater than S100A8 and S100A12 [PMID:24643522].","key_references":[{"PMID":"24643522","why":"S100A4 proinflammatory effect partly via TLR4"}],"covers":["LR003221","LR006439"]},"LR006448":{"pair":"S100A8 -> TLR2","headline":"S100A8 signals partly through TLR2, secondary to TLR4; functional evidence from full text.","interaction_type":"functional only","direction_and_effect":"TLR2-deficient macrophages had an attenuated TNF-alpha release to mMrp8 (p < 0.05), hMrp8 induced NF-kappaB activation in HEK cells expressing hTLR2 (p < 0.01), and an anti-TLR2 mAb attenuated hMrp8-stimulated TNF-alpha from human monocytes (p < 0.05) [PMID:26329314]. Agonist, with TLR2 contributory and TLR4 predominant [PMID:26329314].","molecular_requirements":"TLR4 is the predominant receptor; TLR2 contributes. TLR2 acts as a heterodimer with TLR1 or TLR6 in general, but that is background in the paper and not tested for Mrp8 [PMID:26329314].","affinity_potency":[],"species_and_systems":"Murine macrophages (wild type and TLR-deficient), human monocytes and HEK293 cells expressing hTLR2; mouse pair is not ortholog-inferred [PMID:26329314].","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible.","caveats":"Binding to TLR2 is not shown; only functional dependence. LPS contamination was ruled out with heat-inactivation and polymyxin B [PMID:26329314]. Mrp8 pre-exposure also induces tolerance.","key_references":[{"PMID":"26329314","why":"TLR2 contributes to Mrp8-induced inflammation and tolerance, TLR4 predominant"}],"covers":["LR003231","LR006448"]},"LR006457":{"pair":"S100B -> AGER","headline":"S100B-RAGE is well supported: crystal structure, micromolar affinity, database binding records and functional work.","interaction_type":"direct binding","direction_and_effect":"S100B is recognized via the amino-terminal V-domain of RAGE; a 2.55 A crystal structure of S100B with a V-domain peptide (residues 54-68) shows two S100B dimers per peptide [PMID:25945582]. Structures are recorded in PDB [DB:PDB 4XYN] [DB:PDB 5D7F], with BioGRID, IntAct and UniProt interaction records [DB:BioGRID] [DB:IntAct] [DB:UniProt]. S100B triggers inflammation through RAGE [PMID:25945582]. Agonist. A second paper reports an additional S100B receptor, ALCAM, active in RAGE-/- cells [PMID:23729438].","molecular_requirements":"The V-domain is the recognition element [PMID:25945582].","affinity_potency":[{"value":"Kd 2.7 +/- 0.5 microM (wild-type V-domain); 1.3 +/- 0.7 microM (W61A mutant)","assay":"fluorescence titration","system":"S100B with intact RAGE V-domain, in vitro","cite":"PMID:25945582"}],"species_and_systems":"Human proteins in vitro [PMID:25945582]; mouse endothelial cells for the second paper [PMID:23729438].","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible. RAGE is flagged as a receptor [flag].","caveats":"Affinity values are reported as '2.7\u00b10.5' and '1.3\u00b10.7' microM in the abstract; structure used a peptide not full receptor. Abstracts only.","key_references":[{"PMID":"25945582","why":"Crystal structure and affinities of S100B with RAGE V-domain"},{"PMID":"23729438","why":"S100B also signals via ALCAM in RAGE-/- cells"}],"covers":["LR003241","LR006457"]},"LR004729":{"pair":"SCGB1A1 -> LRP2","headline":"Megalin is a co-receptor needed for CCSP uptake with cubilin, but does not bind CCSP itself; indirect evidence.","interaction_type":"functional only","direction_and_effect":"Internalization of CCSP was blocked by antibodies against megalin, and megalin-deficient mice showed defective tubular uptake and urinary CCSP excretion [PMID:11278724]. BioGRID lists a reconstituted complex [DB:BioGRID].","molecular_requirements":"Megalin is described as an endocytic receptor that does not bind CCSP but associates with cubilin, acting as a coreceptor for cubilin-mediated uptake [PMID:11278724].","affinity_potency":[],"species_and_systems":"Human CCSP in cultured cells with megalin antibodies; mouse megalin-deficient animals [PMID:11278724].","localisation_and_range":"CCSP is secreted [flag]; renal proximal tubule uptake.","caveats":"Per the abstract, megalin does not bind CCSP directly, so a ligand-receptor edge depends on cubilin. Abstract only. A second confirmed paper is not shown.","key_references":[{"PMID":"11278724","why":"Megalin as endocytic coreceptor for cubilin-bound CCSP"}],"covers":["LR001333","LR004729"]},"LR005296":{"pair":"Sectm1a -> Cd7","headline":"Mouse K12 (Sectm1a) binds mouse CD7; supporting papers are mainly human SECTM1, so mouse evidence is thin.","interaction_type":"direct binding","direction_and_effect":"Mouse K12-Fc bound mouse CD7 but not human CD7, and inhibited concanavalin A-induced proliferation of mouse lymph node T cells [PMID:10652336]. Other work on human SECTM1 shows CD7 binding on monocytes [PMID:24157461] and negative GM-CSF regulation in KG1a cells via SECTM1-Fc [PMID:24211252].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"The mouse pair is ortholog-inferred. Mouse binding is from the abstract of PMID:10652336; the other two papers used human SECTM1 and human cells [PMID:24157461] [PMID:24211252].","localisation_and_range":"Sectm1a is flagged secreted [flag].","caveats":"PMID:24211252 evidence was browser-read and the quote is unverified (spot-check pending). The mouse-specific statement comes from an abstract only. No affinity.","key_references":[{"PMID":"10652336","why":"Mouse K12 binds mouse but not human CD7"},{"PMID":"24157461","why":"Human SECTM1 binds CD7 on monocytes"}],"covers":["LR005296"]},"LR008509":{"pair":"SELE -> SELPLG","headline":"PSGL-1 binding to E-selectin shown in CHO transfectants and flow assays; glycan-dependent. Two abstract-level papers with database support.","interaction_type":"direct binding","direction_and_effect":"PSGL-1 (SELPLG) acts as a mucin-like ligand for E-selectin; microspheres coated with PSGL-1 attached and rolled on E-selectin-expressing cells under flow [PMID:9128259] [PMID:8621728].","molecular_requirements":"PSGL-1 bound P- and E-selectin only when co-expressed with C2GnT and an alpha1,3 fucosyltransferase; tyrosine-to-phenylalanine mutation abolished P-selectin but not E-selectin binding [PMID:8621728]. The first 19 amino acids with a sialyl Lewis x glycan at Thr16 were sufficient for E-selectin attachment, and more than one E-selectin site is suggested [PMID:9128259].","affinity_potency":[],"species_and_systems":"Human PSGL-1 in CHO transfectants and recombinant PSGL-1 on microspheres in a flow chamber [PMID:8621728] [PMID:9128259].","localisation_and_range":"Both annotated membrane-bound [flag]; contact-dependent (juxtacrine) adhesion, consistent with flow-chamber rolling [PMID:9128259].","caveats":"Holds only for properly glycosylated PSGL-1. Both papers read as abstract only (9128259 also had full text excerpts). No affinity reported. IntAct solid-phase record and Reactome E-selectin binding records also exist [DB:IntAct] [DB:Reactome].","key_references":[{"PMID":"8621728","why":"glycosylation requirements for PSGL-1 binding to E-selectin"},{"PMID":"9128259","why":"PSGL-1 N-terminal determinants for E-selectin rolling"}],"covers":["LR008509"]},"LR006475":{"pair":"SELENOP -> LRP8","headline":"LRP8 is the SELENOP receptor driving selenium uptake and ferroptosis protection in MYCN-amplified neuroblastoma; functional evidence, binding itself taken from prior work.","interaction_type":"functional only","direction_and_effect":"LRP8 overexpression conferred ferroptosis resistance and raised GPX4 protein; LRP8 loss caused ferroptosis, and SELENOP boosted GPX4 only in LRP8-proficient cells, so SELENOP signals through LRP8 as a selenium-supply receptor [PMID:37435859].","molecular_requirements":"Uptake supplies selenocysteine for GPX4 translation; low system Xc- activity makes cells dependent on LRP8. Other co-receptors not reported in our evidence [PMID:37435859].","affinity_potency":[],"species_and_systems":"Human neuroblastoma cells (SK-N-DZ) in vitro and orthotopic xenografts; mouse pair is ortholog-inferred [PMID:37435859].","localisation_and_range":"SELENOP is annotated secreted and LRP8 transmembrane [flag]; paracrine or endocrine uptake by receptor-mediated endocytosis is implied by the paper [PMID:37435859].","caveats":"This paper did not measure binding; it cites earlier studies for LRP2 and LRP8 being SELENOP receptors [PMID:37435859]. Abstract-level curation (full text excerpts available). No database records.","key_references":[{"PMID":"37435859","why":"LRP8-dependent SELENOP-derived selenium uptake and ferroptosis"}],"covers":["LR003259","LR006475"]},"LR008464":{"pair":"SELP -> SELPLG","headline":"Well-supported direct binding by database records including a PDB structure; no curator-verified paper in our evidence.","interaction_type":"direct binding","direction_and_effect":"P-selectin binds PSGL-1 as its ligand [DB:Reactome]; direction and signalling effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence beyond a co-crystal structure of one chain each [DB:PDB 1G1S].","affinity_potency":[],"species_and_systems":"Records are for human proteins; experimental species not reported in our evidence.","localisation_and_range":"Both annotated membrane-bound [flag]; contact-dependent.","caveats":"No paper was confirmed (one abstract_insufficient). Support is from databases: structure [DB:PDB 1G1S], SPR and X-ray records [DB:IntAct], affinity capture-Western [DB:BioGRID], binding reactions [DB:Reactome]. The HGNC name match is only a name [DB:HGNC approved name].","key_references":[],"covers":["LR008464"]},"LR001966":{"pair":"SELPLG -> SIGLEC5","headline":"Soluble Siglec-5 binds PSGL-1 in recombinant and cell assays and blocks leukocyte rolling; one paper only.","interaction_type":"direct binding","direction_and_effect":"Soluble Siglec-5 variants bound PSGL-1 and inhibited leukocyte rolling over E- and P-selectin in vitro, while adhesion onto VCAM1 was unaffected; this is antagonist/decoy-like action [PMID:27892504]. sSiglec-5/C4BP (0.8 mg/kg) reduced rolling leukocytes in healthy mice: 10.9 +/- 3.7 versus 23.5 +/- 9.3 leukocytes/field/min [PMID:27892504].","molecular_requirements":"Binding between ectodomains was dose-, calcium- and sialic acid-dependent; sialidase pre-treatment reduced binding by 79 +/- 4% [PMID:27892504]. Soluble variants bound human and murine PSGL1 similarly [PMID:27892504].","affinity_potency":[],"species_and_systems":"Human recombinant proteins and PBMCs, plus in vivo mouse experiments [PMID:27892504]. Duolink-PLA showed proximity (<40 nm) in 31 +/- 4% of PBMCs [PMID:27892504].","localisation_and_range":"PSGL-1 is flagged membrane-bound [flag]; Siglec-5 acted here in soluble form as a decoy [PMID:27892504].","caveats":"One paper; no affinity reported. The authors tried co-immunoprecipitation at the cell surface, but the excerpt does not report the result [PMID:27892504]. No database records.","key_references":[{"PMID":"27892504","why":"Siglec-5 binds PSGL1 and soluble Siglec-5 blocks rolling in vitro and in mice"}],"covers":["LR001966"]},"LR004738":{"pair":"SEMA3A -> PLXNA1","headline":"SEMA3A signals via a NRP1/PlexinA1 complex in cells; PlexinA1 alone does not bind Sema3A.","interaction_type":"direct binding","direction_and_effect":"Sema3A interaction with NP-1/Plex 1 complexes induces adherent cells to round up, and dominant-negative Plex 1 in sensory neurons blocks Sema3A-induced growth cone collapse [PMID:10520994]. Sema3 signals are transduced equally effectively by PlexinA1 or PlexinA2 [PMID:11239433]. Interaction class is stimulatory [flag].","molecular_requirements":"Plex 1 alone does not bind Sema3A; the NP-1/Plex 1 complex has higher affinity for Sema3A than NP-1 alone [PMID:10520994]. Sema3A/NP1 releases PlexinA1 sema-domain autoinhibition [PMID:11239433]. Reactome: Sema3A binds Nrp-1 bound to PlexinA [DB:Reactome].","affinity_potency":[{"value":"6-fold higher affinity","assay":"AP-Sema3A binding, NP-1/Plex 1 cells versus NP-1 cells","system":"COS-7 cells","cite":"PMID:10520994"}],"species_and_systems":"Experiments used mouse-labelled proteins in COS-7 cells and DRG neurons (chick E7 DRG in [PMID:11239433]); the human pair is projected from mouse [flag].","localisation_and_range":"SEMA3A is flagged as secreted and not transmembrane [flag], so it acts as a diffusible paracrine cue on membrane receptors.","caveats":"Binding is to the NRP1/PlexinA1 complex, not PlexinA1 alone, so PLXNA1 on its own is not shown as a receptor. Evidence for direct binding in this pair rests on complex assays.","key_references":[{"PMID":"10520994","why":"NP-1/Plex 1 complex is the high-affinity Sema3A receptor"},{"PMID":"11239433","why":"PlexinA1 activation and autoinhibition in Sema3A signalling"}],"covers":["LR001342","LR004738"]},"LR004747":{"pair":"SEMA3D -> NRP1","headline":"Zebrafish in vivo knockdown data (two papers, abstract-level) support SEMA3D acting through Nrp1 for repulsion and actin stabilization.","interaction_type":"functional only","direction_and_effect":"In zebrafish, Sema3D may act as a repellent through receptors containing Npn-1A and as an attractant via Npn-1A plus Npn-2B [PMID:15456815]. Separately, autocrine Sema3d signaling through Neuropilin1 regulates actin organization via RhoA upstream of Rock, stabilizing the endothelial sheet [PMID:27799363].","molecular_requirements":"Npn-1A alone is tied to nucMLF repulsion; Npn-1A plus Npn-2B to attraction [PMID:15456815]. The endothelial Nrp1 effect was independent of PlxnD1 [PMID:27799363].","affinity_potency":[],"species_and_systems":"Zebrafish morpholino and mutant embryos in both papers; the curator's species label says human for PMID 27799363, but the text describes zebrafish [PMID:27799363]. The human and mouse pairs are ortholog-inferred.","localisation_and_range":"SEMA3D is annotated secreted [flag]; autocrine and mesenchymal paracrine sources are described [PMID:27799363].","caveats":"Both papers read as abstracts (the second has full-text excerpts); genetic knockdown, no binding or affinity data. One review_only row is not shown.","key_references":[{"PMID":"15456815","why":"Zebrafish Sema3D repulsion and attraction via Npn-1A and Npn-2B"},{"PMID":"27799363","why":"Sema3d-Nrp1 autocrine actin control in endothelial migration"}],"covers":["LR001351","LR004747"]},"LR006484":{"pair":"SEMA3D -> NRP2","headline":"Zebrafish genetic evidence that Sema3D attraction involves Npn-1A/Npn-2B heterodimers; no binding data.","interaction_type":"functional only","direction_and_effect":"Sema3D appears attractive to telencephalic neurons forming the anterior commissure, and knockdown of Npn-2B phenocopied this defect [PMID:15456815].","molecular_requirements":"The authors propose that attraction is mediated by Npn-1A-Npn-2B heterodimers [PMID:15456815]; NRP2 acts with NRP1, not alone.","affinity_potency":[],"species_and_systems":"Zebrafish morpholino knockdown; the pair is ortholog-inferred for human and mouse [PMID:15456815].","localisation_and_range":"SEMA3D is annotated secreted and NRP2 transmembrane [flag].","caveats":"The supporting sentence is from a browser-read Discussion that is marked as an unverifiable quote with spot-check pending. No binding or affinity data; three other rows were abstract_insufficient.","key_references":[{"PMID":"15456815","why":"Zebrafish Sema3D attraction via Npn-1A and Npn-2B"}],"covers":["LR003268","LR006484"]},"LR006493":{"pair":"SEMA4A -> PLXNB3","headline":"Sema4A binds Plexin-B3 in COS-7 transfection assays in one abstract-level paper; mouse pair is the direct one.","interaction_type":"direct binding","direction_and_effect":"Sema4A binds Plexin-B1, -B2 and -B3 in transfected COS-7 cells, and Rnd1 with these plexins induced cell contraction [PMID:20043131].","molecular_requirements":"Rnd1 co-expression was used for signalling readout [PMID:20043131]. Other requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"COS-7 cells and mouse hippocampal neurons [PMID:20043131]; the human pair is ortholog-inferred.","localisation_and_range":"SEMA4A is flagged secreted [flag]. IntAct lists a cross-linking study [DB:IntAct].","caveats":"One confirming paper, abstract only; binding is not specific to Plexin-B3. Three other rows were review_only.","key_references":[{"PMID":"20043131","why":"Sema4A binds Plexin-B3 in COS-7"}],"covers":["LR003277","LR006493"]},"LR004756":{"pair":"SEMA4C -> PLXNB2","headline":"Sema4C binds Plexin-B2 and signals through it in cerebellar development and breast cancer cells; binding plus functional evidence.","interaction_type":"direct binding","direction_and_effect":"Sema4C protein bound Plexin-B2-expressing cerebellar granule cells; Sema4C promoted granule-cell migration in transwell and explant assays, and had no effect on Plxnb2-/- cells, so the effect needs Plexin-B2 (agonist) [PMID:21122816]. In breast cancer cells, Sema4C/PlexinB2/LARG signalling maintains RhoA-GTP and cell growth [PMID:29555978].","molecular_requirements":"Binding to Plexin-B2 was strong, to Plexin-B1 weaker, none to Plexin-B3 in full-text excerpts [PMID:21122816]. Downstream, LARG, ErbB2 and RhoA-dependent kinases are named effectors [PMID:29555978].","affinity_potency":[],"species_and_systems":"Cerebellar work used mouse knockouts and mouse cells (dossier labels species human) [PMID:21122816]; breast cancer work used human mammary carcinoma cells and mice [PMID:29555978]. Human pair is ortholog-inferred.","localisation_and_range":"Sema4C is flagged transmembrane, not secreted [flag]; contact-dependent signalling is likely but substrate-coated assays used a recombinant protein [PMID:21122816].","caveats":"Binding paper read from abstract and excerpts; breast cancer paper abstract only. Sema4C-/- phenotype partial penetrance and other Plexin-B2 ligands likely exist [PMID:21122816]. IntAct has one solid-phase assay record [DB:IntAct].","key_references":[{"PMID":"21122816","why":"Binding and knockout genetics for Sema4C-Plexin-B2"},{"PMID":"29555978","why":"Sema4C/PlexinB2 signalling in breast cancer"}],"covers":["LR001360","LR004756"]},"LR004765":{"pair":"SEMA7A -> ITGA1","headline":"Alpha1beta1 integrin is reported to mediate Sema7A-driven cytokine production; evidence is abstract-only and chain-level.","interaction_type":"functional only","direction_and_effect":"Sema7A on activated T cells stimulates cytokine production in monocytes and macrophages through alpha1beta1 integrin (VLA-1) [PMID:17377534]. Reactome lists a SEMA7A:Integrin alpha1beta1 complex [DB:Reactome].","molecular_requirements":"The alpha1 chain acts with beta1; chain-alone sufficiency is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Curator notes describe human monocytes/macrophages and Sema7a-/- mice [PMID:17377534]. Human pair is ortholog-inferred.","localisation_and_range":"Ligand carries secreted and transmembrane flags; the abstract describes it as GPI-anchored [flag][PMID:17377534].","caveats":"Abstract only; the pair is the alpha1 chain of a heterodimer, no binding or affinity data in our evidence.","key_references":[{"PMID":"17377534","why":"Sema7A signals through alpha1beta1 integrin in monocytes/macrophages"}],"covers":["LR001369","LR004765"]},"LR003289":{"pair":"SERPINE1 -> LRP1B","headline":"Evidence concerns uPA:PAI-1 complexes with uPAR on LRP1B, not free PAI-1; indirect and weak for a direct pair.","interaction_type":"functional only","direction_and_effect":"An LRP1B minireceptor formed immunoprecipitable cell-surface complexes with uPAR in the presence of uPA:PAI-1 complexes, but internalised them far more slowly than the LRP minireceptor, impairing uPAR regeneration and cell migration [PMID:12194987]. This indicates a negative regulatory, not activating, effect.","molecular_requirements":"Requires uPA:PAI-1 complex and uPAR for complex formation [PMID:12194987].","affinity_potency":[],"species_and_systems":"Cell-based work with an LRP1B minireceptor (mLRP1B4); species labelled human [PMID:12194987]. Mouse pair is ortholog-projected.","localisation_and_range":"Cell-surface complex; LRP1B is flagged as a receptor [flag].","caveats":"Free PAI-1 binding is not shown. One paper, abstract only.","key_references":[{"PMID":"12194987","why":"LRP1B with uPAR and uPA:PAI-1 impairs uPAR regeneration"}],"covers":["LR003289","LR006505"]},"LR004774":{"pair":"SERPING1 -> SELE","headline":"C1 inhibitor binds E-selectin through its glycans and inhibits endothelial-leukocyte adhesion; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Plasma C1INH bound P- and E-selectins by FACS and immunoprecipitation and inhibited endothelial-leukocyte adhesion dose-dependently, with significant (>50%) inhibition at 250 microg/mL or higher [PMID:14568956]. Curators label it antagonist.","molecular_requirements":"Binding is via sialyl Lewis(x)-related moieties on C1INH N-glycans, which sit on its amino-terminal domain rather than the serpin domain [PMID:14568956].","affinity_potency":[],"species_and_systems":"Plasma C1INH with cell-based and tissue-culture adhesion assays; species labelled human [PMID:14568956]. Mouse pair is ortholog-projected. BioGRID lists an affinity-capture-western record [DB:BioGRID].","localisation_and_range":"E-selectin is flagged as receptor and transmembrane [flag]; contact-dependent at the endothelium.","caveats":"Glycan-mediated, not classic protein-protein binding; no affinity reported; abstract only.","key_references":[{"PMID":"14568956","why":"C1INH binds selectins and blocks adhesion"}],"covers":["LR001379","LR004774"]},"LR008419":{"pair":"SFRP1 -> WNT1","headline":"No curator-confirmed paper; support is one BioGRID record.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; the only record is BioGRID affinity-capture-western [DB:BioGRID, PMID:10347172].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"SFRP1 is flagged secreted [flag]; the row is a ligand-ligand class interaction.","caveats":"No confirmed papers: judged papers were a different entity, review only or abstract_insufficient. This pair rests on a database record alone, and SFRP1-WNT is a ligand-ligand (decoy) relationship rather than a receptor interaction.","key_references":[],"covers":["LR008419"]},"LR003298":{"pair":"SFTPD -> LRP1","headline":"SP-D collagenous tails bind a calreticulin/CD91 complex per one abstract-level paper; LRP1 alone not shown.","interaction_type":"direct binding","direction_and_effect":"Collagenous tails of SP-A/SP-D stimulate proinflammatory mediator production and phagocytosis via the calreticulin/CD91 complex; agonist-like [PMID:14531999].","molecular_requirements":"The curator notes calreticulin may be an obligate co-receptor partner, so LRP1 alone may not be the direct binding partner [PMID:14531999].","affinity_potency":[],"species_and_systems":"Human ligand and receptor listed; both species pairs ortholog-inferred [PMID:14531999].","localisation_and_range":"SP-D is flagged secreted [flag].","caveats":"One paper, abstract only, covering SP-A and SP-D together; binding is to a complex, not LRP1 alone.","key_references":[{"PMID":"14531999","why":"Collectin tails bind calreticulin/CD91"}],"covers":["LR003298","LR006513"]},"LR001975":{"pair":"SFTPD -> SIRPA","headline":"SP-D binds the D3 domain of SIRPalpha and signals anti-inflammatory; two abstract-level papers plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Via the globular head SP-D binding to SIRPalpha blocks proinflammatory mediator production (antagonist-like) [PMID:14531999]. A second paper reports Ca2+- and carbohydrate-dependent binding to the membrane-proximal Ig domain D3, distinct from the CD47 site [PMID:22511785].","molecular_requirements":"SIRPalpha D3 domain with specific N-glycosylated residues is needed [PMID:22511785]. Reactome has SIRPA:SFTPD complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in both papers; mouse pair is ortholog-inferred.","localisation_and_range":"SIRPA is flagged transmembrane and SP-D secreted [flag].","caveats":"Both papers are abstract-only; no affinity reported.","key_references":[{"PMID":"22511785","why":"SP-D binds SIRPalpha D3 domain, Ca2+/carbohydrate-dependent"},{"PMID":"14531999","why":"Globular-head binding and anti-inflammatory signalling"}],"covers":["LR001975","LR005305"]},"LR008923":{"pair":"SHANK1 -> SSTR2","headline":"UniProt notes SHANK1 PDZ binding to the SSTR2 C-terminus; an intracellular interaction, not a ligand-receptor one.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence; UniProt states SHANK1 interacts with the C-terminus of SSTR2 via the PDZ domain [DB:UniProt].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; assay not reported in our evidence.","localisation_and_range":"Not a secreted ligand per our evidence; intracellular C-terminal binding [DB:UniProt].","caveats":"Database only; no judged paper supports it (two rows concerned different entities, one unresolvable).","key_references":[],"covers":["LR008923"]},"LR009148":{"pair":"SHBG -> CLDN4","headline":"SHBG-CLDN4 rests on a single BioGRID two-hybrid record; one paper was review-only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence; the only record is a two-hybrid [DB:BioGRID].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Two-hybrid, species not reported [DB:BioGRID].","localisation_and_range":"SHBG is flagged secreted [flag].","caveats":"Database-only and weak method; the judged paper was review-only.","key_references":[],"covers":["LR009148"]},"LR004783":{"pair":"SHH -> HHIP","headline":"SHH binds HHIP directly, with a co-crystal structure; HHIP is an inhibitory receptor.","interaction_type":"direct binding","direction_and_effect":"Hip binds all three mammalian Hedgehog proteins with an affinity comparable to that of Ptc-1 and attenuates Hedgehog signalling [PMID:10050855]. Crystal structures of human HHIP ectodomain with Shh were solved [PMID:19561611]. It is an inhibitor of Hh signaling [PMID:19561611].","molecular_requirements":"HHIP loops BL1 and BL2 of the beta-propeller contact ShhN; a Shh zinc ion contributes to the interface and Ca2+ likely prevents electrostatic repulsion [PMID:19561611]. A single-chain receptor is sufficient; structure PDB 3HO5 [DB:PDB 3HO5].","affinity_potency":[],"species_and_systems":"Human HHIP ectodomain and the ShhN domain, recombinant [PMID:19561611]; the 1999 paper used mammalian proteins, species unspecified [PMID:10050855]. Mouse pair is the curated one; human is ortholog-inferred.","localisation_and_range":"HHIP is a membrane glycoprotein tethered to the cell surface [PMID:10050855] [PMID:19561611]; SHH is flagged secreted [flag].","caveats":"A decoy-like negative feedback receptor, not a signalling receptor. Affinity described only as comparable to Ptc-1, no value in the dossier. One pending paper not shown.","key_references":[{"PMID":"19561611","why":"Crystal structure of HHIP-Shh complex"},{"PMID":"10050855","why":"Hip binds Hedgehog proteins; negative feedback"}],"covers":["LR001388","LR004783"]},"LR001984":{"pair":"SLIT1 -> ROBO2","headline":"Functional evidence only for SLIT1-ROBO2 from two abstract-only papers; ortholog-inferred in both species.","interaction_type":"functional only","direction_and_effect":"Endogenous Robos mediate Slit's growth-promoting effects on axons and dendrites in Robo1;Robo2 deficient neurons [PMID:21600986]. In a mouse stroke model, neuroblasts use Slit1-Robo2 signalling to disrupt the actin cytoskeleton in reactive astrocytes; Slit1 overexpression improved neuroblast positioning and functional recovery [PMID:30547091].","molecular_requirements":"Robo1 and Robo2 are deleted together in PMID:21600986, so Robo2 alone is not isolated there.","affinity_potency":[],"species_and_systems":"Mouse cortical neurons [PMID:21600986]; mouse ischemic-stroke model [PMID:30547091].","localisation_and_range":"SLIT1 flagged secreted and ROBO2 secreted/transmembrane [flag]; Reactome has a SLIT1:ROBO2 plasma membrane complex [DB:Reactome].","caveats":"No direct binding assay in our evidence; both papers abstract-only. The curator labelled PMID:30547091 antagonist, which is not explained in the abstract. No affinity.","key_references":[{"PMID":"30547091","why":"Slit1-Robo2 signalling in neuroblast migration in vivo"},{"PMID":"21600986","why":"Robo-dependent Slit growth effects in neurons"}],"covers":["LR001984","LR005313"]},"LR004792":{"pair":"SLIT2 -> ROBO4","headline":"SLIT2 is a putative ROBO4 (Magic roundabout) ligand; one functional abstract and one BioGRID record.","interaction_type":"functional only","direction_and_effect":"Activation of MRB (ROBO4) via Slit2 inhibited VEGF- and FGF-induced endothelial migration, partly via Ras-Raf-Mek-Erk [PMID:15894287]. Annotated antagonist-type effect on migration.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Endothelial cells, human [PMID:15894287].","localisation_and_range":"Not reported in our evidence; SLIT2 flagged secreted [flag].","caveats":"Slit2 is called only a 'putative ligand', and MRB over-expression activates it ligand-independently, so physiological ligand role is not established [PMID:15894287]. Abstract only. BioGRID lists an affinity capture-Western record from a different paper [DB:BioGRID]. One review-only row not shown.","key_references":[{"PMID":"15894287","why":"Slit2 activation of MRB inhibits endothelial migration"}],"covers":["LR001397","LR004792"]},"LR006529":{"pair":"SLIT3 -> ROBO3","headline":"SLIT3 directly associates with ROBO3 in ELISA and, in chicken granulosa cells, interacts physically with all four ROBOs.","interaction_type":"direct binding","direction_and_effect":"SLIT3 directly associated with ROBO1 and ROBO3, and siRNA knockdown of both blocked SLIT3 suppression of preosteoclast migration and osteoclastogenesis [PMID:29504949]. SLIT3 was reported to interact physically with the four ROBO receptors in chicken granulosa cells [PMID:30288875].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding ELISA and siRNA in osteoclast-lineage cells [PMID:29504949]; chicken granulosa cells [PMID:30288875]. Human pair is ortholog-inferred.","localisation_and_range":"SLIT3 flagged secreted, ROBO3 transmembrane [flag]; SLIT3 acts in an autocrine/paracrine fashion [PMID:30288875].","caveats":"ROBO1 and ROBO3 are reported together. The chicken paper is abstract only and the method for physical interaction is not described in it; ROBO1/2 expression was more regulated by SLIT3 than ROBO3/4 [PMID:30288875]. Four abstracts insufficient.","key_references":[{"PMID":"29504949","why":"ELISA binding and knockdown for ROBO1/ROBO3"},{"PMID":"30288875","why":"Physical interaction with four ROBOs, chicken"}],"covers":["LR003315","LR006529"]},"LR001993":{"pair":"SLITRK3 -> PTPRS","headline":"SLITRK3-PTPsigma rests on one family-level cell aggregation assay.","interaction_type":"functional only","direction_and_effect":"Slitrk3-expressing cells aggregated with PTPsigma-expressing cells [PMID:23345436].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse L cells [PMID:23345436]. Both pairs ortholog-inferred.","localisation_and_range":"Cell-contact adhesion; SLITRK3 flagged transmembrane [flag].","caveats":"Single paper, browser-read with spot-check pending; direct binding not shown, no affinity.","key_references":[{"PMID":"23345436","why":"Slitrk3 and PTPsigma aggregation"}],"covers":["LR001993","LR005322"]},"LR001399":{"pair":"SOST -> LRP5","headline":"Sclerostin binds LRP5 and LRP6 and antagonises canonical Wnt signalling; two papers plus database records.","interaction_type":"direct binding","direction_and_effect":"Sclerostin antagonises canonical Wnt signalling in A293T and MC3T3 cells, reversed by LRP5 overexpression [PMID:15778503]. SOST binds the LRP5/6 ectodomain and disrupts Wnt-induced Frizzled-LRP complex formation in Xenopus embryos and mammalian cells [PMID:15908424].","molecular_requirements":"Binding maps to the first two YWTD-EGF repeat domains of LRP5; canonical Wnt did not appear to compete with sclerostin for LRP5 binding [PMID:15778503]. Sclerostin binds LRP6 as well as LRP5 [PMID:15778503].","affinity_potency":[],"species_and_systems":"Human A293T cells, mouse MC3T3 osteoblastic cells and Xenopus embryos [PMID:15778503][PMID:15908424]. Both human and mouse pairs are ortholog-inferred. BioGRID and IntAct also list records [DB:BioGRID][DB:IntAct].","localisation_and_range":"SOST is flagged secreted and LRP5 as a transmembrane receptor [flag]; sclerostin acts on osteoblast cells [PMID:15778503].","caveats":"Both papers were read as abstracts only. No affinity reported. Binding is to LRP5 and LRP6 together, so paralog specificity is not resolved. Pairs are ortholog-inferred.","key_references":[{"PMID":"15778503","why":"Sclerostin binds LRP5/6 and maps the binding domain"},{"PMID":"15908424","why":"SOST binds LRP5/6 ectodomain and disrupts Frizzled-LRP complex"}],"covers":["LR001399","LR004794"]},"LR006538":{"pair":"SPP1 -> ITGA8","headline":"Spp1 is proposed to act on fibroblast-SMC communication through Itga8/Itgb1 in Marfan aneurysm; computational/expression-led, abstract-only.","interaction_type":"functional only","direction_and_effect":"Spp1 might regulate fibroblast and SMC communication primarily through Itga8/Itgb1; Spp1 reduced Acta2 and Tagln in SMCs and increased collagen expression in fibroblasts [PMID:35414038].","molecular_requirements":"Itga8 with Itgb1 is the proposed receptor [PMID:35414038]. Reactome lists an Integrin alpha8beta1:SPP1 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Fbn1C1041G/+ Marfan mice and single-cell data; plasma SPP1 in patients [PMID:35414038].","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; ITGA8 is a receptor [flag].","caveats":"Language is 'might regulate'; direct binding is not shown in this paper. The dossier assay detail notes effect direction as antagonist, while the abstract describes suppression of SMC contractile genes; no antagonism of the receptor is shown. Abstract only.","key_references":[{"PMID":"35414038","why":"Spp1-Itga8/Itgb1 proposed in Marfan aortic aneurysm"}],"covers":["LR003331","LR006538"]},"LR006547":{"pair":"SVEP1 -> TIE1","headline":"SVEP1 (Polydom) binds TIE1 directly, shown by two 2023 studies with pull-down and solid-phase binding.","interaction_type":"direct binding","direction_and_effect":"Polydom directly binds Tie1 and promotes lymphatic endothelial cell migration in a Tie1-dependent manner via PI3K/Akt; Akt phosphorylation rose but no significant Tie1 phosphorylation was induced [PMID:37338522]. In zebrafish svep1 and tie1 mutants share lymphatic defects and show genetic interaction [PMID:37097004].","molecular_requirements":"Polydom binds Tie1 via CCP20 [PMID:37338522]. Tie2 showed no significant binding to Polydom [PMID:37338522]; in the other study SVEP1 association with TIE2 was seen in co-IP but not in pull-down [PMID:37097004]. The C-terminus of human SVEP1 (aa 2261-3571) was sufficient for TIE1 binding [PMID:37097004].","affinity_potency":[{"value":"43 \u00b1 4 nM","assay":"apparent dissociation constant, solid-phase binding of Tie1 to coated Polydom","system":"recombinant proteins","cite":"PMID:37338522"}],"species_and_systems":"Zebrafish Svep1/Tie1 and human SVEP1/TIE1 in transfected HEK293T cells [PMID:37097004]; Polydom/Tie1 with mouse Polydom-deficient LECs [PMID:37338522]. Mouse pair is projected from human.","localisation_and_range":"SVEP1 flagged secreted [flag]; described as an ECM protein [PMID:37338522].","caveats":"Both papers abstract-level with excerpts. Tie1 is an orphan receptor and signalling output is Akt, not Tie1 phosphorylation. TIE2 binding is inconsistent between assays.","key_references":[{"PMID":"37338522","why":"Polydom binds Tie1 via CCP20, Kd 43 nM, drives LEC migration"},{"PMID":"37097004","why":"svep1-tie1 genetic and binding evidence in zebrafish and human"}],"covers":["LR003340","LR006547"]},"LR006556":{"pair":"TAFA5 -> FPR2","headline":"FAM19A5/TAFA5 acts through FPR2 in mouse macrophages and FPR2-expressing cells; functional evidence from one paper.","interaction_type":"functional only","direction_and_effect":"FAM19A5 elicited chemotaxis of FPR2-expressing RBL-2H3 cells but not vector or FPR1 cells [PMID:29138422]. In mouse BMDMs, FAM19A5 inhibited RANKL-induced osteoclast formation, reversed by the FPR2 antagonist WRW4 or FPR2 deficiency, but not by the FPR1 antagonist cyclosporin H [PMID:29138422]. Curators label it an agonist [PMID:29138422].","molecular_requirements":"FPR2 alone suffices in RBL-2H3 cells; the effect is pertussis-toxin sensitive, consistent with G-protein signalling [PMID:29138422].","affinity_potency":[{"value":"2 \u00b5M","assay":"FAM19A5 concentration used in chemotaxis and osteoclast assays (not an EC50)","system":"mouse BMDMs, RBL-2H3 cells","cite":"PMID:29138422"}],"species_and_systems":"Mouse BMDMs, FPR2 knockout mice, RBL-2H3 cells expressing FPR1/FPR2 [PMID:29138422]. Human pair is projected from mouse evidence.","localisation_and_range":"FAM19A5 described as a brain-specific chemokine and annotated secreted [flag].","caveats":"Direct binding was not shown in the evidence we hold; the paper reads as a functional/antagonist-reversal study and was read as abstract plus excerpts [PMID:29138422].","key_references":[{"PMID":"29138422","why":"FPR2 antagonism and deficiency reverse FAM19A5 effects on macrophages"}],"covers":["LR003353","LR006556"]},"LR004819":{"pair":"TCN2 -> LRP2","headline":"Megalin (LRP2) binds the TC-B12 complex with high affinity; evidence is rabbit/rat, human and mouse pairs are inferred.","interaction_type":"direct binding","direction_and_effect":"Ligand blotting showed 125I-TC-B12 binds exclusively to megalin in rabbit kidney cortex, and SPR showed a high-affinity interaction with purified rabbit megalin [PMID:8710919]. 125I-TC-B12 was endocytosed in a RAP-inhibitable way in megalin-expressing cells and in perfused rat proximal tubules [PMID:8710919]. This makes megalin an uptake receptor for vitamin B12 [PMID:8710919].","molecular_requirements":"Binding is Ca2+ dependent and inhibited by RAP; the complex is TC bound to B12 [PMID:8710919]. The related receptor LRP (\u03b12MR) showed no measurable affinity [PMID:8710919].","affinity_potency":[],"species_and_systems":"Rabbit TC-B12 and purified rabbit megalin (SPR), rat yolk sac carcinoma cells and rat kidney [PMID:8710919]. Both listed pairs (human, mouse) are ortholog-inferred. Reactome also lists the complex [DB:Reactome].","localisation_and_range":"Megalin is a 600-kDa endocytic receptor of renal proximal tubule epithelium and other absorptive epithelia [PMID:8710919]; TCN2 annotated secreted [flag].","caveats":"Abstract only; no KD value is given in our excerpt. Human evidence is not directly held.","key_references":[{"PMID":"8710919","why":"SPR, ligand blotting and uptake show megalin binds TC-B12"}],"covers":["LR001424","LR004819"]},"LR006565":{"pair":"TENM4 -> ADGRL2","headline":"Cell-aggregation evidence that teneurin-4 cells adhere to latrophilin-expressing cells; no binding data for ADGRL2 specifically.","interaction_type":"functional only","direction_and_effect":"Cells expressing Lphn1/2/3 formed large aggregates with cells expressing Ten2 or Ten4, indicating intercellular adhesion [PMID:24273166].","molecular_requirements":"Binding is mapped to the lectin-like domain of latrophilins in the abstract; ADGRL2 specific requirements are not reported in our evidence [PMID:24273166].","affinity_potency":[],"species_and_systems":"HEK293T cell aggregation assay; species unspecified. The human pair and the mouse pair are both ortholog-inferred [PMID:24273166].","localisation_and_range":"Both partners have transmembrane flags [flag]; the adhesion assay is consistent with contact-dependent interaction.","caveats":"The aggregation assay does not distinguish ADGRL2 from the other latrophilins in the abstract-level evidence. Pulldown binding in the same paper is described in our evidence for Lphn1 only. The curator quote is a browser read, unverifiable, spot-check pending.","key_references":[{"PMID":"24273166","why":"Latrophilin cells aggregate with Ten4 cells"}],"covers":["LR003362","LR006565"]},"LR004837":{"pair":"TGFB1 -> SDC2","headline":"Syndecan-2 ectodomain binds TGF-beta directly, with regulatory effect on signalling; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"S2 core protein ectodomain directly bound TGF-beta, and S2 promoted TGF-beta binding in renal papillary fibroblasts; S2 regulates TGF-beta-mediated matrix deposition [PMID:14976204].","molecular_requirements":"Ectodomain binds; a cytoplasmic-truncated S2 also promoted binding [PMID:14976204]. TGF-beta isoform not stated in our evidence.","affinity_potency":[],"species_and_systems":"Renal papillary fibroblast transfection; species not reported in our evidence [PMID:14976204].","localisation_and_range":"TGFB1 is flagged secreted [flag]. SDC2 is annotated transmembrane [flag]; it is a transmembrane heparan sulfate proteoglycan [PMID:14976204].","caveats":"Abstract read only; isoform of TGF-beta not specified, and affinity not reported. Syndecan acts as a regulator rather than a signalling receptor. One further paper abstract-insufficient.","key_references":[{"PMID":"14976204","why":"S2 ectodomain directly binds TGF-beta"}],"covers":["LR001442","LR004837"]},"LR007429":{"pair":"TGFB1 -> TGFBR1:TGFBR2","headline":"Classic heteromeric type I/II receptor complex with cross-linking and cloning evidence.","interaction_type":"direct binding","direction_and_effect":"TGF-beta binds the type II receptor, which needs kinase activity and association with type I to signal growth inhibition [PMID:1333888]. GtoPdb lists both as agonist [DB:GtoPdb].","molecular_requirements":"Receptor I requires receptor II to bind TGF-beta, and receptor II requires receptor I to signal [PMID:1333888]. Cross-linking showed ligand contacting types I and II, plus type III [PMID:7693660].","affinity_potency":[],"species_and_systems":"Rat-1 cells with human ligand [PMID:7693660]; porcine endothelial cells transfected with cDNA [PMID:8242743]; receptor mutants in cultured cells [PMID:1333888].","localisation_and_range":"TGFB1 is flagged secreted [flag]. Complex flagged transmembrane [flag]; Reactome places it at the plasma membrane [DB:Reactome R-HSA-170840].","caveats":"All three papers read as abstracts and are from the 1990s in non-human cell lines. Affinity values are not given in the dossier.","key_references":[{"PMID":"1333888","why":"Heteromeric type I/II receptor requirement"},{"PMID":"8242743","why":"Type I receptor cloned; complex with type II"},{"PMID":"7693660","why":"Cross-linking of TGF-beta to type I and II receptors"}],"covers":["LR007429"]},"LR006835":{"pair":"TGFB2 -> TGFBR1","headline":"TGF-beta2 to TGFBR1: no direct evidence; the one confirmed paper concerns a type II receptor isoform and TGFBR1 is not directly tested.","interaction_type":"functional only","direction_and_effect":"The confirmed paper shows TbetaRII-B, a spliced type II receptor variant, binds TGF-beta2 and signals via Smad in cells lacking TbetaRIII [PMID:11157754]. GtoPdb lists TGFB2-TGFBR1 as agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence for TGFBR1 itself.","affinity_potency":[],"species_and_systems":"Human, Smad reporter assays in L6 cells [PMID:11157754].","localisation_and_range":"Ligand secreted [flag].","caveats":"Curators call this support weak; the evidence sentence is generic pathway background. Abstract-only.","key_references":[{"PMID":"11157754","why":"TGF-beta2 signalling through TbetaRII-B, indirect for TGFBR1"}],"covers":["LR006835"]},"LR006574":{"pair":"TGFB3 -> ITGAV","headline":"Integrin alphaV (as alphaVbeta6) binds latent TGF-beta3 by structure and binding assays; chain-only row.","interaction_type":"direct binding","direction_and_effect":"alphaVbeta6 binds the RGDLXXL/I motif in the TGF-beta1 and TGF-beta3 prodomains with high affinity (crystal structures, mutations, peptide affinity) [PMID:25383667]. alphaVbeta6 binds and activates latent TGFbeta3 [PMID:11821050].","molecular_requirements":"Binding requires the heterodimer; the LXXL/I helix sits in a hydrophobic pocket of the beta6 subunit, so alphaV alone is not shown to suffice [PMID:25383667].","affinity_potency":[],"species_and_systems":"Human proteins in the 2002 work [PMID:11821050]; the structure species is not stated in our evidence. Mouse pair is ortholog-projected.","localisation_and_range":"Ligand secreted, annotated transmembrane [flag]; contact with matrix-bound latent complex.","caveats":"The bound species is the latency-associated peptide (LAP) complex, not mature TGF-beta. Integrin acts to activate TGF-beta release rather than transduce a TGF-beta signal [PMID:11821050]. Abstract-only reading.","key_references":[{"PMID":"25383667","why":"Crystal structure of alphaVbeta6 with the RGDLXXL/I prodomain motif"},{"PMID":"11821050","why":"alphaVbeta6 binds and activates latent TGFbeta3"}],"covers":["LR003373","LR006574"]},"LR004846":{"pair":"TGFB3 -> TGFBR1","headline":"TGF-beta3 to TGFBR1 rests on database records, including a ligand-receptor structure; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists TGFB3-TGFBR1 as agonist [DB:GtoPdb]; a structure of the TGF-beta signalling complex exists [DB:PDB 2PJY]. IntAct lists molecular sieving [DB:IntAct].","molecular_requirements":"UniProt says ligands assemble TGFBR1 and TGFBR2 heterohexamers; not reported for TGFBR1 alone in our evidence.","affinity_potency":[],"species_and_systems":"No papers verified; four judged abstract-insufficient.","localisation_and_range":"Ligand secreted [flag].","caveats":"No curator-verified paper; annotated stimulatory [flag].","key_references":[],"covers":["LR001451","LR004846"]},"LR003379":{"pair":"TGM2 -> LRP5","headline":"One abstract reports extracellular TG2 interacting with LRP5 and activating beta-catenin signalling in VSMCs.","interaction_type":"functional only","direction_and_effect":"Extracellular TG2 interacts with LRP5 and activates beta-catenin signalling in vascular smooth muscle cells [PMID:18405667].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Primary vascular smooth muscle cells; species not stated in the abstract [PMID:18405667]. The mouse pair is the non-inferred one.","localisation_and_range":"TGM2 is flagged secreted [flag]; extracellular TG2 acts on the cell [PMID:18405667].","caveats":"One abstract only, no direct binding measurement described.","key_references":[{"PMID":"18405667","why":"Extracellular TG2 interacts with LRP5 in VSMCs"}],"covers":["LR003379","LR006580"]},"LR006583":{"pair":"THBS1 -> ITGAV","headline":"Supported by a platelet affinity-chromatography study (alphaVbeta3) and a prostate cancer paper; moderate evidence.","interaction_type":"direct binding","direction_and_effect":"A second platelet integrin, with an alpha chain comigrating with alphaV, bound thrombospondin-Sepharose and was eluted with GRGDSP peptide; alphaVbeta3 appears to act as a THBS1 receptor on endothelial and smooth muscle cells [PMID:2478219]. In human prostate cancer cells, THBS1 mediated migration by interacting with ITGAV (agonist-like), with colocalisation of THBS1 and ITGAV on TGFbeta stimulation [PMID:39304722].","molecular_requirements":"The receptor is alphaVbeta3: it shares the beta3 chain with GPIIb-IIIa [PMID:2478219]. RGD-dependent elution suggests an RGD-site interaction [PMID:2478219]. BioGRID and Reactome records concern ITGB3 and alphaIIbbeta3 rather than alphaV [DB:BioGRID][DB:Reactome].","affinity_potency":[],"species_and_systems":"Human platelets (affinity chromatography) [PMID:2478219]; human prostate cancer cell lines and xenografts [PMID:39304722].","localisation_and_range":"THBS1 is flagged secreted [flag], so it likely acts as a soluble or matrix-associated ligand; range is not reported in our evidence beyond that.","caveats":"The 1989 paper was read as abstract only and identifies alphaV by comigration and antibody, not sequence. The cancer paper's evidence is colocalisation and migration. Database examples shown concern ITGB3, not ITGAV. No affinity reported.","key_references":[{"PMID":"2478219","why":"THBS1-Sepharose retains platelet alphaVbeta3"},{"PMID":"39304722","why":"THBS1 interacts with ITGAV in TGFbeta-driven prostate cancer migration (full text)"}],"covers":["LR003382","LR006583"]},"LR004864":{"pair":"THBS1 -> ITGB3","headline":"Supported by one 1989 abstract showing platelet GPIIb-IIIa and an alphaVbeta3-like integrin bind THBS1 on an affinity column; GPIIb-IIIa binds weakly.","interaction_type":"direct binding","direction_and_effect":"Platelet integrin complexes bound to thrombospondin-Sepharose and were specifically eluted with the peptide GRGDSP [PMID:2478219]. Agonist/antagonist action not reported in our evidence.","molecular_requirements":"The beta3 subunit is shared by GPIIb-IIIa and a second integrin with an alphaV-like alpha subunit; GPIIb-IIIa appears to bind relatively weakly [PMID:2478219]. Reactome lists integrin alphaIIbbeta3:THBS1 [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human platelet membrane proteins, solubilised and run on a thrombospondin-Sepharose column [PMID:2478219].","localisation_and_range":"THBS1 is flagged secreted [flag]; binding was tested with purified protein, so range is not addressed.","caveats":"Single paper, abstract only; five other judged rows were abstract_insufficient. No affinity measured. Beta3 is shared by two integrins, so the pair does not say which alpha chain is needed. BioGRID lists reconstituted-complex records [DB:BioGRID].","key_references":[{"PMID":"2478219","why":"Platelet integrins bind thrombospondin-Sepharose"}],"covers":["LR001469","LR004864"]},"LR003388":{"pair":"THBS4 -> ITGB1","headline":"THBS4 interacts with ITGB1 to drive HCC proliferation through FAK/PI3K/AKT; co-IP evidence.","interaction_type":"direct binding","direction_and_effect":"THBS4 as an oncogene interacts with integrinbeta1 to regulate HCC development via FAK/PI3K/AKT [PMID:32567740]. Agonist-like.","molecular_requirements":"Also binds ITGB5 and ITGA5 in the same study [PMID:32567740].","affinity_potency":[],"species_and_systems":"Human HCC cell lines and tissues, in vitro and in vivo [PMID:32567740].","localisation_and_range":"THBS4 flagged secreted [flag].","caveats":"Abstract-level read; IntAct co-IP record [DB:IntAct]. Mouse pair ortholog-inferred.","key_references":[{"PMID":"32567740","why":"THBS4 interacts with ITGB1 in HCC"}],"covers":["LR003388","LR006589"]},"LR006592":{"pair":"THY1 -> ADGRE5","headline":"THY1 binds CD97 (ADGRE5) in human cell and protein binding assays, via the CD97 stalk; single paper read as abstract.","interaction_type":"direct binding","direction_and_effect":"CD97-bearing cells adhere to Thy-1 and soluble CD97 binds immobilised Thy-1; both CD97 and Thy-1 blocking mAbs partly block binding [PMID:22210915].","molecular_requirements":"CD97 engages Thy-1 through its stalk: stalk-directed mAb blocked more than EGF-like-domain mAb, and CD97 lacking the stalk and soluble EMR2 failed to bind. Binding was calcium independent [PMID:22210915].","affinity_potency":[],"species_and_systems":"Human: PMNC, CHO transfectants, activated dermal endothelial cells and immobilised protein [PMID:22210915].","localisation_and_range":"Thy-1 on activated endothelial cells binds CD97 on myeloid cells, so contact-dependent (juxtacrine). Note ADGRE5 carries a secreted flag [flag] but the paper describes cell adhesion [PMID:22210915].","caveats":"Abstract only; blocking was partial; no affinity reported [PMID:22210915].","key_references":[{"PMID":"22210915","why":"Thy-1 as CD97 binding partner, stalk-dependent"}],"covers":["LR003391","LR006592"]},"LR003397":{"pair":"THY1 -> ITGB2","headline":"Thy-1 binds beta2 integrins (Mac-1, alphaX-beta2) in human cell and protein assays; evidence is complex-level.","interaction_type":"direct binding","direction_and_effect":"Thy-1/Mac-1 mediates leukocyte adhesion and transendothelial migration [PMID:15004192].","molecular_requirements":"ITGB2 is the shared beta chain; the Thy-1 binding shown is for Mac-1 and the alphaX I-domain, not the beta2 chain alone [PMID:15004192][PMID:15850796].","affinity_potency":[],"species_and_systems":"Human: monocytes, PMNs, endothelial cells, purified protein [PMID:15004192]; recombinant I-domain [PMID:15850796].","localisation_and_range":"Membrane-bound; contact-dependent.","caveats":"Both abstract only; chain-level row inherits complex evidence; mouse pair is ortholog-inferred.","key_references":[{"PMID":"15004192","why":"Thy-1/Mac-1 binding"},{"PMID":"15850796","why":"alphaX I-domain binds Thy-1"}],"covers":["LR003397","LR006598"]},"LR008617":{"pair":"TIGIT -> NECTIN2","headline":"TIGIT binds PVRL2 (NECTIN2) and inhibits NK cytotoxicity; structural and interaction-database support.","interaction_type":"direct binding","direction_and_effect":"Antagonist/inhibitory: TIGIT inhibits NK cytotoxicity directly through its ITIM and protects normal cells from NK killing [PMID:19815499].","molecular_requirements":"TIGIT binds PVR and PVRL2 but not PVRL3 [PMID:19815499]. A PDB structure of the pair exists [DB:PDB 5V52]; IntAct lists SPR, crystallography and solid-phase assays [DB:IntAct].","affinity_potency":[],"species_and_systems":"Human NK cells and tumour cell killing assays [PMID:19815499].","localisation_and_range":"Both membrane proteins [flag]; juxtacrine NK-target contact.","caveats":"Primary paper is abstract only; no affinity reported; one row judged review_only.","key_references":[{"PMID":"19815499","why":"TIGIT binds PVRL2 and inhibits NK cytotoxicity"}],"covers":["LR008617"]},"LR004873":{"pair":"TIMP2 -> ITGA3","headline":"TIMP-2 acts on endothelial cells via alpha3beta1 integrin; one abstract-read paper, partly functional.","interaction_type":"functional only","direction_and_effect":"The anti-angiogenic effects of TIMP-2, independent of MMP inhibition, required alpha 3 beta 1 integrin-mediated binding of TIMP-2 to endothelial cells, decreasing PTP activity associated with beta1 and dissociating SHP-1 [PMID:12887919]. This is inhibitory for endothelial proliferation.","molecular_requirements":"Acts via the alpha3beta1 heterodimer; ITGA3 alone is not tested in our evidence [PMID:12887919].","affinity_potency":[],"species_and_systems":"Endothelial cells in vitro and angiogenesis in vivo; species not specified in the curated row [PMID:12887919]. Mouse pair is ortholog-inferred.","localisation_and_range":"TIMP2 is flagged secreted and ITGA3 as a receptor [flag].","caveats":"Abstract-only; the cited sentence states a requirement for alpha3beta1, not direct binding to ITGA3. Two other papers were abstract_insufficient and one is pending.","key_references":[{"PMID":"12887919","why":"TIMP-2 requires alpha3beta1 for anti-angiogenic effect"}],"covers":["LR001478","LR004873"]},"LR008842":{"pair":"TNC -> ITGA5","headline":"Only database records for other integrins; no verified paper for alpha5.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper; one row was different_entity and two abstract_insufficient [outcome_counts]. Records describe alpha8beta1 and alpha9beta1 with tenascin-C [DB:Reactome][DB:UniProt].","molecular_requirements":"Receptor entity is labelled integrin alpha5beta1 [flag]; beta partner not evidenced.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Cited records do not concern alpha5; pair is unsupported in our evidence.","key_references":[],"covers":["LR008842"]},"LR004882":{"pair":"TNC -> ITGA9","headline":"Integrin alpha9beta1 is a TNC receptor driving migration and lung metastasis of human osteosarcoma cells in mouse xenografts.","interaction_type":"functional only","direction_and_effect":"ITGA9 knockdown abolished TNC-specific transwell migration, and knockdown of TNC or ITGA9 reduced lung metastasis in nude mice [PMID:29259017]. TNC/alpha9beta1 signalling destroys actin stress fibers and inhibits YAP target gene expression [PMID:29259017]. UniProt notes ITGA9:ITGB1 interacts with TNC via its third fibronectin type III domain [DB:UniProt].","molecular_requirements":"Alpha9beta1 heterodimer acts; the study knocked down the ITGA9 chain [PMID:29259017].","affinity_potency":[],"species_and_systems":"Human osteosarcoma KRIB and GBM T98G cell lines, grafted into nude mice [PMID:29259017].","localisation_and_range":"Autocrine and paracrine signalling suggested; TNC deposited as matrix substratum [PMID:29259017].","caveats":"Functional (knockdown) evidence; direct binding not shown in the paper excerpts. Two other papers were abstract_insufficient.","key_references":[{"PMID":"29259017","why":"TNC/integrin alpha9beta1 in osteosarcoma metastasis"}],"covers":["LR001487","LR004882"]},"LR001489":{"pair":"TNC -> ITGB1","headline":"Beta1 integrin pairs (alpha7beta1, alpha9beta1, alpha2beta1) mediate responses to tenascin-C; three papers, mostly abstract-only.","interaction_type":"functional only","direction_and_effect":"Alpha7beta1 associated with tenascin-C VFDNFVLK peptides, and function-blocking anti-alpha7 and anti-beta1 antibodies abolished neurite outgrowth [PMID:14715956]. TNC and integrin alpha9beta1 were essential for lung metastasis in xenografts [PMID:29259017]. Anti-beta1 mAb inhibited endothelial attachment to tenascin up to 80% [PMID:7693733].","molecular_requirements":"Beta1 acts with different alpha chains (alpha7, alpha9, alpha2) [PMID:14715956][PMID:29259017][PMID:7693733].","affinity_potency":[],"species_and_systems":"Human cells and mouse xenograft [PMID:29259017]; cerebellar granule neurons [PMID:14715956]; HUVEC [PMID:7693733].","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"Single-chain entry; alpha partner determines the interaction. Three more rows abstract_insufficient.","key_references":[{"PMID":"14715956","why":"alpha7beta1 and TNC peptide"},{"PMID":"29259017","why":"TNC/alpha9beta1 in metastasis"},{"PMID":"7693733","why":"alpha2beta1 in endothelial attachment"}],"covers":["LR001489","LR004884"]},"LR009652":{"pair":"TNF -> FAS","headline":"Only a BioGRID co-purification record supports this pair; no curator-verified paper confirms direct binding.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"The only record is a BioGRID affinity capture-Western entry [DB:BioGRID][PMID:12753742]. Species not reported in our evidence beyond the human pair.","localisation_and_range":"TNF is flagged secreted and transmembrane, FAS flagged as a transmembrane receptor [flag].","caveats":"No papers were confirmed. Our curation judged six papers as review-only, different-entity or abstract-insufficient, none confirming. An affinity-capture result does not show direct binding, and TNF and FAS are not canonical partners in our evidence. Treat as unsupported.","key_references":[],"covers":["LR009652"]},"LR009274":{"pair":"TNF -> TRAF2","headline":"TRAF2 is an intracellular adaptor in TNF receptor complexes; support is from co-purification databases only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Reactome describes TRAF2 within cIAP1,2:TRAF2:TRAF3:NIK complexes binding the TNFR2 trimer,. UniProt notes TRAF2 within complex I upon TNF stimulation [DB:UniProt][PMID:19150425].","affinity_potency":[],"species_and_systems":"BioGRID affinity capture-Western records [DB:BioGRID][PMID:12887920], IntAct co-immunoprecipitation records [DB:IntAct][PMID:21822306], and Reactome records [DB:Reactome]. Species not reported in our evidence beyond the human pair.","localisation_and_range":"TRAF2 has no secreted or receptor flag [flag].","caveats":"No papers were confirmed; one paper was judged to concern a different entity. The records reflect receptor-complex pull-down, not TNF binding TRAF2 (our inference). This is probably not a true ligand-receptor pair.","key_references":[],"covers":["LR009274"]},"LR007438":{"pair":"TNFSF11 -> TNFRSF11B","headline":"OPG (TNFRSF11B) is a secreted decoy that binds RANKL and blocks osteoclast formation; supported by papers and a complex structure.","interaction_type":"direct binding","direction_and_effect":"The RANKL ligand was expression-cloned using OPG/OCIF and induces osteoclast-like cell formation [PMID:9520411]. The effects of the ligand are blocked in vitro and in vivo by OPG [PMID:9568710], and OPG negatively regulates osteoclastogenesis and binds RANKL [PMID:12221720]. Effect: OPG acts as an antagonist/decoy.","molecular_requirements":"Not reported in our evidence beyond ligand-receptor binding. PDB 3URF contains chains of both proteins [DB:PDB 3URF].","affinity_potency":[],"species_and_systems":"Mouse cells and mice in the cloning and activity papers [PMID:9520411]. The 12221720 abstract uses mouse osteoblast and bone marrow cocultures although the dossier labels it human. BioGRID reconstituted complex [DB:BioGRID]; IntAct [DB:IntAct]; Reactome [DB:Reactome].","localisation_and_range":"OPG is described as a secreted member of the TNF receptor family [PMID:9520411]; RANKL is flagged secreted and transmembrane [flag].","caveats":"All three papers were read as abstracts. OPG is flagged as not a receptor or transmembrane [flag].","key_references":[{"PMID":"9520411","why":"Expression cloning of the OPG ligand"},{"PMID":"9568710","why":"OPG ligand activity blocked by OPG"},{"PMID":"12221720","why":"OPG binds RANKL and limits osteoclast differentiation"}],"covers":["LR007438"]},"LR001498":{"pair":"TNFSF13B -> TNFRSF13B","headline":"BAFF binds TACI with sub-nanomolar affinity; two abstract-only papers plus extensive database records.","interaction_type":"direct binding","direction_and_effect":"TACI binds BAFF (zTNF4) [PMID:10801128]; TACI expressed in HEK293T cells confers BAFF binding and TACI-Fc recognises soluble and membrane BAFF, with NF-kappaB signalling [PMID:10956646]. Soluble TACI-Ig inhibited proteinuria and prolonged survival in NZBWF1 lupus mice [PMID:10801128]. Annotated stimulatory [flag].","molecular_requirements":"Reactome lists a sBAFF,sAPRIL complex with 3xTACI and BCMA [DB:Reactome]; requirements not tested in our papers.","affinity_potency":[{"value":"subnanomolar affinity","assay":"BLyS binding to TACI expressed on cells (abstract wording, no exact value)","system":"HEK293T cells","cite":"PMID:10956646"}],"species_and_systems":"Human proteins [PMID:10956646]; TACI-Ig blockade in mice [PMID:10801128].","localisation_and_range":"BAFF flagged both secreted and transmembrane; TACI transmembrane [flag]. TACI-Fc recognised both cleaved soluble and membrane BAFF [PMID:10956646].","caveats":"Both papers read as abstract only. Also supported by BioGRID, IntAct and GtoPdb records [DB:BioGRID][DB:IntAct][DB:GtoPdb].","key_references":[{"PMID":"10956646","why":"Sub-nanomolar BLyS binding to TACI"},{"PMID":"10801128","why":"TACI and BCMA identified as BAFF receptors"}],"covers":["LR001498","LR004889"]},"LR004891":{"pair":"TNFSF13B -> TNFRSF17","headline":"BAFF binds BCMA, supported by three abstract-only binding papers and database records.","interaction_type":"direct binding","direction_and_effect":"BCMA specifically binds TALL-1 (BAFF); soluble BCMA blocks TALL-1 binding and B-cell costimulation, and BCMA overexpression activates NF-kappaB, potentiated by TALL-1 [PMID:10908663]. TACI and BCMA bind zTNF4 [PMID:10801128]. Annotated stimulatory [flag].","molecular_requirements":"BCMA signalling to NF-kappaB depends on TRAF5, TRAF6, NIK and IKK in dominant-negative experiments [PMID:10908663]. Reactome lists a complex with TACI and BCMA [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human proteins [PMID:10908663]; TACI-Ig in lupus mice (TACI, not BCMA) [PMID:10801128].","localisation_and_range":"BAFF flagged secreted and transmembrane; BCMA transmembrane [flag].","caveats":"Papers are abstract only; BAFF affinity for BCMA is much weaker than APRIL's, per a paper listed under a different pair, so not shown here. One paper reports APRIL competes with TALL-I for BCMA binding [PMID:10973284].","key_references":[{"PMID":"10908663","why":"BCMA binds TALL-1 and activates NF-kappaB"},{"PMID":"10801128","why":"TACI and BCMA identified as BAFF receptors"},{"PMID":"10973284","why":"APRIL and TALL-I compete for BCMA/TACI"}],"covers":["LR001500","LR004891"]},"LR006619":{"pair":"TNR -> PTPRZ1","headline":"Tenascin-R binds the RPTPzeta ectodomain, with crystal structure, Kd values and a PNN functional test; strong support.","interaction_type":"direct binding","direction_and_effect":"TNR associates with the RPTPzeta ectodomain; a structural basis is given, and interface mutation (RPTPzeta-AAA, Y368/Q369/D370) disrupted perineuronal net assembly, so the interaction is needed for net architecture [PMID:37356715]. Signalling effect on RPTPzeta not reported in our evidence.","molecular_requirements":"A loop in the single FN domain of phosphacan inserts into a groove in the C-terminal Fg domain of TNR; the GAG region is not essential for net rescue [PMID:37356715]. Phosphacan is the secreted RPTPzeta splice form.","affinity_potency":[{"value":"KD 112 nM","assay":"binding assay with Ca2+ (5 mM CaCl2)","system":"TNR with RPTPzeta ectodomain, recombinant","cite":"PMID:37356715"},{"value":"KD 712 nM","assay":"binding assay with EDTA (5 mM)","system":"same, divalent cations removed","cite":"PMID:37356715"}],"species_and_systems":"Recombinant proteins and crystals for binding; mouse cortical cultures from Ptprz1 knockout mice for function [PMID:37356715]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"TNR is a matricellular/extracellular matrix protein [PMID:37356715]; PTPRZ1 is flagged secreted and transmembrane [flag], the ectodomain or phosphacan form acts.","caveats":"Curator verified from abstract; full-text excerpts used. Affinity falls six-fold without Ca2+ [PMID:37356715]. BioGRID and PDB records are consistent [DB:BioGRID, DB:PDB 8FN9].","key_references":[{"PMID":"37356715","why":"Structure, KD and perineuronal net function of TNR-RPTPzeta"}],"covers":["LR003418","LR006619"]},"LR004828":{"pair":"Trf -> Tfr2","headline":"Transferrin binds TfR2 with 27 nm affinity by surface plasmon resonance with soluble proteins; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Iron-loaded transferrin binds TfR2; TfR2 showed no detectable binding to HFE by co-immunoprecipitation or surface plasmon resonance [PMID:11027676]. Signalling effect not reported in our evidence.","molecular_requirements":"Soluble forms were used; subunit requirements not reported in our evidence.","affinity_potency":[{"value":"27 nm","assay":"surface plasmon resonance, iron-loaded Tf","system":"soluble proteins","cite":"PMID:11027676"}],"species_and_systems":"Soluble recombinant proteins; species is not stated in the abstract. The listed pair is a mouse, ortholog-inferred interaction.","localisation_and_range":"Trf is flagged secreted; Tfr2 flagged receptor [flag]. The study used soluble forms.","caveats":"Abstract read only. The affinity is described as 25-fold lower than the affinity of TfR for Tf [PMID:11027676].","key_references":[{"PMID":"11027676","why":"TfR2 affinity for iron-loaded transferrin, 27 nm"}],"covers":["LR004828"]},"LR006628":{"pair":"TULP1 -> TYRO3","headline":"Tulp1 binds Tyro3 as one of three TAM receptors; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"Agonist: Tulp1 interacts with Tyro3, Axl and MerTK of the TAM subfamily [PMID:20978472]. Tyro3-specific activation is not separately described in the abstract. [PMID:20978472]","molecular_requirements":"Five minimal phagocytic determinants (K/R(X)1-2KKK) in the Tulp1 N-terminus are essential for MerTK binding, receptor phosphorylation and phagocytosis; the C-terminal region binds phagocytic prey [PMID:20978472].","affinity_potency":[],"species_and_systems":"Retinal pigment epithelium and macrophage phagocytosis assays; species not stated in the abstract [PMID:20978472]. One of the human/mouse pairs is ortholog-inferred.","localisation_and_range":"Unconventionally secreted, no classical signal peptide [PMID:20978472]; ligand flagged secreted and not transmembrane [flag].","caveats":"Abstract read only; no affinity value. Evidence for each TAM receptor shares the same sentence, so receptor-specific binding strength not reported in our evidence. Detailed motif mapping is for MerTK.","key_references":[{"PMID":"20978472","why":"Tulp1 interacts with Tyro3, Axl and MerTK"}],"covers":["LR003427","LR006628"]},"LR004909":{"pair":"UCN2 -> CRHR2","headline":"Urocortin 2 binds and activates CRF2 receptor selectively; supported by two abstract-level papers plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"Agonist: Ucn II binds selectively to CRF-R2 with no appreciable activity on CRF-R1 [PMID:11226328]. Stresscopin-related peptide, equated to UCN2 by the curators, was identified as a specific type 2 CRH receptor ligand [PMID:11329063]. GtoPdb records a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"pKd 8.5 to 8.6","assay":"GtoPdb curated affinity range","system":"not specified in dossier","cite":"PMID:15450949"}],"species_and_systems":"Mouse peptide and receptor in the Ucn II study [PMID:11226328]; human peptide and receptor in the stresscopin study [PMID:11329063]. Both human and mouse pairs are listed, neither ortholog-inferred.","localisation_and_range":"Ligand flagged secreted, receptor transmembrane [flag]; Ucn II acts centrally after central administration in rodent [PMID:11226328].","caveats":"Both primary papers were read as abstracts only. Linking stresscopin-related peptide to UCN2 rests on the curator note. No Kd or Ki is given in the abstracts.","key_references":[{"PMID":"11226328","why":"Cloning of Ucn II and selective CRF-R2 binding"},{"PMID":"11329063","why":"Stresscopin-related peptide as type 2 CRH receptor ligand"}],"covers":["LR001519","LR004909"]},"LR008743":{"pair":"VASP -> CXCR2","headline":"Only IntAct co-immunoprecipitation supports this; VASP is not an evident extracellular ligand and the curation judged the entity different.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond IntAct anti-bait coimmunoprecipitation records [DB:IntAct].","localisation_and_range":"Not reported in our evidence; no secreted flag for VASP, CXCR2 is flagged as a transmembrane receptor [flag].","caveats":"No papers were judged; the single judged row was 'different_entity'. Evidence is two IntAct coimmunoprecipitation records from PMID 21876773 [DB:IntAct], which show association, not ligand-receptor signalling.","key_references":[],"covers":["LR008743"]},"LR007078":{"pair":"VCAM1 -> ITGA9:ITGB1","headline":"Complex-level version of the alpha9beta1 result: one confirmed paper, functional adhesion in human cells.","interaction_type":"functional only","direction_and_effect":"alpha9beta1 mediates stable cell adhesion to recombinant and TNF-alpha-induced HUVEC VCAM-1; adhesion of alpha9-transfected cells was completely inhibited by anti-alpha9beta1 antibody Y9A2 [PMID:10209034].","molecular_requirements":"Requires alpha9beta1; the paper tested the heterodimer on the cell surface [PMID:10209034].","affinity_potency":[],"species_and_systems":"Human: SW480 and CHO transfectants, HUVEC, neutrophils [PMID:10209034].","localisation_and_range":"Cell-surface/recombinant VCAM-1 adhesion; VCAM1 flagged secreted and transmembrane [flag].","caveats":"Single paper, adhesion assays only; no affinity. The curator read it as abstract (full text also present) [PMID:10209034].","key_references":[{"PMID":"10209034","why":"alpha9beta1 mediates adhesion to VCAM-1"}],"covers":["LR007078"]},"LR004918":{"pair":"VCAM1 -> ITGAD","headline":"alphaD beta2 binds VCAM-1 in human transfectants and with soluble protein and I domain; one confirmed paper, abstract only.","interaction_type":"direct binding","direction_and_effect":"Expression of alphaDbeta2 in a lymphoid cell lacking alpha4 integrins confers binding to VCAM-1; soluble alphaDbeta2 binds VCAM-1 and recombinant alphaD I domain binds specifically [PMID:10438935]. UniProt agrees [DB:UniProt].","molecular_requirements":"The alphaD I domain contains the binding site; VCAM-1 aspartate D40 is needed; alphaDbeta2 is the functional heterodimer [PMID:10438935].","affinity_potency":[],"species_and_systems":"Human transfectants and recombinant proteins; adhesion under flow comparable to alpha4beta1 [PMID:10438935]. Mouse pair is ortholog-inferred.","localisation_and_range":"Cell-surface VCAM-1 (flagged secreted and transmembrane) [flag].","caveats":"Single abstract-level paper; the stored partner is ITGAD alone although beta2 is required. BioGRID: reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"10438935","why":"alphaDbeta2 and its I domain bind VCAM-1"}],"covers":["LR001529","LR004918"]},"LR004927":{"pair":"VEGFA -> GPC1","headline":"VEGF165 binds glypican-1 with sub-nanomolar apparent Kd via heparan sulfate; a presenting co-receptor, one paper.","interaction_type":"direct binding","direction_and_effect":"Glypican-1 from rat myoblasts binds VEGF165 but not VEGF121, and the authors describe it as an extracellular chaperone that potentiates VEGF165 binding to KDR [PMID:10196157].","molecular_requirements":"Binding is mediated by glypican-1 heparan sulfate chains: heparinase abolishes it and excess heparin or heparan sulfate inhibits it [PMID:10196157].","affinity_potency":[{"value":"Kd 3 x 10(-10) M","assay":"solid-phase binding, apparent dissociation constant","system":"rat myoblast glypican-1","cite":"PMID:10196157"}],"species_and_systems":"Human VEGF165 with rat myoblast glypican-1; human endothelial cell glypican-1 also bound [PMID:10196157].","localisation_and_range":"Glypican-1 is GPI-anchored per the abstract [PMID:10196157]; GPC1 is flagged secreted in the entity record [flag].","caveats":"One paper, abstract only. The interaction is carbohydrate-mediated, so it is not a classic signalling receptor. VEGF121 does not bind. BioGRID lists the same paper [DB:BioGRID].","key_references":[{"PMID":"10196157","why":"Glypican-1 binding to VEGF165 and chaperone role"}],"covers":["LR001538","LR004927"]},"LR006646":{"pair":"VEGFA -> PTPRZ1","headline":"VEGF165 interacts directly with PTPRZ1 (RPTPbeta/zeta) in endothelial and glioma cells by co-IP and proximity ligation, independent of VEGFR2; one paper.","interaction_type":"direct binding","direction_and_effect":"VEGF165 interacts with RPTPbeta/zeta, which mediates VEGF165-induced c-Src-dependent beta3 Tyr773 phosphorylation, cell-surface nucleolin localisation and endothelial migration; RPTPbeta/zeta knockdown abolished these effects [PMID:25644401].","molecular_requirements":"Interaction was seen in a VEGFR-independent manner; VEGFR2 did not associate with RPTPbeta/zeta, and the VEGF-RPTPbeta/zeta signal persisted with bevacizumab present in PLA (legend) [PMID:25644401]. No subunit requirement reported.","affinity_potency":[],"species_and_systems":"Human umbilical vein endothelial cells and U87MG glioma cells, with endogenous VEGF; co-IP/Western, double immunofluorescence and proximity ligation [PMID:25644401]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGFA flagged secreted; PTPRZ1 flagged both secreted and transmembrane [flag]. The paper describes it as a transmembrane phosphatase [PMID:25644401].","caveats":"Single paper; the evidence is co-IP and in situ proximity, not purified-protein binding with affinity, so directness is inferred from the authors' interpretation. BioGRID records the same paper [DB:BioGRID]. No affinity reported.","key_references":[{"PMID":"25644401","why":"VEGF165-RPTPbeta/zeta interaction in HUVEC and U87MG cells"}],"covers":["LR003445","LR006646"]},"LR004936":{"pair":"VEGFC -> ITGA9","headline":"VEGF-C binds integrin alpha9beta1 in a solid-phase assay, but only one paper and the evidence is for the alpha9beta1 heterodimer.","interaction_type":"direct binding","direction_and_effect":"Recombinant VEGF-C bound purified alpha9beta1 integrin in a dose- and cation-dependent fashion; alpha9beta1-expressing cells adhered and migrated on VEGF-C, blocked by a function-blocking antibody [PMID:15590642].","molecular_requirements":"The evidence is for the alpha9beta1 heterodimer, so ITGA9 alone is not shown to suffice; ITGB1 is the partner chain [PMID:15590642].","affinity_potency":[],"species_and_systems":"Recombinant human proteins; mouse embryonic fibroblasts, SW-480 cells and microvascular endothelial cells are used [PMID:15590642]. Both listed interactions are ortholog-inferred.","localisation_and_range":"VEGFC flagged secreted [flag]; integrins are membrane receptors, but this dossier carries no receptor flag for ITGA9.","caveats":"Single abstract-read paper; no affinity reported; no database records in this dossier.","key_references":[{"PMID":"15590642","why":"VEGF-C binds alpha9beta1 integrin"}],"covers":["LR001547","LR004936"]},"LR004945":{"pair":"VIP -> VIPR2","headline":"Established direct VIP agonist action at VPAC2, supported by many human recombinant binding and cAMP studies; shares VIP with VPAC1.","interaction_type":"direct binding","direction_and_effect":"VIP acts as an agonist at human VPAC2, binding and stimulating cAMP in CHO transfectants [PMID:16930633] [PMID:10801840]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"VPAC2 N-terminal residue E24A abolished 125I-VIP binding, with I31A and T274A reducing it [PMID:9454823]. C-terminal helical structure of ligands is needed for VIP2 recognition among related peptides [PMID:9928018].","affinity_potency":[{"value":"Ki 16 nM","assay":"competitive inhibition of 125I-VIP binding","system":"CHO transfectants, human VIPR2","cite":"PMID:9152366"},{"value":"pEC50 7.3","assay":"cAMP","system":"CHO cells, human VPAC2","cite":"PMID:16930633"},{"value":"pEC50 9.3","assay":"adenylyl cyclase stimulation","system":"cells expressing human VPAC2","cite":"PMID:10801840"}],"species_and_systems":"Human recombinant receptors in CHO and Cos cells; some papers also tested rat receptors [PMID:9437714].","localisation_and_range":"VIP is flagged secreted and VIPR2 transmembrane [flag].","caveats":"Most rows are analogue/selectivity studies using VIP as the reference, abstracts only. VIP binds VPAC1 and VPAC2 with similar potency, so it is not subtype-selective. Mouse pair is ortholog-inferred. Reactome and UniProt records also describe VIP receptors binding VIP [DB:Reactome R-HSA-420233] [DB:UniProt].","key_references":[{"PMID":"10801840","why":"Alanine scan of VIP on VPAC1 and VPAC2"},{"PMID":"9152366","why":"VIP Ki at VPAC2 in CHO transfectants"},{"PMID":"16930633","why":"VIP potency at VPAC2 in cAMP and calcium assays"}],"covers":["LR001556","LR004945"]},"LR008185":{"pair":"VTN -> ITGAV:ITGB5","headline":"AlphaVbeta5 mediates cellular uptake and degradation of vitronectin in human cells; one abstract-only functional paper.","interaction_type":"functional only","direction_and_effect":"Antibodies against alphaVbeta5, but not alphaVbeta3, inhibited vitronectin degradation by 80%; RGDS peptide blocked internalisation, so alphaVbeta5 mediates endocytic clearance of the conformationally altered, heparin-binding form [PMID:7685013]. Reactome and IntAct also list the pair [DB:Reactome] [DB:IntAct].","molecular_requirements":"The complex of ITGAV and ITGB5; specificity over alphaVbeta3 shown by antibodies [PMID:7685013].","affinity_potency":[],"species_and_systems":"Adherent cells (species not stated in the abstract; curator lists human) [PMID:7685013].","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"This is a clearance/endocytosis result, not a signalling or binding measurement. Abstract only; no affinity.","key_references":[{"PMID":"7685013","why":"alphaVbeta5 antibodies block vitronectin degradation by 80%"}],"covers":["LR008185"]},"LR004954":{"pair":"VTN -> ITGB8","headline":"No paper supports this chain-only pair; Reactome assertion only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. Reactome lists vitronectin binding to alphaVbeta3, alphaVbeta5 and alphaVbeta8 [DB:Reactome].","molecular_requirements":"ITGB8 would act as alphaVbeta8 per Reactome [DB:Reactome]; not tested in our papers.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"All 6 judged abstracts were insufficient; no curator-verified paper. Support rests on database records [DB:Reactome].","key_references":[],"covers":["LR001565","LR004954"]},"LR006655":{"pair":"VWF -> ITGB1","headline":"Only the VWF propolypeptide has been shown to support beta1 integrin (alpha4beta1, alpha9beta1) adhesion; functional only.","interaction_type":"functional only","direction_and_effect":"pp-vWF promoted cell adhesion through alpha9beta1 or alpha4beta1 in G-361 or MOLT-3 cells, blocked by anti-alpha9 or anti-alpha4 antibody [PMID:10816592].","molecular_requirements":"beta1 pairs with alpha4 or alpha9; the evidence is on alpha-chain antibody blocking, not beta1 alone [PMID:10816592].","affinity_potency":[],"species_and_systems":"Human cells, G-361, MOLT-3 and SW480 transfectants [PMID:10816592]. Both pairs are ortholog-inferred.","localisation_and_range":"Beta1 is flagged non-secreted and a receptor [flag].","caveats":"Ligand is the propolypeptide, not mature VWF. Cell adhesion only; beta1-specific evidence is not reported in our evidence.","key_references":[{"PMID":"10816592","why":"pp-vWF supports alpha4beta1 and alpha9beta1 adhesion"}],"covers":["LR003455","LR006655"]},"LR004963":{"pair":"WNT1 -> FZD5","headline":"WNT1 signals through FZD5 in a HEK293 reporter knockout-panel study; functional evidence only.","interaction_type":"functional only","direction_and_effect":"Wnt1, Wnt8a, Wnt7b, Wnt8b and Wnt10a induced signalling via FZD5 and FZD8 in the FZD knockout reporter system [PMID:28733458]. The pair is annotated stimulatory.","molecular_requirements":"FZD5 and FZD8 are both named for Wnt1; whether either alone suffices is not reported in our evidence [PMID:28733458].","affinity_potency":[],"species_and_systems":"Human HEK293 reporter cells with multiplex CRISPR FZD knockouts; the mouse pair is ortholog-inferred [PMID:28733458].","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"Functional readout only; no binding data. FZD8 is an alternative in the same statement.","key_references":[{"PMID":"28733458","why":"Wnt1 signals via FZD5 and FZD8 in knockout reporter cells"}],"covers":["LR001574","LR004963"]},"LR005359":{"pair":"WNT1 -> ROR2","headline":"WNT1 binds ROR2 by co-immunoprecipitation, but ROR2 modulates rather than simply activates WNT1 signalling.","interaction_type":"direct binding","direction_and_effect":"Immunoprecipitation showed physical interaction between human Ror2 and mammalian Wnt1 and Wnt3 [PMID:15388793]. Ror2 antagonised Wnt1-mediated cytosolic beta-catenin stabilisation yet potentiated Wnt1 activity in the reporter assay [PMID:15388793].","molecular_requirements":"Binding did not change Ror2 autophosphorylation [PMID:15388793]. Co-receptor needs not reported in our evidence.","affinity_potency":[],"species_and_systems":"Osteoblastic cells with human Ror2, abstract only [PMID:15388793]. BioGRID has an affinity capture-western record [DB:BioGRID].","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"Co-IP does not prove direct binding; effect depends on the readout step [PMID:15388793].","key_references":[{"PMID":"15388793","why":"Ror2 binds Wnt1; opposite effects on Wnt1 and Wnt3"}],"covers":["LR002033","LR005359"]},"LR001579":{"pair":"WNT1 -> RYK","headline":"WNT1 binds RYK in co-IP and AP-fusion assays; RYK acts with Frizzled, supported by two papers.","interaction_type":"direct binding","direction_and_effect":"Wnt-1 and Wnt-3a bound Ryk in co-IP; Ryk siRNA abolished Wnt-1-induced TCF-luciferase, and Ryk acts as a coreceptor with Frizzled [PMID:15454084]. Wnt1 binds Ryk in a second paper, where Wnts repel corticospinal axons via Ryk [PMID:16116452].","molecular_requirements":"A ternary complex of Ryk, Wnt-1 and Frizzled-8-CRD-Fc was reported [PMID:15454084], so Frizzled is a partner.","affinity_potency":[{"value":"Kd 7.89 nM","assay":"AP-fusion binding on COS cells (curator note; ligand not specified)","system":"COS cells","cite":"PMID:16116452"}],"species_and_systems":"Human 293T cells [PMID:15454084]; mouse spinal-cord axon assays, browser-read [PMID:16116452].","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"The second paper's quote is browser-read and unverified; its Kd 7.89 nM is recorded in a curator note with AP-fusion binding on COS cells, and the ligand it applies to is not stated.","key_references":[{"PMID":"15454084","why":"Ryk binds Wnt-1; coreceptor with Frizzled"},{"PMID":"16116452","why":"Wnt1 binds Ryk; axon repulsion"}],"covers":["LR001579","LR004968"]},"LR006664":{"pair":"WNT10A -> FZD10","headline":"WNT10A is implied as a FZD10 ligand by knockdown in lung mesenchymal cells; no binding data.","interaction_type":"functional only","direction_and_effect":"Fzd10 knockdown reduced Wnt7b- and Wnt10a-induced Wnt/beta-catenin activation, implying they may be Fzd10 ligands [PMID:29844390].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Lung-resident mesenchymal stem cells and bleomycin fibrosis model; the excerpts refer to mouse lung tissue, abstract plus excerpts [PMID:29844390]. The human pair is projected from mouse.","localisation_and_range":"WNT10A is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag.","caveats":"The authors hedge ('may be the ligands'); binding is not shown.","key_references":[{"PMID":"29844390","why":"Fzd10 knockdown reduces Wnt10a signalling"}],"covers":["LR003464","LR006664"]},"LR008068":{"pair":"WNT10A -> FZD5:LRP6","headline":"WNT10A acts via FZD5 in reporter cells and docks to FZD5 in silico; LRP6 is not addressed.","interaction_type":"functional only","direction_and_effect":"Wnt10a induced signalling via FZD5 and FZD8 in reporter cells [PMID:28733458]. A family case study found that WNT10A wild-type and variant each had three docked binding sites with FZD5 [PMID:38280992].","molecular_requirements":"LRP6 is not reported in either paper; only FZD5 is supported.","affinity_potency":[],"species_and_systems":"Human HEK293 reporter cells [PMID:28733458]; in silico docking in a clinical genetics report [PMID:38280992].","localisation_and_range":"WNT10A is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag.","caveats":"The docking is a prediction from a hypohidrotic ectodermal dysplasia case report [PMID:38280992].","key_references":[{"PMID":"28733458","why":"Wnt10a signals via FZD5"},{"PMID":"38280992","why":"WNT10A-FZD5 docking"}],"covers":["LR008068"]},"LR008167":{"pair":"WNT10B -> FZD7:LRP5","headline":"FZD7 is reported as the WNT10B receptor in human trophoblast cells; the LRP5 chain is not addressed.","interaction_type":"functional only","direction_and_effect":"WNT10B signalling stimulated cytoskeletal remodelling via Rac1, with FZD7 identified as the cognate receptor to up-regulate cell migration [PMID:29979633].","molecular_requirements":"Only FZD7 is named; a role for LRP5 is not reported in our evidence [PMID:29979633].","affinity_potency":[],"species_and_systems":"BeWo and JAR trophoblast cells [PMID:29979633]; pair is human.","localisation_and_range":"Ligand flagged secreted; LRP5 flagged transmembrane [flag].","caveats":"Chain-only evidence from an abstract; the complex was not tested. ","key_references":[{"PMID":"29979633","why":"FZD7 identified as cognate WNT10B receptor"}],"covers":["LR008167"]},"LR003469":{"pair":"WNT10B -> LRP5","headline":"No confirmed paper; supported only by an IntAct co-immunoprecipitation record.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence beyond an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-54924173].","molecular_requirements":"Whether Frizzled is also required is not reported in our evidence.","affinity_potency":[],"species_and_systems":"The mouse entry is not ortholog-inferred and the human entry is; the experimental species of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand flagged secreted, LRP5 flagged receptor and transmembrane [flag].","caveats":"Two papers were judged abstract-insufficient, so none confirms the pair.","key_references":[],"covers":["LR003469","LR006669"]},"LR006673":{"pair":"WNT11 -> FZD5","headline":"WNT11 activation of FZD5 is supported functionally in cardiac fibroblasts; direct binding was not shown.","interaction_type":"functional only","direction_and_effect":"Recombinant Wnt11 increased FZD5 expression, ERK/p38 activation and EGFR phosphorylation in cardiac fibroblasts; si-FZD5 reversed Wnt11-induced fibrotic marker expression, so FZD5 mediates the effect (agonist direction annotated) [PMID:34564708].","molecular_requirements":"FZD5 crosstalk with EGFR was needed for the fibrotic response; whether Wnt11 binds FZD5 directly, or recruits EGFR, is stated as needing future study [PMID:34564708].","affinity_potency":[],"species_and_systems":"Neonatal rat cardiac fibroblasts treated with recombinant rat Wnt11, plus a mouse TAC pressure-overload model; the dossier labels species as human, and the human pair is ortholog-inferred [PMID:34564708].","localisation_and_range":"Wnt11 is flagged secreted [flag]; the paper shows Wnt11 secreted from cardiomyocytes and fibroblasts acting on fibroblasts [PMID:34564708].","caveats":"Authors note few studies report a Wnt11-FZD5 interaction [PMID:34564708]. No binding assay; no affinity.","key_references":[{"PMID":"34564708","why":"Si-FZD5 blocks Wnt11 pro-fibrotic effects in cardiac fibroblasts"}],"covers":["LR003473","LR006673"]},"LR004972":{"pair":"WNT2 -> FZD9","headline":"Functional evidence: only Wnt-2 among Wnts tested activated rat Frizzled-9 in TCF transcription in 293T cells.","interaction_type":"functional only","direction_and_effect":"Of several Wnt members transfected with Rfz9, only Wnt-2 activated Rfz9 in TCF-dependent transcription [PMID:12138115]. Deleting the Wnt-binding domain caused loss of Wnt-2-dependent TCF transcription [PMID:12138115].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat Frizzled-9 in 293T cells; the human and mouse pairs are projected from this by orthology [PMID:12138115].","localisation_and_range":"WNT2 is annotated as secreted [flag].","caveats":"Rat receptor, not human. No direct binding measured; abstract read only [PMID:12138115].","key_references":[{"PMID":"12138115","why":"Only Wnt-2 activated rat Fz9 in TCF reporter"}],"covers":["LR001583","LR004972"]},"LR005368":{"pair":"WNT2B -> FZD4","headline":"Supported by functional EMT data in human cells and a competition study with Tsukushi; both read from abstracts.","interaction_type":"functional only","direction_and_effect":"WNT2b induced EMT in HT29 cells through FZD4 activation [PMID:31359032]. Tsukushi binds the Fzd4 cysteine-rich domain and competes with Wnt2b, inhibiting Wnt signalling [PMID:21856951][DB:UniProt].","molecular_requirements":"Fzd4 cysteine-rich domain is the Wnt-binding site; LRP5/6 is the co-receptor in the general model, not tested for this pair [PMID:21856951].","affinity_potency":[{"value":"2.3 x 10(-10) M","assay":"Tsukushi binding to Fzd4 cysteine-rich domain (not Wnt2b itself)","system":"not stated in abstract","cite":"PMID:21856951"}],"species_and_systems":"Human cells and Crohn's disease tissue [PMID:31359032]; chick eye and mouse knockout [PMID:21856951].","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"The affinity belongs to Tsukushi-Fzd4, not Wnt2b-Fzd4. Direct Wnt2b-Fzd4 binding is only background in the abstract. Both papers abstract only.","key_references":[{"PMID":"31359032","why":"WNT2b induces EMT through FZD4"},{"PMID":"21856951","why":"Tsukushi competes with Wnt2b for Fzd4"}],"covers":["LR002042","LR005368"]},"LR008059":{"pair":"WNT3 -> FZD4:LRP6","headline":"No curated paper supports WNT3 -> FZD4:LRP6; the only record is a database interaction entry.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence beyond the complex name.","affinity_potency":[],"species_and_systems":"Species of the database experiment not reported in our evidence; the pair is annotated human.","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"No paper was confirmed for this pair (outcomes: review_only, abstract_insufficient, different_entity). The one IntAct record is a surface plasmon resonance entry for accession pair O75581-P56703 [DB:IntAct] and does not identify the Frizzled member [PMID:31036956].","key_references":[],"covers":["LR008059"]},"LR003487":{"pair":"WNT3 -> LRP5","headline":"Zebrafish study using fluorescence cross-correlation reports that Lrp5 is required for Wnt3-Fzd1 binding; direct Wnt3-LRP5 binding is untested.","interaction_type":"functional only","direction_and_effect":"Lrp5 is required for the Wnt3-Fzd1 interaction in a fluorescence cross-correlation assay [PMID:33236989]; the authors state that the Kd for Wnt3-LRP5 remains to be measured.","molecular_requirements":"Lrp5 acts as an essential co-receptor component for Wnt3-Fzd1 binding [PMID:33236989].","affinity_potency":[],"species_and_systems":"Zebrafish brain in vivo; the dossier labels species human, so pair species and experimental species differ. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Wnt3 spreads extracellularly and interacts with heparan sulfate proteoglycans, supporting a diffusive paracrine range [PMID:33236989].","caveats":"The paper determined Wnt3-Fzd1 affinity but no value is in our dossier. The pair as listed (WNT3 -> LRP5) is not itself shown to bind; the evidence is Lrp5 dependence of Wnt3-Fzd1 binding.","key_references":[{"PMID":"33236989","why":"Lrp5 required for Wnt3-Fzd1 interaction in zebrafish brain"}],"covers":["LR003487","LR006687"]},"LR001597":{"pair":"WNT3 -> LRP6","headline":"WNT3 is functionally grouped with Wnt3a-class proteins that depend on the LRP6 third propeller, from antibody blockade only.","interaction_type":"functional only","direction_and_effect":"Co-receptor role: Wnt3a-class anti-LRP6 antibodies, which bind the third propeller, block growth of MMTV-Wnt3 xenografts in vivo [PMID:20713706].","molecular_requirements":"The third propeller of LRP6 is implicated for Wnt3a-class proteins; Wnt1-class proteins use the first propeller [PMID:20713706].","affinity_potency":[],"species_and_systems":"MMTV-Wnt3 tumour xenografts in vivo; species labelled human [PMID:20713706]. Abstract only. IntAct has one surface plasmon resonance record for O75581-P56703 [DB:IntAct].","localisation_and_range":"Ligand is flagged secreted [flag]; range not reported in our evidence.","caveats":"Evidence is indirect antibody blockade; direct WNT3-LRP6 binding is not reported in the abstract. The listed IntAct pmid is 31036956, not in our papers.","key_references":[{"PMID":"20713706","why":"Anti-LRP6 antibody classes block Wnt3 xenografts"}],"covers":["LR001597","LR004986"]},"LR006691":{"pair":"WNT3A -> FZD4","headline":"WNT3A activating FZD4 is supported by binding and functional papers; one cited binding is only from full text of a different study.","interaction_type":"direct binding","direction_and_effect":"WNT-3A activated the WNT-beta-catenin pathway (LRP6 phosphorylation, beta-catenin stabilization) through FZD4 in 32D cells [PMID:25605717]. FZD4-G protein complex dissociates on WNT-3A stimulation [PMID:27458145]. Wnt3/Wnt3a induced signaling via all FZDs in a CRISPR FZD-mutant system [PMID:28733458].","molecular_requirements":"Binding was to purified FZD cysteine-rich domains by bio-layer interferometry [PMID:25605717]. Canonical signaling involved LRP6 phosphorylation [PMID:25605717]; in HEK293T cells lacking FZD1,2,4,5,7,8, Wnt3 could not induce beta-catenin signaling [PMID:28733458].","affinity_potency":[],"species_and_systems":"Human ligand and receptor in all papers; 32D cells [PMID:25605717], HEK293 cells [PMID:30304675, PMID:27458145], HEK293T CRISPR mutants [PMID:28733458]. Human and mouse versions of the pair are listed.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"PMID:25605717 and PMID:27458145 were read as abstracts only. PMID:28733458 states the FZD finding generically across FZDs. In PMID:30304675 WNT3A binding to FZD4 was a positive control, not the study's focus. Affinity values for FZD4 are not given in our evidence.","key_references":[{"PMID":"25605717","why":"Binding mapping plus 32D cell canonical activation via FZD4"},{"PMID":"30304675","why":"WNT3A bound sFZD4-Fc and cell-surface SNAP-FZD4"},{"PMID":"28733458","why":"Functional FZD rescue map; Wnt3a signals via all FZDs"}],"covers":["LR003491","LR006691"]},"LR001588":{"pair":"WNT3A -> FZD6","headline":"WNT3A acts on FZD6 in functional assays; two of three papers are indirect and one is a disease-genetics study.","interaction_type":"functional only","direction_and_effect":"Recombinant WNT-3A, among other WNTs, changed FZD6 surface mobility in FRAP, agonist effect [PMID:24873871]. Cells with a FZD6 nonsense mutation responded aberrantly to WNT-3A [PMID:21665003]. GtoPdb lists an Agonist interaction [DB:GtoPdb].","molecular_requirements":"Reported effects are on FZD6 alone; coreceptor requirement is not reported in our evidence. In PMID:24873871 FZD6 mobility effects relate to putative precoupling of Gi/o proteins.","affinity_potency":[],"species_and_systems":"Human FZD6-GFP in HEK293T/17 cells [PMID:24873871]; human fibroblasts and Fzd6-/- mice [PMID:21665003]. The mouse pair is ortholog-inferred.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"The curated direct_binding label for PMID:30594556 comes from a study where SMOC-2 interacted with Fzd6 and LRP6 and enhanced Wnt3a-receptor interaction; it was read as abstract only. PMID:21665003 was read as abstract only and is a genetic study. No affinity reported.","key_references":[{"PMID":"24873871","why":"WNT-3A changed FZD6 mobility in FRAP"},{"PMID":"21665003","why":"FZD6 mutant fibroblasts respond aberrantly to WNT-3A"},{"PMID":"30594556","why":"SMOC-2 enhanced Wnt3a-Fzd6 interaction"}],"covers":["LR001588","LR004977"]},"LR003496":{"pair":"WNT3A -> PTK7","headline":"PTK7 co-precipitates Wnt3a but inhibits canonical Wnt signalling; single abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"PTK7/Otk co-precipitates canonical Wnt3a but inhibits rather than activates canonical Wnt activity; loss of PTK7 activates it [PMID:21772251]. Effect is antagonist.","molecular_requirements":"Epistasis places PTK7 at the level of the Frizzled receptor [PMID:21772251].","affinity_potency":[],"species_and_systems":"Co-precipitation plus Xenopus, Drosophila and luciferase reporter assays [PMID:21772251]. Species of the co-IP proteins are not stated beyond the curator's human label.","localisation_and_range":"PTK7 flagged both secreted and receptor [flag]; a transmembrane receptor per the paper [PMID:21772251].","caveats":"Abstract only; co-precipitation does not prove direct binding. The authors propose PTK7 diverts Wnt into non-canonical signalling.","key_references":[{"PMID":"21772251","why":"PTK7 co-precipitates Wnt3a and inhibits canonical signalling"}],"covers":["LR003496","LR006696"]},"LR004981":{"pair":"WNT3A -> RYK","headline":"RYK acts as a Wnt co-receptor with Frizzled and is required for Wnt-3a induced neurite outgrowth; direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"Ryk is required for neurite outgrowth induced by Wnt-3a and activates the canonical pathway via Dishevelled; effect is stimulatory [PMID:15454084].","molecular_requirements":"Ryk works as a co-receptor along with Frizzled and binds Dishevelled [PMID:15454084].","affinity_potency":[],"species_and_systems":"Mouse DRG explants and Ryk siRNA transgenic mice; Wnt-3a conditioned medium [PMID:15454084]. Human pair is ortholog-inferred; mouse pair is direct.","localisation_and_range":"Not reported in our evidence beyond ligand flag as secreted [flag].","caveats":"Single paper; no direct binding of Wnt-3a to Ryk is reported in our evidence, and Ryk depends on Frizzled.","key_references":[{"PMID":"15454084","why":"Ryk as Wnt co-receptor needed for Wnt-3a neurite outgrowth"}],"covers":["LR001592","LR004981"]},"LR004990":{"pair":"WNT5A -> FZD1","headline":"Wnt5a binds the FZD1 CRD with intermediate affinity and co-immunoprecipitates with FZD1, but does not drive FZD1-dependent TCF signalling.","interaction_type":"conflicting","direction_and_effect":"Wnt-5a coimmunoprecipitated with human Hfz1, yet Wnt-5a did not cooperate with Hfz1 in TCF-dependent transcription, whereas Wnt-3a did [PMID:10557084]. UniProt likewise says FZD1 is apparently not activated by WNT5A [DB:UniProt].","molecular_requirements":"The binding data use the FZD1 cysteine-rich domain (CRD) alone [PMID:25605717]. Co-receptor needs not reported in our evidence.","affinity_potency":[{"value":"KD = 22\u201326 nm","assay":"Bio-layer interferometry, purified WNT-5A binding to FZD CRD-Fc, reported jointly for the FZD1/2/4 CRDs","system":"mouse proteins, in vitro","cite":"PMID:25605717"}],"species_and_systems":"Mouse proteins by bio-layer interferometry [PMID:25605717]; human cells by co-IP [PMID:10557084]. The dossier also lists an inferred ortholog pair in mouse.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"The affinity paper was read from a browser full text and its quote is flagged unverifiable, spot-check pending [PMID:25605717]. The 10557084 evidence is from the abstract only, and the binding does not translate into canonical signalling. BioGRID has one Affinity Capture-Western record [DB:BioGRID].","key_references":[{"PMID":"25605717","why":"BLI binding of WNT-5A to FZD1 CRD"},{"PMID":"10557084","why":"Co-IP of Hfz1 with Wnt-5a, without TCF activation"}],"covers":["LR001601","LR004990"]},"LR008077":{"pair":"WNT5A -> FZD5:LRP6","headline":"No paper evidence for WNT5A with the FZD5:LRP6 complex; database records only.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. BioGRID records LRP6 - WNT5A Affinity Capture-Western [DB:BioGRID]; Reactome lists WNT5A:FZD complexes [DB:Reactome].","molecular_requirements":"Not reported in our evidence; records concern individual chains.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Rests on database records alone; the judged papers were review-only.","key_references":[],"covers":["LR008077"]},"LR006709":{"pair":"WNT5A -> TLR4","headline":"WNT5A binds TLR4 directly (SPR, pulldown, co-localisation) and signals through it; one paper.","interaction_type":"direct binding","direction_and_effect":"Agonist: Wnt5a acts as a TLR4 ligand; TNF-alpha induction in mouse cells was entirely TLR4-dependent, and in human cells IL-10 induction relied on TLR2/4-MyD88 [PMID:31098409].","molecular_requirements":"Signalling is MyD88-dependent in part (partially in mouse); TLR4 with MD2 was also tested by SPR [PMID:31098409]. Need for other subunits: not reported in our evidence.","affinity_potency":[{"value":"KD ~27 nM","assay":"SPR, saturable binding, as stated in the text (TLR4/MD2 ~45 nM)","system":"recombinant proteins","cite":"PMID:31098409"}],"species_and_systems":"Human and mouse myeloid cells; Wnt5a and hTLR4-GFP co-localised and capped in NIH3T3 cells [PMID:31098409].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Single paper curated from the abstract. Wnt5a effects are opposite in species: pro-inflammatory in mouse, anti-inflammatory in human myeloid cells [PMID:31098409]. Polymyxin B blocked part of the response but TLR-blocking antibodies did not, so the binding mode differs from LPS [PMID:31098409].","key_references":[{"PMID":"31098409","why":"SPR, pulldown, co-localisation and species-divergent signalling"}],"covers":["LR003509","LR006709"]},"LR007708":{"pair":"WNT5B -> FZD3:LRP5","headline":"Only FZD3 itself is supported (NSCLC PCP signalling); LRP5 involvement is not shown.","interaction_type":"functional only","direction_and_effect":"Stimulatory through FZD3: WNT5B-dependent DVL3 recruitment and JNK activation via RAC1 in NSCLC cells [PMID:39094673].","molecular_requirements":"The abstract names FZD3 and DVL3, not LRP5; the complex requirement is not reported in our evidence. Since the pathway is described as non-canonical WNT-PCP, LRP5 need is unproven [PMID:39094673].","affinity_potency":[],"species_and_systems":"NSCLC specimens and cell lines; species of cells not stated [PMID:39094673].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Evidence is for FZD3 alone and the abstract only; the complex pair rests on this one paper. Other papers were review-only or insufficient.","key_references":[{"PMID":"39094673","why":"WNT5B-FZD3-DVL3 signalling in NSCLC"}],"covers":["LR007708"]},"LR010678":{"pair":"WNT6 -> FZD1:LRP6","headline":"No verified paper; the only database line says FZD1 is apparently not activated by WNT6.","interaction_type":"database-asserted only","direction_and_effect":"Direction not reported. UniProt says FZD1 is apparently not activated by WNT6 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"No paper confirmed the pair; the sole database record is a negative statement [DB:UniProt].","key_references":[],"covers":["LR010678"]},"LR006718":{"pair":"WNT6 -> LRP6","headline":"Functional support only: anti-LRP6 antibody blockade inhibits WNT6 signalling; no direct WNT6 binding shown in our evidence.","interaction_type":"functional only","direction_and_effect":"Wnt1-specific anti-LRP6 Fab fragments inhibited signalling by a class of Wnt proteins that includes Wnt6, in a SuperTopFlash reporter assay [PMID:20713706]. LRP6 acts as a Wnt co-receptor and the antibodies bind its first propeller [PMID:20713706].","molecular_requirements":"Wnt6 is inferred to depend on LRP6 propeller 1, from antibody blockade; whether other receptor chains are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cells (HEK293 reporter assay); the mouse pair is projected from human evidence [PMID:20713706].","localisation_and_range":"WNT6 is flagged secreted and LRP6 transmembrane [flag]; a secreted ligand acting on a membrane receptor.","caveats":"Evidence is indirect (antibody inhibition, not binding of WNT6 to LRP6); the curator row was read in a browser and the quote is unverified; the dossier holds one paper.","key_references":[{"PMID":"20713706","why":"Anti-LRP6 antibodies block Wnt6-class signalling"}],"covers":["LR003518","LR006718"]},"LR008158":{"pair":"WNT7A -> FZD5:LRP5","headline":"No paper evidence; support rests on UniProt records for WNT7A-FZD5.","interaction_type":"database-asserted only","direction_and_effect":"No confirmed paper. UniProt records FZD5 interacting with WNT7A and WNT7A promoting synapse formation via FZD5 [DB:UniProt].","molecular_requirements":"The LRP5 chain is not addressed in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; LRP5 is flagged transmembrane [flag].","caveats":"Both judged papers were review-only; no experiment supports the complex or LRP5.","key_references":[],"covers":["LR008158"]},"LR007780":{"pair":"WNT7A -> WIF1","headline":"WNT7A-WIF1 rests only on IntAct surface plasmon resonance records; WIF1 is not a membrane receptor.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as an inhibitory ligand-ligand interaction; no paper in our evidence was judged for it, and one review was set aside as review-only.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental system not reported in our evidence beyond IntAct listing surface plasmon resonance with PMIDs 22986341 and 26342861 [DB:IntAct].","localisation_and_range":"WIF1 is flagged not a receptor and not transmembrane [flag]; it is a secreted-type partner, so any effect would be extracellular sequestration, not signalling.","caveats":"No curator-verified paper. Support is two IntAct records [DB:IntAct]; in LR resources this is a ligand-ligand (decoy-type) entry rather than a receptor pair.","key_references":[],"covers":["LR007780"]},"LR005377":{"pair":"WNT7B -> FZD5","headline":"WNT7B signals through FZD5 in a FZD-knockout reporter map; functional evidence, no binding data.","interaction_type":"functional only","direction_and_effect":"In HEK293 cells lacking several FZDs, Wnt7b induced signalling via FZD5 and FZD8 [PMID:28733458].","molecular_requirements":"Rescue was tested with single FZDs; co-receptor needs not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HEK293 reporter with multiplex CRISPR FZD knockout [PMID:28733458]. Mouse pair ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Reporter activation does not show direct binding. Two further papers were abstract-insufficient.","key_references":[{"PMID":"28733458","why":"FZD-Wnt functional map, WNT7B via FZD5/FZD8"}],"covers":["LR002051","LR005377"]},"LR008086":{"pair":"WNT7B -> FZD7:LRP6","headline":"WNT7B acting through FZD7 is supported by two abstract-level papers; LRP6 as part of the complex is not addressed.","interaction_type":"direct binding","direction_and_effect":"WNT7B signals to FZD7. One paper reports Fzd7 binds Wnt7b and modulates beta-catenin levels, possibly via the canonical Wnt pathway [PMID:33934523]. Another identifies Fz7 as the receptor for Wnt7b-driven dendrite growth, acting via non-canonical CaMKII and JNK signalling [PMID:29898920].","molecular_requirements":"FZD7 is the only chain with evidence. LRP6 is not mentioned in either abstract; its requirement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pancreatic cancer cells (Capan-2, Panc-1) with knockdown and overexpression [PMID:33934523]; hippocampal neurons, with in vivo Fz7 loss of function in mouse hippocampus [PMID:29898920].","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"Both papers were read as abstracts only. The binding claim in [PMID:33934523] is a one-line mechanistic statement; no binding assay is described in the abstract. The two papers describe opposite pathway outputs (canonical vs non-canonical), consistent with context dependence but not resolved.","key_references":[{"PMID":"33934523","why":"Fzd7 binds Wnt7b in pancreatic cancer cells"},{"PMID":"29898920","why":"Fz7 as Wnt7b receptor in neuronal dendrites"}],"covers":["LR008086"]},"LR008176":{"pair":"WNT7B -> FZD8:LRP5","headline":"WNT7B binding FZD8 on fibroblast-like synoviocytes is proposed in one 2026 abstract; LRP5 is not addressed.","interaction_type":"functional only","direction_and_effect":"The authors suggest macrophage-secreted Wnt7b bound the FZD8 receptor on fibroblast-like synoviocytes (FLSs), activating Wnt/beta-catenin signalling and promoting rheumatoid arthritis [PMID:42393256].","molecular_requirements":"FZD8 only; LRP5 is not mentioned in the available abstract text, so it is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Collagen-induced arthritis mice and macrophage-FLS co-culture; the abstract lists Co-IP among the methods [PMID:42393256]. Species of the co-culture cells is not reported in our evidence.","localisation_and_range":"Wnt7b is secreted by macrophages and acts on neighbouring FLSs (paracrine), from the paper text [PMID:42393256]; the ligand is also flagged secreted [flag].","caveats":"Abstract only, and the stored abstract is truncated. The binding statement is phrased as a suggestion. No result for LRP5 is given.","key_references":[{"PMID":"42393256","why":"Macrophage Wnt7b to FZD8 on FLSs in arthritis"}],"covers":["LR008176"]},"LR005386":{"pair":"WNT9B -> FZD5","headline":"WNT9B signals through FZD5 in reporter assays in two independent papers (human HEK293 panel and mouse nephron progenitor-like cells).","interaction_type":"functional only","direction_and_effect":"Wnt9b induced canonical signalling with FZD5 and FZD8, and FZD4 and FZD10 [PMID:28733458]. In M15 mesonephric-mesenchyme cells, co-transfected Fzd5 raised the WNT9b signal to 16.8-fold and Fzd5 siRNA reduced it by 52%; curators label it agonist [PMID:30978219].","molecular_requirements":"RSPO1 treatment augmented the WNT9b response 4.8-fold; Lrp6 knockdown cut the signal 60%, so optimal response needs RSPO1, FZD5 and LRP6 [PMID:30978219].","affinity_potency":[{"value":"16.8-fold","assay":"beta-catenin luciferase reporter, Fzd5 co-transfection with WNT9b","system":"M15 cells","cite":"PMID:30978219"}],"species_and_systems":"HEK293 FZD knockout reporter panel, human [PMID:28733458]; M15 cells from E10.5 mesonephric mesenchyme and CITED1+ NPCs from embryonic mouse kidney [PMID:30978219]. Human and mouse pairs listed.","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Both studies use functional reporters; no direct binding. The second paper was read as abstract only and shows a minimal response to WNT9b alone without RSPO1 or FZD5 [PMID:30978219].","key_references":[{"PMID":"28733458","why":"FZD knockout/rescue reporter map showing WNT9B signalling"},{"PMID":"30978219","why":"FZD5, LRP6 and RSPO1 needed for WNT9b response in M15 cells"}],"covers":["LR002060","LR005386"]},"LR006745":{"pair":"WNT9B -> FZD6","headline":"WNT9B changes FZD6 membrane mobility in a FRAP assay; functional evidence only.","interaction_type":"functional only","direction_and_effect":"Recombinant WNT-9B, along with WNT-1, -2, 3A, -4, -5A, -7A and -10B, affected FZD6 surface mobility and thus acts on this receptor; curators label it agonist [PMID:24873871].","molecular_requirements":"Changes in FZD6 mobility relate to putative precoupling to Gi/o proteins (sensitive to pertussis toxin and NEM); no co-receptor reported for WNT9B here [PMID:24873871].","affinity_potency":[],"species_and_systems":"HEK293T/17 cells expressing FZD6-GFP, recombinant human WNT proteins; mouse pair is ortholog-inferred [PMID:24873871].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"FRAP mobility is an indirect readout of interaction, not binding or signalling output; no affinity or potency reported for WNT9B.","key_references":[{"PMID":"24873871","why":"FRAP assay showing WNT-9B effects on FZD6 mobility"}],"covers":["LR003545","LR006745"]},"LR012397":{"pair":"ZNRF3 -> FZD9:LRP6","headline":"Database-asserted only: ZNRF3 (an E3 ligase) is listed as inhibiting a FZD:LRP receptor complex; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Marked inhibitory in the resource, with ZNRF3 acting as a membrane receptor-receptor regulator rather than a classical secreted ligand [flag]. UniProt states ZNRF3 interacts with LRP6, FZD4, FZD5, FZD6 and FZD8 [PMID:22575959][DB:UniProt]; IntAct records anti-bait co-immunoprecipitation (Q9ULT6-O75581) [DB:IntAct]; BioGRID records ZNRF3 - LRP6: Affinity Capture-Western; LRP6 - ZNRF3: Affinity Capture-Western [DB:BioGRID]; Reactome lists ZNRF3,RNF43 binding the FZD:LRP5/6 receptor complex [DB:Reactome]. Functional effect not reported in our evidence.","molecular_requirements":"The listed FZD9 partner is not named in the UniProt statement; LRP6 evidence is present [DB:UniProt]. Whether FZD or LRP alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human. Experimental system not reported in our evidence beyond the database assay labels.","localisation_and_range":"ZNRF3 is flagged as a receptor, not secreted [flag]; this is a membrane-level interaction.","caveats":"All papers for this pair are pending or insufficient; support comes only from databases. The pair is a receptor-receptor complex projection and a given FZD paralog may not have been tested individually.","key_references":[],"covers":["LR012397"]},"LR000967":{"pair":"KNG1 -> PLAUR","headline":"High-molecular-mass kininogen binds soluble uPAR in a domain-mapping binding study; one abstract-read paper plus databases.","interaction_type":"direct binding","direction_and_effect":"Biotinylated high-molecular-mass kininogen (HK) binds soluble uPAR, with binding inhibited by HK, 56HKa and 46HKa [PMID:14764580]. Effect on signalling is not reported in our evidence.","molecular_requirements":"Two suPAR-binding sites were mapped on kininogen: a higher-affinity site in the light chain and a lower-affinity site in the heavy chain; suPAR domains 2 and 3 are mainly involved. HK binds uPAR as part of a multiprotein receptor complex on HUVEC [PMID:14764580].","affinity_potency":[],"species_and_systems":"Soluble uPAR and HUVEC cells; competitive binding assay and peptide mapping [PMID:14764580]. Mouse pair is projected from human evidence.","localisation_and_range":"Ligand annotated as secreted; PLAUR as secreted and transmembrane [flag]; uPAR is described as GPI-linked [PMID:14764580].","caveats":"Abstract-only reading; the paper concerns the HK protein, not bradykinin peptide. BioGRID reconstituted complex and Reactome records agree [DB:BioGRID][DB:Reactome].","key_references":[{"PMID":"14764580","why":"Maps kininogen-suPAR binding sites by competition binding"}],"covers":["LR000967","LR004389"]},"LR008950":{"pair":"IL15 -> IL2RA","headline":"No paper evidence; only a PDB quaternary complex and a UniProt entry that mentions IL15RA, so the IL2RA link is weak.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. The one review-only row was not read as primary evidence.","molecular_requirements":"PDB 4GS7 is the structure of the interleukin-15 quaternary complex, with chains of P40933 and P31785 [DB:PDB 4GS7] [PMID:23104097]. The UniProt entry for P31785 says it acts probably in association with IL15RA in IL15-driven neutrophil phagocytosis [DB:UniProt] [PMID:15123770].","affinity_potency":[],"species_and_systems":"Human; PDB entry by X-ray diffraction [DB:PDB 4GS7]. No cell system reported in our evidence.","localisation_and_range":"IL15 is flagged secreted and non-transmembrane [flag].","caveats":"Support is from databases alone. A structure of a complex does not show a direct IL15-IL2RA contact, and the dossier does not say which chain is IL2RA.","key_references":[],"covers":["LR008950"]},"LR000886":{"pair":"IL1RN -> IL1R2","headline":"Direct binding of IL-1ra to the type II IL-1 receptor shown by radioligand competition on human cells; database records agree.","interaction_type":"direct binding","direction_and_effect":"IL-1ra binds the type II receptor with an affinity equal to IL-1 alpha and 15-fold lower than IL-1 beta, suggesting it may be a weaker competitor of IL-1 [PMID:1834644]. Reactome lists an IL1R1:IL1R2:IL1RN complex [DB:Reactome]. The curated 'Stimulatory' label is not explained in our evidence.","molecular_requirements":"Single receptor chain IL1R2 on cells was sufficient for binding in the assay [PMID:1834644]. Co-receptor needs are not reported in our evidence.","affinity_potency":[{"value":"KD = 15 +/- 3 nM","assay":"radioligand competition binding","system":"human Raji B cells","cite":"PMID:1834644"},{"value":"KD = 8 +/- 4 nM","assay":"radioligand binding","system":"human polymorphonuclear leukocytes","cite":"PMID:1834644"},{"value":"KD = 1.4 +/- 0.2 microM","assay":"radioligand binding","system":"mouse 70Z/3 pre-B cells, human IL-1ra","cite":"PMID:1834644"}],"species_and_systems":"Human and rodent IL-1ra on human Raji and PMN cells and mouse pre-B cells; native cell receptors, not recombinant [PMID:1834644].","localisation_and_range":"IL1RN is flagged secreted [flag].","caveats":"Abstract only. Binding to mouse cells was weak and attributed to cell type rather than species [PMID:1834644]. Mouse pair is projected from human evidence.","key_references":[{"PMID":"1834644","why":"Binding affinity of IL-1ra to type II IL-1 receptor"}],"covers":["LR000886","LR004316"]}};